#define TEST(s) if (!(s)) { cout << __LINE__ << " " << #s << endl; exit(-1); }

int B[4][4], x, y;
int manhattan_distance = 0;
int md(int i, int j) {
  int a = B[i][j] - 1;
  return abs(a%4 - j) + abs(a/4 - i);
}
int move(int d) {
  int dx[] = {-1,0,1,0}, dy[] = {0,-1,0,1};
  int X = x + dx[d], Y = y + dy[d];
  if (X < 0 || X >= 4 || Y < 0 || Y >= 4) return false;
  manhattan_distance -= md(X,Y);
  swap(B[x][y], B[X][Y]);
  manhattan_distance += md(x,y);
  x = X; y = Y;
  return true;
}

const int INF = 9999999;
int rbfs() {
  typedef pair<int, bool> result;
  function<result(int,int,int,int)> rec = [&](int depth, int prev, int lower, int bound) {
    if (lower > bound) return result(lower, false);
    if (manhattan_distance == 0) return result(depth, true);
    int score = manhattan_distance + depth;

    int F[4] = {INF+1, INF+1, INF+1, INF+1};
    for (int d = 0; d < 4; ++d) {
      if (abs(prev - d) == 2) continue;
      if (move(d)) {
        F[d] = depth + manhattan_distance + 1;
        if (score < lower) F[d] = min(F[d], lower);
        move((d + 2) % 4);
      }
    }

    while (1) {
      int d = 0, th = INF;
      for (int j = 0; j < 4; ++j) 
        if      (F[j] < F[d]) { th = F[d]; d = j; }
        else if (F[j] < th) { th = F[j]; }
      if (F[d] > bound) return result(F[d], false);
      move(d);
      result z = rec(depth + 1, d, F[d], min(bound, th));
      if (z.snd) return z;
      F[d] = z.fst;
      move((d + 2) % 4);
    }
  };
  printf("%d\n", rec(0, 100, 0, INF).fst);
  return 0;
}

int main() {
  for (int i = 0; i < 4; ++i) {
    for (int j = 0; j < 4; ++j) {
      scanf("%d", &B[i][j]);
      if (B[i][j] == 0) { x = i, y = j; }
      else { manhattan_distance += md(i, j); }
    }
  }
  rbfs();
}

