void initMove(){
  // Can Move Right?
  Move[0][RIGHT]=Move[1][RIGHT]=Move[2][RIGHT]=true;
  Move[4][RIGHT]=Move[5][RIGHT]=Move[6][RIGHT]=true;
  Move[8][RIGHT]=Move[9][RIGHT]=Move[10][RIGHT]=true;
