int getdistance(vector<vector<int> > v)
{
	int ret = 0;

	for (int i = 0; i < 4; i++)
	{
		for (int j = 0; j < 4; j++)
		{
			if (i == 3 && j == 3)
			{
				if (v[i][j] != 0)
				{
					ret++;
				}
			}
			else if (v[i][j] != i * 4 + j + 1)
			{
				ret++;
			}
		}
	}

	return ret;
}

