	int getMD(){
		int sum = 0 ;
		for(int i=0;i<4;i++){
			for(int j=0;j<4;j++){
				if(v[i][j]==0){
					sum += abs(i-3) + abs(j-3);
				}
				else{
					sum += abs(i-((v[i][j]-1) / 4)) + abs(j-((v[i][j]-1) % 4));
				}
			}
		}
		return sum;
	}
};
