int astar(puzzle pz) {
	priority_queue<state> pq;
	/*for (int i = 0; i < num; i++) {
		if (pz.p[i] == 0) continue;
		sum += md[i][pz.p[i] - 1];
	}*/
	pz.cost = 0;
