	state initial;
	initial.pu = pz;
	initial.es = pz.mdp;
	pq.push(initial);
	state st1;
	puzzle p, tmp;
	while (!pq.empty()) {
		state st = pq.top(); pq.pop();
		p = st.pu;
		if (!p.mdp) return p.cost;
		m[p] = true;
		int sx = p.sp / nd;
		int sy = p.sp % nd;
		for (int r = 0; r < nd; r++) {
			int tx = sx + ud[r];
			int ty = sy + lr[r];
			if (tx >= nd || tx < 0 || ty >= nd || ty < 0) continue;
			tmp = p;
			tmp.mdp = p.mdp - md[tx * nd + ty][p.p[tx * nd + ty] - 1] + md[sx*nd + sy][p.p[tx * nd + ty] - 1];
			tmp.sp = tx * nd + ty;
			swap(tmp.p[tx * nd + ty], tmp.p[sx * nd + sy]);
			if (!m[tmp]) {
				tmp.cost++;
				state st1;
				st1.es = tmp.cost + tmp.mdp;
				st1.pu = tmp;
				pq.push(st1);
			}
		}
	}
}

