inline i32 getAllMD()
{
	i32 sum = 0;
	for ( i32 i = 0; i < 16; i++ ) {
		if ( S[i] == 'a' ) continue;
		sum += mdt[i][S[i] - 'b'];
	};
	return (sum);
}

void dfs(i32 n, i32 prev) {
	if ( md == 0 ) { ans = n; return; }
	if ( md + n > limit ) return;

	for ( i32 i = 0; i < 4; i++ ) {
		i32 npos = space + d[i];
		if ( i == 1 && (space & 3) == 0 ) continue;
		if ( i == 2 && (space & 3) == 3 ) continue;
		if ( npos < 0 || 15 < npos ) continue;
