const int num = 16, ud[] = { -1, 0, 1, 0 }, lr[] = { 0, -1, 0, 1 }, nd = 4;
const char wa[] = { 'u', 'l', 'd', 'r' };
int md[num][num];
vector<int> way;
int lm;
struct puzzle {
	int sp, p[num], mdp;
	string way;
	bool operator < (const puzzle &pu) const {
		for (int i = 0; i < num; i++) {
			if (p[i] == pu.p[i]) continue;
			return p[i] < pu.p[i];
		}
		return false;
	}
};
puzzle pu;
bool dfs(int de, int prev, puzzle pu) {
	if (pu.mdp + de> lm) return false;
	//cout << "mdp" << pu.mdp << endl;
	if (!pu.mdp) { /*cout << "mdp" << pu.mdp << endl; */return true; }
	int sx = pu.sp / nd;
	int sy = pu.sp % nd;
	int tx, ty, ns;
	puzzle tmp = pu;
	for (int r = 0; r < nd; r++) {
		if (max(r, prev) - min(r, prev) == 2) continue;
		tx = sx + ud[r];
		ty = sy + lr[r];
		if (tx >= nd || tx < 0 || ty >= nd || ty < 0) continue;
		ns = tx * nd + ty;
		tmp.mdp = pu.mdp - md[ns][pu.p[ns] - 1] + md[sx*nd + sy][pu.p[ns] - 1];
		tmp.sp = ns;
		swap(tmp.p[ns], tmp.p[sx * nd + sy]);
		if (dfs(de + 1, r, tmp)) { way.push_back(r); /*cout << "sp" << tmp.sp << "r" << r << endl;*/ return true; };
	}
	return false;
}

