typedef vector<int> Board;

const int INF=INT_MAX/3;

int heuristic(Board &b, Board &goal){
	int S=0;
	for(int i=0;i<16;i++){
		if(b[i]!=0){
			for(int j=0;j<16;j++){
				if(b[i]==goal[j]){
					S=S+abs((i/4)-(j/4))+abs((i%4)-(j%4));
					break;
				}
			}
		}
	}
	return S;
}

void Adj(Board &u, vector<Board> &adj){
	int zero;
	for(int i=0;i<16;i++){
		if(u[i]==0){zero=i;}
	}

	if(zero<12){
		Board v(16);
		v=u;
		swap(v[zero],v[zero+4]);
		adj.push_back(v);
	}
	if(zero>3){
		Board v(16);
		v=u;
		swap(v[zero],v[zero-4]);
		adj.push_back(v);
	}
	if(zero%4 == 0 || zero%4 == 1 || zero%4 == 2){
		Board  v(16);
		v=u;
		swap(v[zero],v[zero+1]);
		adj.push_back(v);
	}
	if(zero%4 == 1 || zero%4 == 2 ||zero%4 == 3){
		Board v(16);
		v=u;
		swap(v[zero],v[zero-1]);
		adj.push_back(v);
	}
}

bool DLS(Board &b, Board &goal, int limit,int depth){
	if(b == goal){
		return true;
	}
	if(depth+heuristic(b,goal)<=limit){
		vector<Board> adj;
		Adj(b,adj);
		for(int i=0;i<adj.size();i++){
			if(DLS(adj[i], goal, limit, depth+1)==true){
				return true;
			}
		}
	}
	return false;
}

int IDDFS(Board &init,Board &goal){
	for (int limit=1; ; limit++){
		bool found = DLS(init,goal,limit,0);
		if(found){
			return limit;
		}
	}
}

