void dfs(lli md,lli s,lli x,lli y){
    if(md+s > lim) return;
    if(m.find(f) != m.end()){
        if(m[f] > s) m[f] = s;
        else return;
    }else{
        m[f] = s;
    }
    if(s > lim/2) return;
    for(lli i = 0;i < 4;i++){
        if(isin(x+dx[i],y+dy[i])){
            swap(f[x+dx[i]][y+dy[i]],f[x][y]);
            dfs(md+m_dist(f[x][y],x,y)-m_dist(f[x][y],x+dx[i],y+dy[i]),s+1,x+dx[i],y+dy[i]);
            swap(f[x+dx[i]][y+dy[i]],f[x][y]);            
        }
    }
}

void dfs2(lli md,lli s,lli x,lli y){
    if(md+s > lim) return;
    if(w.find(g) != w.end()){
        if(w[g] > s) w[g] = s;
        else return;
    }else{
        w[g] = s;
    }
    if(m.find(g) != m.end()){
        ans = min(ans,s+m[g]);
