	}
};

signed main() {
	State s;
	int MDT[N*N][N*N];
	for ( int i = 0; i < N*N; i++ ) {
		for ( int j = 0; j < N*N; j++ ) {
			MDT[i][j] = abs(i/N-j/N) + abs(i%N-j%N);			
		}
	}
	s.pre = -1;
	s.cost = s.esti = 0;	
	for ( int i = 0; i < N*N; i++ ) {
		cin >> s.puz[i];
		if ( s.puz[i] == 0 ) {
			s.zero = i;
			s.puz[i] = N*N-1;			
		} else {
			s.puz[i]--;
		}

		s.esti += abs(i/N-s.puz[i]/N) + abs(i%N-s.puz[i]%N);		
	}
	//cout << s.esti << endl;
	map<Comp, bool> used;	
	priority_queue<State, vector<State>, greater<State> > Q;	
