            dfs(md+m_dist(f[x][y],x,y)-m_dist(f[x][y],x+dx[i],y+dy[i]),s+1,x+dx[i],y+dy[i]);
            swap(f[x+dx[i]][y+dy[i]],f[x][y]);            
        }
    }
}

void dfs2(lli md,lli s,lli x,lli y){
