    if(w.find(g) != w.end()){
        if(w[g] > s) w[g] = s;
        else return;
    }else{
        w[g] = s;
    }
    if(m.find(g) != m.end()){
        ans = min(ans,s+m[g]);
        flag = true;
    }
    if(s > lim/2) return;
    for(lli i = 0;i < 4;i++){
        if(isin(x+dx[i],y+dy[i])){
            swap(g[x+dx[i]][y+dy[i]],g[x][y]);
            dfs2(md+m_dist(g[x][y],x,y)-m_dist(g[x][y],x+dx[i],y+dy[i]),s+1,x+dx[i],y+dy[i]);
            swap(g[x+dx[i]][y+dy[i]],g[x][y]);            
        }
    }
}


