int estmd(){
	int ret=0;
	for(int i=0;i<4;i++)for(int j=0;j<4;j++){
		if(puz[i][j] == -1)continue;
		ret+=abs(puz[i][j]/4-i)+abs(puz[i][j]%4-j);
	}
