long long hash(const int *board)
{
    const static long long fact[]={1307674368000LL,87178291200LL,6227020800LL,479001600LL,39916800LL,3628800LL,362880LL,40320LL,5040LL,720LL,120LL,24LL,6LL,2LL,1LL};
    long long h=0;
    int work;
    for(int i=0; i<15; i++) {
        work=board[i];
        for(int j=0; j<i; j++) {
            if(board[j]<board[i]) --work;
        }
        h+=work*fact[i];
    }
    return h;
}

int search()
{
    while(!ol.empty()) {
        pair<int,state> temp=ol.top();
        ol.pop();
        int nowcost=temp.first;
        state now=temp.second;
        if(nowcost==now.first) return now.first;
        int h=hash(now.second);
        int hl=h&0xffff;
        int hn=h>>16;
        if(cl[hl].find(hn)!=cl[hl].end()) continue;
        cl[hl].insert(hn);

        int f;
        for(f=0; f<16&&now.second[f]; f++);

        for(int i=0; i<4; i++) {
            int ty=f/4+dy[i];
            int tx=f%4+dx[i];
            if(tx<0||3<tx||ty<0||3<ty) continue;
            int t=ty*4+tx;
            state next=now;
            next.first++;
            swap(next.second[f],next.second[t]);
            int h=hash(next.second);
            int hl=h&0xffff;
            int hn=h>>16;
            if(cl[hl].find(hn)!=cl[hl].end()) continue;
            int nextcost=nowcost+1-md[t][now.second[t]]+md[f][next.second[f]];
            ol.push(pair<int,state>(nextcost,next));
        }

    }
    return -1;
}

