bool CountMove(std::vector<TFifteenPuzzle>& NextTargets,
	          const TFifteenPuzzle& Goal,
	          std::set<TFifteenPuzzle>& History)
{
	if(std::find(NextTargets.begin(), NextTargets.end(), Goal) != NextTargets.end()) return true;
	std::vector<TFifteenPuzzle> NewTargets;
	for(std::vector<TFifteenPuzzle>::const_iterator It = NextTargets.begin(); It != NextTargets.end(); ++It){
		RenewTargets(*It, mpUp,    NewTargets, History);
		RenewTargets(*It, mpDown,  NewTargets, History);
		RenewTargets(*It, mpLeft,  NewTargets, History);
		RenewTargets(*It, mpRight, NewTargets, History);
	}
	NextTargets = NewTargets;
	return false;
}

int CountMinimumMove(const TFifteenPuzzle& Puzzle)
{
	std::vector<TFifteenPuzzle> Targets(1, Puzzle);
	std::set<TFifteenPuzzle> History;
	int Count = 0;
	TFifteenPuzzle Target;
	while(!CountMove(Targets, Target, History)) ++Count;
	return Count;
}

