    ll manhattan_distance(){
        ll sum = 0;
        FOR(y, 0, W){
            FOR(x, 0, W){
                ll v = A[y][x];
                ll tx, ty; // 最終的にいるべき場所
                // 0はMDに含めない
                if(v!=0){
                    v--;
                    tx = v%W;
                    ty = v/W;
                    ll dist = abs(x - tx) + abs(y - ty);
                    sum += dist;
                }
            }
        }
