// depth : 現在深度
bool dfs(ll depth, ll limit, Puzzle pz, Point prev){
    // of << endl << "depth " << depth << endl;
    // pz.print();

    // pn(depth);
    ll MD = pz.manhattan_distance();
    if(MD==0){
        return true;
    }

    // pruning
    if(depth+MD > limit) return false;

    auto sp = pz.get_space();

    // 解けてないなら4方向へ移動
    FOR(i, 0, 4){
        ll sx = sp.x;
        ll sy = sp.y;

        // target position
        ll tx = sx + dx[i];
        ll ty = sy + dy[i];

        auto cp = pz;

        // in range
        if(0<=tx && tx<W && 0<=ty && ty<W){
            swap(cp.A[sy][sx], cp.A[ty][tx]);

            bool is_new_destination = true;
            if(cp.get_space()==prev){
                is_new_destination = false;
            }

            if(is_new_destination && dfs(depth+1, limit, cp, sp)){
                return true;
            }
        }
    }
    return false;
}


