const int N = 4;
using mat = vector<vector<int> >;

mat goal;
int calcCost(mat &pos){
  static int idxX[N * N], idxY[N * N], init = 1;
  if(init){
    init = 0;
    for(int i=0;i<N;i++)
      for(int j=0;j<N;j++) idxX[goal[i][j]] = j, idxY[goal[i][j]] = i;
  }

  int res = 0;  
  for(int i=0;i<N;i++)
    for(int j=0;j<N;j++){
      if(pos[i][j] == 0) continue;
      res += abs(i - idxY[pos[i][j]]) + abs(j - idxX[pos[i][j]]);
    }
  return res;
}


int dfs(mat &pos, int y, int x, int pre, int limit){
  if(calcCost(pos) == 0) return 1;
  if(limit - calcCost(pos) < 0) return 0;

  const int dx[] = {0, 1, 0, -1};
  const int dy[] = {-1, 0, 1, 0};
  for(int i=0;i<4;i++){
    int nx = x + dx[i];
    int ny = y + dy[i];
    if(nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
    if((i + 2) % 4 == pre) continue;
    swap(pos[y][x], pos[ny][nx]);
    if(dfs(pos, ny, nx, i, limit - 1)) return 1;
    swap(pos[y][x], pos[ny][nx]);
  }
  return 0;
}

