#include<bits/stdc++.h>
#define rep(i, n) for (int i = 0; i < (n); ++i) 
#define PI acos(-1)

using namespace std;
using ll = long long;
using P = pair<int, int>;
using LP = pair<ll, ll>;
using PZL = vector<vector<int>>;

#define bsize 4

int potential(PZL p) {
    int res = 0;
    rep(i, bsize) {
        rep(j, bsize) {
            int x = (p[i][j] - 1) % bsize;
            int y = (p[i][j] - 1) / bsize;
            if (p[i][j] == 0) continue;
            res += abs(j - x) + abs(i - y);
        }
    }
    return res;
}

ll encode(PZL p) {
    ll res = 0;
    ll base = 1;
    rep(i, bsize) {
        rep(j, bsize) {
            if (i == 0 && j == 0) continue;
            res += p[i][j] * base;
            base *= bsize * bsize;
        }
    }
    return res;
}

PZL decode(ll hash) {
    PZL p(bsize, vector<int>(bsize));
    vector<bool> num(bsize * bsize, false);
    rep(i, bsize) {
        rep(j, bsize) {
            if (i == 0 && j == 0) continue;
            p[i][j] = hash % (bsize * bsize);
            num[p[i][j]] = true;
            hash /= bsize * bsize;
        }
    }
    rep(i, bsize * bsize) {
        if (!num[i]) p[0][0] = i;
    }
    return p;
}

P findZero(ll hash) {
    rep(i, bsize) {
        rep(j, bsize) {
            if (i == 0 && j == 0) continue;
            if (hash % (bsize * bsize) == 0) return P(i, j);
            hash /= bsize * bsize;
        }
    }
    return P(0, 0);
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    PZL puzzle(bsize, vector<int>(bsize)); 
    PZL ans(bsize, vector<int>(bsize));
    rep(i, bsize) {
        rep(j, bsize) {
            cin>>puzzle[i][j];
            ans[i][j] = i * bsize + j + 1;
        }
    }
    ans[bsize - 1][bsize - 1] = 0;
    ll ahash = encode(ans);

    vector<P> direc {P(1, 0), P(-1, 0), P(0, 1), P(0, -1)};
    priority_queue<pair<P, ll>, vector<pair<P, ll>>, greater<pair<P, ll>>> q;
    set<ll> visited;
    q.push(pair<P, ll>(P(potential(puzzle), 0), encode(puzzle)));

    int res = 0;
    while (!q.empty()) {
        pair<P, ll> p = q.top(); q.pop();
        ll hash = p.second;
        int w = p.first.second;

        if (hash == ahash) {
            res = w;
            break;
        }

        if (visited.find(hash) != visited.end()) continue;
        visited.insert(hash);

        if (p.first.first > 45) continue;
        PZL pzl = decode(hash);
        P z;
        rep(i, bsize) {
            rep(j, bsize) {
                if (pzl[i][j] == 0) z = P(i, j);
            }
        }
        for (auto d : direc) {
            int ni = z.first + d.first;
            int nj = z.second + d.second;
            if (ni < 0 || ni >= bsize || nj < 0 || nj >= bsize) continue;
            swap(pzl[z.first][z.second], pzl[ni][nj]);
            q.push(pair<P, ll>(P(w + 1 + potential(pzl), w + 1), encode(pzl)));
            swap(pzl[z.first][z.second], pzl[ni][nj]);
        }
    }
    cout<<res<<endl;
}

