			{
				result = create(side, new_data, p->steps[side] + 1, p->f[side] + dif_f, hash_table, heap, &n);
			}
			catch (...)
			{
				return 1;
			}
			if (result != 0) {
				break;
			}
		}
		if (zero_index < 12) {
			new_data = move_down(p->data, zero_index, &dif_f, goal[side]);
			try
			{
				result = create(side, new_data, p->steps[side] + 1, p->f[side] + dif_f, hash_table, heap, &n);
			}
			catch (...)
			{
				return 1;
			}
			if (result != 0) {
				break;
