int getAllMD(Puzzle pz) {
	int sum = 0;
	rep(i, 0, N2) {
		if(pz.f[i] == N2) continue;
		sum += MDT[i][pz.f[i] - 1];
	}
	return sum;
}
bool isSolved() {
