#include<iostream>
#include<string>
#include<queue>
#include<set>

using namespace std;

const int N=4;
const int N2=16;

const int dx[4]={-1,0,1,0};
const int dy[4]={0,-1,0,1};

int MDT[N2][N2];

class puzzle
{
public:
	int f[N2];
	int space;
	int MD;
	int cost;

	bool operator<(const puzzle &p)const
	{
		for(int i=0;i<N2;i++)
		{
			if(f[i]==p.f[i])continue;
			return f[i]<p.f[i];
		}
		return false;
	}
};

class state
{
public:
	puzzle p;
	int est;//estimated
	bool operator<(const state &s)const
	{
		return est>s.est;
	}
};

int getallMD(puzzle p)
{
	int sum=0;
	for(int i=0;i<N2;i++)
	{
		if(p.f[i]==N2)continue;
		sum+=MDT[i][p.f[i]-1];
	}
	return sum;
}

int encode(puzzle s)
{
	int cur=0,enc=0;
	for(int i=0;i<N2;i++)
	{
		if(s.f[i]==N2)
		{
			s.f[i]=0;
			break;
		}
	}
	for(int i=0;i<N2-1;i++)
	{
		cur=s.f[i];
		for(int j=i+1;j<N2;j++)
		{
			if(cur<s.f[j])s.f[j]--;
		}
		(enc+=s.f[i])*=N2-1-i;
	}
	return enc;
}

int astar(puzzle s)
{
	priority_queue<state>PQ;
	s.MD=getallMD(s);
	s.cost=0;
	set<int>V;
	puzzle u,v;
	state initial;
	initial.p=s;
	initial.est=s.MD;;
	PQ.push(initial);

	while(!PQ.empty())
	{
		state st=PQ.top();PQ.pop();
		u=st.p;
		if(u.MD==0)return u.cost;
		V.insert(encode(u));
		int sx=u.space/N;
		int sy=u.space%N;

		for(int r=0;r<4;r++)
		{
			int tx=sx+dx[r];
			int ty=sy+dy[r];
			if(tx<0||tx>=N||ty<0||ty>=N)continue;
			v=u;
			v.MD-=MDT[tx*N+ty][v.f[tx*N+ty]-1];
			v.MD+=MDT[sx*N+sy][v.f[tx*N+ty]-1];
			swap(v.f[sx*N+sy],v.f[tx*N+ty]);
			v.space=tx*N+ty;
			if(!V.count(encode(v)))
			{
				v.cost++;
				state news;
				news.p=v;
				news.est=v.cost+v.MD;
				PQ.push(news);
			}
		}
	}

	return -1;
}

int main()
{
	for(int i=0;i<N2;i++)
	{
		for(int j=0;j<N2;j++)
		{
			MDT[i][j]=abs(i/N-j/N)+abs(i%N-j%N);
		}
	}

	puzzle in;

	for(int i=0;i<N2;i++)
	{
		cin>>in.f[i];
		if(in.f[i]==0)
		{
			in.f[i]=N2;
			in.space=i;
		}
	}

	cout<<astar(in)<<endl;

	return 0;
}

#include<iostream>
#include<map>
#include<array>

struct Board {
	std::array<int, 16> arrange{};
	int zero_pos;
};

int search(Board, int, int);
bool is_destination(Board);

int move_direction[4] = { 1, -1, 4, -4 };
std::map<std::array<int, 16>, int> dp;

int main()
{
	Board board;
	for (int i = 0; i < 16; ++i)
	{
		std::cin >> board.arrange[i];
		if (!board.arrange[i])
			board.zero_pos = i;
	}

	std::cout << search(board, 45, 0) << std::endl;

	return 0;
}

int search(Board board, int min, int depth)
{
	if (dp.find(board.arrange) != dp.end()) return dp[board.arrange];
	if (is_destination(board)) return 0;
	if (min == 0) return 45;

	bool move_condi[4] = {
		board.zero_pos % 4 != 3, board.zero_pos % 4 != 0,
		board.zero_pos / 4 != 3, board.zero_pos / 4 != 0
	};
	for (int condi_i = 0; condi_i < 4; ++condi_i)
	{
		if (!move_condi[condi_i]) continue;

		int next_zero_pos = board.zero_pos + move_direction[condi_i];
		Board next_board = board;
		next_board.arrange[board.zero_pos] = next_board.arrange[next_zero_pos];
		next_board.arrange[next_zero_pos] = 0;
		next_board.zero_pos = next_zero_pos;

		int min_tmp = search(next_board, min - 1, depth + 1) + 1;
		if (min_tmp < min)
			min = min_tmp;
	}
	dp[board.arrange] = min;
	return min;
}

bool is_destination(Board board)
{
	for (int i = 0; i < 15; ++i)
		if (board.arrange[i] != i + 1) return false;
	if (board.arrange[15] != 0) return false;

	return true;
}

#include <iostream>
#include <stack>
#include <cstdlib>
#include <vector>
#define N 4
#define N2 16
#define MAX_DEPTH 45 
using namespace std;

class game{
  public:
  int board[N2];
  int w;
  int last_move;
  int depth;
  int mnh;
};
game start;

vector<int> move_list[N2];
int dist[N2][N2];

void print(game &g){
  for(int i=0;i<N2;i++){
    printf(" %d",g.board[i]);
  }
  cout<<" mnh: "<<g.mnh<<endl;
}


bool dfs(int depth){
  stack<game> s;
  s.push(start);

  game g;
  while(!s.empty()){
    g=s.top();s.pop();
    if(g.mnh==0) return true;
    if(g.depth==depth) continue;
    if(g.depth+g.mnh>depth) continue;

    for(int move:move_list[g.w]){
      if(g.last_move==-move) continue;
      game h=g;
      int to=h.w+move;
      h.mnh -= dist[to][h.board[to]-1];
      h.mnh += dist[h.w][h.board[to]-1];
      swap(h.board[h.w],h.board[to]);
      h.w = to;
      h.depth++;
      h.last_move=move;
      s.push(h);
    }
  }
  return false;
}

void initialize(){
  for(int i=0;i<N2;i++){
    if(i%N<N-1) move_list[i].push_back(1);
    if(i%N>0  ) move_list[i].push_back(-1);
    if(i/N<N-1) move_list[i].push_back(N);
    if(i/N>0  ) move_list[i].push_back(-N);
  }

  //i=board,j=piece-1
  for(int i=0;i<N2;i++){
    for(int j=0;j<N2;j++){
      dist[i][j] = abs(j%N-i%N) + abs(j/N-i/N);
    }
  }

  start.mnh=0;
  for(int i=0;i<N2;i++){
    if(i==start.w) continue;
    start.mnh += dist[i][start.board[i]-1];
  }
}

int solve(){
  initialize();
  for(int i=start.mnh;i<=MAX_DEPTH;i++){
    if(dfs(i)){
      return i;
    }
  }
  return -1;
}

int main(){
  for(int i=0;i<N2;i++){
    int tmp; cin>>tmp;
    if(tmp==0){
      start.board[i]=N2;
      start.w=i;
    }else{
      start.board[i]=tmp;
    }
  }
  start.depth=0;
  start.last_move=0;

  cout<<solve()<<endl;
}

#include<iostream>
