using namespace std;

constexpr int n = 4;
const int n2 = n*n;

struct Puzzle{
public:
  int f[n2], space, tile;
  int cost;

  bool operator < (const Puzzle& p) const{
    for(int i=0; i<n2; i++){
      if(f[i] == p.f[i]) continue;
      return f[i] < p.f[i];
    }

    return false;
  }

  void setWrongTiles(){
    int sum = 0;
    for(int i=0; i<n2; i++){
      if(f[i] == n2) continue;
      if(f[i]-1 != i) sum++;
    }
    tile = sum;
  }
};

struct State{
public:
  vector<State> solve;
  Puzzle puzzle;
  int estimated;

  void print(){
    for(int i=0; i<n2; i++){
      cout << ((puzzle.f[i] == n2)? 0: puzzle.f[i]) << " ";
      if(i%n == n-1) cout << endl;
    }
  }

  bool operator < (const State& s) const{
    return estimated < s.estimated;
  }

  bool operator > (const State& s) const{
    return estimated > s.estimated;
  }
};

constexpr int dx[] = {-1, 0, 1, 0}, dy[] = {0, -1, 0, 1};

int dfs(int cnt, State s){
  if(cnt == 0){
    if(s.puzzle.tile == 0) return s.puzzle.cost;
    else return -1;
  }

  int sx = s.puzzle.space / n, sy = s.puzzle.space % n;

  for(int i=0; i<4; i++){
    int nx = sx + dx[i], ny = sy + dy[i];
    if(nx < 0 || nx >= n || ny < 0 || ny >= n) continue;

    Puzzle np = s.puzzle;
    swap(np.f[nx * n + ny], np.f[sx * n + sy]);
    np.cost++;
    np.space = nx * n + ny;
    np.setWrongTiles();

    State next;
    next.puzzle = np;
    next.estimated = np.tile;

    if(next.estimated > cnt) continue;

    int tmp = dfs(cnt-1, next);
    if(tmp != -1) return tmp;
  }
  return -1;
}

int IDA(Puzzle in){
  constexpr int MAX = 100;
  in.setWrongTiles();

  State s;
  s.puzzle = in;
  s.puzzle.cost = 0;
  s.estimated = in.tile;

  for(int i=s.estimated; i<=MAX; i++){
    int ans = dfs(i, s);
    if(ans != -1){
      return ans;
    }
  }
  return -1;
}

int main(){
  Puzzle in;
  for(int i=0; i<n2; i++){
    cin >> in.f[i];
    if(in.f[i] == 0){
      in.space = i;
      in.f[i] = n2;
    }
  }

  cout << IDA(in) << endl;

  return 0;
}

