    Board board;

    for (int32_t r = 0; r < N; r++) {
        for (int32_t c = 0; c < N; c++) {
            int32_t v;
            cin >> v;
            board.set(r, c, v);
        }
    }

    int32_t limit = 0;

    while (!dfs(board, board, 0, manhattan(board), limit)) limit++;

    return 0;
}

