const int LIMIT = 45;
const int mx[4] = {0,-1,0,1};
const int my[4] = {-1,0,1,0};

struct Puzzle {
    int p[N2], h, d;
};

Puzzle ans;
int limit, md[N2][N2];

bool visit(Puzzle a,int prev) {
    if(a.h==0) {
        ans = a;
        return true;
    }
    if(a.d + a.h > limit) return false;
    int blank; Puzzle b;
    for(int i=0; i<N2; i++) {
        if(a.p[i]==0) blank=i;
    }
    int bx = blank%N, by = blank/N;

    for(int i=0; i<4; i++) {
        int x=bx+mx[i],y=by+my[i];
        if(x<0 || x>=N || y<0 || y>=N) continue;
        if(abs(prev-i) == 2) continue;
        b = a;
        b.h += md[blank][b.p[y*N+x]-1] - md[y*N+x][b.p[y*N+x]-1];
        swap(b.p[blank],b.p[y*N+x]);
        b.d++;
        if(visit(b,i)) return true;
    }
    return false;
}

void IDA(Puzzle init) {
