class board{
public:
    int moves;
    int wrongs;
    int zero_place;
    int cost;
    char pre;
    vector<int> tiles;

    explicit board(vector<int> num, int move, char pr){
        wrongs = 0;
        tiles = num;
        REP(i, 16){
            if(num[i] == 0)
                zero_place = i;
            else
                wrongs += dist[num[i]][(answer[i] + 15)%16];
        }
        moves = move;
        cost = wrongs + moves;
        pre = pr;
    }

    void board_to_int(char p){
        ll k = 0;
        REP(i, 11)
            k += (tiles[i+5] * pow(16, i));
        for(int i = searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]].size(); i > 0 ; i--)
            if(k == searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]][i-1])
                return;
        pq.push(board(tiles, moves+1, p));
        searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]].push_back(k);
        return;
    }

    void move() {
        if(dir[zero_place][0] && pre != 'l'){
            swap(tiles[zero_place], tiles[zero_place-1]);
            board_to_int('r');
            swap(tiles[zero_place], tiles[zero_place-1]);
        }
