int solve(Status status){
    priority_queue< pair<int, Status>, vector< pair<int, Status> >, greater< pair<int, Status> > > pq;
    map<Board, int> b2s;

    pq.emplace(0 + status.get_mhd(), status);
    b2s[status.get_board()] = 0;
    while (not pq.empty()){
//        cout << pq.size() << ' ' << b2s.size() << endl;
        int p;
        Status st;
        tie(p, st) = pq.top();
        pq.pop();
//        if (st.get_mhd() == 0){
//            return p;
//        }
        int steps = p - st.get_mhd();
        auto bd = st.get_board();
        if (b2s[bd] < steps) continue;
        for (auto d : {Direction::Left, Direction::Right, Direction::Up, Direction::Down}){
            Status new_st{st};
            if (new_st.slide(d)){
                int new_p = steps + 1 + new_st.get_mhd();
                if (new_p > DEPTH_LIMIT) continue;
                auto new_bd = new_st.get_board();
                auto it = b2s.find(new_bd);
                if (it == b2s.end() or it->second > steps + 1){
                    b2s[new_bd] = steps + 1;
                    pq.emplace(new_p, new_st);
                    if (new_st.get_mhd() == 0) return new_p;
                }
            }
        }
    }
    return -1;
}

int calc_MHD(Board & board){
    // Calculates the sum of Manhattan distances
    // from current position to goal position 
    // for all panels except blank (=0) panel. 
    int mhdist = 0;
    int src = 0;
    for (auto dst : board){
        if (dst == 0){
            ++src;
            continue;
        }
        dst = (dst + WH - 1) % WH;
        int drow = abs(src / W - dst / W);
        int dcol = abs(src % W - dst % W);
        mhdist += drow + dcol;
        ++src;
    }
    return mhdist;
}


Position find_blank(Board & board){
    // Find a blank (=0) panel on a board with width=W and height=H
    // and return its position (row, col).
    for(int i = 0; i != WH; ++i){
        if (board[i]) continue;
        return {i / W, i % W};
    }
}


