const int dx[] = {1, 0, -1, 0}, dy[] = {0, 1, 0, -1};

struct S {
	vi f;
	int x, y, cnt;
};

int check(S s) {
	int res = 0;
	if(s.x % 4 != 3) res |= 0b1000;
	if(s.y % 4 != 3) res |= 0b0100;
	if(s.x % 4 != 0) res |= 0b0010;
	if(s.y % 4 != 0) res |= 0b0001;
	return res;
}

S next(vi f, int x, int y, int cnt, int num) {
	if(num == 1) {
		swap(f[4*y+x], f[4*y+x+1]);
		x++;
		return S{f, x, y, cnt+1};
	}
	if(num == 2) {
		swap(f[4*y+x], f[4*(y+1)+x]);
		y++;
		return S{f, x, y, cnt+1};
	}
	if(num == 3) {
		swap(f[4*y+x], f[4*y+x-1]);
		x--;
		return S{f, x, y, cnt+1};
	}
	if(num == 4) {
		swap(f[4*y+x], f[4*(y-1)+x]);
		y--;
		return S{f, x, y, cnt+1};
	}
	return S();
}


