			s.x = i%4;
			s.y = i/4;
		}
	}

	queue<S> q;
	q.push(s);
	set<vi> memo;

	while(q.size()) {
		s = q.front(); q.pop(); 
		if(s.f == ans) break;

		int chk = check(s);
		if(chk >> 3 & 1) {
			S _s = next(s.f, s.x, s.y, s.cnt, 1);
			if(!memo.count(_s.f)) {
				memo.insert(_s.f);
				q.push(_s);
			}
		}
		if(chk >> 2 & 1) {
			S _s = next(s.f, s.x, s.y, s.cnt, 2);
			if(!memo.count(_s.f)) {
				memo.insert(_s.f);
				q.push(_s);
			}
		}
		if(chk >> 1 & 1) {
			S _s = next(s.f, s.x, s.y, s.cnt, 3);
			if(!memo.count(_s.f)) {
				memo.insert(_s.f);
				q.push(_s);
			}
		}
		if(chk & 1) {
			S _s = next(s.f, s.x, s.y, s.cnt, 4);
			if(!memo.count(_s.f)) {
				memo.insert(_s.f);
				q.push(_s);
			}
		}
	}

	cout << s.cnt << endl;
	return 0;
}

