string a,ans;
struct Pt{
    string s;
    int lo;
};
queue<Pt> q;
queue<int> d;
const int dx[]={-4,-1,1,4};
set<string> u;

int bfs(Pt f){
    d.push(0);
    q.push(f);

    while(!q.empty()){
        Pt wd=q.front();
        int step=d.front();
        string ns=wd.s;
        int nlo=wd.lo;

        if( ns==ans ){
            return step;
        }
        for(int i=0;i<4;i++){
            int nx=nlo+dx[i];
            if(nlo==0||nlo==4||nlo==8||nlo==12){
                if(i==1) continue;
            }
            if(nlo==3||nlo==7||nlo==11||nlo==15){
                if(i==2) continue;
            }
            if( nx>=0&&nx<16 ){
                swap(ns[nx],ns[nlo]);
                if(!u.count(ns)){
                    Pt r;
                    r.lo=nx;
                    r.s=ns;
                    q.push(r);
                    d.push(step+1);
                    u.insert(ns);
                }
                swap(ns[nx],ns[nlo]);
            }
        }
        q.pop();
        d.pop();
    }
}

