			if (0 <= e && e < 16 && (e & 3) - (z & 3) == dx) {
				ull w = v;
				w -= ((1ULL * g) << (e << 2));
				w += ((1ULL * g) << (z << 2));
				if (w == goal) return a.dist + 1;
				que.push(state{ w, a.dist + 1 });
			}
		}
	}
	return -1;
}
