			return f[i] < p.f[i];
		}
		return false;
	}
};

struct state {
	puzzle p;
	int score;
	bool operator >( const state s ) const
	{
		return score > s.score;
	}
};

int MDT[N2][N2];

int getSum( puzzle x )
{
	int sum = 0;
	for( int i = 0; i < N2; i++ ) {
		if( x.f[i] == N2 ) continue;
		sum += MDT[i][x.f[i] - 1];
	}
	return sum;
}

int main()
{
	puzzle sp;
	for( int i = 0; i < N2; i++ ) {
		cin >> sp.f[i];
		if( sp.f[i] == 0 ) {
			sp.space = i;
			sp.f[i] = N2;
		}
	}

	for( int i = 0; i < N2; i++ ) {
		for( int j = 0; j < N2; j++ ) {
			MDT[i][j] = abs( i / N - j / N ) + abs( i % N - j % N );
		}
	}
	state s;
	sp.MD = getSum( sp );
	s.p = sp;
	s.score = sp.MD;
	int dirh[] = { 0, 0, -1, 1 };
	int dirv[] = { -1, 1, 0, 0 };
	priority_queue<state, vector<state>, greater<state> > que;
	map<puzzle, int> m;
	que.push( s );
	int ans = 0;
	while( !que.empty() ) {
		state ts = que.top();
		que.pop();
		puzzle tp = ts.p;
		if( tp.MD == 0 ) {
			ans = tp.depth;
			break;
		}
		m[tp] = 1;
		int sy = tp.space / N;
		int sx = tp.space % N;
		for( int i = 0; i < 4; i++ ) {
			int nx = sx + dirh[i];
			int ny = sy + dirv[i];
			if( nx < 0 || N <= nx || ny < 0 || N <= ny ) continue;
			int ni = ny * N + nx;
			puzzle v = tp;
			v.MD -= MDT[ni][v.f[ni] - 1];
			v.MD += MDT[tp.space][v.f[ni] - 1];
			swap( v.f[ni], v.f[v.space] );
			v.space = ni;
			if( m.find( v ) == m.end() ) {
				v.depth++;
				state news;
				news.p = v;
				news.score = v.MD + v.depth;
				que.push( news );
			}
		}
	}

	cout << ans << endl;
}

