}st_move;

// パネルの移動座標を保持する配列
st_move move_p[] = { {-1, 0},   // 上
                     {0, -1},   // 左
                     {0, 1},    // 右
                     {1, 0}     // 下
                    };

// パネルの移動状態を表現する列挙型
