// パネルの並びの情報を持つクラス
class Board
{
    public:
        // パネルの並びを保持する配列
        int panel[PANEL_NUM];
        // ゼロのパネルの位置
        int zeroPos;
        // ゴールに到達するまでに必要なコスト
        int cost;
        // 並び替えた回数
        int moveCount;

        // コンストラクタ
        Board(int board[], int mCount)
        {
            for(int i = 0; i < PANEL_NUM; i++)
            {
                panel[i] = board[i];
            }

            zeroPos = searchZeroPos();
            cost = calcMoveDistance();

            moveCount = mCount;
        }

        // 演算子のオーバーロード ( sort()で使用 )
        bool operator < ( const Board &e ) const
        {
            // costをキーにして並べ替える
            return cost < e.cost;
        }

        // 配列中のゼロの位置を探索する関数
        int searchZeroPos()
        {
            for(int i = 0; i < PANEL_NUM; i++)
            {
                if( panel[i] == 0 )
                {
                    return i;
                }
            }

            return -1;
        }

        // ゴールに到達したかを判定する関数
        bool reachGoal()
        {
            for(int i = 0; i < PANEL_NUM; i++)
            {
                if( panel[i] != ary_Target[i] )
                {
                    return false;
                }
            }

            return true;
        }

        // パネルの並びから, 正解までに必要な移動距離を求める
        int calcMoveDistance()
        {
            int num = 0;
            int distance = 0;

            for(int i = 0; i < PANEL_NUM; i++)
            {
                num = panel[i];

                // 最短の移動距離の和を求める
                distance += moveDistance[num][i];
            }

            return distance;
        }

        // パネルの配列の要素の比較を実施する
        bool panelCompare(int compPanel[])
        {
            for(int i = 0; i < PANEL_NUM; i++)
            {
                if( panel[i] != compPanel[i ] )
                {
                    return false;
                }
            }

            return true;
        }
};

// 移動したパネルの状態を保持するvector
vector<Board> v_board;

// 検索したパネルを保持するvector
vector<Board> v_history;

// 最小移動回数を保持する変数
int minMoveCount;

void panelMoveOperation();
int calcArrayNum(int x, int y);

// メイン関数
int main(void)
{
    int ary_panel[PANEL_NUM];

    minMoveCount = 0;

    // 初期状態を設定する
    for(int i = 0; i < PANEL_NUM; i++)
    {
        cin >> ary_panel[i];
    }

    // 初期設定
    Board Bad = Board(ary_panel, 0);

    v_board.push_back(Bad);
    v_history.push_back(Bad);

    panelMoveOperation();

    // 結果の表示
    cout << minMoveCount << endl;

    return 0;
}

// x, y 座標から配列の要素数へ変換する関数
int calcArrayNum(int x, int y)
{
    return 4 * x + y;
}

// パネルの移動操作を実施する関数
void panelMoveOperation(void)
{
    // 要素の並び替えを実施する
    sort(v_board.begin(), v_board.end());

    // コストの一番小さい, 先頭要素を取り出す
    Board Bad = Board(v_board[0].panel, v_board[0].moveCount);
    // 全要素を削除する
    v_board.erase(v_board.begin(), v_board.end());

    // 並び替えた状態がゴールに到達しているかを確認する
    if( Bad.reachGoal() == true )
    {
        // 検索終了
        minMoveCount = Bad.moveCount;
        return;
    }

    int x, y;

    // ゼロの位置を x, y 座標に変換する
    x = Bad.zeroPos / 4;
    y = Bad.zeroPos % 4;

    // 上下左右にパネルを移動させる
    for(int i = 0; i < MOVE_LAST; i++)
    {

        int tx, ty;
        bool searchFlag;

        // 移動後の座標を計算する
        tx = x + move_p[i].x;
        ty = y + move_p[i].y;

        if( ( 0 <= tx && tx <= 3 ) && ( 0 <= ty && ty <= 3 ) )
        {
            searchFlag = true;

            // 移動用の新しい実体を作成する
            Board newBoard = Board(Bad.panel, Bad.moveCount);

            int moveNum, movePos;

            // 座標から配列の要素No.へ変換する
            movePos = calcArrayNum(tx, ty);
            // 移動するパネルNo.を取得する
            moveNum = newBoard.panel[movePos];

            // パネルを入れ替える
            swap(newBoard.panel[Bad.zeroPos], newBoard.panel[movePos]);
            newBoard.moveCount++;

            for(int num = 0; num < v_history.size(); num++)
            {
                if( v_history[num].panelCompare(newBoard.panel) == true )
                {
                    searchFlag = false;
                    break;
                }
            }

            if( searchFlag == true )
            {
                // コストの再計算を実施する
                newBoard.cost = newBoard.cost - moveDistance[moveNum][movePos] + moveDistance[moveNum][newBoard.zeroPos];

                // 新しい盤面を vector に追加する
                v_board.push_back(newBoard);
                v_history.push_back(newBoard);

            }
        }
    }

    // 再帰呼び出しを実施
    panelMoveOperation();

    return;
}

