#include <iostream>
#include <cstdio>
#include <vector>
using namespace std;

#define RC2P(r,c) (((r)<<2)+(c))	//r*4+c
#define P2R(p) ((p)>>2)				//p/4
#define P2C(p) ((p)&3)				//p%4
#define HASHMAX 1000003

typedef unsigned long long int Pkey;

struct Pandt{
	Pkey p;
	int t;
};

Pkey fact(int a);
int dist(Pkey x);
int abs(int x);
void insert(vector<Pkey> &A, Pkey v);
Pkey extract(vector<Pkey> &A);
Pkey PtoI(vector<int> p);
vector<int> ItoP(Pkey ii);
int SolvePuzzle(vector<int> P);


vector< Pandt > Puzzles(HASHMAX);

int h1(Pkey key){ return key % HASHMAX; }
int h2(Pkey key){ return (key % (HASHMAX - 1)) + 1; }
int HashFind(Pkey key);
int HashInsert(Pkey key, int val);


int SearchPuzzle(Pkey x);

void InitHash(){
	Pandt Nullpandt;
	Nullpandt.p = 0;
	Nullpandt.t = -1;
	for (int i = 0; i < HASHMAX; i++){
		Puzzles[i] = Nullpandt;
	}
}

int HashFind(Pkey key){

	int curhash = h1(key);
	int sechash = h2(key);
	for (int i = 0; i < HASHMAX; i++){
		if (Puzzles[curhash].p == key && Puzzles[curhash].t != -1){
			return Puzzles[curhash].t;
		}
		else if (Puzzles[curhash].t == -1){
			return -1;
		}
		else{
			curhash = (curhash + sechash) % HASHMAX;
		}
	}
	return -1;
}

int HashInsert(Pkey key, int val){

	int curhash = h1(key);
	int sechash = h2(key);
	for (int i = 0; i < HASHMAX; i++){
		if (Puzzles[curhash].t == -1){
			Puzzles[curhash].t = val;
			Puzzles[curhash].p = key;
			return curhash;
		}
		else{
			curhash = (curhash + sechash) % HASHMAX;
		}
	}
	return -1;
}

void swap(int &a, int &b){
	int tmp = a;
	a = b;
	b = tmp;
	return;
}

Pkey fact(int a){
	Pkey b = 1;
	for (int i = 2; i <= a; i++){
		b = b * i;
	}
	return b;
}

Pkey multiab(Pkey a, int b){
	Pkey result = 0;
	for (int i = 0; i < b; i++){
		result += a;
	}
	return result;
}

int divab(Pkey a, Pkey b){
	int result = 0;
	while(a >= b){
		a -= b;
		result++;
	}
	return result;
}

int dist(Pkey x){
	std::vector<int> P = ItoP(x);
	int result = 0;
	for (int i = 0; i < 16; i++){
		if (P[i] == 0) continue;
		result += abs(P2C(P[i] - 1) - P2C(i)) + abs(P2R(P[i] - 1) - P2R(i));
	}
	int s = SearchPuzzle(x);
	return -result - (s == -1 ? 1048576 : Puzzles[s].t);
}

int abs(int x){
	return x < 0 ? -x : x;
}

void insert(vector< Pkey > &A, Pkey v){
	int n = A.size();
	A.push_back(v);
	while (n != 0){
		int i = (n - 1) >> 1;
		if (dist(A[n]) > dist(A[i])){
			Pkey tmp = A[n];
			A[n] = A[i];
			A[i] = tmp;
		}
		n = i;
	}
	return;
}

Pkey extract(vector< Pkey > &A){
	int n = A.size() - 1;
	Pkey res = A[0];
	A[0] = A[n];
	A.pop_back();

	for (int i = 0, j; 2 * i + 1 < n;){
		j = 2 * i + 1;
		if (j != n - 1 && dist(A[j]) < dist(A[j + 1])){
			j++;
		}
		if (dist(A[i]) < dist(A[j])){
			Pkey tmp = A[j];
			A[j] = A[i];
			A[i] = tmp;
		}
		i = j;
	}
	return res;
}


Pkey PtoI(vector<int> p){
	int x;
	Pkey result = 0;
	for (int i = 0; i < 15; i++){
		for (int j = 0; j < 16 - i; j++){
			if (p[j] == i){
				x = j;
				p.erase(p.begin() + j);
				break;
			}
		}
		result += multiab(fact(15-i), x);
	}
	return result;
}

vector<int> ItoP(Pkey ii){
	vector<int> result(16, -1);
	for (int i = 0; i < 16; i++){
		int index = divab(ii, fact(15 - i));
		ii -= multiab(fact(15 - i), index);
		int curindex = -1;
		int x = -1;
		for (int j = 0; j < 16; j++){
			if (result[j] == -1){
				curindex++;
			}
			if (curindex == index) {
				x = j;
				break;
			}
		}
		result[x] = i;
	}
	return result;
}

int SearchPuzzle(Pkey x){
	return HashFind(x);
}

int SolvePuzzle(vector<int> P){
	vector< Pkey > Que;
	HashInsert(PtoI(P), 0);
	insert(Que, PtoI(P));
	int answer = 10000;
	while (!Que.empty()){
		Pkey extp = extract(Que);
		int extt = HashFind(extp);
		vector<int> Q = ItoP(extp);
		int Cursor;
		bool isAligned = true;
		for (int i = 0; i < 16; i++){
			if (Q[i] != ((i + 1) & 15)){
				isAligned = false;
				break;
			}
		}
		if (isAligned){
			answer = extt;
			break;
		}
		for (int i = 0; i < 16; i++){
			if (Q[i] == 0){
				Cursor = i;
				break;
			}
		}
		if (extt >= 45) continue;
		vector<int> Qnext;
		int Qsearch;
		Pkey iQnext;
		if (Cursor >= 4){
			Qnext = Q;
			swap(Qnext[Cursor], Qnext[Cursor - 4]);
			iQnext = PtoI(Qnext);
			Qsearch = SearchPuzzle(iQnext);
			if (Qsearch == -1){
				HashInsert(iQnext, extt + 1);
				insert(Que, iQnext);
			}else if (Puzzles[Qsearch].t > extt + 1){
				Puzzles[Qsearch].t = extt + 1;
				insert(Que, iQnext);
			}
		}
		if (Cursor < 12){
			Qnext = Q;
			swap(Qnext[Cursor], Qnext[Cursor + 4]);
			iQnext = PtoI(Qnext);
			Qsearch = SearchPuzzle(iQnext);
			if (Qsearch == -1){
				HashInsert(iQnext, extt + 1);
				insert(Que, iQnext);
			}
			else if (Puzzles[Qsearch].t > extt + 1){
				Puzzles[Qsearch].t = extt + 1;
				insert(Que, iQnext);
			}
		}
		if (P2C(Cursor) != 0){
			Qnext = Q;
			swap(Qnext[Cursor], Qnext[Cursor - 1]);
			iQnext = PtoI(Qnext);
			Qsearch = SearchPuzzle(iQnext);
			if (Qsearch == -1){
				HashInsert(iQnext, extt + 1);
				insert(Que, iQnext);
			}
			else if (Puzzles[Qsearch].t > extt + 1){
				Puzzles[Qsearch].t = extt + 1;
				insert(Que, iQnext);
			}
		}
		if (P2C(Cursor) != 3){
			Qnext = Q;
			swap(Qnext[Cursor], Qnext[Cursor + 1]);
			iQnext = PtoI(Qnext);
			Qsearch = SearchPuzzle(iQnext);
			if (Qsearch == -1){
				HashInsert(iQnext, extt + 1);
				insert(Que, iQnext);
			}
			else if (Puzzles[Qsearch].t > extt + 1){
				Puzzles[Qsearch].t = extt + 1;
				insert(Que, iQnext);
			}
		}
	}

	return answer;
}

int main(){

	InitHash();

	int k;
	vector<int> P;
	for (int i = 0; i < 16; i++){
		scanf("%d", &k);
		P.push_back(k);
	}
	int n = SolvePuzzle(P);

	printf("%d\n", n);

	return 0;
}

