	{
		std::cin >> board.arrange[i];
		if (!board.arrange[i])
			board.zero_pos = i;
	}
	board.distance = 0;
	board.pre_dir = -1;
	std::cout << search(board) << std::endl;

	return 0;
}

int search(Board start)
{
	if (equal_goal(start.arrange)) return 0;

	std::vector<Board> queue;
	queue.push_back(start);

	int move_dir[4] = { -4, -1, 4, 1 };
	for (int queue_i = 0; ; ++queue_i)
	{
		int zero_pos = queue[queue_i].zero_pos;
		bool can_move[4] = {
			zero_pos / 4 != 0, zero_pos % 4 != 0,
			zero_pos / 4 != 3, zero_pos % 4 != 3
		};
		for (int dir_i = 0; dir_i < 4; ++dir_i)
		{
			if ((dir_i + 2) % 4 == queue[queue_i].pre_dir || !can_move[dir_i]) continue;

			Board board = queue[queue_i];
			int next_zero_pos = zero_pos + move_dir[dir_i];
			board.arrange[zero_pos] = board.arrange[next_zero_pos];
			board.arrange[next_zero_pos] = 0;
			board.zero_pos = next_zero_pos;
			board.distance++;
			board.pre_dir = dir_i;

			if (equal_goal(board.arrange)) return board.distance;
			queue.push_back(board);
		}
	}
	return -1;
}

bool equal_goal(std::array<int, 16> arrange)
{
	for (int i = 0; i < 15; ++i)
		if (arrange[i] != i + 1)
			return false;
	if (arrange[15] != 0)
		return false;

	return true;
}

