const int N = 4;
int dx[4] = {0, 1, 0, -1}, dy[4] = {-1, 0, 1, 0};

struct State {
	vector<int> puz;
	int zero;
	int cost;
	int esti;
	bool operator < (const State &s) const {
		return esti < s.esti;
	}
	bool operator > (const State &s) const {
		return esti  > s.esti;
	}
};

int main() {
	State s;
	s.cost = s.esti = 0;	
	s.puz = vector<int>(N*N);
	for ( int i = 0; i < N*N; i++ ) {
		cin >> s.puz[i];
		if ( s.puz[i] == 0 ) {
			s.zero = i;
			s.puz[i] = N*N-1;			
		} else {
			s.puz[i]--;
		}

		s.esti += abs(i/N-s.puz[i]/N) + abs(i%N-s.puz[i]%N);		
	}
	//cout << s.esti << endl;
	map<vector<int>, bool> used;
	priority_queue<State, vector<State>, greater<State> > Q;	
	Q.push(s);
	int cnt = 0;
	while ( !Q.empty() ) {	 			
		State p = Q.top(); Q.pop();

		//for ( int i = 0; i < N*N; i++ ) cout << s.puz[i] << " ";
		//cout << endl;
		// cout << p.cost << " " << p.esti << endl;			

		if ( p.esti-p.cost == 0 ) {
			cout << p.cost << endl;			
			return 0;
		}

		if ( used.count(p.puz) ) continue;
		used[p.puz] = true;

		for ( int i = 0; i < 4; i++ ) {
			int y = p.zero/N, x = p.zero%N;
			int ny = y+dy[i], nx = x+dx[i];
			if ( ny < 0 || nx < 0 || ny >= N || nx >= N ) continue;
			s = p;			
			int ch_id = ny*4+nx;
			int ch_dat = s.puz[ch_id];
			s.esti -= abs(y-(N-1)) + abs(x-(N-1));			
			s.esti -= abs(ny-ch_dat/N) + abs(nx-ch_dat%N);			
			s.esti += abs(y-ch_dat/N) + abs(x-ch_dat%4);			
			s.esti += abs(ny-(N-1)) + abs(nx-(N-1));				
			s.esti++;
			s.cost++;
			swap(s.puz[s.zero], s.puz[ch_id]);			
			s.zero = ch_id;
			Q.push(s);			
		}
		cnt++;

	}

	return 0;
}

