	int pos1[16], pos2[16];
	for (int i = 0; i < 16; i++)
	{
		pos1[s.puzzle[i]] = i;
		pos2[goal.puzzle[i]] = i;
	}
	for (int i = 0; i < 16; i++)
	{
		int manhattan = 0;
		manhattan += abs(pos1[i] / 4 - pos2[i] / 4);
		manhattan += abs(pos1[i] % 4 - pos2[i] % 4);
		eva += manhattan;
	}
	return eva;
}

int solve(State start)
{
	priority_queue<State, vector<State>, greater<State>> pq;

	pq.push(start);

	while (!pq.empty())
	{
		State ts = pq.top();
		pq.pop();

		if (checkedState == nullptr)
		{
			checkedState = new OwnNode(ts.puzzle);
		}
		else
		{
			checkedState->insert(ts.puzzle);
		}

		if (ts == goal)
		{
			return ts.depth;
		}

		int zeroi = -1;
		for (int i = 0; i < 16; i++)
		{
			if (ts.puzzle[i] == 0)
			{
				zeroi = i;
				break;
			}
		}

		if (zeroi <= 11)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi + 4];
			tts.puzzle[zeroi + 4] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (!checkedState->find(tts.puzzle))
			{
				pq.push(tts);
			}
		}
		if (zeroi % 4 != 3)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi + 1];
			tts.puzzle[zeroi + 1] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (!checkedState->find(tts.puzzle))
			{
				pq.push(tts);
			}
		}
		if (zeroi % 4 != 0)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi - 1];
			tts.puzzle[zeroi - 1] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (!checkedState->find(tts.puzzle))
			{
				pq.push(tts);
			}
		}
		if (4 <= zeroi)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi - 4];
			tts.puzzle[zeroi - 4] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (!checkedState->find(tts.puzzle))
			{
				pq.push(tts);
			}
		}
	}

	return -1;
}

