		v=u;
		swap(v[zero],v[zero-1]);
		adj.push_back(v);
	}
}

bool DLS(Board &b,Board &prev, int limit,int depth){
	if(b == goal){
		return true;
	}
	if(depth<=limit){
		vector<Board> adj;
		Adj(b,adj);
		for(int i=0;i<adj.size();i++){
			if(prev==adj[i]) continue;
			if(DLS(adj[i], b, limit, depth+1)==true){
				return true;
			}
		}
	}
	return false;
}

