    }
};

int getallmd(node a)
{
    int sum=0;
    for(int i=0; i<N; i++)
    {
        if(a.s[i] == N) continue;
        sum+=mp[i][a.s[i]-'0'-1];
    }
    return sum;
}

int check(node a)
{
    for(int i=0; i<N; i++)
        if(a.s[i]-'0'!=i+1) return 0;
    return 1;
}

void bfs(node a)
{
    node now,tmp;
    priority_queue<node>Q;
    a.cost=0;
    a.md=a.ans=getallmd(a);
    map<string,int>ms;
    ms[a.s]=1;
    Q.push(a);

    while(!Q.empty())
    {
        now=Q.top();
        Q.pop();
        if(check(now))
        {
            printf("%d\n",now.cost);
            return ;
        }
        int x=now.space/4;
        int y=now.space%4;
        for(int i=0; i<4; i++)
        {
            int tx=x+nx[i][0];
            int ty=y+nx[i][1];
            if(tx<0 || ty<0 || tx>=4 || ty>=4) continue;
            tmp=now;
            tmp.md-=mp[tx*4+ty][tmp.s[tx*4+ty]-'0'-1];
            tmp.md+=mp[x*4+y][tmp.s[tx*4+ty]-'0'-1];
            swap(tmp.s[x*4+y],tmp.s[tx*4+ty]);
            tmp.space=tx*4+ty;
            tmp.cost++;
            tmp.ans=tmp.cost+tmp.md;
            if(!ms[tmp.s])
                Q.push(tmp);
        }
    }
}

