struct State
{
	int puzzle[16];
	int depth;
	int evaluation;
	int prev;

	bool operator<(const State& s)const
	{
		return evaluation < s.evaluation;
	}

	bool operator>(const State& s)const
	{
		return evaluation > s.evaluation;
	}

	bool operator==(const State& s)const
	{
		for (int i = 0; i < 16; i++)
		{
			if (puzzle[i] != s.puzzle[i])
			{
				return false;
			}
		}
		return true;
	}
};

struct OwnNode
{
	int key[16];
	OwnNode* left;
	OwnNode* right;

	OwnNode():left(nullptr),right(nullptr){}
	OwnNode(int key[]) :OwnNode()
	{
		for (int i = 0; i < 16; i++)
		{
			this->key[i] = key[i];
		}
	}

	void insert(int nkey[])
	{
		int i = 0;
		for (; i < 16; i++)
		{
			if (key[i] != nkey[i])
			{
				break;
			}
		}
		if (i == 16)
		{
			return;
		}
		if (key[i]>nkey[i])
		{
			if (left == nullptr)
			{
				left = new OwnNode(nkey);
			}
			else
			{
				left->insert(nkey);
			}
		}
		else
		{
			if (right == nullptr)
			{
				right = new OwnNode(nkey);
			}
			else
			{
				right->insert(nkey);
			}
		}
	}

	bool find(int fkey[])
	{
		int i = 0;
		for (; i < 16; i++)
		{
			if (key[i] != fkey[i])
			{
				break;
			}
		}
		if (i == 16)
		{
			return true;
		}
		if (key[i]>fkey[i])
		{
			if (left == nullptr)
			{
				return false;
			}
			else
			{
				return left->find(fkey);
			}
		}
		else
		{
			if (right == nullptr)
			{
				return false;
			}
			else
			{
				return right->find(fkey);
			}
		}
	}

	void deleteAll()
	{
		if (left != nullptr)
		{
			left->deleteAll();
		}
		else
		{
			delete left;
			left = nullptr;
		}
		if (right != nullptr)
		{
			right->deleteAll();
		}
		else
		{
			delete right;
			right = nullptr;
		}
	}
};

State goal;
OwnNode* checkedState;

int heuristic(State& s)
{
	int eva = 0;
	int pos1[16], pos2[16];
	for (int i = 0; i < 16; i++)
	{
		pos1[s.puzzle[i]] = i;
		pos2[goal.puzzle[i]] = i;
	}
	for (int i = 0; i < 16; i++)
	{
		int manhattan = 0;
		manhattan += abs(pos1[i] / 4 - pos2[i] / 4);
		manhattan += abs(pos1[i] % 4 - pos2[i] % 4);
		eva += manhattan;
	}
	return eva;
}

int solve(State start, int limit)
{
	priority_queue<State, vector<State>, greater<State>> pq;

	pq.push(start);

	while (!pq.empty())
	{
		State ts = pq.top();
		pq.pop();

		if (checkedState == nullptr)
		{
			checkedState = new OwnNode(ts.puzzle);
		}
		else
		{
			checkedState->insert(ts.puzzle);
		}

		if (ts == goal)
		{
			return ts.depth;
		}

		int zeroi = -1;
		for (int i = 0; i < 16; i++)
		{
			if (ts.puzzle[i] == 0)
			{
				zeroi = i;
				break;
			}
		}

		if (ts.prev!=3&&zeroi <= 11)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi + 4];
			tts.puzzle[zeroi + 4] = t;
			tts.depth++;
			tts.prev = 0;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (!checkedState->find(tts.puzzle))
			{
				//checkedState->insert(tts.puzzle);
				pq.push(tts);
			}
		}
		if (ts.prev != 1 && zeroi % 4 != 3)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi + 1];
			tts.puzzle[zeroi + 1] = t;
			tts.depth++;
			tts.prev = 2;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (!checkedState->find(tts.puzzle))
			{
			//	checkedState->insert(tts.puzzle);
				pq.push(tts);
			}
		}
		if (ts.prev != 2 && zeroi % 4 != 0)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi - 1];
			tts.puzzle[zeroi - 1] = t;
			tts.depth++;
			tts.prev = 1;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (!checkedState->find(tts.puzzle))
			{
			//	checkedState->insert(tts.puzzle);
				pq.push(tts);
			}
		}
		if (ts.prev != 0 && 4 <= zeroi)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi - 4];
			tts.puzzle[zeroi - 4] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			tts.prev = 3;
			if (!checkedState->find(tts.puzzle))
			{
			//	checkedState->insert(tts.puzzle);
				pq.push(tts);
			}
		}
	}

	checkedState->deleteAll();
	delete checkedState;
	checkedState = nullptr;

	return solve(start, limit + 2);
}

