		if ( p.cost >= 45 ) continue;
		if ( p.esti >= 50 ) continue;

		//for ( int i = 0; i < N*N; i++ ) cout << s.puz[i] << " ";
		//cout << endl;
		// cout << p.cost << " " << p.esti << endl;			

		if ( p.esti-p.cost == 0 ) {
			cout << p.cost << endl;
			return 0;
		}		

		Comp c;
		for ( int i = 0; i < N*N; i++ ) c.puz[i] = p.puz[i];		
		if ( used.count(c) ) continue;		
		used[c] = p.cost;		

		for ( int i = 0; i < 4; i++ ) {
			int y = p.zero/N, x = p.zero%N;
			int ny = y+dy[i], nx = x+dx[i];
			if ( ny < 0 || nx < 0 || ny >= N || nx >= N ) continue;
			if ( s.pre == ny*4+nx ) continue;			
			s = p;			
			int ch_id = ny*4+nx;
			int ch_dat = s.puz[ch_id];		
			int dat_y = ch_dat/N;
			int dat_x = ch_dat%N;			
			swap(s.puz[s.zero], s.puz[ch_id]);
			Comp cc = c;
			swap(cc.puz[s.zero], cc.puz[ch_id]);			
			if ( used.count(cc) ) continue;			
			//s.esti -= abs(y-(N-1)) + abs(x-(N-1));			
			//s.esti -= abs(ny-dat_y) + abs(nx-dat_x);			
			//s.esti += abs(y-dat_y) + abs(x-dat_x);			
			//s.esti += abs(ny-(N-1)) + abs(nx-(N-1));
			s.esti -= MDT[p.zero][N*N-1];
			s.esti -= MDT[ny*N+nx][ch_dat];
			s.esti += MDT[p.zero][ch_dat];
			s.esti += MDT[ny*N+nx][N*N-1];			
			if ( s.esti-p.esti >= 3 ) continue;
			s.esti++;
			s.cost++;			
			s.pre = s.zero;
			s.zero = ch_id;
			Q.push(s);
		}			
	}

	return 0;
}

