#define max(a,b) (a)>(b)?(a):(b)

using namespace std;

typedef pair<int, int> pii;

struct State
{
	int puzzle[16];
	int depth;
	int evaluation;

	bool operator<(const State& s)const
	{
		return evaluation < s.evaluation;
	}

	bool operator>(const State& s)const
	{
		return evaluation > s.evaluation;
	}

	bool operator==(const State& s)const
	{
		for (int i = 0; i < 16; i++)
		{
			if (puzzle[i] != s.puzzle[i])
			{
				return false;
			}
		}
		return true;
	}
};

State goal;
vector<State> checkedState;

int heuristic(State s)
{
	int eva = 0;
	int pos1[16], pos2[16];
	for (int i = 0; i < 16; i++)
	{
		pos1[s.puzzle[i]] = i;
		pos2[goal.puzzle[i]] = i;
	}
	for (int i = 0; i < 16; i++)
	{
		int manhattan = 0;
		manhattan += abs(pos1[i] / 4 - pos2[i] / 4);
		manhattan += abs(pos1[i] % 4 - pos2[i] % 4);
		eva += manhattan;
	}
	return eva*2.5;
}

int solve(State start)
{
	priority_queue<State, vector<State>, greater<State>> pq;

	pq.push(start);

	while (!pq.empty())
	{
		State ts = pq.top();
		pq.pop();

		checkedState.push_back(ts);

		if (ts == goal)
		{
			return ts.depth;
		}

		int zeroi = -1;
		for (int i = 0; i < 16; i++)
		{
			if (ts.puzzle[i] == 0)
			{
				zeroi = i;
				break;
			}
		}

		if (zeroi <= 11)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi + 4];
			tts.puzzle[zeroi + 4] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (find(checkedState.begin(), checkedState.end(), tts) == checkedState.end())
			{
				pq.push(tts);
			}
		}
		if (zeroi % 4 != 3)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi + 1];
			tts.puzzle[zeroi + 1] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (find(checkedState.begin(), checkedState.end(), tts) == checkedState.end())
			{
				pq.push(tts);
			}
		}
		if (zeroi % 4 != 0)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi - 1];
			tts.puzzle[zeroi - 1] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (find(checkedState.begin(), checkedState.end(), tts) == checkedState.end())
			{
				pq.push(tts);
			}
		}
		if (4 <= zeroi)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi - 4];
			tts.puzzle[zeroi - 4] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (find(checkedState.begin(), checkedState.end(), tts) == checkedState.end())
			{
				pq.push(tts);
			}
		}
	}

	return -1;
}

int main()
{
	State start;

	goal.depth = 0;
	goal.evaluation = 0;
	for (int i = 0; i < 16; i++)
	{
		goal.puzzle[i] = (i + 1) % 16;
	}

	for (int i = 0; i < 16; i++)
	{
		int n;
		cin >> n;

		start.puzzle[i] = n;
	}

	start.depth = 0;
	start.evaluation = 0;

	printf("%d\n", solve(start));

	return 0;
}

