  priority_queue <X,vector<X>,greater<X>> pzq;
  pzq.push(mp3(manpz(pz),0,pz));

  for(;!pzq.empty();){

    vvi now=pzq.top().se;
    int how=pzq.top().fi.se;
    int man=pzq.top().fi.fi;
