class Board
{
public:
  vector<vector<int>> fld;
  int sr, sc;
  int dist;
  static vector<vector<vector<int>>> dt;
  bool operator < ( const Board& b ) const
  {
    for ( auto i = 0; i < 4; ++i )
      for ( auto j = 0; j < 4; ++j )
        {
          if ( fld[i][j] != b.fld[i][j] )
            return fld[i][j] < b.fld[i][j];
        }
    return false;
  }
  void print()
  {
    for ( auto i = 0; i < 4; ++i )
      {
        for ( auto j = 0; j < 4; ++j )
          cout << " " << fld[i][j] + 1;
        cout << endl;
      }
    cout << sr << " " << sc << endl;
    cout << dist << endl;
  }
  void calcdist();
};

vector<vector<vector<int>>> Board::dt(4, vector<vector<int>>(4, vector<int>(16)));

void Board::calcdist()
{
  dist = 0;
  for ( auto i = 0; i < 4; ++i )
    for ( auto j = 0; j < 4; ++j )
      dist += dt[i][j][fld[i][j]];
}

class FifteenPuzzle
{
public:
  vector<int> dr, dc;
  int limit;
  Board bbd;
  FifteenPuzzle()
  {
    dr = {1, 0, -1, 0}; dc = {0, 1, 0, -1};
  }
  int solve( Board bd );
  bool dfs( int c, int dir );
};

bool FifteenPuzzle::dfs( int c, int dir )
{
  if ( bbd.dist == 0 )
    {
      cout << c << endl;
      return true;
    }

  if ( bbd.dist + c >= limit )
    return false;

  for ( auto i = 0; i < 4; ++i )
    {
      if ( abs( i - dir ) == 2 ) continue;

      int nr = bbd.sr + dr[i];
      int nc = bbd.sc + dc[i];
      if ( nr < 0 || nr > 3 || nc < 0 || nc > 3 ) continue;

      Board sbd = bbd;

      swap(bbd.fld[nr][nc], bbd.fld[bbd.sr][bbd.sc]);
      bbd.sr = nr;
      bbd.sc = nc;
      bbd.calcdist();

      if ( dfs( c+1, i ) )
        return true;

      bbd = sbd;
    }
  return false;
}

int FifteenPuzzle::solve( Board bd )
{
  bbd = bd;

  for ( limit = 0; limit < 100; ++limit )
    {
      if  ( dfs( 0, 8 ) )
        return 0;
    }

  cout << "no answer" << endl;
  return 1;
}

