bool range(int y, int x) {return 0 <= y && y < N && 0 <= x && x < N;}

int h2_dfs(int boundary, State state, int from) {
    int find = -1;
    s.insert(state.state); // visited

    P blank = state.blank;
    rep(i, 4) {
        if (from == (i + 2) % 4) continue;
        int y = d[i] + blank.first, x = d[i + 1] + blank.second; // next blank position
        if (range(y, x)) { // can be replaced
            string tmp = state.state; // next state (string)
            int p = blank.first * N + blank.second, q = y * N + x;
            if (N < 4) swap(tmp[p], tmp[q]);
            else swap(tmp[2 * p], tmp[2 * q]), swap(tmp[2 * p + 1], tmp[2 * q + 1]);

            int num;
            if (N < 4) num = state.state[q] - '1';
            else num = stoi(state.state.substr(2 * q, 2)) - 1;
            // calcurate manhattan distance
            int manhattan = state.h - ((abs(num / N - y) + abs(num % N - x)))
            + (abs(num / N - blank.first) + abs(num % N - blank.second));

            if (manhattan == 0) { // answer
                find = state.g + 1;
                path = state.path + r[i];
                break;
            }

            if (state.g + 1 + manhattan > boundary) continue; // estimate value is over boundary
            find = h2_dfs(boundary, State{state.g + 1, manhattan, tmp, P(y, x), state.path + r[i]}, i);
            if (find != -1) break;
        }
    }
    return find;
}

int ids_h2(string state, int manhattan, P blank) {
    int i = manhattan, find = -1;
    while(find == -1 && i < 81) {
        s.clear();
        find = h2_dfs(i, State{0, manhattan, state, blank, ""}, -1);
        i++;
    }
    return find;
}

