struct puzzle {
	int sp, p[num], mdp, cost;
	//string way;
	bool operator < (const puzzle &pu) const {
		for (int i = 0; i < num; i++) {
			if (p[i] == pu.p[i]) continue;
			return p[i] < pu.p[i];
		}
		return false;
	}
};
struct state {
	puzzle pu;
	//int es = pu.mdp + pu.cost;
	bool operator < (const state &s) const {
		return pu.mdp + pu.cost > s.pu.mdp + s.pu.cost;
		//return es > s.es;
	}
};
puzzle pu;
int astar() {
	priority_queue<state> pq;
	map<puzzle, bool> m;
	state s;
	s.pu = pu;
	//s.es = pu.mdp;
	pq.push(s);
	state st, st1;
	puzzle p;
	int tx, ty, ns;
	while (!pq.empty()) {
		st = pq.top(); pq.pop();
		p = st.pu;
		//cout << "cost" <<  p.cost << endl;
		//cout << "mfp" << p.mdp << endl;
		if (!p.mdp) return p.cost;
		puzzle tmp;
		m[p] = true;
		int sx = p.sp / nd;
		int sy = p.sp % nd;
		for (int r = 0; r < nd; r++) {
			tx = sx + ud[r];
			ty = sy + lr[r];
			tmp = p;
			if (tx >= nd || tx < 0 || ty >= nd || ty < 0) continue;
			ns = tx * nd + ty;
			tmp.mdp = p.mdp - md[ns][p.p[ns] - 1] + md[sx*nd + sy][p.p[ns] - 1];
			tmp.sp = ns;
			swap(tmp.p[ns], tmp.p[sx * nd + sy]);
			tmp.cost = p.cost + 1;
			//cout << tmp.cost << endl;
			if (!m[tmp]) {
				st1.pu = tmp;
				//st1.es = tmp.cost + tmp.mdp;
				pq.push(st1);
			}
		}
	}
}

