                        {true, true, false, false}}; /* left, up, down, right */
vector<int> original(16, 0);

class board;

priority_queue<board> pq;
vector<ll> searched[16][16][16][16];

class board{
public:
    int moves;
    int wrongs;
    int zero_place;
    int cost;
    vector<int> tiles;

    explicit board(vector<int> num, int move){
        wrongs = 0;
        tiles = num;
        REP(i, 16){
            if(num[i] == 0)
                zero_place = i;
            if(num[i] != answer[i])
                wrongs++;
        }
        moves = move;
        cost = wrongs + moves;
    }

    void board_to_int(){
        ll k = 0;
        REP(i, 12)
            k += (tiles[i+4] * pow(16, i));
        for(int i = searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]].size(); i > 0 ; i--)
            if(k == searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][i-1])
                return;
        pq.push(board(tiles, moves+1));
        searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]].push_back(k);
        return;
    }

    void move() {
        if(dir[zero_place][0]){
            swap(tiles[zero_place], tiles[zero_place-1]);
            board_to_int();
            swap(tiles[zero_place], tiles[zero_place-1]);
        }
        if(dir[zero_place][1]){
            swap(tiles[zero_place], tiles[zero_place-4]);
            board_to_int();
            swap(tiles[zero_place], tiles[zero_place-4]);
        }
        if(dir[zero_place][2]){
            swap(tiles[zero_place], tiles[zero_place+4]);
            board_to_int();
            swap(tiles[zero_place], tiles[zero_place+4]);
        }
        if(dir[zero_place][3]){
            swap(tiles[zero_place], tiles[zero_place+1]);
            board_to_int();
            swap(tiles[zero_place], tiles[zero_place+1]);
        }
    }
};

bool operator< (board b1, board b2){
    return ((b1.cost > b2.cost) ? true : false);
}

int solve(){
    pq.push(board(original, 0));
    while(1){
        auto target = pq.top();
        if(target.wrongs == 0)
            return target.cost;
        pq.pop();
        target.move();
    }
}

int main() {
    REP(i, 16) cin >> original[i];
    int move = solve();
    cout << move << endl;
    return 0;
}

// Iterative Deepening
#include<stdio.h>
#include<iostream>
#include<cmath>
#include<string>
#include<cassert>
using namespace std;
#define N 4
#define N2 16
#define LIMIT 100

static const int dx[4] = {0, -1, 0, 1};
static const int dy[4] = {1, 0, -1, 0};
static const int char dir[4] = {'r', 'u', 'l', 'd'};
int MDT[N2][N2];

struct Puzzle { int f[N2], space, MD; };

Puzzle state;
int limit;  /* 深さの制限 */
int path[LIMIT];

int getAllMD(Puzzle pz) {
  int sum = 0;
  for ( int i = 0; i < N2; i++ ) {
    if ( pz.f[i] == N2 ) continue;
    sum += MDT[i][pz.f[i] - 1];
  }
  return sum;
}

bool isSolved() {
  for ( int i = 0; i < N2; i++ ) if ( state.f[i] != i + 1 ) return false;
  return true;
}


bool dfs(int depth, int prev) {
  if ( state.MD == 0 ) return true;
  /* 現在の深さにヒューリスティックを足して制限を超えたら枝を刈る */
  if ( depth + state.MD > limit ) return false;

  int sx = state.space / N;
  int sy = state.space % N;
  Puzzle tmp;

  for ( int r = 0; r < 4; r++ ) {
    int tx = sx + dx[r];
    int ty = sy + dy[r];
    if ( tx < 0 || ty < 0 || tx >= N || ty >= N ) continue;
    if ( max(prev, r)-min(prev, r) == 2 ) continue;
    tmp = state;
    /* マンハッタン距離の差分を計算しつつ、ピースをスワップ */
    state.MD -= MDT[tx * N + ty][state.f[tx * N + ty] - 1];
    state.MD += MDT[sx * N + sy][state.f[tx * N + ty] - 1];
    swap(state.f[tx * N + ty], state.f[sx * N + sy]);
    state.space = tx * N + ty;
    if ( dfs(depth + 1, r) ) { path[depth] = r; return true; }
    state = tmp;
  }

  return false;
}

/* 反復深化 */
string iterative_deepening(Puzzle in) {
  in.MD = getAllMD(in);  /* 初期状態のマンハッタン距離 */

  for ( limit = in.MD; limit <= LIMIT; limit++ ) {
    state = in;
    if ( dfs(0, -100) ) {
      string ans = "";
      for ( int i = 0; i < limit; i++ ) ans += dir[path[i]];
      return ans;
    }
  }

  return "unsolvable";
}

int main() {
  for ( int i = 0; i < N2; i++ )
    for ( int j = 0; j < N2; j++ )
      MDT[i][j] = abs(i / N - j / N) + abs(i % N - j % N);

  Puzzle in;

  for ( int i = 0; i < N2; i++ ) {
    cin >> in.f[i];
    if ( in.f[i] == 0 ) {
      in.f[i] = N2;
      in.space = i;
    }
  }
  string ans = iterative_deepening(in);
  cout << ans.size() << endl;

  return 0;
}

