struct state
{	
	vector<vector<int> > v;

	int dist1;
	int dist2;
	int spacex;
	int spacey;

	state(vector<vector<int> > v1, int d1, int d2, int s1, int s2) : v(v1), dist1(d1), dist2(d2), spacex(s1), spacey(s2) { }
};

bool operator<(const state& s1, const state& s2) { return s1.dist1 + s1.dist2 > s2.dist1 + s2.dist2; }

map<vector<vector<int> >, bool> D;

int getdistance(vector<vector<int> > v)
{
	vector<pair<int, int> > r1(16);

	for (int i = 0; i < 4; i++)
	{
		for (int j = 0; j < 4; j++)
		{
			r1[(v[i][j] + 15) % 16] = make_pair(j, i);
		}
	}

	int ret = 0;

	for (int i = 0; i < 16; i++)
	{
		int cx = i % 4;
		int cy = i / 4;

		ret += abs(r1[i].first - cx) + abs(r1[i].second - cy);
	}

	return ret;
}

int main()
{
	vector<vector<int> > start(4, vector<int>(4));

	int ssx = -1, ssy = -1;

	for (int i = 0; i < 4; i++)
	{
		for (int j = 0; j < 4; j++)
		{
			scanf("%d", &start[i][j]);

			if (start[i][j] == 0)
			{
				ssx = j;
				ssy = i;
			}
		}
	}

	priority_queue<state> que;

	que.push(state(start, 0, getdistance(start), ssx, ssy)); D[start] = true;

	while (!que.empty())
	{
		state s1 = que.top(); que.pop();

		if (s1.dist2 == 0)
		{
			printf("%d\n", s1.dist1); break;
		}

		int zx = s1.spacex;
		int zy = s1.spacey;

		for (int i = 0; i < 4; i++)
		{
			int tx = zx + dx[i];
			int ty = zy + dy[i];

			if (0 <= tx && tx < 4 && 0 <= ty && ty < 4)
			{
				vector<vector<int> > v2(s1.v);

				swap(v2[ty][tx], v2[zy][zx]);

				int target = v2[zy][zx];

				if (!D[v2])
				{
					D[v2] = true;

					int dist = s1.dist2;

					dist -= abs(3 - zx) + abs(3 - zy) + abs((target - 1) % 4 - tx) + abs((target - 1) / 4 - ty);
					dist += abs(3 - tx) + abs(3 - ty) + abs((target - 1) % 4 - zx) + abs((target - 1) / 4 - zy);

					que.push(state(v2, s1.dist1 + 1, dist, tx, ty));
				}
			}
		}
	}

	return 0;
}

