const int W = 4;

struct Point{
    ll x;
    ll y;
    Point(ll x, ll y): x(x), y(y) {}
    Point(){}
};

struct Puzzle{
    ll A[W][W];
    vector<ll> path;

    Point get_space(){
        Point p;
        FOR(y, 0, W){
            FOR(x, 0, W){
                if(A[y][x]==0){
                    p.x = x;
                    p.y = y;
                    return p;
                }
            }
        }
        return p;
    }

    bool operator<(const Puzzle &b)const
    {
        FOR(y, 0, W){
            FOR(x, 0, W){
                if(A[y][x] != b.A[y][x]){
                    return A[y][x] < b.A[y][x];
                }
            }
        }
        return false;
    }

    bool is_solved(){
        FOR(y, 0, W){
            FOR(x, 0, W){
                ll target = W*y + x + 1;
                if(y==W-1 && x==W-1) target = 0;
                if(A[y][x]!=target) return false;
            }
        }
        return true;
    }

    void print(){
        FOR(y, 0, W){
            FOR(x, 0, W){
                cout << A[y][x] << ' ';
            }
            cout << endl;
        }
    }
};

