int getsum(Mond pz){
    int sum = 0;
    for (int i = 0; i < NN; i++){
        if (pz.f[i] == NN) continue;
        sum += RYOMA[i][pz.f[i] - 1];
    }
    return sum;
}

bool defa(int fat, int af6){
    if (kaku.Atom == 0) return true;
    if (fat + kaku.Atom > mits) return false;

    int sx = kaku.sawa / MAX;
    int sy = kaku.sawa % MAX;
    Mond tmp;

    for (int r = 0; r < 4; r++){
        int tx = sx + xdo[r];
        int ty = sy + ydo[r];
        if (tx < 0 || ty < 0 || tx >= MAX || ty >= MAX) continue;
        if (max(af6, r) - min(af6, r) == 2) continue;
        tmp = kaku;

        kaku.Atom -= RYOMA[tx * MAX + ty][kaku.f[tx * MAX + ty] - 1];
        kaku.Atom += RYOMA[sx * MAX + sy][kaku.f[tx * MAX + ty] - 1];
        swap(kaku.f[tx * MAX + ty], kaku.f[sx * MAX + sy]);
        kaku.sawa = tx * MAX + ty;
        if (defa(fat + 1, r)){
            tee[fat] = r;
            return true;
        }
        kaku = tmp;
    }
    return false;
}

