using namespace std;

const int N = 16;
const int sN = 4;
int md[N][N];

struct pz {
	int a[N];
	int t, sp;

	bool operator < (const pz &p) const {
		for (int i = 0; i < N; i++) {
			if (a[i] == p.a[i])
				continue;
			return a[i] > p.a[i];
		}
		return false;
	}
};

struct state {
	pz p1;
	int ds;
	bool operator < (const state &st) const {
		return ds > st.ds;
	}
};

int dis(pz p) {
	int d = 0;
	for (int i = 0; i < N; i++)
		if (p.a[i] != i + 1)
			d += md[i][p.a[i] - 1];
	return d;
}

int main()
{
	pz p;
	int n = -1;
	map<pz, bool> v;

	for (int i = 0; i < N; i++) {
		cin >> p.a[i];
		if (p.a[i] == 0) {
			p.a[i] = N;
			p.sp = i;
		}
	}

	for (int i = 0; i < N; i++)
		for (int j = 0; j < N; j++)
			md[i][j] = abs(i / sN - j / sN) + abs(i % sN - j % sN);

	p.t = 0;
	state st;
	st.p1 = p;
	st.ds = dis(p);
	v[p] = true;

	priority_queue<state> que;
	que.push(st);

	while (!que.empty()) {
		state st1 = que.top();
		pz g = st1.p1;
		que.pop();

		if (dis(g) == 0) {
			n = g.t;
			break;
		}

		int u = g.sp;

		if(u % sN != 0){
			pz h = g;
			h.t++;
			h.sp--;
			swap(h.a[u], h.a[u - 1]);
			if (!v[h]) {
				v[h] = true;
				state st2;
				st2.p1 = h;
				st2.ds = h.t + dis(h);
				que.push(st2);
			}
		}
		if (u % sN != sN - 1) {
			pz h = g;
			h.t++;
			h.sp++;
			swap(h.a[u], h.a[u + 1]);
			if (!v[h]) {
				v[h] = true;
				state st2;
				st2.p1 = h;
				st2.ds = h.t + dis(h);
				que.push(st2);
			}
		}
		if (u / sN != 0) {
			pz h = g;
			h.t++;
			h.sp -= sN;
			swap(h.a[u], h.a[u - sN]);
			if (!v[h]) {
				v[h] = true;
				state st2;
				st2.p1 = h;
				st2.ds = h.t + dis(h);
				que.push(st2);
			}
		}
		if (u / sN != sN - 1) {
			pz h = g;
			h.t++;
			h.sp += sN;
			swap(h.a[u], h.a[u + sN]);
			if (!v[h]) {
				v[h] = true;
				state st2;
				st2.p1 = h;
				st2.ds = h.t + dis(h);
				que.push(st2);
			}
		}
	}

	cout << n << endl;

	return 0;
}

