const int N = 4;
int dx[4] = {0, 1, 0, -1}, dy[4] = {-1, 0, 1, 0};

struct Comp {
	int puz[16];	
	bool operator < (const Comp &c) const {
		for ( int i = 0; i < N*N; i++ ) {
			if ( puz[i] == c.puz[i] ) continue;
			return puz[i] < c.puz[i];
		}
		return false;
	}	
};

struct State {
	int puz[16];
	int zero;
	int cost;
	int esti;
	int pre;
	bool operator < (const State &s) const {
		return esti < s.esti;
	}
	bool operator > (const State &s) const {
		return esti  > s.esti;
	}
};

signed main() {
	State s;
	s.pre = -1;
	s.cost = s.esti = 0;	
	for ( int i = 0; i < N*N; i++ ) {
		cin >> s.puz[i];
		if ( s.puz[i] == 0 ) {
			s.zero = i;
			s.puz[i] = N*N-1;			
		} else {
			s.puz[i]--;
		}

		s.esti += abs(i/N-s.puz[i]/N) + abs(i%N-s.puz[i]%N);		
	}
	//cout << s.esti << endl;
	map<Comp, bool> used;	
	priority_queue<State, vector<State>, greater<State> > Q;	
	Q.push(s);
	int cnt = 0;
	while ( !Q.empty() ) {	 			
		State p = Q.top(); Q.pop();	
		if ( p.cost >= 45 ) continue;
		if ( p.esti >= 50 ) continue;

		//for ( int i = 0; i < N*N; i++ ) cout << s.puz[i] << " ";
		//cout << endl;
		// cout << p.cost << " " << p.esti << endl;			

		if ( p.esti-p.cost == 0 ) {
			cout << p.cost << endl;
			return 0;
		}		

		Comp c;
		for ( int i = 0; i < N*N; i++ ) c.puz[i] = p.puz[i];		
		if ( used.count(c) ) continue;		
		used[c] = p.cost;		

		for ( int i = 0; i < 4; i++ ) {
			int y = p.zero/N, x = p.zero%N;
			int ny = y+dy[i], nx = x+dx[i];
			if ( ny < 0 || nx < 0 || ny >= N || nx >= N ) continue;
			if ( s.pre == ny*4+nx ) continue;			
			s = p;			
			int ch_id = ny*4+nx;
			int ch_dat = s.puz[ch_id];
			int dat_y = ch_dat/N;
			int dat_x = ch_dat%N;			
			swap(s.puz[s.zero], s.puz[ch_id]);
			Comp cc = c;
			swap(cc.puz[s.zero], cc.puz[ch_id]);			
			if ( used.count(cc) ) continue;			
			s.esti -= abs(y-(N-1)) + abs(x-(N-1));			
			s.esti -= abs(ny-dat_y) + abs(nx-dat_x);			
			s.esti += abs(y-dat_y) + abs(x-dat_x);			
			s.esti += abs(ny-(N-1)) + abs(nx-(N-1));			
			s.esti++;
			s.cost++;
			s.pre = s.zero;
			s.zero = ch_id;
			Q.push(s);
		}			
	}

	return 0;
}

