};
queue<pair<Puzzle, int>>Q; Puzzle Z;
char manh(Puzzle y) {
	char sum = 0; pair<char, char> p[16];
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			p[y.x[i][j]] = make_pair(i, j);
		}
	}
	for (int i = 0; i < 16; i++) {
		int X = (i - 1) / 4, Y = (i - 1) % 4;
		if (i == 0) { X = 3; Y = 3; }
		sum += abs(X - p[i].first) + abs(Y - p[i].second);
	}
	return sum;
}
int main() {
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			int p1; cin >> p1;
			Z.x[i][j] = p1;
		}
	}
	Q.push(make_pair(Z, 0));
	int G = manh(Z);
	int PR = 30;
	if (G <= 20)PR = G + 10;
	while (!Q.empty()) {
		Puzzle r = Q.front().first;
		Puzzle s; int V = Q.front().second;
		pair<char, char>z; Q.pop();
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				if (r.x[i][j] == 0) z = make_pair(i, j);
			}
		}
		int dx[4] = { 0,1,0,-1 };
		int dy[4] = { 1,0,-1,0 };
