				for (int k = 0; k < 4; k++)s.x[j][k] = r.x[j][k];
			}
			char px = z.first + dx[i], py = z.second + dy[i];
			if (py < 0 || py > 3)continue;
			if (px < 0 || px > 3)continue;
			swap(s.x[z.first][z.second], s.x[px][py]);
			int R1 = manh(r), R2 = manh(s);
			if (R1 >= R2 - 2 && V + 1 + R2 <= PR) {
				int OK = 1;
				for (int j = 0; j < 4; j++) {
					for (int k = 0; k < 4; k++) {
						if (s.x[j][k] != (j * 4 + k + 1) % 16) OK = 0;
