		else
			start.empty = i;
    }
    std::priority_queue<Status, std::vector<Status>, std::greater<Status>> pq;
    std::set<std::array<int, 16>> done;
    pq.push(start);

    while (!pq.empty())
    {
        Status min{pq.top()};
