        {
            shift_empty(min, 2);
            auto next{done.find(min.board)};
            if (min.distance + min.h <= 45 && done.find(min.board) == done.end())
                pq.push(min);
            shift_empty(min, 0);
        }
        if (min.empty >= 4)
        {
            shift_empty(min, 1);
            auto next{done.find(min.board)};
            if (min.distance + min.h <= 45 && done.find(min.board) == done.end())
                pq.push(min);
            shift_empty(min, 3);
        }
        if (min.empty < 12)
        {
            shift_empty(min, 3);
            auto next{done.find(min.board)};
            if (min.distance + min.h <= 45 && done.find(min.board) == done.end())
                pq.push(min);
            shift_empty(min, 1);
        }
    }
    return 0;
}

void shift_empty(Status& tmp, int com)
{
    const int dir[4]{-1, -4, 1, 4};
    std::swap(tmp.board[tmp.empty], tmp.board[tmp.empty + dir[com]]);
    tmp.empty += dir[com];
    tmp.h = 0;
    for (int i{}; i < 16; i++)
		if (i != tmp.empty)
        	tmp.h += std::abs(tmp.board[i] % 4 - i % 4) + std::abs(tmp.board[i] / 4 - i / 4);
    return;
}

