string hashkey(vector<int> cell){
  string hash;
  for(const auto& e: cell){
    hash += to_string(e) + ",";
  }
  return hash;
}

vector<string> split(const string &str, char sep)
{
  vector<string> v;
  stringstream ss(str);
  string buffer;
  while( getline(ss, buffer, sep) ) {
      v.push_back(buffer);
  }
  return v;
}
vector<int> dehash(string hash){
  vector<int> cell;
  vector<string> board = split(hash, ',');
  for(const auto& e : board){
    cell.push_back(stoi(e));
  }
  return cell;
}

int estimateH(vector<int> cell, string hash){
  int hr = 0; // heuristic
  for(int i = 0 ; i < SIZE ; i++){
    if(cell[i] == 0){
      cell[i] = SIZE;
    }
    int rowhr = abs( (cell[i]-1)%WIDTH - i%WIDTH );
    int colhr = abs( (cell[i]-1)/WIDTH - i/WIDTH );
    hr += rowhr + colhr;
  }
  static double acc = 0.9; // accelarater
  static unsigned int count = 0;
  count++;
  if(count == 52700){
    acc = 1.3;
  }
  hr = (int)(hr*acc);
	return hr;
}

void updateGQ(vector<int> curCell,int space, int dir, string curHash){
  vector<int> nextCell(curCell);
  int moveto = space + dir; // move to = space(0) + direction
  nextCell[space] = nextCell[moveto];
  nextCell[moveto] = 0;
  const string nextHash = hashkey(nextCell); 
  if( !Node[nextHash].visited ){
    Node[nextHash].visited = true;
  	Node[nextHash].dist = Node[curHash].dist + 1;
    int dist_ev = Node[nextHash].dist + estimateH(nextCell,nextHash);
		Q.insert(make_pair(dist_ev, nextHash));
  }
  return;
}

void move(vector<int> curCell, string curHash){
  for(int i = 0 ; i < SIZE ; i++ ){
    if(curCell[i] == 0){
      if(Move[i][LEFT]){
        updateGQ(curCell, i, -1, curHash); 
      }
      if(Move[i][RIGHT]){
        updateGQ(curCell, i, 1, curHash); 
      }
      if(Move[i][UP]){
        updateGQ(curCell, i, -4, curHash); 
      }
      if(Move[i][DOWN]){
        updateGQ(curCell, i, 4, curHash); 
      }
    }
  }
  return;
}

