struct Board {
	std::array<int, 16> arrange{};
	int zero_pos;
};

int search(Board, int, int);
bool is_destination(Board);

int move_direction[4] = { 1, -1, 4, -4 };

int main()
{
	Board board;
	for (int i = 0; i < 16; ++i)
	{
		std::cin >> board.arrange[i];
		if (!board.arrange[i])
			board.zero_pos = i;
	}


	std::cout << search(board, 45, 0) << std::endl;

	return 0;
}

int search(Board board, int min, int depth)
{
	if (is_destination(board)) return 0;

	bool move_condi[4] = {
		board.zero_pos % 4 != 3, board.zero_pos % 4 != 0,
		board.zero_pos / 4 != 3, board.zero_pos / 4 != 0
	};
	for (int condi_i = 0; condi_i < 4; ++condi_i)
	{
		if (!move_condi[condi_i] || min == 1) continue;

		int next_zero_pos = board.zero_pos + move_direction[condi_i];
		Board next_board = board;
		next_board.arrange[board.zero_pos] = next_board.arrange[next_zero_pos];
		next_board.arrange[next_zero_pos] = 0;
		next_board.zero_pos = next_zero_pos;

		int min_tmp = search(next_board, min - 1, depth + 1) + 1;
		if (min_tmp < min)
			min = min_tmp;
	}
	return min;
}

bool is_destination(Board board)
{
	for (int i = 0; i < 15; ++i)
		if (board.arrange[i] != i + 1) return false;
	if (board.arrange[15] != 0) return false;

	return true;
}

