const char wa[] = { 'u', 'l', 'd', 'r' };
int md[num][num];
vector<int> way;
int lm;


struct puzzle {
    int sp, p[num], mdp;
    string way;
    bool operator < (const puzzle &pu) const {
        for (int i = 0; i < num; i++) {
            if (p[i] == pu.p[i]) continue;
            return p[i] < pu.p[i];
        }
        return false;
    }
};

puzzle pu;

bool dfs(int de, int pr) {
    if (de + pu.mdp > lm) return false;
    if (pu.mdp == 0) return true;
    int sx = pu.sp / nd;
    int sy = pu.sp % nd;
    int tx, ty, ns;
    puzzle tmp;
    for (int r = 0; r < nd; r++) {
        if (max(r, pr) - min(r, pr) == 2) continue;
        tx = sx + ud[r];
        ty = sy + lr[r];
        tmp = pu;
        if (tx >= nd || tx < 0 || ty >= nd || ty < 0) continue;
        ns = tx * nd + ty;
        pu.mdp -= md[ns][pu.p[ns]- 1];
        pu.mdp += md[pu.sp][pu.p[ns] - 1];
        pu.sp = ns;
        swap(pu.p[ns], pu.p[sx * nd + sy]);
        if (dfs(de + 1, r)) {
            way.push_back(r);
            return true;
        }
        pu = tmp;
    }
    return false;
}

