struct OwnNode
{
	int key[16];
	OwnNode* left;
	OwnNode* right;

	OwnNode():left(nullptr),right(nullptr){}
	OwnNode(int key[]) :OwnNode()
	{
		for (int i = 0; i < 16; i++)
		{
			this->key[i] = key[i];
		}
	}

	void insert(int nkey[])
	{
		int i = 0;
		for (; i < 16; i++)
		{
			if (key[i] != nkey[i])
			{
				break;
			}
		}
		if (i == 16)
		{
			return;
		}
		if (key[i]>nkey[i])
		{
			if (left == nullptr)
			{
				left = new OwnNode(nkey);
			}
			else
			{
				left->insert(nkey);
			}
		}
		else
		{
			if (right == nullptr)
			{
				right = new OwnNode(nkey);
			}
			else
			{
				right->insert(nkey);
			}
		}
	}

	bool find(int fkey[])
	{
		int i = 0;
		for (; i < 16; i++)
		{
			if (key[i] != fkey[i])
			{
				break;
			}
		}
		if (i == 16)
		{
			return true;
		}
		if (key[i]>fkey[i])
		{
			if (left == nullptr)
			{
				return false;
			}
			else
			{
				return left->find(fkey);
			}
		}
		else
		{
			if (right == nullptr)
			{
				return false;
			}
			else
			{
				return right->find(fkey);
			}
		}
	}

	void deleteAll()
	{
		if (left != nullptr)
		{
			left->deleteAll();
		}
		else
		{
			delete left;
			left = nullptr;
		}
		if (right != nullptr)
		{
			right->deleteAll();
		}
		else
		{
			delete right;
			right = nullptr;
		}
	}
};

State goal;

int heuristic(State& s)
{
	int eva = 0;
	int pos1[16], pos2[16];
	for (int i = 0; i < 16; i++)
	{
		pos1[s.puzzle[i]] = i;
		pos2[goal.puzzle[i]] = i;
	}
	for (int i = 0; i < 16; i++)
	{
		int manhattan = 0;
		manhattan += abs(pos1[i] / 4 - pos2[i] / 4);
		manhattan += abs(pos1[i] % 4 - pos2[i] % 4);
		eva += manhattan;
	}
	return eva;
}

