int MDT[N2][N2];
struct puzzle{int f[N2],space,MD;};
puzzle state;
int lim;
int path[LIM];
int getallMD(puzzle pz){
  int sum=0;
  for(int i=0;i<N2;i++){
    if(pz.f[i]==N2)continue;
    sum+=MDT[i][pz.f[i]-1];
  }
  return sum;
}
bool solved(){
  for(int i=0;i<N2;i++)if(state.f[i]!=i+1)return false;
  return true;
}
bool dfs(int de,int pr){
  if(state.MD==0)return true;
  if(de+state.MD>lim)return false;
  int sx=state.space/N;
  int sy=state.space%N;
  puzzle tmp;
  for(int r=0;r<4;r++){
    int tx=sx+dx[r];
    int ty=sy+dy[r];
    if(tx<0||ty<0||tx>=N||ty>=N)continue;
    if(max(pr,r)-min(pr,r)==2)continue;
    tmp=state;
    state.MD-=MDT[tx*N+ty][state.f[tx*N+ty]-1];
    state.MD+=MDT[sx*N+sy][state.f[tx*N+ty]-1];
    swap(state.f[tx*N+ty],state.f[sx*N+sy]);
    state.space=tx*N+ty;
    if(dfs(de+1,r)){
      path[de]=r;
      return true;
    }
    state=tmp;
  }
  return false;
}
string iterative(puzzle in){
  in.MD = getallMD(in);
  for(lim=in.MD;lim<=LIM;lim++){
    state=in;
