void Board::calcdist()
{
  dist = 0;
  for ( auto i = 0; i < 4; ++i )
    for ( auto j = 0; j < 4; ++j )
      dist += dt[i][j][fld[i][j]];
}

class State
{
public:
  Board bd;
  int h;
  bool operator < ( const State& s ) const
  {
    return h > s.h;
  }
};

class FifteenPuzzle
{
public:
  priority_queue<State> pq;
  map<Board,bool> m;
  vector<int> dr,dc;
  FifteenPuzzle(){}
  FifteenPuzzle( State st )
  {
    pq.push(st);
    m[st.bd] = true;
    dr = {1, -1, 0, 0}; dc = {0, 0, 1, -1};
  }
  int solve();
};

int FifteenPuzzle::solve()
{
  State nst;

  while ( ! pq.empty() )
    {
      State st = pq.top();
      pq.pop();

      Board b = st.bd;

      if ( b.dist == 0 )
        {
          cout << b.cost << endl;
          return 0;
        }

      for ( auto i = 0; i < 4; ++i )
        {
          int nr = b.sr + dr[i];
          int nc = b.sc + dc[i];
          if ( nr < 0 || nr > 3 || nc < 0 || nc > 3 ) continue;

          Board nb = b;
          nb.fld[b.sr][b.sc] = b.fld[nr][nc];
          nb.fld[nr][nc] = 15;
          nb.sr = nr;
          nb.sc = nc;
          nb.cost = b.cost + 1;
          nb.calcdist();

          if ( m.count(nb) == 0 )
            {
              State nst;
              nst.bd = nb;
              nst.h = nb.cost + nb.dist;
              pq.push(nst);
              m[nb] = true;
            }
        }
    }

  return 0;
}

