  if(state.MD == 0) return true;
  if(depth + state.MD > limit) return false;
  Puzzle temp;
  int sx, sy, tx, ty;
  sx = state.space/N; sy = state.space%N;
  for(int r=0; r<4; r++)
  {
    tx = sx + x[r]; ty = sy + y[r];
    if(ty < 0 || tx < 0 || tx >=N || ty >= N) continue;
    if(max(previous, r) - min(previous, r) == 2) continue;
    temp = state;
    state.MD -= MDT[tx*N + ty][state.f[tx*N + ty]-1];
    state.MD += MDT[state.space][state.f[tx*N + ty] -1];
    swap(state.f[state.space], state.f[tx*N + ty]);
    state.space = tx*N + ty;
    if(dfs(depth+1, r))           //tai
    {
      path[depth] = r; return true;// xiu le
    }
    state = temp;
  }
  return false;
}
string iterative_deepening(Puzzle &p)
{
  p.MD = getMD(p);
  for(limit = p.MD; limit<=LIMIT; limit++)
  {
    state = p;
    if(dfs(0, -100))
    {
      string ans = "";
      for(int i=0; i<limit; i++)
      {
        ans += c[path[i]];
      }
      return ans;
    }
  }
  return "unsolvable";
}
