    if(g.board[i]!=i+1) return false;
  }
  return true;
}

bool dfs(int depth){
  stack<game> s;
  s.push(start);

  while(!s.empty()){
    game g=s.top();s.pop();
    if(depth==g.depth){
      if(is_goal(g)) return true;
      continue;
    }

    for(int move:move_list[g.w]){
      if(g.last_move==-move) continue;
      game h=g;
      swap(h.board[h.w],h.board[h.w+move]);
      h.w = h.w+move;
      h.depth++;
      h.last_move=move;
      s.push(h);
    }
  }
  return false;
}

