using namespace std;

const int N = 4;

struct Puzzle {
    array<array<int, N>, N> board;
    array<int, 2> empty;
    int cost;

    bool operator < (const Puzzle &p) const {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                if (board[i][j] != p.board[i][j])
                    return board[i][j] < p.board[i][j];
            }
        }
        return false;
    }
};

int distance(const Puzzle& p) {
    const auto M = N - 1;
    int d = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            auto x = p.board[i][j];
            if (x == 0)
                x = 16;
            auto m = (x - 1) % N;
            auto n = (x - 1) / N;

            auto dx = i - m;
            auto dy = j - n;
            if (dx < 0) dx = -dx;
            if (dy < 0) dy = -dy;
            d += dx + dy;
        }
    }
    return d;
}

struct State {
    Puzzle puzzle;
    int rank;

    bool operator < (const State& other) const {
        return rank > other.rank;
    }
};

const vector<array<int, 2>> dir = {
    {-1, 0}, // left
    {0, -1}, // up
    {1, 0},  // right
    {0, 1},  // down
};

bool solved(const Puzzle& p) {
    const auto M = N - 1;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int x = i == M && j == M ? 0 : i * N + j + 1;
            if (p.board[i][j] != x) {
                return false;
            }
        }
    }
    return true;
}

int main() {
    Puzzle start;
    start.cost = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int x;
            cin >> x;
            if (x == 0) {
                start.empty = {i, j};
            }
            start.board[i][j] = x;
        }
    }

    Puzzle ans;
    set<Puzzle> visited;
    priority_queue<State> Q;
    Q.push(State{start, distance(start)});
    while (!Q.empty()) {
        auto state = Q.top();
        Q.pop();
        auto u = state.puzzle;
        if (solved(u)) {
            ans = std::move(u);
            break;
        }
        for (auto& d : dir) {
            auto tx = u.empty[0] + d[0];
            auto ty = u.empty[1] + d[1];
            if (tx < 0 || ty < 0 || tx >= N || ty >= N) {
                continue;
            }
            auto v = u;
            swap(v.board[v.empty[0]][v.empty[1]], v.board[tx][ty]);
            v.empty = {tx, ty};
            ++v.cost;
            if (visited.find(v) == visited.end()) {
                visited.insert(v);
                Q.push(State{v, v.cost+distance(v)});
            }
        }
    }
    cout << ans.cost << endl;

    return 0;
}

#include<iostream>
