#define minus(x, y) (x > y ? x - y :  y - x)

uint64_t GetFinal()
{
	uint64_t res = 0;
	for(int i = 0; i < 16; i++)
	{
		uint64_t iBit = (i+1) & 0xf;
		//printf("%d\n", iBit);
		res |= iBit << 60 - i*4;
	}
	return res;
}

void PrintVal(uint64_t iVal)
{
	for(int i = 0 ;i < 4; i++)
	{
		for(int j = 0; j < 4; j++)
		{
			uint64_t iMask = 0xf;
			int shift = 60 - 4*(4*i + j);
			int digit = (iVal >> shift) & iMask;
			printf("%d ", digit);
		}
		printf("\n");
	}
}

uint64_t Shift(uint64_t iVal, int iLft, int iRgt)
{
	uint64_t iMask = 0xf;
	uint64_t iDst = (iVal & (iMask << (60 - iRgt*4)));
	if(iLft < iRgt)
		iDst = iDst << (4 * (iRgt - iLft));
	else
		iDst = iDst >> (4 * (iLft - iRgt));
	//printf("dst %d\n", iDst);

	iVal &= ~(iMask << (60 - iRgt*4)); //抹除
	iVal |= iDst;
	return iVal;
}

uint64_t L(uint64_t iVal, int iZeroIdx)
{
	return Shift(iVal, iZeroIdx, iZeroIdx - 1);
}

uint64_t R(uint64_t iVal, int iZeroIdx)
{
	return Shift(iVal, iZeroIdx, iZeroIdx + 1);
}

uint64_t U(uint64_t iVal, int iZeroIdx)
{
	return Shift(iVal, iZeroIdx, iZeroIdx - 4);
}

uint64_t D(uint64_t iVal, int iZeroIdx)
{
	return Shift(iVal, iZeroIdx, iZeroIdx + 4);
}

enum eDirection
{
	eUp = 0x01,
	eDown = 0x02,
	eLeft = 0x04,
	eRight = 0x08,
};

struct Node
{	
	uint64_t iFromVal;
	uint32_t iZeroIdx;
	int iFrom;
