	*/
};

int FindDirection(int iZeroIdx)
{
	int ret = 0;
	if(iZeroIdx % 4 != 0)
		ret |= eLeft;

	if((iZeroIdx + 1) % 4 != 0)
		ret |= eRight;

	if(3 < iZeroIdx && iZeroIdx < 16)
		ret |= eUp;

	if(0 <= iZeroIdx && iZeroIdx < 12)
		ret |= eDown;

	return ret;
}

bool CanSolve(uint64_t iVal)
{
	uint64_t iMask = 0xf;
	int sum = 0;
	int iZeroRow = 0;
	for(int i = 0; i < 16; i++)
	{
		uint64_t iLft = (iVal & (iMask << 60 - 4*i)) >> (60 - 4*i);
		if(iLft == 0)
		{
	//		printf("zero pos %d\n", i);
			iZeroRow = i / 4;
		}
		if(i == 15)
			break;
		for(int j = i + 1; j < 16; j++)
		{
			uint64_t iRgt = (iVal & (iMask << 60 - 4*j)) >> (60 - 4*j);
			if(iLft != 0 && iRgt != 0 && iRgt < iLft)
				sum ++;
		}
	}

//	printf("zero row %d nixu pair %d\n", iZeroRow, sum);

	if(iZeroRow % 2)
		return sum%2 == 0;

	return sum % 2 == 1;
}

int GetManhatonDistance(int iLft, int iRgt)
{
	int iLftRow = iLft / 4;
	int iLftCol = iLft % 4;

	int iRgtRow = iRgt / 4;
	int iRgtCol = iRgt % 4;

	int d = minus(iRgtRow, iLftRow) + minus(iRgtCol, iLftCol);
//	printf("x (%d, %d) y (%d, %d) d %d\n", iLftRow, iLftCol, iRgtRow, iRgtCol, d);
	return d;
}

int EvaluateStatus(uint64_t iVal)
{
	int sum = 0;
	uint64_t iMask = 0xf;
	for(int i = 0; i < 16; i++)
	{
		int iLft = (iVal & (iMask << 60 - 4*i)) >> (60 - 4*i);
		int iPos = iLft - 1; // what it should be

		if(iLft != 0 && i != iPos)
		{
			//printf("val %d in %d should be pos %d\n", iLft, i, iPos);
			sum += GetManhatonDistance(i, iPos);
		}
	}
//	PrintVal(iVal);
//	printf("diff %d\n", sum);
	return sum;
}
