struct state
{	
	vector<vector<int> > v;

	int dist1;
	int dist2;
	int spacex;
	int spacey;

	state(vector<vector<int> > v1, int d1, int d2, int s1, int s2) : v(v1), dist1(d1), dist2(d2), spacex(s1), spacey(s2) { }
};

bool operator<(const state& s1, const state& s2) { return s1.dist1 + s1.dist2 < s2.dist1 + s2.dist2; }
bool operator>(const state& s1, const state& s2) { return s1.dist1 + s1.dist2 > s2.dist1 + s2.dist2; }

map<vector<vector<int> >, bool> D;

int getdistance(vector<vector<int> > v)
{
	vector<pair<int, int> > r1(16);

	for (int i = 0; i < 4; i++)
	{
		for (int j = 0; j < 4; j++)
		{
			r1[(v[i][j] + 15) % 16] = make_pair(j, i);
		}
	}

	int ret = 0;

	for (int i = 0; i < 16; i++)
	{
		int cx = i % 4;
		int cy = i / 4;

		ret += abs(r1[i].first - cx) + abs(r1[i].second - cy);
	}

	return ret;
}

int main()
{
	vector<vector<int> > start(4, vector<int>(4));

	int ssx = -1, ssy = -1;

