			if (start[i][j] == 0)
			{
				ssx = j;
				ssy = i;
			}
		}
	}

	priority_queue<state, vector<state>, greater<state> > que;

	que.push(state(start, 0, getdistance(start), ssx, ssy)); D[start] = true;

	while (!que.empty())
	{
		state s1 = que.top(); que.pop();

		if (s1.dist2 == 0)
		{
			printf("%d\n", s1.dist1); break;
		}

		int zx = s1.spacex;
