int dfs(int x, int y, int p, int dep, const int lim) {
  int h = calc();

  if(h == 0) return dep;
  if(dep+h > lim) return -1;

  for(int i = 0; i < N; i++) {
    int nx = x+dx[i], ny = y+dy[i], res;
    if(~p && i == (p+2)%N) continue;
    if(!is_in(nx, ny)) continue;
    swap(&mas[y][x], &mas[ny][nx]);
    res = dfs(nx, ny, i, dep+1, lim);
    if(~res) return res;
    swap(&mas[y][x], &mas[ny][nx]);
  }
  return -1;
}
void get_empty(int *x, int *y) {

  for(int i = 0; i < N; i++) {
    for(int j = 0; j < N; j++) {
      if(!mas[i][j]) {
    *x = j;
    *y = i;
    return;
      }
    }
  }
}
int solve() {
  int x, y, lim, ans;
  get_empty(&x, &y);
  for(lim = 0; lim < 50; lim++) {
    copy(cpy, mas);
    if((ans = dfs(x, y, -1, 0, lim)) != -1) return ans;
    copy(mas, cpy);
  }
  return -1;
}
int main() {
  input();
  cout<<solve()<<endl;
  return 0;
}

