int getG(int st[])
{
    int dis=0;
    for(int i=0;i<n*n;i++)
    {
        int d=st[i]-1;
        if(st[i]!=16)
            dis+=abs(d/n-i/n)+abs(d%n-i%n);
    }
    return dis;
}

void dfs(int pos,int step,int top,int g)
{
    if(step>=top || getG(G)+step>g) return;
