        int ty=pos/4+dir[i][0];
        int tx=pos%4+dir[i][1];
        if(ty<0 || ty>=n || tx<0 || tx>=n)
            continue;
        swap(G[pos],G[ty*4+tx]);
        dfs(ty*4+tx,step+1,top,g);
        swap(G[pos],G[ty*4+tx]);
    }
}
