    bool operator < (const STATE& tgt) const {
	return f > tgt.f; // ?¨????
    }
};
inline bool is_searched(const STATE& s) {
    return (memo.find(s.b) != memo.end());
}
inline void searched(const STATE& s) {
    memo.insert(s.b);
}
inline bool is_goal(const STATE& s) {
    for(int i=0; i<H; i++) {
	for(int j=0; j<W; j++) {
	    if( i == H-1 and j == W-1 )  return true;
	    if( s.b[i][j] != (i*W)+j+1 ) return false;
	}
    }
}

inline void where0(const STATE& s, int& h, int& w) {
    for(int i=0; i<H; i++)
	for(int j=0; j<W; j++)
	    if( s.b[i][j] == 0 ) {
		h = i;
		w = j;
	    }
}

inline int manhattan_dis(const int tgt, const int h, const int w) {
    if(tgt == 0 ) return 0;
    int tgt_h = (tgt-1)/W;
    int tgt_w = (tgt-1)%W;
    return abs(tgt_h - h) + abs(tgt_w - w);
}

inline int heuristic(const vector<vector<short>>& b) {
    int ans = 0;
    for(int i=0; i<H; i++) {
	for(int j=0; j<W; j++) {
	    ans += manhattan_dis(b[i][j],i,j);
	}
    }
    return ans;
}

const int dx[] = { 1, 0,-1, 0}; 
const int dy[] = { 0, 1, 0,-1};
inline vector<STATE> adjcency(const STATE& cur) {
    int h,w;   where0(cur,h,w);
    vector<STATE> ans;
    vector<vector<short>> b = cur.b;

    for(int i=0; i<4; i++) { // 4??????
	int nh = h+dy[i], nw = w+dx[i];
	if( nh >= 0 and nh < H and nw >= 0 and nw < W ) {
	    swap(b[nh][nw], b[h][w]);
	    int heu = heuristic(b);
//	    if( cur.g+1+heu <= 24 )
		ans.push_back( STATE{cur.g+1+heu, cur.g+1, b} );
	    swap(b[nh][nw], b[h][w]);
	}
    }
    return ans;
}

