  vector<int> start_vec(N,-1);
  for(int i=0;i<N;i++) {
    cin >> start_vec[i];
    solve[i] = i+1;
  }
  solve[N-1] = 0;

  state start = *(new state(start_vec,0));

  cout << search(start) << endl;
}

