static const int dx[4] = {-1, 0, 1, 0}; //??£??\???{}
static const int dy[4] = {0, -1, 0, 1};
static const int dir[4] = {'u', 'l', 'd', 'r'};

int MDT[N2][N2];

struct Puzzle {
	int p[N2], space, MD;
	int cost;

	bool operator < (const Puzzle &p1) const { //????????§?????????
		for (int i = 0; i < N2; i++) {
			if (p[i] == p1.p[i]) continue;
			return p[i] < p1.p[i];
		}
		return false;
	}
};

struct State {
	Puzzle puzzle;
	int estimated;
	bool operator < (const State &s) const {
		return estimated > s.estimated;
	}
};

int getAllMD(Puzzle pz) {
	int sum = 0;
	for (int i = 0; i < N2; i++) {
		if (pz.p[i] == N2) continue;
		sum += MDT[i][pz.p[i] - 1]; //i????????¨????????????j???????????????
	}
	return sum;
}

int astar(Puzzle in) {
	priority_queue<State> PQ;
	in.MD = getAllMD(in);
	in.cost = 0;
	map<Puzzle, bool> V;
	Puzzle u, v;
	State initial;
	initial.puzzle = in;
	initial.estimated = getAllMD(in);
	PQ.push(initial);

	while (!PQ.empty()) {
		State st = PQ.top();
		PQ.pop();
		u = st.puzzle;

		if (u.MD == 0) return u.cost;
		V[u] = true;

		int sx = u.space / N;
		int sy = u.space % N;

		for (int r = 0; r < 4; r++) {
			int tx = sx + dx[r];
			int ty = sy + dy[r];
			if (tx < 0 || ty < 0 || tx >= N || ty >= N) continue;
			v = u;

			v.MD -= MDT[tx * N + ty][v.p[tx * N + ty] - 1];
			v.MD += MDT[sx * N + sy][v.p[tx * N + ty] - 1];
			swap(v.p[tx * N + ty], v.p[sx * N + sy]);
			v.space = tx * N + ty;
			if (!V[v]) {
				v.cost++;
				State news;
				news.puzzle = v;
				news.estimated = v.cost + v.MD;
				PQ.push(news);
			}
		}
	}
	return -1;
}

