	node ** stackA, ** stackB;
	int pointerA, pointerB;
	int max_depth;
	node ** hash_table;
	int finished;
	int result;

	stackA = (node **)malloc(sizeof(node *) * STACK_SIZE);
	stackB = (node **)malloc(sizeof(node *) * STACK_SIZE);
	pointerA = 0;
	pointerB = 0;
	hash_table = (node **)malloc(sizeof(node *) * HASH_SIZE);
	for (int i = 0; i < HASH_SIZE; i++) {
		hash_table[i] = NULL;
	}

	data = 0;
	for (int i = 0; i < 16; i++) {
		unsigned int a;
		std::cin >> a;
		data = (data << 4) + a;
	}
	//std::printf("%016llx\n", data);

	max_depth = Mdistance(data);
	//std::printf("max_depth:%d\n", max_depth);

	try
	{
		finished = create(data, 0, hash_table, stackA, stackB, &pointerA, &pointerB, max_depth);
	}
	catch (...)
	{
		return 1;
	}
	if (finished) {
		std::printf("0");
		return 0;
	}

	while (1) {
