#define DIVN 4

struct Pandt{
	unsigned long long int p;
	int t;
};

unsigned long long int fact(int a);
int dist(unsigned long long int x);
int abs(int x);
void insert(vector<Pandt> &A, Pandt v);
Pandt extract(vector<Pandt> &A);
