typedef vector<int> Board;

const int INF=INT_MAX/3;

void Adj(Board &u, vector<Board> &adj){
	int zero;
	for(int i=0;i<16;i++){
		if(u[i]==0){zero=i;}
	}

	if(zero<12){
		Board v(16);
		v=u;
		swap(v[zero],v[zero+4]);
		adj.push_back(v);
	}
	if(zero>3){
		Board v(16);
		v=u;
		swap(v[zero],v[zero-4]);
		adj.push_back(v);
	}
	if(zero%4 == 0 || zero%4 == 1 || zero%4 == 2){
		Board  v(16);
		v=u;
		swap(v[zero],v[zero+1]);
		adj.push_back(v);
	}
	if(zero%4 == 1 || zero%4 == 2 ||zero%4 == 3){
		Board v(16);
		v=u;
		swap(v[zero],v[zero-1]);
		adj.push_back(v);
	}
}

bool DLS(Board &b, Board &goal, int depth){
	if(b == goal){
		return true;
	}
	if(depth>0){
		vector<Board> adj;
		Adj(b,adj);
		for(int i=0;i<adj.size();i++){
			if(DLS(adj[i], goal, depth-1)==true){
				return true;
			}
		}
	}
	return false;
}

int IDDFS(Board &init,Board &goal){
	for (int depth=1; ; depth++){
		bool found = DLS(init,goal,depth);
		if(found){
			return depth;
		}
	}
}

