typedef unsigned long long int TBoard;
const static TBoard Answer = 0x123456789ABCDEF0;
typedef std::map<TBoard, bool> TTable;

TBoard InputBoard(std::istream& in)
{
    TBoard Board = 0;
    // for(int i = 15; i >= 0; --i){
    //     int n;
    //     std::cin >> n;
    //     Board += n * std::pow(0x10, i);
    // }
    for(int i = 0; i < 16; ++i){
        int n;
        std::cin >> n;
        Board <<= 4;
        Board += n;
    }
    return Board;
}
int FindZero(TBoard Board)
{
    for(int i = 0; i < 16; ++i){
        if((Board & 0xF) == 0){
            return 15-i;
        }
        Board >>= 4;
    }
    assert(false);
}
TBoard Swap(TBoard Board, int i, int j)
{
    assert(0 <= i && i < 16);
    assert(0 <= j && j < 16);
    i = 15 - i;
    j = 15 - j;
    TBoard MaskX = 0xFL << (i*4);
    TBoard MaskY = 0xFL << (j*4);
    TBoard x = (Board & MaskX) >> (i*4);
    TBoard y = (Board & MaskY) >> (j*4);
    // int x = (Board >> (i*4) & 0xF);
    // int y = (Board >> (j*4) & 0xF);
    Board &= ~MaskX;
    Board &= ~MaskY;
    Board |= x << (j*4);
    Board |= y << (i*4);
    return Board;
}
std::vector<TBoard> GetMoved(const TBoard& Board)
{
    int i = FindZero(Board);

    std::vector<TBoard> Result;
    if(i > 3){
        Result.push_back(Swap(Board, i, i-4));
    }
    if(i < 0xC){
        Result.push_back(Swap(Board, i, i+4));
    }
    if((i == 0 || i == 4 || i == 8 || i == 0xC) == false){
        Result.push_back(Swap(Board, i, i-1));
    }
    if((i == 3 || i == 7 || i == 0xB || i == 0xF) == false){
        Result.push_back(Swap(Board, i, i+1));
    }

    return Result;
}
void Print(const TBoard& Board, char c)
{
    for(int i = 0; i < 4; ++i){
        std::cerr << c;
        for(int j = 0; j < 4; ++j){
            std::cerr << ((Board >> (15-(i*4+j))*4) & 0xF) << " ";
        }
        std::cerr << std::endl;
    }
    std::cerr << std::endl;
}
int Solve(const TBoard& Board)
{
    TTable Table;
    int Cost = 0;
    std::queue<TBoard> q;
    q.push(Board);
    Table[Board] = true;

    std::queue<TBoard> temp;
    while(!q.empty()){
        TBoard B = q.front();
        q.pop();
        // Print(B, ' ');
        if(B == Answer) return Cost;
        std::vector<TBoard> Boards = GetMoved(B);
        for(std::size_t i = 0; i < Boards.size(); ++i){
            if(Table[Boards[i]]) continue;
            temp.push(Boards[i]);
            Table[Boards[i]] = true;
            // Print(Boards[i], '\t');
        }
        if(q.empty()){
            std::swap(q, temp);
            ++Cost;
            // std::cerr << "Cost" << Cost << std::endl;
        }
    }
    assert(false);
}
int main()
{
    TBoard Board = InputBoard(std::cin);
    std::cout << Solve(Board) << std::endl;
    return 0;
}

