Node* find(string x) {
    Node *p = root;

    while(p!=NULL && p->n!=x) {
        if(x < p->n) p = p->l;
        else p = p->r;
    }

    return p;
}


void insert(string x, int m) {
    Node *p = root;
    Node *p_prev = NULL;
    Node *xx = new Node(); xx->n = x; xx->m = m;

    while(p!=NULL) {
        p_prev = p;

        if(x < p->n) p = p->l;
        else p = p->r;
    }

    if(p_prev==NULL) root = xx;
    else if(x < p_prev->n) p_prev->l = xx;
    else p_prev->r = xx;
}






