using namespace std;
const int n = 4;
struct no{
    int a[n][n];//棋盘
    int cost;//从开始节点到现在的花费
    int x, y;//0的行和列
};
bool operator < (no c, no d){
    for(int i = 0; i < n; i++){
        for(int j = 0; j < n; j++){
            if(c.a[i][j] == d.a[i][j]) continue;
            return c.a[i][j] > d.a[i][j];
        }
    }
}
struct m{
    no node;
    int dis;//从开始节点到当前状态+当前状态到终点的曼哈顿距离
};
bool operator < (m c, m d){
    return c.dis > d.dis;
}
no s, g;//s开始节点，g终点
int MDT(no c){//计算c状态与终点之间的曼哈顿距离
    int sum = 0;
    for(int i = 0; i < n; i++){
        for(int j = 0; j < n; j++){
            int temp = c.a[i][j] == 0 ? 16 : c.a[i][j];
            int x = (temp - 1) / 4;
            int y = (temp - 1) % 4;
            sum += (abs(i-x) + abs(j-y));
        }
    }
    return sum;
}
int isEqual(no c, no d){
    for(int i = 0; i < n; i++){
        for(int j = 0; j < n; j++){
            if(c.a[i][j] != d.a[i][j]) return 0;
        }
    }
    return 1;
}
void astar(){
    int dy[] = {-1, 0, 1, 0};
    int dx[] = {0, -1, 0, 1};//左，上，右，下

    priority_queue<m> q;
    map<no, bool> used;
    s.cost = 0;
    m start;
    start.node = s;
    start.dis = s.cost + MDT(s);
    q.push(start);
    while(!q.empty()){
        m temp = q.top() ; q.pop();
        no t = temp.node;
        used[t] = true;
        if(MDT(t) == 0){
            printf("%d\n", t.cost);
            break;
        }
        for(int k = 0; k < 4; k++){
            int nx = t.x + dx[k];
            int ny = t.y + dy[k];
            if(0 <= nx && nx < n && 0 <= ny && ny < n){
                no u = t;
                u.a[t.x][t.y] = t.a[nx][ny];
                u.a[nx][ny] = 0;
                u.x = nx; u.y = ny;
                if(!used[u]){
                    u.cost ++;
                    m v;
                    v.node = u;
                    v.dis = u.cost + MDT(u);
                    q.push(v);
                }
            }
        }
    }
}
