#define N 4
#define N2 16
using namespace std;

struct game{
  int b[N2];
  bool operator < (const game &other) const{
    for(int i=0;i<N2;i++){
      if(b[i]<other.b[i]){
        return true;
      }else if(b[i]>other.b[i]){
        return false;
      }
    }
    return false;
  }
};
game g;
map<game,int> checked;
queue<game> q;

void print(game _g){
  for(int i=0;i<N2;i++)
    printf("%d ",_g.b[i]);
  printf("\n");
}

bool clear(game _g){
  for(int i=0;i<N2;i++){
    if(_g.b[i]!=i+1) return false;
  }
  return true;
}

int solve(){
  q.push(g);
  checked.insert(make_pair(g,0));
  int depth;
  while(!q.empty()){
    g=q.front();q.pop();
    depth=checked[g];
    if(clear(g)){ return depth; }
    int w;
    for(int i=0;i<N2;i++){
      if(g.b[i]==N2) {
        w=i;
        break;
      }
    }
    vector<int> v;
    if(w%N<N-1) v.push_back(1);
    if(w%N>0  ) v.push_back(-1);
    if(w/N<N-1) v.push_back(N);
    if(w/N>0  ) v.push_back(-N);
    for(int i:v){
      game gt=g;
      swap(gt.b[w],gt.b[w+i]);
      if(checked.find(gt)==checked.end()){
        q.push(gt);
        checked.insert(make_pair(gt,depth+1));
      }
    }
  }
  return -1;
}


int main(){
  for(int i=0;i<N2;i++) {
    int tmp; cin>>tmp;
    if(tmp==0) tmp=N2;
    g.b[i]=tmp;
  }

  cout<<solve()<<endl;
}

