    cin.tie(0);
    ios::sync_with_stdio(false);

    for (int i = 0; i < N2; i++) {
      for (int j = 0; j < N2; j++) {
        MDT[i][j] = abs(i/N - j/N) + abs(i%N - j%N);
      }
    }

    Puzzle in;
    for (int i = 0; i < N2; i++) {
      cin >> in.f[i];
      if (in.f[i] == 0) {
        in.f[i] = N2;
        in.space = i;
      }
    }

    string ans = iterative_deepening(in);
    cout << ans.size() << endl;

    return 0;
}

