using namespace std;

#define SIDE 4
#define N 16
#define LIMIT 100

struct Board {
  int a[N];
  int md, c, zero_pos;

  bool operator < (const Board &b) const {
    for (int i = 0; i < N; i++) {
      if (a[i] == b.a[i]) continue;
      return a[i] < b.a[i];
    }
    return false;
  }
};

struct State {
  Board b;
  int e; // estimated

  bool operator < (const State &s) const {
    return e > s.e;
  }
};

int DX[4] = { 0, 1, 0, -1 };
int DY[4] = { 1, 0, -1, 0 };
char DIR[4] = { 'u', 'r', 'd', 'l' };

int MDs[N][N];

int get_MD_sum(Board in) {
  int sum = 0;
  for (int i = 0; i < N; i++) {
    if (in.a[i] == N) continue;
    sum += MDs[i][in.a[i] - 1];
  }
  return sum;
}

void astar(Board in) {
  State s;
  s.e = in.md = get_MD_sum(in);
  s.b = in;

  priority_queue<State> q;
  q.push(s);

  map<Board, bool> visited;

  while (!q.empty()) {
    Board cur_b = q.top().b; q.pop();

    if (cur_b.md == 0) {
      cout << cur_b.c << endl;
      return;
    }

    visited[cur_b] = true;

    int sx = cur_b.zero_pos / SIDE;
    int sy = cur_b.zero_pos % SIDE;

    for (int i = 0; i < 4; i++) {
      int new_x = sx + DX[i];
      int new_y = sy + DY[i];

      if (new_x < 0 || new_x >= SIDE || new_y < 0 || new_y >= SIDE) continue;

      Board new_b = cur_b;

      new_b.md -= MDs[new_x * SIDE + new_y][new_b.a[new_x * SIDE + new_y] - 1];
      new_b.md += MDs[sx * SIDE + sy][new_b.a[new_x * SIDE + new_y] - 1];

      swap(new_b.a[sx * SIDE + sy], new_b.a[new_x * SIDE + new_y]);
      new_b.zero_pos = new_x * SIDE + new_y;

      if (!visited[new_b]) {
        new_b.c++;
        State new_s;
        new_s.b= new_b;
        new_s.e = new_b.c + new_b.md;
        q.push(new_s);
      }
    }
  }

  cout << "no goal" << endl;
}

