int Astar(Puzzle s){
    priority_queue<State> PQ;
    s.MD=getAllMD(s);
    s.cost=0;
    map<Puzzle,bool> V;
    Puzzle u,v;
    State initial;
    initial.puzzle=s;
    initial.estimated=getAllMD(s);
    PQ.push(initial);

    while(!PQ.empty()){
        State st=PQ.top(); PQ.pop();
        u=st.puzzle;

        if(u.MD==0) return u.cost;
        V[u]=true;

        int sx=u.space/N;
        int sy=u.space%N;

        for(int r=0;r<4;r++){
            int tx=sx+dx[r];
            int ty=sy+dy[r];
            if(tx<0||ty<0||tx>=N||ty>=N) continue;
            v=u;

            v.MD -= MDT[tx*N+ty][v.f[tx*N+ty]-1];
            v.MD += MDT[sx*N+sy][v.f[tx*N+ty]-1];

            swap(v.f[sx*N+sy],v.f[tx*N+ty]);
            v.space=tx*N+ty;
            if(!V[v]){
                v.cost++;
                State news;
                news.puzzle=v;
                news.estimated=v.cost+v.MD;
                PQ.push(news);
            }
        }
    }
    return -1;
}

