static const int dx_123[4] = {0, -1, 0, 1};//４方向
static const int dy_123[4] = {1, 0, -1, 0};//４方向
static const char houkou[4] ={'r', 'u', 'l', 'd'};//右:right,　上:up,　左:left,　下:down

int ManhattanDistance[N2][N2];
PUZZLE jyoutai;
int limit;//深さのlimit
int miti[LIMITMAX];

int GetallManhattanDistance(PUZZLE);
bool dfs(int, int);
//int max(int, int);
