  for(i=0;i<N2;i++){
    for(j=0;j<N2;j++){
      ManhattanDistance[i][j] = abs( i/N1 - j/N1 ) + abs(i%N1 -j%N1); 
    }
  }


  for(i=0;i<N2;i++){
    cin >> in.f[i];
