*/
int GetallManhattanDistance(PUZZLE p){//全てのマンハッタン距離を取得する

  int goukei = 0;
  int i,j,k;

  for(i=0;i<N2;i++){
    if(p.f[i] == N2)continue;
    goukei += ManhattanDistance[i][p.f[i]-1];
  }

  return goukei;
}

bool dfs(int depth, int prev){

  int i,j,k;
  int r;
  int sx,sy;
  PUZZLE tmp;
  int tx,ty;

  if(jyoutai.MD == 0) return true ;
  //現在の深さにヒューリスティックを足して制限を超えたら枝を切る

  if( depth + jyoutai.MD > limit ) return false;

  sx = jyoutai.kuuhaku / N1;
  sy = jyoutai.kuuhaku % N1;

  for(r=0;r<4;r++){
    tx = sx + dx_123[r];
    ty = sy + dy_123[r];

    if(tx < 0 || tx >= N1 || ty < 0 || ty >= N1 ) continue;
    if(max(prev, r) - min(prev, r) == 2 ) continue;
    tmp = jyoutai;
    //マンハッタン距離の差分を計算しつつ、ピースをスワップ
    jyoutai.MD -= ManhattanDistance[tx * N1 + ty][jyoutai.f[tx * N1 + ty]-1];
    jyoutai.MD += ManhattanDistance[sx * N1 + sy][jyoutai.f[tx * N1 + ty]-1];
    swap(jyoutai.f[tx * N1 + ty], jyoutai.f[sx * N1 + sy]);
    jyoutai.kuuhaku = tx * N1 + ty;
    if( dfs(depth + 1, r) ){
      miti[depth] = r;
      return true;
    }
    jyoutai = tmp;
  }

  return false;
}
