string  iterative_deepning(PUZZLE in){//反復深化

  int i,j,k;
  //string  kotae = "";
  //char kotae2[] = "unsolvable";

  in.MD = GetallManhattanDistance(in);//初期のマンハッタン距離

  for(limit = in.MD; limit <= LIMITMAX; limit++ ){
    jyoutai = in;
    if( dfs(0, -100) ){
      string kotae = "";
      for(i = 0; i < limit; i++) kotae += houkou[miti[i]];
      return kotae;
    } 
  }

  return "できませんでした";

}

