int dx[] = { 0, 1, 0, -1 };
int dy[] = { 1, 0, -1, 0 };
int MDT[4][4][16];

struct Point {
    int x;
    int y;
};

void dfs(Point nowpos, Point prevpos, int depth) {
    if (MD == 0) {
        ans = true;
        return;
    }
    if (depth + MD > limit) {
        return;
    }

    int MD_bk = MD;
    for (int i = 0; i < 4; i++) {
        Point nextpos = nowpos;
        nextpos.x += dx[i];
        nextpos.y += dy[i];
        if (nextpos.x < 0 || nextpos.x > 3 || nextpos.y < 0 || nextpos.y > 3 || (nextpos.y == prevpos.y && nextpos.x == prevpos.x)) {
            continue;
        }
        MD = MD_bk - MDT[nextpos.y][nextpos.x][field[nextpos.y][nextpos.x]] + MDT[nowpos.y][nowpos.x][field[nextpos.y][nextpos.x]];
        swap(field[nextpos.y][nextpos.x], field[nowpos.y][nowpos.x]);
        dfs(nextpos, nowpos, depth + 1);
        swap(field[nextpos.y][nextpos.x], field[nowpos.y][nowpos.x]);
    }
}

void calc_MD() {
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 1; k <= 15; k++) {
                MDT[i][j][k] = abs(i - (k - 1) / 4) + abs(j - (k - 1) % 4);
            }
        }
    }
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            if (field[i][j] != 0) {
                MD += MDT[i][j][field[i][j]];
            }
        }
    }
}

