            }
        }
    }
    calc_MD();

    temp.x = temp.y = -1;
    for (int i = 0; i <= 45; i++) {
        limit = i;
        dfs(space, temp, 0);
        if (ans == true) {
            cout << i << endl;
            break;
        }
    }

    return 0;
}

