using namespace std;

#define N 4
#define NPANEL (N * N)
#define EMPTY 0

int manhattan_sum(short panels[]) {
  int result = 0;
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      int v = panels[i * N + j] - 1;
      if (v == EMPTY - 1)
        v = NPANEL - 1;
      int tmp = abs(i - v / N) + abs(j - v % N);
      result += tmp;
    }
  }
  return result;
}

class State {
public:
  short panels[NPANEL];
  short empty;
  int estimate;
  State(short p[]) {
    for (int i = 0; i < NPANEL; i++) {
      panels[i] = p[i];
      if (p[i] == EMPTY)
        empty = i;
    }
    estimate = manhattan_sum(panels);
  }
  void print() {
    for (int i = 0; i < NPANEL; i++) {
      if (i != 0 && i % N == 0)
        printf("\n");
      printf("%d ", panels[i]);
    }
    printf("\n");
  }
  bool is_completed() {
    for (int i = 1; i < NPANEL; i++)
      if (panels[i - 1] != i)
        return false;
    return true;
  }
  State left() { return slide(empty, empty - 1); }
  State above() { return slide(empty, empty - N); }
  State right() { return slide(empty, empty + 1); }
  State bottom() { return slide(empty, empty + N); }
  State slide(int x, int y) {
    auto s = State(panels);
    swap(s.panels[x], s.panels[y]);
    s.empty = y;
    s.estimate = manhattan_sum(s.panels);
    return s;
  }

  vector<State> nexts() {
    vector<State> v;
    if (empty % N != 0)
      v.push_back(left());
    if (empty >= N)
      v.push_back(above());
    if (empty % N != N - 1)
      v.push_back(right());
    if (empty <= NPANEL - N - 1)
      v.push_back(bottom());
    return v;
  }
  bool operator<(const State &s) const {
    for (int i = 0; i < NPANEL - 1; i++) {
      if (panels[i] == s.panels[i])
        continue;
      return panels[i] < s.panels[i];
    }
    return false;
  }
};

