class board{
public:
	vector<vector<int>> data;
	int ncost;
	int hcost;
	PII zpoint;

	int culonecost(int i, int j){
		if(data[i][j]==0){
			return abs(SIZE-1-i) + abs(SIZE-1-j);
		}
		int x = (data[i][j]-1)%SIZE;
		int y = (data[i][j]-1)/SIZE;
		return abs(i-y) + abs(j-x);
	}

	void setup(){
		hcost = 0;
		REP(i, SIZE){
			REP(j, SIZE){
				hcost+=culonecost(i, j);
				if(data[i][j]==0){
					zpoint=PII(i, j);
				}
			}
		}
	}

	board(vector<vector<int>> d){
		REP(i, SIZE){
			REP(j, SIZE){
				data[i][j]=d[i][j];
			}
		}
		hcost = 0;
		setup();
	}

	board(){
		data.resize(SIZE, vector<int>(SIZE));
	}

	void swap(int i, int j, int k, int l){
		hcost -= culonecost(i, j);
		hcost -= culonecost(k, l);
		std::swap(data[i][j], data[k][l]);
		hcost += culonecost(i, j);
		hcost += culonecost(k, l);
		if(data[i][j]==0){
			zpoint=PII(i, j);
		}else{
			zpoint=PII(k, l);
		}
	}

	bool onboard(int i, int j){
		return 0<=i&&0<=j&&i<SIZE&&j<SIZE;
	}

};

int mx[]={1, 0, -1, 0}, my[]={0, 1, 0, -1};

bool func(board &boa, int time, int lx, int ly){
	if(boa.hcost - boa.culonecost(boa.zpoint.first, boa.zpoint.second) > time * 1)return false;
	if(boa.hcost==0)return true;
	bool res = false;
	REP(i, 4){
		int y = boa.zpoint.first;
		int x = boa.zpoint.second;
		int ny = y + my[i];
		int nx = x + mx[i];
		if(lx==nx&&ly==ny)continue;
		if(!boa.onboard(ny, nx))continue;
		boa.swap(y, x, ny, nx);
		res |= func(boa, time-1, x, y);
		boa.swap(y, x, ny, nx);
		if(res)return true;
	}
	return res;
}


