  }
  return true;
}

bool dfs(int depth){
  stack<game> s;
  s.push(start);

  while(!s.empty()){
    game g=s.top();s.pop();
    if(depth==g.depth){
      if(is_goal(g)) return true;
      continue;
    }

    if(g.depth+g.mnh>MAX_DEPTH) continue;

    for(int move:move_list[g.w]){
      if(g.last_move==-move) continue;
      game h=g;
      h.mnh -= dist[h.w+move][h.board[h.w+move]-1];
      h.mnh += dist[h.w][h.board[h.w+move]-1];
      swap(h.board[h.w],h.board[h.w+move]);
      h.w = h.w+move;
      h.depth++;
      h.last_move=move;
      s.push(h);
    }
  }
  return false;
}

void initialize(){
  for(int i=0;i<N2;i++){
    if(i%N<N-1) move_list[i].push_back(1);
    if(i%N>0  ) move_list[i].push_back(-1);
    if(i/N<N-1) move_list[i].push_back(N);
    if(i/N>0  ) move_list[i].push_back(-N);
  }

  //i=board,j=piece-1
  for(int i=0;i<N2;i++){
    for(int j=0;j<N2;j++){
      dist[i][j] = abs(j%N-i%N) + abs(j/N-i/N);
    }
  }

  start.mnh=0;
  for(int i=0;i<N2;i++){
    if(i==start.w) continue;
    start.mnh += dist[i][start.board[i]-1];
  }
}

int solve(){
  initialize();
  for(int i=1;i<MAX_DEPTH;i++){
    if(dfs(i)){
      return i;
    }
  }
  return -1;
}

int main(){
  for(int i=0;i<N2;i++){
    int tmp; cin>>tmp;
    if(tmp==0){
      start.board[i]=N2;
      start.w=i;
    }else{
      start.board[i]=tmp;
    }
  }
  start.depth=0;
  start.last_move=0;

  cout<<solve()<<endl;
}

