const int N = 16;
const int sN = 4;
const double fq = 1.27;

struct pz{
	int a[N];
	int t;

	bool operator < (const pz &p) const {
		for (int i = 0; i < N; i++) {
			if (a[i] == p.a[i])
				continue;
			return a[i] > p.a[i];
		}
		return false;
	}
};

int dis(int a[]) {
	int d = 0;
	for (int i = 0; i < N; i++)
		d += abs((a[i] - 1) / sN - i / sN) + abs((a[i] - 1) % sN - i % sN);
	return d;
}

int main()
{
	pz p;
	int n = -1;
	map<pz, bool> v;

	for (int i = 0; i < N; i++)
		cin >> p.a[i];

	p.t = 0;
	int mxD = min(dis(p.a) + 15, 46);

	queue<pz> que;
	que.push(p);
	v[p] = true;

	while (!que.empty()) {
		pz g = que.front();
		que.pop();

		bool f = 1;

		for (int i = 0; i < N - 1; i++) {
			if (g.a[i] != (i + 1)) {
				f = 0;
				break;
			}
		}

		if (f == 1) {
			n = g.t;
			break;
		}

		for (int i = 0; i < N; i++) {
			if (g.a[i] == 0) {
				if(i % sN != 0){
					g.t++;
					swap(g.a[i], g.a[i - 1]);
					if (!v[g] && g.t + dis(g.a) < mxD) {
						v[g] = true;
						que.push(g);
					}
					swap(g.a[i], g.a[i - 1]);
					g.t--;
				}
				if (i % sN != sN - 1) {
					g.t++;
					swap(g.a[i], g.a[i + 1]);
					if (!v[g] && g.t + dis(g.a) < mxD) {
						v[g] = true;
						que.push(g);
					}
					swap(g.a[i], g.a[i + 1]);
					g.t--;
				}
				if (i / sN != 0) {
					g.t++;
					swap(g.a[i], g.a[i - sN]);
					if (!v[g] && g.t + dis(g.a) < mxD) {
						v[g] = true;
						que.push(g);
					}
					swap(g.a[i], g.a[i - sN]);
					g.t--;
				}
				if (i / sN != sN - 1) {
					g.t++;
					swap(g.a[i], g.a[i + sN]);
					if (!v[g] && g.t + dis(g.a) < mxD) {
						v[g] = true;
						que.push(g);
					}
					swap(g.a[i], g.a[i + sN]);
					g.t--;
				}
			}
		}
	}

	cout << n << endl;

	return 0;
}

#include <stdio.h>
