                 		1,3,2,0,2,1,2,2,2,3,3,0,3,1,3,2};
int dir[4][2] = {1,0,-1,0,0,1,0,-1};

int judge() //空滑块所在的行加上逆序数为偶数有解
{
	int cnt = 0;
	for(int i=0; i<16; i++)
	{
		if(st[i] == 0)
		{
			cnt += 1+i/4;
		}

		for(int j=i+1; j<16; j++)
		{
			if(st[j] && st[i] > st[j])
				cnt++;
		}
	}
	return !(cnt%2);
}

int mhd()
{
	int cnt=0;
	for(int i=0; i<16; i++)
	{
		if(st[i] == 0)
			continue;
		int tt = st[i];
		cnt += abs(i/4-goal[tt][0]) + abs(i%4-goal[tt][1]);
	}
	return cnt;
}

int dfs(int xy,int pre_move,int d,int mv_len)
{
	if(d+mhd() > mv_len)
		return 0;
	if(d==mhd())
		return memcmp(st,en,sizeof(st))==0;

	for(int i=0; i<4; i++)
	{
		if(i+pre_move == 3)
			continue;
		int dx = xy/4 + dir[i][0];
		int dy = xy%4 + dir[i][1];
		int dz = dx*4 + dy;
		if(dx>=0 && dy>=0 &&dx<4 && dy<4)
		{
			swap(st[xy],st[dz]);
			if(dfs(dz,i,d+1,mv_len))
				return 1;
			swap(st[xy],st[dz]);
		}
	}
}

