int d_x[4] = { -1,0,1,0 };
int d_y[4] = { 0,1,0,-1 };

int t[4][4];
int level = 0;

int countpath() {
	int ret = 0;
	int tmp;
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			if (t[i][j] != 0) {
				tmp = t[i][j] - 1;
				ret += abs(tmp / 4 - i) + abs(tmp % 4 - j);
			}
		}
	}
	return ret;
}

bool check(int depth, int pre, int px, int py) {
	int w = countpath();
	if (w + depth > level) return false;
	if (w == 0)return true;
	int dx, dy;
	for (int i = 0; i < 4; i++) {
		if (abs(i - pre) != 2) {
			dx = px + d_x[i];
			dy = py + d_y[i];
			if (dx < 0 || dx == 4 || dy < 0 || dy == 4) continue;
			swap(t[dx][dy], t[px][py]);
			if (check(depth + 1, i, dx, dy)) return true;
			swap(t[dx][dy], t[px][py]);
		}

	}
	return false;
}

void solution(int px, int py) {
	for (level = 0;; level++) {
		if (check(0, 9, px, py)) {
			cout << level << endl;
			return;
		}
	}
}

