static const int dx[4] = {0, -1, 0, 1};
static const int dy[4] = {1, 0, -1, 0};
static const char dir[4] = {'u', 'l', 'd', 'r'};
int mdt[N2][N2];

struct Puzzle {
    int f[N2], space, md;
    int cost;

    bool operator<(const Puzzle &p) const {
        REP(i, N2) {
            if (f[i] == p.f[i]) continue;
            return f[i] < p.f[i];
        }
        return false;
    }
};

struct State {
    Puzzle p;
    int e;
    bool operator<(const State &s) const { return e > s.e; }
};

int getAllMd(Puzzle p) {
    int sum = 0;
    REP(i, N2) {
        if (p.f[i] == N2) continue;
        sum += mdt[i][p.f[i] - 1];
    }
    return sum;
}

int astar(Puzzle p) {
    priority_queue<State> pq;
    p.md = getAllMd(p);
    p.cost = 0;
    map<Puzzle, bool> m;
    State init;
    init.p = p;
    init.e = p.md;
    pq.push(init);

    while (!pq.empty()) {
        State st = pq.top();
        pq.pop();
        Puzzle u = st.p;
        if (u.md == 0) return u.cost;
        m[u] = true;

        int sx = u.space / N;
        int sy = u.space % N;
        REP(i, 4) {
            int tx = sx + dx[i];
            int ty = sy + dy[i];
            if (tx < 0 || ty < 0 || tx >= N || ty >= N) continue;
            Puzzle v = u;
            v.md -= mdt[tx * N + ty][v.f[tx * N + ty] - 1];
            v.md += mdt[sx * N + sy][v.f[tx * N + ty] - 1];

            swap(v.f[sx * N + sy], v.f[tx * N + ty]);
            v.space = tx * N + ty;
            if (!m[v]) {
                v.cost++;
                State news;
                news.p = v;
                news.e = v.cost + v.md;
                pq.push(news);
            }
        }
    }
    return -1;
}

