    int dist_ev = Node[nextHash].dist + estimateH(nextCell,nextHash);
		Q.insert(make_pair(dist_ev, nextHash));
  }
  return;
}

void move(vector<int> curCell, string curHash){
  for(int i = 0 ; i < SIZE ; i++ ){
    if(curCell[i] == 0){
      if(Move[i][LEFT]){
        updateGQ(curCell, i, -1, curHash); 
      }
      if(Move[i][RIGHT]){
        updateGQ(curCell, i, 1, curHash); 
      }
      if(Move[i][UP]){
        updateGQ(curCell, i, -4, curHash); 
      }
      if(Move[i][DOWN]){
        updateGQ(curCell, i, 4, curHash); 
      }
    }
  }
  return;
}

