typedef struct Node
{
    int puzzle[N2];
    int space;
    int md;
    int depth;
    int pre;
} Node;


Node s_node;
Node cur_n;
int md[N2][N2];
int ans;

void input_table() {
    s_node = Node();
    int in[N2];
    for (int i = 0; i < N2; ++i)
    {
        int tmp;
        scanf("%d", tmp)
        cin >> tmp;
        if(tmp == 0) {
            tmp = N2;
