    in.MD=getAllMD(in);

    for(limit=in.MD;limit<=LIMIT;++limit){
        state=in;
        if(dfs(0,-100)){
            string ans="";
            for(int i=0;i<limit;++i){
                ans+=dir[path[i]];
            }
            return ans;
        }
    }
    return "unsolvable";
}

