};

bool check(BOARD &b) {
    for (int i = 0; i < boardw; ++i) {
        for (int j = 0; j < boardw; ++j) {
            if (b.map[i][j] == 0) continue;
            int tgt = i * boardw + j + 1;
            if (b.map[i][j] != tgt) {
                return false;
            }
        }
    }
    return true;
}

int dfs(BOARD &b, int depth, int dir) {
    if (depth == 0) {
        if (check(b)) {
            return 1;
        } else {
            return -1;
        }
    }

    int px, py;
    for (int i = 0; i < boardw; ++i) {
        for (int j = 0; j < boardw; ++j) {
            if (b.map[i][j] == 0) {
                px = j;
                py = i;
            }
        }
    }
    int est = 0;
    for (int i = 0; i < boardw; ++i) {
        for (int j = 0; j < boardw; ++j) {
            if (i * j == boardw * boardw) continue;
            for (int k = 0; k < boardw; ++k) {
                for (int l = 0; l < boardw; ++l) {
                    if (i * boardw + j + 1 == b.map[k][l]) {
                        est += std::abs(k - i) + std::abs(l - j);
                    }
                }
            }
        }
    }
    if (est > depth) {
        return -1;
    }
    int dx[] = {0, 1, 0, -1};
    int dy[] = {1, 0, -1, 0};
    for (int k = 0; k < 4; k++) {
        if (dir != -1 && k == (dir + 2) % 4) {
            continue;
        }
        int tx = px + dx[k];
        int ty = py + dy[k];
        if (tx < 0 || tx >= boardw || ty < 0 || ty >= boardw) continue;
        int temp = b.map[py][px];
        b.map[py][px] = b.map[ty][tx];
        b.map[ty][tx] = temp;

        int ret = dfs(b, depth - 1, k);

        temp = b.map[py][px];
        b.map[py][px] = b.map[ty][tx];
        b.map[ty][tx] = temp;
        if (ret != -1) return ret;
    }
    return -1;
}

