			tts.puzzle[zeroi + 1] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (find(checkedState.begin(), checkedState.end(), tts) == checkedState.end())
			{
				pq.push(tts);
			}
		}
		if (zeroi % 4 != 0)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi - 1];
			tts.puzzle[zeroi - 1] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (find(checkedState.begin(), checkedState.end(), tts) == checkedState.end())
			{
				pq.push(tts);
			}
		}
		if (4 <= zeroi)
		{
			State tts = ts;
			int t = tts.puzzle[zeroi];
			tts.puzzle[zeroi] = tts.puzzle[zeroi - 4];
			tts.puzzle[zeroi - 4] = t;
			tts.depth++;
			tts.evaluation = heuristic(tts) + tts.depth;
			if (find(checkedState.begin(), checkedState.end(), tts) == checkedState.end())
			{
				pq.push(tts);
			}
		}
	}

	return -1;
}

