class board{
public:
    int moves;
    int wrongs;
    int zero_place;
    int cost;
    char pre;
    vector<int> tiles;
    ll k;

    explicit board(vector<int> num, int move, char pr, ll id, int zp, int w){
        wrongs = w;
        k = id;
        tiles = num;
        if(pr == 'a'){
            REP(i, 16){
                if(k < 11)
                    k += num[i + 5] * pow(16, i);
                if(num[i] == 0)
                    zero_place = i;
                else
                    wrongs += dist[num[i]][(answer[i] + 15)%16];
            }
            searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]].push_back(k);
        }
        else{
            zero_place = zp;
            wrongs = w;
        }
        moves = move;
        cost = wrongs + moves;
        pre = pr;
    }

    void board_to_int(char p, int d){
        ll new_k;
        int new_w = wrongs - dist[tiles[zero_place + d]][zero_place + d] + dist[tiles[zero_place + d]][zero_place];
        if(zero_place > 4 && zero_place + d > 4){
            new_k = k - (tiles[zero_place + d] * pow(16, (zero_place+d))) + (tiles[zero_place] * pow(16, zero_place));
            for(int i = searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]].size(); i > 0 ; i--)
                if(new_k == searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]][i-1])
                    return;
            swap(tiles[zero_place], tiles[zero_place + d]);
        } else if(zero_place < 5 && zero_place + d < 5){
            new_k = k;
            swap(tiles[zero_place], tiles[zero_place + d]);
            for(int i = searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]].size(); i > 0 ; i--)
                if(new_k == searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]][i-1]){
                    swap(tiles[zero_place], tiles[zero_place + d]);
                    return;
                }
        } else if(zero_place < 5){
            new_k = k - (tiles[zero_place + d] * pow(16, (zero_place+d)));
            swap(tiles[zero_place], tiles[zero_place + d]);
            for(int i = searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]].size(); i > 0 ; i--)
                if(new_k == searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]][i-1]){
                    swap(tiles[zero_place], tiles[zero_place + d]);
                    return;
                }
        } else{
            new_k = k + (tiles[zero_place] * pow(16, zero_place));
            swap(tiles[zero_place], tiles[zero_place + d]);
            for(int i = searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]].size(); i > 0 ; i--)
                if(new_k == searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]][i-1]){
                    swap(tiles[zero_place], tiles[zero_place + d]);
                    return;
                }
        }
        pq.push(board(tiles, moves+1, p, new_k, zero_place + d, new_w));
        searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]].push_back(new_k);
        swap(tiles[zero_place], tiles[zero_place + d]);
        return;
    }

    void move() {
        if(dir[zero_place][0] && pre != 'l')
            board_to_int('r', -1);
        if(dir[zero_place][1] && pre != 'u')
            board_to_int('d', -4);
        if(dir[zero_place][2] && pre != 'd')
            board_to_int('u', 4);
        if(dir[zero_place][3] && pre != 'r')
            board_to_int('l', 1);
    }
};

bool operator< (board b1, board b2){
    return ((b1.cost > b2.cost) ? true : false);
}

int solve(){
    pq.push(board(original, 0, 'a', 0, 0, 0));
    while(1){
        auto target = pq.top();
        if(target.wrongs == 0)
            return target.moves;
        pq.pop();
        target.move();
    }
}

