struct Puzzle{
  int f[N2],space,MD;
};

Puzzle state;
int limit;
int path[L];

int get(Puzzle pz){
  int sum=0;
  int i;

  for(i=0;i<N2;i++){
    if(pz.f[i]==N2) continue;
    sum+=MDT[i][pz.f[i]-1];
  }
  return sum;
}

bool is(){
  int i;
  for(i=0;i<N2;i++)
    if(state.f[i]!=i+1)
      return false;
  return true;
}

