const int N=4;

struct state{
  vector<int> board;
  int dist;
  int bi,bj;
  int miss_cnt;
  int mh_dist;
  int pre;
};

int h0(const state& s){
  return s.dist;
}
int h1(const state& s){
  return s.dist+s.miss_cnt;
}
int h2(const state& s){
  return s.dist+s.mh_dist;
}

int di[]={0,1,0,-1};
int dj[]={1,0,-1,0};

