}
int Solve(const TBoard& Start, const TBoard& Goal)
{
    std::priority_queue<TState, std::vector<TState>, TGreater> Open;
    std::map<TBoard, int> Table;
    Open.push(TState(Start, 0));

    while(!Open.empty()){
        TState State = Open.top();
        Open.pop();
        // Print(State.Board, ' ');
        // std::cerr << " Cost:" << State.Cost << ", Estimate:" << State.Total - State.Cost << ", Total:" << State.Total << std::endl;
        if(State.Board == Goal) return State.Cost;
        int Cost  = State.Cost + 1;
        std::vector<TBoard> Boards = GetMoved(State.Board);
        for(std::size_t i = 0; i < Boards.size(); ++i){
            const TBoard Board = Boards[i];
            std::map<TBoard, int>::iterator It = Table.find(Board);
            if(It == Table.end() || Cost < It->second){
                Table[Board] = Cost;
                Open.push(TState(Board, Cost));
                // Print(Board, '\t');
            }
        }
    }
    assert(false);
}
