  for(int i=0;i<N2;i++){
    int tmp; cin>>tmp;
    if(tmp==0){
      start.board[i]=N2;
      start.w=i;
    }else{
      start.board[i]=tmp;
    }
  }
  start.depth=0;
  start.last_move=0;

  cout<<solve()<<endl;
}

