#include<bits/stdc++.h>

using namespace std;

typedef unsigned long long ull;

class Puzzle
{
public:
    vector<int> pos;
    int g,e;

    ull P=1e8+7;

    Puzzle()
    {
        pos.resize(16);
    }

    bool operator < (const Puzzle & b) const
    {
        return e<b.e;
    }

    bool operator > (const Puzzle & b) const
    {
        return e>b.e;
    }


    bool finished()
    {
        bool flag=true;
        for(int i=0;i<15;i++)
        {
            if(pos[i]!=i+1)
            {
                flag=false;
            }
        }
        if(pos[15]!=0)
        {
            flag=false;
        }
        return flag;
    }

    int mhd(int a,int b)
    {
        return abs(a/4-b/4)+abs(a%4-b%4);
    }

    int getPos(int a)
    {
        int p;
        if(a==0)
        {
            p=15;
        }else
        {
            p=a-1;
        }
        return p;
    }

    int estimate()
    {
        int sum=0;
        for(int i=0;i<16;i++)
        {
            sum+=mhd(i,getPos(pos[i]));
        }
        sum-=mhd(getZero(),15);
        return sum;
    }

    ull getHash()
    {
        ull Hash=0;
        for(int i=0;i<16;i++)
        {
            Hash=Hash*P+pos[i];
        }
        return Hash;
    }

    int getZero()
    {
        for(int i=0;i<16;i++)
        {
            if(pos[i]==0) return i;
        }
        return 0;
    }

    void _swap(int i,int j)
    {
        swap(pos[i],pos[j]);
    }
};


int dr[4]={1,0,-1,0},dc[4]={0,1,0,-1};

int aStar(Puzzle puzzle)
{
    priority_queue<Puzzle,vector<Puzzle>,greater<Puzzle> > st;

    map<ull,bool> used;

    puzzle.g=0;
    puzzle.e=puzzle.estimate();
    st.push(puzzle);
    used[puzzle.getHash()]=true;

    while(!st.empty())
    {
        Puzzle tmp=st.top();st.pop();
        if(tmp.g>45) continue;
        if(tmp.finished())
        {
            return tmp.g;
        }
        int idx=tmp.getZero();
        int r=idx/4,c=idx%4;
        for(int i=0;i<4;i++)
        {
            int rr=r+dr[i],cc=c+dc[i];
            if(rr<4&&rr>=0&&cc<4&&cc>=0)
            {
                Puzzle newP=tmp;
                newP._swap(idx,rr*4+cc);
                if(!used[newP.getHash()])
                {
                    used[newP.getHash()]=true;
                    newP.g=tmp.g+1;
                    newP.e=newP.g+newP.estimate();
                    st.push(newP);
                }
            }
        }
    }

    return -1;
}

