int mandist(vector<int> a){
  int dist = 0;
  for(int i=0; i<16; i++){
    int tmp = (a[i] == 0 ? 16 : a[i]);
    int x = i % 4; int y = i / 4;
    int tx = (tmp-1) % 4; int ty = (tmp-1) / 4;
    dist += abs(x-tx) + abs(y-ty);
    // cerr << a[i] << " " << abs(x-tx) + abs(y-ty) << endl;
  }
  return -dist;
}

void bfs(vector<int> sss){
  priority_queue< pair< int, pair<int, vector<int> > > > q;
  q.push(make_pair(mandist(sss), make_pair(0, sss)));
  map< vector<int>, bool> mpb;
  while( !q.empty() ){
    pair< int, pair<int, vector<int> > > p = q.top();
    q.pop();

    vector<int> s = p.second.second;
    mpb[s] = true;
    if( check(s) ){
      cout << p.second.first << endl;
      return;
