	for (int r = 0; r < nd; r++) {
		if (max(r, prev) - min(r, prev) == 2) continue;
		tx = sx + ud[r];
		ty = sy + lr[r];
		if (tx >= nd || tx < 0 || ty >= nd || ty < 0) continue;
		ns = tx * nd + ty;
		tmp.mdp = pu.mdp - md[ns][pu.p[ns]-1] + md[sx*nd + sy][pu.p[ns]-1];
		tmp.sp = ns;
		swap(tmp.p[ns], tmp.p[tmp.sp]);
		if (dfs(de + 1, r, tmp)) { way.push_back(r); return true;};
	}
}
