		for (int j = 0; j < num; j++)
			md[i][j] = abs(i / nd - j / nd) + abs(i%nd - j%nd);
	for (int i = 0; i < num; i++) {
		if (pu.p[i] == 0) continue;
		sum += md[i][pu.p[i] - 1];
	}
