    {
        FOR(y, 0, W){
            FOR(x, 0, W){
                if(A[y][x] != b.A[y][x]){
                    return A[y][x] < b.A[y][x];
                }
            }
        }
        return false;
    }

    bool is_solved(){
        FOR(y, 0, W){
            FOR(x, 0, W){
                ll target = W*y + x + 1;
                if(y==W-1 && x==W-1) target = 0;
                if(A[y][x]!=target) return false;
            }
        }
