template<class T, class D>
class HashTable{
public:
  using ull = unsigned int;
  ull tableSize;
  vector<vector<T> > tableKey;
  vector<vector<D> > tableVal;

  HashTable(ull tableSize = 500009){
    for(int i=2;i*i<=tableSize;i++)
      assert(tableSize % i != 0 && "tableSize have to be prime number");
    this->tableSize = tableSize;
    tableKey.resize(tableSize);
    tableVal.resize(tableSize);

  }

  void push(T key, D val, ull hash){
    hash %= tableSize;
    tableKey[hash].push_back_fast(key);
    tableVal[hash].push_back_fast(val);
  }

  bool count(T key, ull hash){
    hash %= tableSize;
    int count = 0;
    for(int i=0;i<tableKey[hash].size();i++)
      if(tableKey[hash][i] == key) count++;
    return count;
  }

  bool exist(T key, ull hash){
    hash %= tableSize;
    for(int i=0;i<tableKey[hash].size();i++) if(tableKey[hash][i] == key) return true;
    return false;
  }

  D& getVal(T key, ull hash){
    hash %= tableSize;
    if(tableKey[hash].size() == 1) return tableVal[hash][0];
    for(int i=0;i<tableKey[hash].size();i++)
      if(tableKey[hash][i] == key) return tableVal[hash][i];

    assert(!"key not exists");
  }
};

template<class T>
void swap(T &a, T &b){
  T tmp = a;
  a = b;
  b = tmp;
}

template<typename T>
class Priority_queue{
public:
  T *A;
  int H;
  int limitSize;
  int sz;
  T MIN;

  constexpr Priority_queue(){H = 0, sz = 0;}
  constexpr Priority_queue(int size, T mn){
    MIN = mn;
    A = new T[size];
    H = 0;
    limitSize = size;
    sz = 0;
  }

  int size(){return sz;}
  int empty(){return sz == 0;}

  void swap(T &a, T & b){
    T tmp = a;
    a = b;
    b = tmp;
  }

  void maxHeapify(int i){
    int l=i * 2;
    int r=i * 2 + 1;
    int largest;
    if(l <= H && A[i] < A[l]) largest = l;
    else largest = i;

    if(r <=H && A[largest] < A[r]) largest = r;

    if(largest != i) {
      swap(A[i], A[largest]);
      maxHeapify(largest);
    }
  }

  void heapIncreaseKey(int i, const T &key){
    A[i] = key;
    while(i > 1 && A[i/2] < A[i]){
      swap(A[i], A[i/2]);
      i /= 2;
    }
  }

  void push(const T &k){
    assert(sz < limitSize);
    sz++;
    H++;
    A[H] = MIN;
    heapIncreaseKey(H, k);  
  }

  T top(){return A[1];}

  T pop(){
    sz--;
    T res = A[1];
    A[1] = A[H];
    H--;
    maxHeapify(1);
    return res;
  }
};


using D = vector<vector<int> >;
const int N = 4;

unsigned long long toHash(D &mp, const unsigned long long B){
  using ull = unsigned long long;
  ull hash = 0;
  for(int i=0;i<N;i++)
    for(int j=0;j<N;j++) hash = hash * B + mp[i][j];
  return hash;
}

unsigned long long getHash(D &mp,unsigned long long hash, int i, int j,int ni, int nj,int flag = 0){
  using ull = unsigned long long;
  static int init = 1;
  const ull B[2] = {17, 1777771};
  static ull pow[2][20];
  if(init){
    init = 0;
    for(int i=0;i<2;i++){
      pow[i][0] = 1;
      for(int j=1;j<20;j++) pow[i][j] = pow[i][j-1] * B[i];
    }
  }

  int idx1 = i * N + j;
  int idx2 = ni * N + nj;
  ull p1 = pow[flag][N * N - 1 - idx1];
  ull p2 = pow[flag][N * N - 1 - idx2];
  return hash - (mp[ni][nj] * p1 + mp[i][j] * p2) + (mp[i][j] * p1 + mp[ni][nj] * p2);
}

int calcCost(D &pos, D &goal){
  static int idxX[N * N], idxY[N * N], flag = 0;
  if(flag == 0){
    flag = 1;
    for(int i=0;i<N;i++)
      for(int j=0;j<N;j++) idxX[goal[i][j]] = j, idxY[goal[i][j]] = i;
  }

  auto abs = [](int a){return a < -a? -a:a;};
  int res = 0;  
  for(int i=0;i<N;i++)
    for(int j=0;j<N;j++){
      if(pos[i][j] == 0) continue;
      res += abs(i - idxY[pos[i][j]]) + abs(j - idxX[pos[i][j]]);
    }

  return res;
}

int calcDiff(D &pos, D &goal, int i, int j, int ni, int nj){
  static int idxX[N * N], idxY[N*N], flag = 0;
  if(flag == 0){
    flag = 1;
    for(int i=0;i<N;i++)
      for(int j=0;j<N;j++) idxX[goal[i][j]] = j, idxY[goal[i][j]] = i;
  }

  int a =
    (pos[ni][nj] != 0 ) * (abs(i - idxY[ pos[ni][nj] ]) + abs(j - idxX[ pos[ni][nj] ])) +
    (pos[i][j] != 0 ) * (abs(ni - idxY[ pos[i][j] ]) + abs(nj - idxX[ pos[i][j] ]));


  int b =
    (pos[i][j] != 0 ) * (abs(i - idxY[ pos[i][j] ]) + abs(j - idxX[ pos[i][j] ])) + 
    (pos[ni][nj] != 0 ) * (abs(ni - idxY[ pos[ni][nj] ]) + abs(nj - idxX[ pos[ni][nj] ]));
  return -a + b;
}

int dijkstra(D start, D goal){

  using ull = unsigned long long;
  const ull B1 = 17;
  const ull B2 = 1777771;
  const ull hashGoal = toHash(goal, B2);
  using P = Pair<int, short>;
  using Pu = Pair<ull, unsigned long long>;
  using PP = Pair<P, Pu>;
  Priority_queue <PP> Q(330000, PP(P(-100000000,-100), Pu(0, 0)));

  Q.push(PP(P(-calcCost(start, goal), 0), Pu(toHash(start, B2), toHash(start, B1))));

  HashTable <ull, int> memo(200017); //<key, val>
  HashTable <ull, D> memo2(200017); // <key, val>
  memo.push(toHash(start, B2), 0, toHash(start, B1));
  memo2.push(toHash(start, B2), start, toHash(start, B1));

  int cnt = 0;
  while(!Q.empty()){
    cnt++;
    int cost1 = -Q.top().first.first;
    int cost2 = Q.top().first.second;
    ull hash1 = Q.top().second.second;
    ull hash2 = Q.top().second.first;
    Q.pop();
    D mp = memo2.getVal(hash2, hash1);
    if(hash2 == hashGoal && mp == goal) return cost2;

    //if(cnt % 10000 == 0) pr(cnt, cost1, cost2, Q.size());

    for(int i=0;i<N;i++)
      for(int j=0;j<N;j++){
	if(j+1<N && (mp[i][j] == 0 || mp[i][j+1] == 0)){
	  D &key = mp; swap(key[i][j], key[i][j+1]);
	  int val = cost2 + 1;
	  ull nhash1 = getHash(key, hash1, i, j, i, j+1, 0);
	  ull nhash2 = getHash(key, hash2, i, j, i, j+1, 1);
	  if(!memo.exist(nhash2, nhash1)) {
	    memo.push(nhash2, val, nhash1);
	    memo2.push(nhash2, key, nhash1);
	    int ncost1 = cost1 + calcDiff(key, goal, i, j, i, j+1) + 1;
	    if(ncost1 <= 45) Q.push(PP(P(-ncost1, val), Pu(nhash2, nhash1)));
	    //assert(ncost1 == calcCost(key, goal) + val);
	    //assert(getHash(key, hash1, i, j, i, j+1, 0) == toHash(key, B1));
	    //assert(getHash(key, hash2, i, j, i, j+1, 1) == toHash(key, B2));

	  }
	  swap(key[i][j], key[i][j+1]);
	}

