using ull = unsigned int;
const int N = 4;
using mat = vector<vector<char> >;

int calcCost(mat &pos, mat &goal){
  static int idxX[N * N], idxY[N * N], init = 1;
  if(init){
    init = 0;
    for(int i=0;i<N;i++)
      for(int j=0;j<N;j++) idxX[goal[i][j]] = j, idxY[goal[i][j]] = i;
  }

  int res = 0;  
  for(int i=0;i<N;i++)
    for(int j=0;j<N;j++){
      if(pos[i][j] == 0) continue;
      res += abs(i - idxY[pos[i][j]]) + abs(j - idxX[pos[i][j]]);
    }
  return res;
}

int calcCostDiff(mat &pos, mat &goal, int i, int j, int ni, int nj){
  static int idxX[N * N], idxY[N * N], init = 1;
  if(init){
    init = 0;
    for(int i=0;i<N;i++)
      for(int j=0;j<N;j++) idxX[goal[i][j]] = j, idxY[goal[i][j]] = i;
  }

  int a = abs(ni - idxY[ pos[i][j] ]) + abs(nj - idxX[ pos[i][j] ]);
  int b = abs(i - idxY[ pos[i][j] ]) + abs(j - idxX[ pos[i][j] ]);
  return -a + b;
}

ull toHash(mat &mp){
  const ull B = 1777771;
  ull hash = 0;
  for(int i=0;i<N;i++)
    for(int j=0;j<N;j++) hash = hash * B + mp[i][j];
  return hash;
}

ull calcHashDiff(mat &mp, int i, int j,int ni, int nj){
  static int init = 1;
  static ull pow[20];
  const ull B = 1777771;
  if(init){
    init = 0;
    pow[0] = 1;
    for(int i=1;i<20;i++) pow[i] = pow[i-1] * B;
  }

  int idx1 = i * N + j;
  int idx2 = ni * N + nj;
  ull p1 = pow[N * N - 1 - idx1];
  ull p2 = pow[N * N - 1 - idx2];
  return -(mp[ni][nj] * p1 + mp[i][j] * p2) + (mp[i][j] * p1 + mp[ni][nj] * p2);
}

int dijkstra(mat start, mat goal){
  using T = tuple<char, ull>;
  using P = pair<char, mat>;
  unordered_map<ull, P> D;

  priority_queue<T, vector<T>, greater<T> > Q;
  Q.push(T(calcCost(start, goal), toHash(start)));
  D[toHash(start)] = P(0, start);
  ull ghash = toHash(goal);
  queue<ull> his;
  his.push(toHash(start));

  while(!Q.empty()){
    int cost;
    ull hash;
    tie(cost, hash) = Q.top(); Q.pop();
    mat &A = D[hash].second;

    if(hash == ghash) return cost;

    his.push(hash);
    if(his.size() > 10000){
      D.erase(his.front());
      his.pop();
    }

    int y, x;
    for(int i=0;i<N;i++)
      for(int j=0;j<N;j++)
	if(A[i][j] == 0) {y = i, x = j;break;}

    const int dx[] = {0, 0, 1, -1};
    const int dy[] = {1, -1, 0, 0};
    for(int i=0;i<4;i++){
      int nx = x + dx[i];
      int ny = y + dy[i];
      if(nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
      swap(A[y][x], A[ny][nx]);
      mat &nA = A;
      int ncost = calcCostDiff(nA, goal, y, x, ny, nx) + cost + 1;
      ull nhash = hash + calcHashDiff(nA, y, x, ny, nx);
      if(!D.count(nhash) && ncost <= 45){
	Q.push(T(ncost, nhash));
	D[nhash] = P(ncost, nA);
      }
      swap(A[y][x], A[ny][nx]);
    }
  }
  assert(0);
}

