struct Puzzle {
	char x[4][4];
};
queue<pair<Puzzle, int>>Q; Puzzle Z;
char manh(Puzzle y) {
	char sum = 0; pair<char, char> p[16];
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			p[y.x[i][j]] = make_pair(i, j);
		}
	}
	for (int i = 0; i < 16; i++) {
		int X = (i - 1) / 4, Y = (i - 1) % 4;
		if (i == 0) { X = 3; Y = 3; }
		sum += abs(X - p[i].first) + abs(Y - p[i].second);
	}
	return sum;
}
int main() {
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			int p1; cin >> p1;
			Z.x[i][j] = p1;
		}
	}
	Q.push(make_pair(Z, 0));
	while (!Q.empty()) {
		Puzzle r = Q.front().first;
		Puzzle s; int V = Q.front().second;
		pair<char, char>z; Q.pop();
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				if (r.x[i][j] == 0) z = make_pair(i, j);
			}
		}
		int dx[4] = { 0,1,0,-1 };
		int dy[4] = { 1,0,-1,0 };
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				for (int k = 0; k < 4; k++)s.x[j][k] = r.x[j][k];
			}
			char px = z.first + dx[i], py = z.second + dy[i];
			if (py < 0 || py > 3)continue;
			if (px < 0 || px > 3)continue;
			swap(s.x[z.first][z.second], s.x[px][py]);
			int R1 = manh(r), R2 = manh(s);
			if (R1 >= R2 - 2 && V + 1 + R2 <= 30) {
				int OK = 1;
				for (int j = 0; j < 4; j++) {
					for (int k = 0; k < 4; k++) {
						if (s.x[j][k] != (j * 4 + k + 1) % 16) OK = 0;
					}
				}
				if (OK) {
					cout << V + 1 << endl;// cout << ' ' << cnt << endl;
					return 0;
				}
				Q.push(make_pair(s, V + 1));
			}
		}
	}
	return 0;
}

