    {5, 4, 3, 4, 4, 3, 2, 3, 3, 3, 1, 2, 2, 1, 0, 1},   // 15
};


// パネルの状態を保持する配列
int ary_panel[PANEL_NUM];

// 動かしたパネルを記憶しておく配列
int ary_movedPanel[MAX_STEP];

// 検索中かを保持するフラグ
// true : 検索中, false : 検索終了
bool searchState;

void panelMoveOperation(int stepLimit, int moveCount, int zeroPos, int lowerCount);
int calcArrayNum(int x, int y);
int searchZeroPos(int panel[]);
bool reachGoal(int panel[]);
int calcMoveDistance(int panel[]);

// メイン関数
int main(void)
{
    int lowerMoveCount = 0;

    searchState = true;

    // 初期状態を設定する
    for(int i = 0; i < PANEL_NUM; i++)
    {
        cin >> ary_panel[i];
    }

    // 初期設定
    ary_movedPanel[0] = 0;

    // 正解に到達するまでの最短手数を求めておく
    lowerMoveCount = calcMoveDistance(&ary_panel[0]);

    for(int stepLimit = 0; stepLimit <= MAX_STEP; stepLimit++)
    {
        int zeroPos = searchZeroPos(&ary_panel[0]);

        // 検索可能な手数を順番に増やして検索する
        panelMoveOperation(stepLimit, 0, zeroPos, lowerMoveCount);

        if( searchState == false )
        {
            // 検索終了
            printf("%d\n", stepLimit);
            break;
        }
    }

    return 0;
}

// パネルの移動操作を実施する関数
// stepLimit  : 検索可能な手数の上限値
// moveCount  : パネルを移動させた回数
// zeroPos    : 配列中のパネルのゼロの位置
// lowerCount : 正解までに必要な最短の移動距離
void panelMoveOperation(int stepLimit, int moveCount, int zeroPos, int lowerCount)
{
    int newLowerCount = 0;

    if( stepLimit == moveCount )
    {

        // 並び替えた状態がゴールに到達しているかを確認する
        if( reachGoal(&ary_panel[0]) == true )
        {
            // 検索終了
            searchState = false;
        }

        return;
    }

    // 上下左右にパネルを移動させてみる
    for(int i = 0; i < MOVE_LAST; i++)
    {
        int x, y;

        //zeroPos = searchZeroPos();

        // ゼロの位置から x, y 座標に変換する
        x = zeroPos / 4;
        y = zeroPos % 4;

        int tx, ty;

        // 移動後の座標を計算する
        tx = x + move_p[i].x;
        ty = y + move_p[i].y;

        if( ( 0 <= tx && tx <= 3 ) && ( 0 <= ty && ty <= 3 ) )
        {
            int moveNum, movePos;

            // 座標から配列の要素No.へ変換する
            movePos = calcArrayNum(tx, ty);
            moveNum = ary_panel[movePos];

            if( moveNum == ary_movedPanel[moveCount] )
            {
                // 前回動かしたパネルなら, 元に戻るだけなので何もしない
                continue;
            }

            // 動かしたパネルを記憶しておく
            ary_movedPanel[moveCount + 1] = moveNum;

            // 数値を入れ替える
            swap(ary_panel[zeroPos], ary_panel[movePos]);

            // 正解までに必要な移動の最短距離を再計算する
            // [現在の最短距離] - [移動前のパネル位置での正解までの距離] + [移動後のパネル位置での正解までの距離]
            // パネルを移動させるので, 移動前の距離は引いておいて, 新たに移動後の距離を足しておく
            newLowerCount = lowerCount - moveDistance[moveNum][movePos] + moveDistance[moveNum][zeroPos];

            // 下限値枝刈り法の実施
            if( ( moveCount + newLowerCount ) <= stepLimit )
            {
                // 再帰呼び出しを実施
                panelMoveOperation(stepLimit, moveCount + 1, movePos, newLowerCount);
            }

            // 再帰呼び出しの前の状態に戻す
            ary_panel[zeroPos] = 0;
            ary_panel[movePos] = moveNum;
        }
    }

    return;
}

// x, y 座標から配列の要素数へ変換する関数
int calcArrayNum(int x, int y)
{
    return 4 * x + y;
}

// 配列中のゼロの位置を探索する関数
int searchZeroPos(int panel[])
{
    for(int i = 0; i < PANEL_NUM; i++)
    {
        if( panel[i] == 0 )
        {
            return i;
        }
    }

    return -1;
}

// ゴールに到達したかを判定する関数
bool reachGoal(int panel[])
{
    for(int i = 0; i < PANEL_NUM; i++)
    {
        if( panel[i] != ary_Target[i] )
        {
            return false;
        }
    }

    return true;
}

// パネルの並びから, 正解までに必要な移動距離を求める
int calcMoveDistance(int panel[])
{
    int num = 0;
    int distance = 0;

    for(int i = 0; i < PANEL_NUM; i++)
    {
        num = panel[i];

        // 最短の移動距離の和を求める
        distance += moveDistance[num][i];
    }

    return distance;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 4;
int dx[4] = {0, 1, 0, -1}, dy[4] = {-1, 0, 1, 0};

struct State {
	vector<int> puz;
	int zero;
	int cost;
	int esti;
	bool operator < (const State &s) const {
		return esti < s.esti;
	}
	bool operator > (const State &s) const {
		return esti  > s.esti;
	}
};

int main() {
	State s;
	s.cost = s.esti = 0;	
	s.puz = vector<int>(N*N);
	for ( int i = 0; i < N*N; i++ ) {
		cin >> s.puz[i];
		if ( s.puz[i] == 0 ) {
			s.zero = i;
			s.puz[i] = N*N-1;			
		} else {
			s.puz[i]--;
		}

		s.esti += abs(i/N-s.puz[i]/N) + abs(i%N-s.puz[i]%N);		
	}
	//cout << s.esti << endl;
	map<vector<int>, int> used;
	priority_queue<State, vector<State>, greater<State> > Q;	
	Q.push(s);
	int cnt = 0;
	int ans = 100;
	while ( !Q.empty() ) {	 			
		State p = Q.top(); Q.pop();
		if ( p.cost >= 45 ) continue;
		if ( s.esti >= 50 ) continue;

		//for ( int i = 0; i < N*N; i++ ) cout << s.puz[i] << " ";
		//cout << endl;
		// cout << p.cost << " " << p.esti << endl;			

		if ( p.esti-p.cost == 0 ) {
			cout << p.cost << endl;
			return 0;
		}		

		if ( used.count(p.puz) &&  used[p.puz] <= p.cost ) continue;		
		used[p.puz] = p.cost;

		for ( int i = 0; i < 4; i++ ) {
			int y = p.zero/N, x = p.zero%N;
			int ny = y+dy[i], nx = x+dx[i];
			if ( ny < 0 || nx < 0 || ny >= N || nx >= N ) continue;
			s = p;			
			int ch_id = ny*4+nx;
			int ch_dat = s.puz[ch_id];
			s.esti -= abs(y-(N-1)) + abs(x-(N-1));			
			s.esti -= abs(ny-ch_dat/N) + abs(nx-ch_dat%N);			
			s.esti += abs(y-ch_dat/N) + abs(x-ch_dat%4);			
			s.esti += abs(ny-(N-1)) + abs(nx-(N-1));				
			s.esti++;
			s.cost++;
			swap(s.puz[s.zero], s.puz[ch_id]);			
			s.zero = ch_id;
			Q.push(s);			
		}			
	}

	return 0;
}

