#define N 4
#define N2 16
#define LIMIT 100

static const int dx[4] = {0,-1,0,1};
static const int dy[4] = {1,0,-1,0};
static const char dir[4] = {'r','u','l','d'};
vector<vector<ll>> MDT(N2,vector<ll>(N2));

struct Puzzle {
    vector<ll> f;
    ll space;
    ll MD;
};

Puzzle state;
ll limit;//深さの制限
vector<ll> path(LIMIT);

ll getAllMD(Puzzle pz){
  ll sum = 0;
  rep(i,N2){
    if(pz.f[i] == N2){
      continue;
    }
    sum += MDT[i][pz.f[i] - 1];
  }
  return sum;
}

bool isSolved(){
  rep(i,N2){
    if(state.f[i] != i+1)return false;
  }
  return true;
}

bool dfs(ll depth,ll prev){
  if(state.MD == 0){return true;}

  //現在の深さにヒューリスティックを足して制限を超えたら枝を刈る
  if(depth + state.MD > limit){
    return false;
  }

  ll sx = state.space / N;
  ll sy = state.space % N;
  Puzzle tmp;

  rep(r,4){
    ll tx = sx + dx[r];
    ll ty = sy + dy[r];
    if(tx < 0 || ty < 0 || tx >= N || ty >= N)continue;
    if(max(prev,(ll)r) - min(prev,(ll)r) == 2)continue;
    tmp = state;
//    rep(i,N2){
//      cout << tmp.f[i] << " ";
//    }
//    cout << endl;

    //マンハッタン距離の差分を計算しつつ、ピースをスワップ
    state.MD -= MDT[tx * N + ty][state.f[tx * N + ty] - 1];
    state.MD += MDT[sx * N + sy][state.f[tx * N + ty] - 1];
    swap(state.f[tx * N + ty],state.f[sx * N + sy]);
    state.space = tx * N + ty;
    if(dfs(depth+1,r)){
      path[depth] = r;
      return true;
    }
    state = tmp;
  }
  return false;
}

/*反復深化*/
string iterative_deepening(Puzzle in){
  in.MD = getAllMD(in); //初期状態のマンハッタン距離
  for(limit = in.MD;limit <= LIMIT;limit++){
    //cout << limit << endl;
    state = in; //deep copy
    if(dfs(0,-100)){
      string ans = "";
      rep(i,limit){
        ans += dir[path[i]];
      }
      return ans;
    }
  }
  return "unsolvable";
}

