const int N = 4;
const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

struct State {
    int a[N * N];
    int sid;
};

State now;
int ans = 45;

int h() {
    int res = 0;
    for(int i = 0; i < N * N; i++) {
        if(now.a[i] != N * N - 1) {
            res += abs(i / N - now.a[i] / N) + abs(i % N - now.a[i] % N);
        }
    }
    return res;
}

// d:今の深さ
// pre:1手前の空きマスの位置
void dfs(int d, int pre) {
    if(d + h() > ans) {
        return;
    }
    if(h() == 0) {
        ans = min(ans, d);
        return;
    }
    for(int i = 0; i < 4; i++) {
        if((now.sid / N + dy[i]) < 0 || (now.sid / N + dy[i]) >= N) {
            continue;
        }
        if((now.sid % N + dx[i]) < 0 || (now.sid % N + dx[i]) >= N) {
            continue;
        }
        int nxt_sid = (now.sid / N + dy[i]) * N + (now.sid % N + dx[i]);
        if(nxt_sid == pre) {
            continue;
        }
        int tmp = now.sid;
        swap(now.a[now.sid], now.a[nxt_sid]);
        now.sid = nxt_sid;
        dfs(d + 1, tmp);
        swap(now.a[nxt_sid], now.a[tmp]);
        now.sid = tmp;
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    for(int i = 0; i < N * N; i++) {
        cin >> now.a[i];
        if(now.a[i] == 0) {
            now.a[i] = N * N - 1;
            now.sid = i;
        } else {
            now.a[i]--;
        }
    }
    dfs(0, -1);
    cout << ans << endl;
}

