    {
        int zeroPos = searchZeroPos();

        // 検索可能な手数を順番に増やしていく
        panelMoveOperation(stepLimit, 0, zeroPos, 0);

        if( searchState == false )
        {
            // 検索終了
            break;
        }
    }

    return 0;
}

// パネルの移動量を保持する構造体
typedef struct
{
    int x;
    int y;
}st_move;

// パネルの移動座標を保持する配列
st_move move_p[] = { {-1, 0},   // 上
                     {0, -1},   // 左
                     {0, 1},    // 右
                     {1, 0}     // 下
                    };

// パネルの移動状態を表現する列挙型
enum E_Move
{
    UP = 0,
    LEFT,
    RIGHT,
    DOWN,
    MOVE_LAST
};

int lastZeroPos = 0, lastMovePos = 0;

// パネルの移動操作を実施する関数
// zeroPos : 配列中のパネルのゼロの位置
void panelMoveOperation(int stepLimit, int moveCount, int zeroPos, int count)
{
    if( stepLimit == moveCount )
    {

        // 並び替えた状態がゴールに到達しているかを確認する
        if( reachGoal() == true )
        {
            // 検索終了
            printf("%d\n", count);
            searchState = false;
        }

        return;
    }

    // 上下左右にパネルを移動させてみる
    for(int i = 0; i < MOVE_LAST; i++)
    {
        int x, y;

        //zeroPos = searchZeroPos();

        // ゼロの位置から x, y 座標に変換する
        x = zeroPos / 4;
        y = zeroPos % 4;

        int tx, ty;

        // 移動後の座標を計算する
        tx = x + move_p[i].x;
        ty = y + move_p[i].y;

        if( 0 <= tx && tx <= 3 )
        {
            if( 0 <= ty && ty <= 3 )
            {
                int moveNum, movePos;

                // 座標から配列の要素No.へ変換する
                movePos = calcArrayNum(tx, ty);
                moveNum = ary_panel[movePos];

                // 数値を入れ替える
                swap(ary_panel[zeroPos], ary_panel[movePos]);

                // 再帰呼び出しを実施
                panelMoveOperation(stepLimit, moveCount + 1, movePos, count + 1);

                // 再帰呼び出しの前の状態に戻す
                ary_panel[zeroPos] = 0;
                ary_panel[movePos] = moveNum;
            }
        }
    }

    return;
}

// x, y 座標から配列の要素数へ変換する関数
int calcArrayNum(int x, int y)
{
    return 4 * x + y;
}

// 配列中のゼロの位置を探索する関数
int searchZeroPos(void)
{
    for(int i = 0; i < PANEL_NUM; i++)
    {
        if( ary_panel[i] == 0 )
        {
            return i;
        }
    }

    return -1;
}

// ゴールに到達したかを判定する関数
bool reachGoal(void)
{
    for(int i = 0; i < PANEL_NUM; i++)
    {
        if( ary_panel[i] != ary_Target[i] )
        {
            return false;
        }
    }

    return true;
}

#include <cstdio>           // printf(), scanf()
