using namespace std;
static const int N = 4;
static const int N2 = 16;

struct puzzle
{
	int f[N2];
	int space;
	int MD;
	int cost;

	bool operator < (const puzzle &p) const
	{
		for (int i = 0; i < N2; ++i)
		{
			if (f[i] != p.f[i])
				return f[i] < p.f[i];
		}

		return false;
	}
};

struct state
{
	puzzle pz;
	int estimated;

	bool operator < (const state &s) const
	{
		return estimated > s.estimated;
	}
};

int MDT[N2][N2];

int
get_all_MD(puzzle pz)
{
	int sum = 0;
	for (int i = 0; i < N2; ++i)
	{
		if (pz.f[i] != N2)
			sum += MDT[i][pz.f[i] - 1];
	}

	return sum;
}

static const int dx[4] = {-1, 0, 1, 0};
static const int dy[4] = {0, -1, 0, 1};
static const char dir[4] = {'u', 'l', 'd', 'r'};

int
astar(puzzle s)
{
	priority_queue<state> PQ;
	map<puzzle, bool> V;
	puzzle u, v;
	state initial;

	s.MD = get_all_MD(s);
	s.cost = 0;
	initial.pz = s;
	initial.estimated = get_all_MD(s);
	PQ.push(initial);

	while (!PQ.empty())
	{
		state st = PQ.top(); PQ.pop();
		u = st.pz;
		if (u.MD == 0)
			return u.cost;

		V[u] = true;
		int sx = u.space / N;
		int sy = u.space % N;

		for (int r = 0; r < 4; ++r)
		{
			int tx = sx + dx[r];
			int ty = sy + dy[r];
			if (tx < 0 || N <= tx || ty < 0 || N <= ty)
				continue;

			v = u;
			int s = sx * N + sy;
			int t = tx * N + ty;
			v.MD -= MDT[t][v.f[t] - 1];
			v.MD += MDT[s][v.f[t] - 1];
			swap(v.f[s], v.f[t]);
			v.space = t;

			if (!V[v])
			{
				state news;

				v.cost++;
				news.pz = v;
				news.estimated = v.cost + v.MD;
				PQ.push(news);
			}
		}
	}

	return -1;
}

int
main(int argc, char** argv)
{
	puzzle in;

	for (int i = 0; i < N2; ++i)
	{
		for (int j = 0; j < N2; ++j)
			MDT[i][j] = abs(i / N - j / N) + abs(i % N - j % N);
	}

	for (int i = 0; i < N2; ++i)
	{
		scanf("%d", &in.f[i]);
		if (in.f[i] == 0)
		{
			in.f[i] = N2;
			in.space = i;
		}
	}

	printf("%d\n", astar(in));
	return 0;
}

