	InitHash();

	int k;
	std::vector<int> P;
	for (int i = 0; i < 16; i++){
		scanf("%d", &k);
		P.push_back(k);
	}
	int n = SolvePuzzle(P);

	printf("%d\n", n);

	return 0;
}

