constexpr i64 H = 4;
constexpr i64 W = 4;

using Board = array<i64,H*W>;

constexpr i64 yx2idx(i64 y, i64 x) {
    return W*y + x;
}

constexpr pair<i64,i64> idx2yx(i64 i) {
    return { i/W, i%W };
}

constexpr i64 ABS(i64 x) {
    return x < 0 ? -x : x;
}

constexpr i64 dist(i64 y1, i64 x1, i64 y2, i64 x2) {
    return ABS(y1-y2) + ABS(x1-x2);
}

constexpr struct CostTable {
    i64 table_[H*W][H*W];  // [値][位置]

    constexpr CostTable() : table_() {
        FOR(n, 1, H*W) REP(i, H*W) {
            auto p1 = idx2yx(n-1);
            auto p2 = idx2yx(i);
            table_[n][i] = dist(p1.first, p1.second, p2.first, p2.second);
        }
    }

    constexpr i64 get(i64 n, i64 i) const { return table_[n][i]; }
} COST_TABLE;

struct Position {
    Board board_;
    i64 idx_;
    i64 least_to_solve_;

    Position(const Board& board) : board_(board), least_to_solve_(0) {
        REP(i, H*W) {
            if(board_[i] == 0) {
                idx_ = i;
                break;
            }
        }
        REP(i, H*W) {
            i64 n = board_[i];
            if(n == 0) continue;
            least_to_solve_ += COST_TABLE.get(n,i);
        }
    }

    const Board& board() const { return board_; }

    i64 idx() const { return idx_; }

    i64 least_to_solve() const { return least_to_solve_; }

    bool is_solved() const {
        REP(i, H*W-1) {
            if(board_[i] != i+1) return false;
        }
        return true;
    }

    bool mv(i64 dir) {
        constexpr i64 DY[4] { -1,  0, 0, 1 };
        constexpr i64 DX[4] {  0, -1, 1, 0 };

        i64 y,x; tie(y,x) = idx2yx(idx_);
        i64 yy = y + DY[dir];
        i64 xx = x + DX[dir];
        if(yy < 0 || H <= yy) return false;
        if(xx < 0 || W <= xx) return false;

        i64 idx_nex = yx2idx(yy,xx);
        i64 n = board_[idx_nex];
        least_to_solve_ -= COST_TABLE.get(n,idx_nex);
        least_to_solve_ += COST_TABLE.get(n,idx_);

        swap(board_[idx_], board_[idx_nex]);
        idx_ = idx_nex;

        return true;
    }
};

template<>
struct Dbg<Position> {
    static void dbg(ostream& out, const Position& pos) {
        dbg_write(out, make_tuple(pos.board(), pos.least_to_solve()));
    }
};

struct Solver {
    static constexpr i64 DEPTH_HARD_MAX = 45;

    i64 depth_max_;

    Solver() {}

    i64 solve(Position pos) {
        for(depth_max_ = 0; depth_max_ <= DEPTH_HARD_MAX; ++depth_max_) {
            DBG(depth_max_);
            if(dfs(pos,-1,0)) return depth_max_;
        }
        return -1;
    }

private:
    bool dfs(Position& pos, i64 dir_pre, i64 depth) {
        constexpr i64 REV[4] { 3, 2, 1, 0 };

        if(pos.is_solved()) return true;
        if(depth + pos.least_to_solve() > depth_max_) return false;

        REP(dir, 4) {
            if(REV[dir] == dir_pre) continue;
            if(!pos.mv(dir)) continue;
            if(dfs(pos, dir, depth+1)) return true;
            pos.mv(REV[dir]);
        }

        return false;
    }
};

void solve() {
    Board board;
    REP(i, H*W) {
        board[i] = RD();
    }

    Position pos(board);
    DBG(pos);

    Solver sol;
    i64 ans = sol.solve(pos);

    PRINTLN(ans);
}

signed main() {


    solve();

    return 0;
}

