    return cost;
}

void dfs(int x,int y,int len,int pre_move)//sx,sy是空格的位置
{
    if(flag) return;
    int dv=hv(map);
    if(len==limit)
    {
        if(dv==0)  //成功 退出
        {
            flag=1;
            length=len;
            return;
        }
        else return;  //超过预设长度 回退
    }
    else if(len<limit)
    {
        if(dv==0)  //短于预设长度 成功 退出
        {
            flag=1;
            length=len;
            return;
        }
    }
    for(int i=0; i<4; i++)
    {
        if(i+pre_move==3&&len>0) continue;//不和上一次移动方向相反,对第二步以后而言
        int tx=x+nx[i][0];
        int ty=y+nx[i][1];
        if(tx>=0&&tx<4&&ty>=0&&ty<4)
        {
            swap(map[x][y],map[tx][ty]);
            int p=hv(map);
            if(p+len<=limit&&flag==0)
            {
                dfs(tx,ty,len+1,i);
                if(flag) return;
            }
            swap(map[x][y],map[tx][ty]);
        }
    }
}

