using namespace std;

using Weight=long long;
using Encoded=long long;

struct State {
    Weight hcost, acost;
    Encoded encoded;
    State() {}
    State(Weight h, Weight a, Encoded e): hcost(h), acost(a), encoded(e) {}
    bool operator>(const State & state2) const {
        if (hcost+acost != state2.hcost+state2.acost) {
            return hcost+acost > state2.hcost+state2.acost;
        } else {
            return acost > state2.acost;
        }
    }
};

const Weight INF=1LL<<59;

template <class T>
using lp_queue=priority_queue<T, deque<T>, greater<T>>;

Encoded encode(vector<long long> d) {
    long long cur=0;
    Encoded enc=0;
    for (size_t i=0; i<d.size()-1; ++i) {
        cur = d[i];
        for (size_t j=i+1; j<d.size(); ++j)
            if (cur < d[j])
                --d[j];

        (enc += d[i]) *= d.size()-i-1;
    }

    return enc;
}

vector<long long> decode(Encoded e) {
    vector<long long> d(16);
    for (size_t i=1; i<=16; ++i) {
        d[16-i] = e % i;
        e /= i;
    }

    for (size_t i=16; i--;)
        for (size_t j=i+1; j<16; ++j)
            if (d[i] <= d[j])
                ++d[j];

    return d;
}

Weight heucost(Encoded start, Encoded end) {
    static const vector<long long> dend=decode(end);
    vector<long long> dstart=decode(start);

    Weight h=0;
    for (size_t i=0; i<16; ++i)
        for (size_t j=0; j<16; ++j)
            if (dstart[i] == dend[j]) {
                h += abs(int(i/4-j/4))+abs(int(i%4-j%4));
                break;
            }

    return h;
}

vector<pair<Weight, Encoded>> pmoves(Encoded cur) {
    vector<long long> d=decode(cur);
    size_t i;
    for (i=0; d[i]; ++i);

    vector<pair<Weight, Encoded>> p;
    if (i/4 < 3) {
        swap(d[i], d[i+4]);
        p.push_back(make_pair(1, encode(d)));
        swap(d[i], d[i+4]);
    }
    if (i/4 > 0) {
        swap(d[i], d[i-4]);
        p.push_back(make_pair(1, encode(d)));
        swap(d[i], d[i-4]);
    }
    if (i%4 < 3) {
        swap(d[i], d[i+1]);
        p.push_back(make_pair(1, encode(d)));
        swap(d[i], d[i+1]);
    }
    if (i%4 > 0) {
        swap(d[i], d[i-1]);
        p.push_back(make_pair(1, encode(d)));
        swap(d[i], d[i-1]);
    }
    return p;
}

Weight astar(Encoded start, Encoded end) {
    lp_queue<State> q;
    q.push(State(heucost(start, end), 0, start));

    Weight opt=INF;
    set<Encoded> visited;
    while (!q.empty()) {
        State p=q.top(); q.pop();
        Weight cur_cost=p.acost;
        Encoded cur_state=p.encoded;
        visited.insert(cur_state);

        if (opt < cur_cost) continue;
        if (cur_state == end)
            if (opt > cur_cost)
                opt = cur_cost;

        vector<pair<Weight, Encoded>> ms=pmoves(cur_state);
        for (pair<Weight, Encoded> m: ms) {
            if (visited.count(m.second)) continue;
            if (cur_cost+m.first >= opt) continue;

            q.push(State(heucost(m.second, end), cur_cost+m.first, m.second));
        }
    }

    return opt;
}

