using namespace std;

int getcost(int i, int j, int tmp)
{
    return abs(i - (tmp - 1) / 4) + abs(j - (tmp - 1) % 4);
}

bool solve(vector<vector<int> > puzzle, int cutoff, int cost)
{
    priority_queue<pair<int, vector<vector<int> > > > qu;
    qu.push(make_pair(-cost, puzzle));
    while(!qu.empty()){
        vector<vector<int> > now = (qu.top()).second;
        int nowcost = (qu.top()).first;
        qu.pop();
        int h = 0;
        for(int i = 0; i < 4; i++){
            for(int j = 0; j < 4; j++){
                int tmp = now[i][j];
                if(tmp != 0) h += getcost(i, j, tmp); 
            }
        }
        // cout << h << endl;
        if(h == 0){
            return true;
        }
        for(int i = 0; i < 4; i++){
            for(int j = 0; j < 4; j++){
                // cout << now[i][j] << " ";
                if(now[i][j] == 0){
                    int dx[4] = {0, 1, 0, -1};
                    int dy[4] = {1, 0, -1, 0};
                    for(int k = 0; k < 4; k++){
                        int nx = i + dx[k];
                        int ny = j + dy[k];
                        if(nx < 0 || ny < 0 || nx >= 4 || ny >= 4) continue;
                        int nowc = getcost(nx, ny, now[nx][ny]);
                        int nextc = getcost(i, j, now[nx][ny]);
                        // cout << now[nx][ny] << " " << nextc - nowc << endl;
                        nowcost -= nextc - nowc + 1;
                        swap(now[i][j], now[nx][ny]);
                        if(nowcost <= cutoff) qu.push(make_pair(nowcost, now));
                        swap(now[i][j], now[nx][ny]);
                        nowcost += nextc - nowc + 1;
                    }
                }
            }
            // cout << endl;
        }
    }
    return false;
}

int main()
{
    vector<vector<int> > puzzle(4);
    int cost = 0;
    for(int i = 0; i < 4; i++){
        for(int j = 0; j < 4; j++){
            int tmp;
            cin >> tmp;
            puzzle[i].push_back(tmp);
            if(tmp != 0) cost += getcost(i, j, tmp);
        }
    }
    // cout << cost << endl;
    for(int i = cost; i <= 45; i++){
        if(solve(puzzle, i, cost)){
            cout << i << endl;
            break;
        }
    }
    return 0;
}

