#include <bits/stdc++.h>
using namespace std;

const int N = 4;
int dx[4] = {0, 1, 0, -1}, dy[4] = {-1, 0, 1, 0};

struct State {
	vector<int> puz;
	int zero;
	int cost;
	int esti;
	bool operator < (const State &s) const {
		return esti < s.esti;
	}
	bool operator > (const State &s) const {
		return esti  > s.esti;
	}
};

int main() {
	State s;
	s.cost = s.esti = 0;	
	s.puz = vector<int>(N*N);
	for ( int i = 0; i < N*N; i++ ) {
		cin >> s.puz[i];
		if ( s.puz[i] == 0 ) {
			s.zero = i;
			s.puz[i] = N*N-1;			
		} else {
			s.puz[i]--;
		}

		s.esti += abs(i/N-s.puz[i]/N) + abs(i%N-s.puz[i]%N);		
	}
	//cout << s.esti << endl;
	map<vector<int>, int> used;
	priority_queue<State, vector<State>, greater<State> > Q;	
	Q.push(s);
	int cnt = 0;
	while ( !Q.empty() ) {	 			
		State p = Q.top(); Q.pop();
		if ( p.cost >= 45 ) continue;
		//if ( s.esti >= 50 ) continue;

		//for ( int i = 0; i < N*N; i++ ) cout << s.puz[i] << " ";
		//cout << endl;
		// cout << p.cost << " " << p.esti << endl;			

		if ( p.esti-p.cost == 0 ) {
			cout << p.cost << endl;
			return 0;
		}		

		if ( used.count(p.puz) &&  used[p.puz] <= p.cost ) continue;		
		used[p.puz] = p.cost;

		for ( int i = 0; i < 4; i++ ) {
			int y = p.zero/N, x = p.zero%N;
			int ny = y+dy[i], nx = x+dx[i];
			if ( ny < 0 || nx < 0 || ny >= N || nx >= N ) continue;
			s = p;			
			int ch_id = ny*4+nx;
			int ch_dat = s.puz[ch_id];
			s.esti -= abs(y-(N-1)) + abs(x-(N-1));			
			s.esti -= abs(ny-ch_dat/N) + abs(nx-ch_dat%N);			
			s.esti += abs(y-ch_dat/N) + abs(x-ch_dat%4);			
			s.esti += abs(ny-(N-1)) + abs(nx-(N-1));				
			s.esti++;
			s.cost++;
			swap(s.puz[s.zero], s.puz[ch_id]);			
			s.zero = ch_id;
			Q.push(s);			
		}			
	}

	return 0;
}

#include<stdio.h>
#include<vector>
#include<cstdlib>
#include<utility>
using namespace std;

class State{
public:
    vector<vector<int>> puzzle;
    int zero_col, zero_row, prev_zero_col, prev_zero_row;
    int edge_len, heuristic;
    State(vector<vector<int>>& arr, const int& zc, const int& zr, const int& pzc, const int& pzr, const int& h): puzzle(arr), zero_col(zc), zero_row(zr), prev_zero_col(pzc), prev_zero_row(pzr), heuristic(h) {
        edge_len = arr.size();
    }
    int get_manhattan_diff(const int& new_zero_col, const int& new_zero_row){
        int diff = 0;
        diff += abs((puzzle[new_zero_row][new_zero_col]-1)/edge_len - zero_row) + abs((puzzle[new_zero_row][new_zero_col]-1)%edge_len - zero_col) - abs((puzzle[new_zero_row][new_zero_col]-1)/edge_len - new_zero_row) - abs((puzzle[new_zero_row][new_zero_col]-1)%edge_len - new_zero_col);
        return diff;
    }
    vector<State> get_next_states(){
        vector<State> res;    
        vector<vector<int>> tmp;
        int diff;
        if(zero_col+1 < edge_len && prev_zero_col != zero_col+1){
            diff = get_manhattan_diff(zero_col+1, zero_row);
            tmp = puzzle;
            swap(tmp[zero_row][zero_col], tmp[zero_row][zero_col+1]);
            res.push_back(State(tmp, zero_col+1, zero_row, zero_col, zero_row, heuristic + diff));
        }
        if(zero_col-1 >= 0 && prev_zero_col != zero_col-1){
            diff = get_manhattan_diff(zero_col-1, zero_row);
            tmp = puzzle;
            swap(tmp[zero_row][zero_col], tmp[zero_row][zero_col-1]);
            res.push_back(State(tmp, zero_col-1, zero_row, zero_col, zero_row, heuristic + diff));
        }
        if(zero_row+1 < edge_len && prev_zero_row != zero_row+1){
            diff = get_manhattan_diff(zero_col, zero_row+1);
            tmp = puzzle;
            swap(tmp[zero_row][zero_col], tmp[zero_row+1][zero_col]);
            res.push_back(State(tmp, zero_col, zero_row+1, zero_col, zero_row, heuristic + diff));
        }
        if(zero_row-1 >= 0 && prev_zero_row != zero_row-1){
            diff = get_manhattan_diff(zero_col, zero_row-1);
            tmp = puzzle;
            swap(tmp[zero_row][zero_col], tmp[zero_row-1][zero_col]);
            res.push_back(State(tmp, zero_col, zero_row-1, zero_col, zero_row, heuristic + diff));
        }
        return res;
    }
};

int get_sum_manhattan(vector<vector<int>>& state){
    int edge_len = state.size(), res = 0;
    for(int i = 0; i < edge_len; i++){
        for(int j = 0; j < edge_len; j++){
            if(state[i][j] != 0)
                res += abs((state[i][j]-1)/edge_len - i) + abs((state[i][j]-1)%edge_len -j); 
        }
    }
    return res;
}

bool DLS(State& state, const int& limit, const int& depth){
    if(depth + state.heuristic > limit) return false;
    if(state.heuristic == 0) return true;
    vector<State> next_states = state.get_next_states();
    for(State s : next_states){
        if(DLS(s, limit, depth+1)) return true;
    }
    return false;
}

int IDA(State& initial_state, const int& max_step){
    for(int l = 0; l <= max_step; l++){
        if(DLS(initial_state, l, 0))
            return l;
    }
    return -1;
}

