using namespace std;
const int maxn = 4;

int dist[maxn*maxn][maxn*maxn];


struct Puzzle
{
    int f[maxn][maxn];
    int spaceX;
    int spaceY;
    int dis;
};

const int dx[] = {1, -1, 0, 0};
const int dy[] = {0, 0, 1, -1};

bool is_valid(int x, int y){
    return x >= 0 && x < maxn && y >= 0 && y < maxn;
}

int getH(const Puzzle& p)
{
    int cnt = 0;
    for(int i = 0; i < maxn; i++)
    {
        for(int j = 0; j < maxn; j++)
        {
            if(p.f[i][j] == 16) continue;
            cnt += dist[i*maxn + j][p.f[i][j]-1];
        }
    }
    return cnt;
}
bool is_solved(const Puzzle& p)
{
    for(int i = 0; i < maxn; i++)
        for(int j = 0; j < maxn; j++)
            if(p.f[i][j] != i*maxn+j+1) return false;
    return true;
}

bool dfs(Puzzle start, int d, int maxd)
{
    if(is_solved(start)) return true;
    if(start.dis + d > maxd) return false;
    //if(start.dis == 0) return true;

    for(int i = 0; i < 4; i++)
    {
        int newX = start.spaceX + dx[i];
        int newY = start.spaceY + dy[i];
        if(!is_valid(newX, newY)) continue;
        Puzzle now = start;
        now.spaceX = newX;
        now.spaceY = newY;
        swap(now.f[start.spaceX][start.spaceY], now.f[newX][newY]);
        now.dis = getH(now);
        if(dfs(now, d+1, maxd)) return true;
    }
    return false;
}

