	{
		if (left != nullptr)
		{
			left->deleteAll();
		}
		else
		{
			delete left;
			left = nullptr;
		}
		if (right != nullptr)
		{
			right->deleteAll();
		}
		else
		{
			delete right;
			right = nullptr;
		}
	}
