int value(array<int, 16> v) {
    int ret = 0;
    REP(i, 16) {
        int x = v[i];
        if (x == 0) { continue; }
        ret += abs(((x - 1) % 4) - (i % 4)) + abs(((x - 1) / 4 - i / 4));
    }
    return ret;
}

int dijkstra(array<int, 16> root) {
    using T = array<int, 16>;
    int zero = (int)(find(root.begin(), root.end(), 0) - root.begin());
    int d, p;
    T board, board1;
    map<T, int> dist;
    priority_queue<tuple<int, int, T, int>, vector<tuple<int, int, T, int>>,
                   greater<tuple<int, int, T, int>>>
        pri;
    pri.push(make_tuple(value(root), value(root), root, zero));
    while (pri.size() != 0) {
        tie(d, p, board, zero) = pri.top();
        pri.pop();
        if (dist.find(board) == dist.end()) {
            if (p == 0) {
                return d;
            }
            dist[board] = d - p;
            vector<int> zero_list;
            if (zero % 4 != 0) { zero_list.PB(zero - 1); }
            if (zero % 4 != 3) { zero_list.PB(zero + 1); }
            if (zero / 4 != 0) { zero_list.PB(zero - 4); }
            if (zero / 4 != 3) { zero_list.PB(zero + 4); }
            for (auto z : zero_list) {
                board1 = board;
                swap(board1[zero], board1[z]);
                if (dist.find(board1) == dist.end()) {
                    int temp = value(board1);
                    pri.push(MT(d - p + 1 + temp, temp, board1, z));
                }
            }
        }
    }
    return -1;
}

