#include <algorithm>
#include <iostream>
#include <map>
#include <queue>

using namespace std;

#define SIDE 4
#define N 16
#define LIMIT 100

struct Board {
  int a[N];
  int md, c, zero_pos;

  bool operator < (const Board &b) const {
    for (int i = 0; i < N; i++) {
      if (a[i] == b.a[i]) continue;
      return a[i] < b.a[i];
    }
    return false;
  }
};

struct State {
  Board b;
  int e; // estimated

  bool operator < (const State &s) const {
    return e > s.e;
  }
};

int DX[4] = { 0, 1, 0, -1 };
int DY[4] = { 1, 0, -1, 0 };
char DIR[4] = { 'u', 'r', 'd', 'l' };

int MDs[N][N];

int get_MD_sum(Board in) {
  int sum = 0;
  for (int i = 0; i < N; i++) {
    if (in.a[i] == N) continue;
    sum += MDs[i][in.a[i] - 1];
  }
  return sum;
}

void astar(Board in) {
  State s;
  s.e = in.md = get_MD_sum(in);
  s.b = in;

  priority_queue<State> q;
  q.push(s);

  map<Board, bool> visited;

  while (!q.empty()) {
    Board cur_b = q.top().b; q.pop();

    if (cur_b.md == 0) {
      cout << cur_b.c << endl;
      return;
    }

    visited[cur_b] = true;

    int sx = cur_b.zero_pos / SIDE;
    int sy = cur_b.zero_pos % SIDE;

    for (int i = 0; i < 4; i++) {
      int new_x = sx + DX[i];
      int new_y = sy + DY[i];

      if (new_x < 0 || new_x >= SIDE || new_y < 0 || new_y >= SIDE) continue;

      Board new_b = cur_b;

      new_b.md -= MDs[new_x * SIDE + new_y][new_b.a[new_x * SIDE + new_y] - 1];
      new_b.md += MDs[sx * SIDE + sy][new_b.a[new_x * SIDE + new_y] - 1];

      swap(new_b.a[sx * SIDE + sy], new_b.a[new_x * SIDE + new_y]);
      new_b.zero_pos = new_x * SIDE + new_y;

      if (!visited[new_b]) {
        new_b.c++;
        State new_s;
        new_s.b= new_b;
        new_s.e = new_b.c + new_b.md;
        q.push(new_s);
      }
    }
  }

  //cout << "no goal" << endl;
}

int main() {
  for (int i = 0; i < N; i++)
    for (int j = 0; j < N; j++)
      MDs[i][j] = abs(i / SIDE - j / SIDE) + abs(i % SIDE - j % SIDE);

  Board in; 

  for (int i = 0; i < N; i++) {
    cin >> in.a[i];
    if (in.a[i] == 0) {
      in.a[i] = N;
      in.zero_pos = i;
    }
  }

  astar(in);
}

#include<stdio.h>
#include<iostream>
#include<cmath>
#include<string>
#include<cassert>
using namespace std;
#define N 4
#define N2 16
#define LIMIT 100

static const int dx[4] = {0, -1, 0, 1};
static const int dy[4] = {1, 0, -1, 0};
static const char dir[4] = {'r', 'u', 'l', 'd'};
int MDT[N2][N2];

struct Puzzle { int f[N2], space, MD; };

Puzzle state;
int limit;
int path[LIMIT];

int getAllMD(Puzzle pz) {
  int sum = 0;
  for ( int i = 0; i < N2; i++ ) {
    if ( pz.f[i] == N2 ) continue;
    sum += MDT[i][pz.f[i] - 1];
  }
  return sum;
}

bool isSolved() {
  for ( int i = 0; i < N2; i++ ) if ( state.f[i] != i + 1 ) return false;
  return true;
}


bool dfs(int depth, int prev) {
  if ( state.MD == 0 ) return true;
  if ( depth + state.MD > limit ) return false;

  int sx = state.space / N;
  int sy = state.space % N;
  Puzzle tmp;

  for ( int r = 0; r < 4; r++ ) {
    int tx = sx + dx[r];
    int ty = sy + dy[r];
    if ( tx < 0 || ty < 0 || tx >= N || ty >= N ) continue;
    if ( max(prev, r)-min(prev, r) == 2 ) continue;
    tmp = state;
    state.MD -= MDT[tx * N + ty][state.f[tx * N + ty] - 1];
    state.MD += MDT[sx * N + sy][state.f[tx * N + ty] - 1];
    swap(state.f[tx * N + ty], state.f[sx * N + sy]);
    state.space = tx * N + ty;
    if ( dfs(depth + 1, r) ) { path[depth] = r; return true; }
    state = tmp;
  }

  return false;
}

string iterative_deepening(Puzzle in) {
  in.MD = getAllMD(in);

  for ( limit = in.MD; limit <= LIMIT; limit++ ) {
    state = in;
    if ( dfs(0, -100) ) {
      string ans = "";
      for ( int i = 0; i < limit; i++ ) ans += dir[path[i]];
      return ans;
    }
  }

  return "unsolvable";
}

int main() {
  for ( int i = 0; i < N2; i++ )
    for ( int j = 0; j < N2; j++ )
      MDT[i][j] = abs(i / N - j / N) + abs(i % N - j % N);

  Puzzle in;

  for ( int i = 0; i < N2; i++ ) {
    cin >> in.f[i];
    if ( in.f[i] == 0 ) {
      in.f[i] = N2;
      in.space = i;
    }
  }
  string ans = iterative_deepening(in);
  cout << ans.size() << endl;

  return 0;
}

