				next_table[a][b][c] = table[b][c];
			}
		}
	}
	tmp_loc = zeroLoc(table);
	switch(tmp_loc){
	case 0:
		swap(next_table[0][0][0],next_table[0][0][1]);
		if(count < max_depth && calcDiffSum(next_table[0]) <= max_depth-count){
			recursive(next_table[0],max_depth,count+1);
		}

