#include <iostream>
#include <queue>
#include <map>
#include <cmath>
using namespace std;

const int N = 16;
const int sN = 4;

struct pz{
	int a[N];
	int t;

	bool operator < (const pz &p) const {
		for (int i = 0; i < N; i++) {
			if (a[i] == p.a[i])
				continue;
			return a[i] > p.a[i];
		}
		return false;
	}
};

int dis(int a[]) {
	int d = 0;
	for (int i = 0; i < N; i++)
		d += abs((a[i] - 1) / sN - i / sN) + abs((a[i] - 1) % sN - i % sN);
	return d;
}

int main()
{
	pz p;
	int n = -1;
	map<pz, bool> v;

	for (int i = 0; i < N; i++)
		cin >> p.a[i];

	p.t = 0;
	int mxD = dis(p.a) + 5;

	queue<pz> que;
	que.push(p);
	v[p] = true;

	while (!que.empty()) {
		pz g = que.front();
		que.pop();

		bool f = 1;

		for (int i = 0; i < N - 1; i++) {
			if (g.a[i] != (i + 1)) {
				f = 0;
				break;
			}
		}

		if (f == 1) {
			n = g.t;
			break;
		}

		for (int i = 0; i < N; i++) {
			if (g.a[i] == 0) {
				if(i % sN != 0){
					g.t++;
					swap(g.a[i], g.a[i - 1]);
					if (!v[g] && dis(g.a) < mxD) {
						v[g] = true;
						que.push(g);
					}
					swap(g.a[i], g.a[i - 1]);
					g.t--;
				}
				if (i % sN != sN - 1) {
					g.t++;
					swap(g.a[i], g.a[i + 1]);
					if (!v[g] && dis(g.a) < mxD) {
						v[g] = true;
						que.push(g);
					}
					swap(g.a[i], g.a[i + 1]);
					g.t--;
				}
				if (i / sN != 0) {
					g.t++;
					swap(g.a[i], g.a[i - sN]);
					if (!v[g] && dis(g.a) < mxD) {
						v[g] = true;
						que.push(g);
					}
					swap(g.a[i], g.a[i - sN]);
					g.t--;
				}
				if (i / sN != sN - 1) {
					g.t++;
					swap(g.a[i], g.a[i + sN]);
					if (!v[g] && dis(g.a) < mxD) {
						v[g] = true;
						que.push(g);
					}
					swap(g.a[i], g.a[i + sN]);
					g.t--;
				}
			}
		}
	}

	cout << n << endl;

	return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int N = 4;
static const int N2 = 16;
static const int LIMIT = 100;

static const int dx[4] = { 0, -1,  0, 1};
static const int dy[4] = { 1,  0, -1, 0};
static const char dir[4] = {'r', 'u', 'l', 'd'};
int MDT[N2][N2];

struct Puzzle {
    int f[N2], space, MD;
    int cost;

    bool operator < (const Puzzle &p) const {
        for (int i = 0; i < N2; i++) {
            if (f[i] == p.f[i]) continue;
            return f[i] < p.f[i];
        }
        return false;
    }
};

struct State {
    Puzzle puzzle;
    int estimated;
    bool operator < (const State &s) const {
        return estimated > s.estimated;
    }
};

int getAllMD(Puzzle pz) {
    int sum = 0;
    for (int i = 0; i < N2; i++) {
        if (pz.f[i] == N2) continue;
        sum += MDT[i][pz.f[i] - 1];
    }
    return sum;
}

int astar(Puzzle s) {
    priority_queue<State> PQ;
    s.MD = getAllMD(s);
    s.cost = 0;
    map<Puzzle, bool> V;
    Puzzle u, v;
    State initial;
    initial.puzzle = s;
    initial.estimated = getAllMD(s);
    PQ.push(initial);

    while (!PQ.empty()) {
        State st = PQ.top(); PQ.pop();
        u = st.puzzle;

        if (u.MD == 0) return u.cost;
        V[u] = true;

        int sx = u.space / N;
        int sy = u.space % N;

        for (int r = 0; r < 4; r++) {
            int tx = sx + dx[r];
            int ty = sy + dy[r];
            if (tx < 0 || ty < 0 || sx >= N || sy >= N) continue;
            v = u;

            v.MD -= MDT[tx*N+ty][v.f[tx*N+ty]-1];
            v.MD += MDT[sx*N+sy][v.f[tx*N+ty]-1];
            swap(v.f[sx*N+sy], v.f[tx*N+ty]);
            v.space = tx*N+ty;

            if (!V[v]) {
                v.cost++;
                State news;
                news.puzzle = v;
                news.estimated = v.cost + v.MD;
                PQ.push(news);
            }
        }
    }
    return -1;
}


int main(void) {
    for (int i = 0; i < N2; i++) {
      for (int j = 0; j < N2; j++) {
        MDT[i][j] = abs(i/N - j/N) + abs(i%N - j%N);
      }
    }

    Puzzle in;
    for (int i = 0; i < N2; i++) {
      cin >> in.f[i];
      if (in.f[i] == 0) {
        in.f[i] = N2;
        in.space = i;
      }
    }

    cout << astar(in) << endl;

    return 0;
}

