const int n = 4;
struct node {
  int B[n][n];
  int x, y; // zero position
  int depth; 
  int manhattan_distance;

  int md(int i, int j) {
    if (B[i][j] == 0) return 0;
    int x = B[i][j] - 1;
    return abs(x%4 - j) + abs(x/4 - i);
  }
  void init() {
    depth = 0;
    manhattan_distance = 0;
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < n; ++j) {
        if (B[i][j] == 0) { x = i; y = j; }
        else manhattan_distance += md(i, j);
      }
    }
    //cout << "manhattan distance = " << manhattan_distance << endl;
  }
  bool move(int d) {  // [0 1 2 3] = [L D R U]
    int dx[] = {-1,0,1,0}, dy[] = {0,-1,0,1};
    int X = x + dx[d], Y = y + dy[d];
    if (X < 0 || X >= n || Y < 0 || Y >= n) return false;
    manhattan_distance -= md(X,Y) + md(x,y);
    swap(B[x][y], B[X][Y]);
    manhattan_distance += md(x,y) + md(X,Y);
    x = X; y = Y;
    depth += 1;
    return true;
  }
  int score() const {
    return depth + manhattan_distance;
  }
  bool is_goal() const {
    for (int i = 0; i < 4; ++i) {
      for (int j = 0; j < 4; ++j) {
        if (i == 3 && j == 3) continue;
        if (B[i][j] != 4*i+j+1) return false;
      }
    }
    return true;
  }
  bool operator<(const node &x) const {
    return score() > x.score();
  }
  long long hash() const {
    long long h = 0, p = 1e9+7;
    for (int i = 0; i < 4; ++i)
      for (int j = 0; j < 4; ++j)
        h = (h * p) + B[i][j];
    return h;

    vector<int> x(16);
    for (int i = 0; i < 4; ++i)
      for (int j = 0; j < 4; ++j)
        x[4*i+j] = B[i][j];
    int n = x.size();
    vector<int> y(n);
    for (int i = 0; i < n; ++i) y[x[i]] = i;
    long long c = 0, fac = 1;
    for (; n > 1; --n) {
      c += fac * x[n-1]; fac *= n;
      swap(x[n-1], x[y[n-1]]);
      swap(y[n-1], y[x[y[n-1]]]);
    }
    return c;
  }
};
