// recursive best first searh
void search(node root) {
  unordered_set<long long> seen;
  typedef pair<int, bool> result;
  function<result(const node&,int,int)> rec = 
    [&](const node &u, int lower, int bound) {

    long long h = u.hash();
    seen.insert(h);
    //cout << "u.score() = " << u.score() << endl;

    /*
    cout << "---" << endl;
    cout << "lower = " << lower << endl;
    cout << "bound = " << bound << endl;
    cout << "manhattan = " << u.manhattan_distance << endl;
    for (int i = 0; i < 4; ++i) {
      for (int j = 0; j < 4; ++j) {
        cout << u.B[i][j] << " ";
      }
      cout << endl;
    }
    */

    if (lower > bound) { seen.erase(h); return result(lower, false); }
    if (u.is_goal()) { seen.erase(h); return result(u.score(), true); }

    vector<pair<node,int>> next;
    for (int d = 0; d < 4; ++d) {
      node v = u; 
      if (v.move(d)) {
        long long hh = v.hash();
        if (seen.count(hh)) continue;
        if (u.score() < lower) next.push_back({v, min(lower, v.score())});
        else                   next.push_back({v, v.score()});
      }
    }
    if (next.size() == 0) { seen.erase(h); return result(9999999, false); }
    while (1) {
      int i = 0, threshold = 99999999;
      for (int j = 0; j < next.size(); ++j) {
        if (next[j].snd < next[i].snd) {
          threshold = next[i].snd; i = j;
        } else if (next[j].snd < threshold) {
          threshold = next[j].snd;
        }
      }
      if (next[i].snd > bound) {
        seen.erase(h);
        return result(next[i].snd, false);
      }
      result z = rec(next[i].fst, next[i].snd, min(bound, threshold));
      if (z.snd) { seen.erase(h); return z; }
      next[i].snd = z.fst;
    }
  };
  result z = rec(root, 0, 9999999);
  cout << z.fst << endl;
}


