            {
                if (p1.first[i][j] == (char)0)
                {
                    tx = j; ty = i;
                }
            }
        }


        // ------ Moving ------ //

        for (int dir = 0; dir < 4; dir++)
        {
            if (0 <= tx + dx[dir] && tx + dx[dir] < p1.first[0].size() && 0 <= ty + dy[dir] && ty + dy[dir] < p1.first.size())
