#define N 4
#define NN 16
#define LIMIT 100

struct Pazzle
{
    int f[NN], space, MD;
};

int MDT[NN][NN];
int limit;
int ans;
int dx[4] = {0, 1, 0, -1};
int dy[4] = {1, 0, -1, 0};
Pazzle state;

int calcAllMD(Pazzle p)
{
    int ret = 0;
    for (int i = 0; i < NN; i++)
    {
        if (p.f[i] == NN)
            continue;
        ret += MDT[i][p.f[i] - 1];
    }
    return ret;
}

bool dfs(int depth, int prev)
{
    if (state.MD == 0)
    {
        ans = depth;
        return true;
    }

    if (state.MD + depth > limit)
        return false;

    int sx = state.space / N;
    int sy = state.space % N;

    Pazzle tmp;

    for (int i = 0; i < 4; i++)
    {
        int tx = sx + dx[i];
        int ty = sy + dy[i];

        if (tx < 0 || tx >= N || ty < 0 || ty >= N)
            continue;
        if (abs(prev - i) == 2)
            continue;

        tmp = state;
        state.MD -= MDT[tx * N + ty][state.f[tx * N + ty] - 1];
        state.MD += MDT[sx * N + sy][state.f[tx * N + ty] - 1];
        swap(state.f[tx * N + ty], state.f[sx * N + sy]);
        state.space = tx * N + ty;
        state.MD = calcAllMD(state);
        if (dfs(depth + 1, i))
            return true;
        state = tmp;
    }

    return false;
}

void iterativeDeepening(Pazzle in)
{
    in.MD = calcAllMD(in);

    for (limit = in.MD; limit <= LIMIT; limit++)
    {
        state = in;
        if (dfs(0, -100))
        {
            cout << ans << endl;
            return;
        }
    }
}

