vector<string> split(const string &str, char sep)
{
    vector<string> v;
    stringstream ss(str);
    string buffer;
    while(getline(ss, buffer, sep) ) {
        v.push_back(buffer);
    }
    return v;
}

vector<int> neighbor(int pos)
{
    vector<int> rt;
    if (pos % N != 0)
        rt.push_back(pos - 1);
    if (pos % N != N - 1)
        rt.push_back(pos + 1);
    if (pos - N >= 0)
        rt.push_back(pos - N);
    if (pos + N < N * N)
        rt.push_back(pos + N);
    return rt;
}

int bfs()
{
    string st;
    int cnt, pos;
    while (!Q.empty()) {
        st = Q.front().first;
        cnt = Q.front().second;
        Q.pop();
        if (mp.count(st)) {
            if (mp[st] == FLG) {
                continue;
            } else if (mp[st] == GOAL) {
                return cnt;
            } else
                printf("ERROR: %d\n", __LINE__);
        }
        mp[st] = FLG;
        vector<string> stv(split(st, ' ')); 
        pos = distance(stv.begin(), find(stv.begin(), stv.end(), "0"));
        vector<int> nb(neighbor(pos));
        for (int i = 0; i < nb.size(); i++) {
            vector<string> tmpv(stv);
            string tmp;
            tmpv[pos] = stv[nb[i]]; tmpv[nb[i]] = stv[pos];
