};

// パネルの並びの情報を持つクラス
class Board
{
    public:
        // パネルの並びを保持する配列
        int panel[PANEL_NUM];
        // ゼロのパネルの位置
        int zeroPos;
        // ゴールに到達するまでに必要なコスト
        int cost;
        // 並び替えた回数
        int moveCount;

        // コンストラクタ
        Board(int board[], int mCount)
        {
            for(int i = 0; i < PANEL_NUM; i++)
            {
                panel[i] = board[i];
            }

            zeroPos = searchZeroPos();
            cost = calcMoveDistance();

            moveCount = mCount;
        }

        // 演算子のオーバーロード ( sort()で使用 )
        bool operator < ( const Board &e ) const
        {
            // costをキーにして並べ替える
            return cost < e.cost;
        }

        // 配列中のゼロの位置を探索する関数
        int searchZeroPos()
        {
            for(int i = 0; i < PANEL_NUM; i++)
            {
                if( panel[i] == 0 )
                {
                    return i;
                }
            }

            return -1;
        }

        // ゴールに到達したかを判定する関数
        bool reachGoal()
        {
            for(int i = 0; i < PANEL_NUM; i++)
            {
                if( panel[i] != ary_Target[i] )
                {
                    return false;
                }
            }

            return true;
        }

        // パネルの並びから, 正解までに必要な移動距離を求める
        int calcMoveDistance()
        {
            int num = 0;
            int distance = 0;

            for(int i = 0; i < PANEL_NUM; i++)
            {
                num = panel[i];

                // 最短の移動距離の和を求める
                distance += moveDistance[num][i];
            }

            return distance;
        }
};

// 初手からの動かしたパネルを記憶しておく配列
int ary_movedPanel[MAX_STEP];

// 移動したパネルの状態を保持するvector
vector<Board> v_board;

// 最小移動回数を保持する変数
int minMoveCount;

void panelMoveOperation();
int calcArrayNum(int x, int y);

