}

// パネルの移動操作を実施する関数
void panelMoveOperation(void)
{
    // 要素の並び替えを実施する
    sort(v_board.begin(), v_board.end());

    // コストの一番小さい, 先頭要素を取り出す
    Board Bad = Board(v_board[0].panel, v_board[0].moveCount);
    // 先頭要素を削除する
    v_board.erase(v_board.begin());

    // 並び替えた状態がゴールに到達しているかを確認する
    if( Bad.reachGoal() == true )
    {
        // 検索終了
        minMoveCount = Bad.moveCount;
        return;
    }

    int x, y;

    // ゼロの位置を x, y 座標に変換する
    x = Bad.zeroPos / 4;
    y = Bad.zeroPos % 4;

    int mCount = 0;

    // 上下左右にパネルを移動させる
    for(int i = 0; i < MOVE_LAST; i++)
    {

        int tx, ty;
        bool searchFlag;

        // 移動後の座標を計算する
        tx = x + move_p[i].x;
        ty = y + move_p[i].y;

        if( ( 0 <= tx && tx <= 3 ) && ( 0 <= ty && ty <= 3 ) )
        {
            searchFlag = true;

            // 移動用の新しい実体を作成する
            Board newBoard = Board(Bad.panel, Bad.moveCount);

            int moveNum, movePos;

            // 座標から配列の要素No.へ変換する
            movePos = calcArrayNum(tx, ty);
            // 移動するパネルNo.を取得する
            moveNum = newBoard.panel[movePos];

            for(int i = 0; i < movedCount; i++)
            {
                if( moveNum == movedPanel[i] )
                {
                    // 前回動かしたパネルなら, 元に戻るだけなので何もしない
                    searchFlag = false;
                    break;
                }
            }

            if( searchFlag == false )
            {
                continue;
            }

            // 動かしたパネルを記憶しておく
            totalCount++;
            ary_movedPanel[totalCount] = moveNum;
            mCount++;

            // パネルを入れ替える
            swap(newBoard.panel[Bad.zeroPos], newBoard.panel[movePos]);
            newBoard.moveCount++;

            // コストの再計算を実施する
            newBoard.cost = newBoard.cost - moveDistance[moveNum][movePos] + moveDistance[moveNum][newBoard.zeroPos];

            // 新しい盤面を vector に追加する
            v_board.push_back(newBoard);
        }
    }

    movedCount = mCount;

    for(int i = mCount; i > 0; i--)
    {
        movedPanel[i - 1] = ary_movedPanel[totalCount - i + 1];
    }

    // 再帰呼び出しを実施
    panelMoveOperation();

    return;
}

