using namespace std;

static const int N = 4;
static const int N2 = 16;
static const int LIMIT = 45;

int MDTable[N2][N2];

struct Puzzle {
    int piece[N2];
    int space;
    int MD;
};

Puzzle state;
int limit;
int path[LIMIT];

static const int dx[4] = {-1, 0, 1, 0};
static const int dy[4] = {0, -1, 0, 1};
static const char dir[4] = {'u', 'l', 'd', 'r'};

int getAllMD(Puzzle puzzle)
{
    int sum = 0;
    for (int i = 0; i < N2; i++)
    {
        if (puzzle.piece[i] == N2)
            continue;
        sum += MDTable[i][puzzle.piece[i] - 1];
    }
    return sum;
}

bool isSolved()
{
    for (int i = 0; i < N2; i++)
        if (state.piece[i] != (i + 1)) // 不正解
            return false;

    return true;
}

bool dfs(int depth, int prev)
{
    if (state.MD == 0)
        return true;
    if (depth + state.MD > limit)
        return false;

    int sx = state.space / N; // 空きマスのx座標
    int sy = state.space % N; // 空きマスのy座標
    Puzzle tmp;

    for (int direct = 0; direct < 4; direct++)
    {
        int tx = sx + dx[direct]; // 遷移先の空きマスのx座標
        int ty = sy + dy[direct]; // 遷移先の空きマスのy座標
        if (tx < 0 || tx >= N || ty < 0 || ty >= N)
            continue; // 枠外にでたら無視
        if (max(prev, direct) - min(prev, direct) == 2)
            continue;
        tmp = state;
        state.MD -= MDTable[tx * N + ty][state.piece[tx * N + ty] - 1];
        state.MD += MDTable[state.space][state.piece[tx * N + ty] - 1];
        swap(state.piece[state.space], state.piece[tx * N + ty]); // ピースを移動
        state.space = tx * N + ty;
        if(dfs(depth + 1, direct))
        {
            path[depth] = direct;
            return true;
        }
        state = tmp;
    }
    return false;
}

string iterative_deepening(Puzzle input)
{
    input.MD = getAllMD(input);

    for(limit = input.MD; limit <= LIMIT; limit++)
    {
        state = input;
        if(dfs(0, -100))
        {
            string answer = "";
            for(int i = 0; i < limit; i++)
                answer += dir[path[i]];
            return answer;
        }
    }
    return "unsolvable";
}

int main()
{
    for (int i = 0; i < N2; i++)
        for (int j = 0; j < N2; j++)
            MDTable[i][j] = abs(i / N - j / N) + abs(i % N - j % N);

    Puzzle input;

    for (int i = 0; i < N2; i++)
    {
        cin >> input.piece[i];
        if (input.piece[i] == 0)
        {
            input.piece[i] = N2;
            input.space = i;
        }
    }

    string answer = iterative_deepening(input);
    cout << answer.size() << endl;
}

