    return visited.find( b ) != visited.end();
}

void Register( const vector<int>& b ) {
    visited.insert( b );
}

bool IsCompleted( const vector<int>& b ) {
    for ( int i=0; i<15; ++i ) {
	if ( b[i] != i+1 ) return false;
    }
    return b[15] == 0;
}

int H1( const vector<int>& b ) {
    int dist = 0;
    for ( int i=0; i<15; ++i ) dist += b[i] == (i+1) ? 1 : 0;
    return dist;
}

int H2( const vector<int>& b ) {
    static int tab[16][2] = {
	{ 3, 3 },//0
	{ 0, 0 }, { 1, 0 }, { 2, 0 }, { 3, 0 },
	{ 0, 1 }, { 1, 1 }, { 2, 1 }, { 3, 1 },
	{ 0, 2 }, { 1, 2 }, { 2, 2 }, { 3, 2 },
	{ 0, 3 }, { 1, 3 }, { 2, 3 } };

    int dist = 0;
    for ( int i=0; i<16; ++i ) {
	if ( b[i] == 0 ) continue;//ignore pos of 0
	int x = i%4;
	int y = i/4;
	dist += abs( tab[b[i]][0] - x ) + abs( tab[b[i]][1] - y );
    }
    return dist;
}

