bool IsCompleted( const vector<int>& b ) {
    for ( int i=0; i<15; ++i ) {
	if ( b[i] != i+1 ) return false;
    }
    return b[15] == 0;
}

int H1( const vector<int>& b ) {
    int dist = 0;
    for ( int i=0; i<15; ++i ) dist += b[i] == (i+1) ? 1 : 0;
    return dist;
}

int H2( const vector<int>& b ) {
    static int tab[16][2] = {
	{ 3, 3 },//0
	{ 0, 0 }, { 1, 0 }, { 2, 0 }, { 3, 0 },
	{ 0, 1 }, { 1, 1 }, { 2, 1 }, { 3, 1 },
	{ 0, 2 }, { 1, 2 }, { 2, 2 }, { 3, 2 },
	{ 0, 3 }, { 1, 3 }, { 2, 3 } };

    int dist = 0;
    for ( int i=0; i<16; ++i ) {
	if ( b[i] == 0 ) continue;//ignore pos of 0
	int x = i%4;
	int y = i/4;
	dist += abs( tab[b[i]][0] - x ) + abs( tab[b[i]][1] - y );
    }
    return dist;
}

const int dx[4] = { -1, 0, 1,  0 };
const int dy[4] = {  0, 1, 0, -1 };
vector<int> board, board_org( 16 );

bool Solve( int x, int y, int curr, int lim ) {

    if ( IsCompleted( board ) ) return true;

    //    cout << "--- " << x << " " << y << " " << curr << " " << lim << endl;
    //    PrintBoard( board );

    if ( curr == lim ) return false;

    for ( int i=0; i<4; ++i ) {

	int nx = x + dx[i];
	int ny = y + dy[i];

	if ( nx < 0 || nx > 3 || ny < 0 || ny > 3 ) continue;

	swap( board[4*y+x], board[4*ny+nx] );

	//	cout << "i = " << i << " " << curr + H2( board ) << endl;
	//	PrintBoard( board );

	if ( curr + H2( board ) > lim ) {
	    swap( board[4*y+x], board[4*ny+nx] );
	    continue;
	}

	if ( Solve( nx, ny, curr+1, lim) ) return true;

	swap( board[4*y+x], board[4*ny+nx] );	
    }

    return false;
}

