  inistate.dist=0;
  inistate.mh_dist=0;
  inistate.pre=-1;
  rep(i,N)rep(j,N){
    int input;
    cin>>input;
    input--;
    inistate.board[i][j]=input;
    if(input==-1){
      inistate.bi=i;
      inistate.bj=j;
    }else{
      int ai=ans_ps[input].fi;
      int aj=ans_ps[input].se;
      inistate.mh_dist+=abs(ai-i)+abs(aj-j);
    }
  }

  priority_queue<state> que;
  que.push(inistate);
  d[inistate.board]=inistate.dist+inistate.mh_dist;
  while(que.size()){
    state crtstate=que.top(); que.pop();
    if(crtstate.dist+crtstate.mh_dist>d[crtstate.board])continue;
    if(crtstate.mh_dist==0){
      cout<<crtstate.dist<<endl;
      break;
    }
    rep(dir,4){
      if(dir==crtstate.pre)continue;
      int bi=crtstate.bi;
      int bj=crtstate.bj;
      int ni=bi+di[dir];
      int nj=bj+dj[dir];
      if(ni<0||ni>=N||nj<0||nj>=N)continue;
      state nxtstate;
      nxtstate.board=crtstate.board;
      nxtstate.dist=crtstate.dist;
      nxtstate.mh_dist=crtstate.mh_dist;

      int num=crtstate.board[ni][nj];
      int ai=ans_ps[num].fi;
      int aj=ans_ps[num].se;
      nxtstate.mh_dist-=abs(ai-ni)+abs(aj-nj);
      nxtstate.mh_dist+=abs(ai-bi)+abs(aj-bj);

      swap(nxtstate.board[bi][bj],nxtstate.board[ni][nj]);
      nxtstate.dist++;
      nxtstate.bi=ni; nxtstate.bj=nj;
      nxtstate.pre=(dir+2)%4;
      if(d.find(nxtstate.board)==d.end()||d[nxtstate.board]>nxtstate.dist+nxtstate.mh_dist){
        d[nxtstate.board]=nxtstate.dist+nxtstate.mh_dist;
        que.push(nxtstate);
      }
    }
  }

  clock_t end=clock();
  //cerr<<"duration = "<<(double)(end-start)/CLOCKS_PER_SEC<<" sec."<<endl;

	return 0;
}

#include <iostream>
#include <cstdio>
#include <vector>
using namespace std;

#define RC2P(r,c) (((r)<<2)+(c))	//r*4+c
#define P2R(p) ((p)>>2)				//p/4
#define P2C(p) ((p)&3)				//p%4
#define HASHMAX 1000003

typedef vector<int> Pkey;

struct Pandt{
	Pkey p;
	int t;
};

int dist(Pkey x);
int abs(int x);
void insert(vector<Pkey> &A, Pkey v);
Pkey extract(vector<Pkey> &A);
int SolvePuzzle(vector<int> P);


vector< Pandt > Puzzles(HASHMAX);

int h1(Pkey key){
	unsigned long long int keyI = 0;
	for (int i = 0; i < 16; i++){
		keyI += (unsigned long long int)(15 << i) & key[i];
	}
	return (int)(keyI % HASHMAX); 
}
int h2(Pkey key){
	unsigned long long int keyI = 0;
	for (int i = 0; i < 16; i++){
		keyI += (unsigned long long int)(15 << i) & key[i];
	}
	return (int)((keyI % (HASHMAX - 1)) + 1);
}
int HashFind(Pkey key);
int HashInsert(Pkey key, int val);


void InitHash(){
	Pandt Nullpandt;
	Nullpandt.p.resize(16);
	for (int i = 0; i < 16; i++) Nullpandt.p[i] = i;
	Nullpandt.t = -1;
	for (int i = 0; i < HASHMAX; i++){
		Puzzles[i] = Nullpandt;
	}
}

int HashFind(Pkey key){

	int curhash = h1(key);
	int sechash = h2(key);
	for (int i = 0; i < HASHMAX; i++){
		if (Puzzles[curhash].p == key && Puzzles[curhash].t != -1){
			return curhash;
		}
		else if (Puzzles[curhash].t == -1){
			return -1;
		}
		else{
			curhash = (curhash + sechash) % HASHMAX;
		}
	}
	return -1;
}

int HashInsert(Pkey key, int val){

	int curhash = h1(key);
	int sechash = h2(key);
	for (int i = 0; i < HASHMAX; i++){
		if (Puzzles[curhash].t == -1){
			Puzzles[curhash].t = val;
			Puzzles[curhash].p = key;
			return curhash;
		}
		else{
			curhash = (curhash + sechash) % HASHMAX;
		}
	}
	return -1;
}

void swap(int &a, int &b){
	int tmp = a;
	a = b;
	b = tmp;
	return;
}

int dist(Pkey x){
	int result = 0;
	for (int i = 0; i < 16; i++){
		if (x[i] == 0) continue;
		result += abs(P2C(x[i] - 1) - P2C(i)) + abs(P2R(x[i] - 1) - P2R(i));
	}
	int s = HashFind(x);
	return -result - (s == -1 ? 1048576 : Puzzles[s].t);
}

int abs(int x){
	return x < 0 ? -x : x;
}

void insert(vector< Pkey > &A, Pkey v){
	int n = A.size();
	A.push_back(v);
	while (n != 0){
		int i = (n - 1) >> 1;
		if (dist(A[n]) > dist(A[i])){
			Pkey tmp = A[n];
			A[n] = A[i];
			A[i] = tmp;
		}
		n = i;
	}
	return;
}

Pkey extract(vector< Pkey > &A){
	int n = A.size() - 1;
	Pkey res = A[0];
	A[0] = A[n];
	A.pop_back();

	for (int i = 0, j; 2 * i + 1 < n;){
		j = 2 * i + 1;
		if (j != n - 1 && dist(A[j]) < dist(A[j + 1])){
			j++;
		}
		if (dist(A[i]) < dist(A[j])){
			Pkey tmp = A[j];
			A[j] = A[i];
			A[i] = tmp;
		}
		i = j;
	}
	return res;
}

int SolvePuzzle(vector<int> P){
	vector< Pkey > Que;
	HashInsert(P, 0);
	insert(Que, P);
	int answer = 10000;
	while (!Que.empty()){
		Pkey extp = extract(Que);
		int extt = Puzzles[HashFind(extp)].t;
		int Cursor;
		bool isAligned = true;
		for (int i = 0; i < 16; i++){
			if (extp[i] != ((i + 1) & 15)){
				isAligned = false;
				break;
			}
		}
		if (isAligned){
			answer = extt;
			break;
		}

		if (extt >= 45) continue;

		for (int i = 0; i < 16; i++){
			if (extp[i] == 0){
				Cursor = i;
				break;
			}
		}
		vector<int> Qnext;
		int Qsearch;
		Pkey iQnext;
		if (Cursor >= 4){
			Qnext = extp;
			swap(Qnext[Cursor], Qnext[Cursor - 4]);
			Qsearch = HashFind(Qnext);
			if (Qsearch == -1){
				HashInsert(Qnext, extt + 1);
				insert(Que, Qnext);
			}
			else if (Puzzles[Qsearch].t > extt + 1){
				Puzzles[Qsearch].t = extt + 1;
				insert(Que, Qnext);
			}
		}
		if (Cursor < 12){
			Qnext = extp;
			swap(Qnext[Cursor], Qnext[Cursor + 4]);
			Qsearch = HashFind(Qnext);
			if (Qsearch == -1){
				HashInsert(Qnext, extt + 1);
				insert(Que, Qnext);
			}
			else if (Puzzles[Qsearch].t > extt + 1){
				Puzzles[Qsearch].t = extt + 1;
				insert(Que, Qnext);
			}
		}
		if (P2C(Cursor) != 0){
			Qnext = extp;
			swap(Qnext[Cursor], Qnext[Cursor - 1]);
			Qsearch = HashFind(Qnext);
			if (Qsearch == -1){
				HashInsert(Qnext, extt + 1);
				insert(Que, Qnext);
			}
			else if (Puzzles[Qsearch].t > extt + 1){
				Puzzles[Qsearch].t = extt + 1;
				insert(Que, Qnext);
			}
		}
		if (P2C(Cursor) != 3){
			Qnext = extp;
			swap(Qnext[Cursor], Qnext[Cursor + 1]);
			Qsearch = HashFind(Qnext);
			if (Qsearch == -1){
				HashInsert(Qnext, extt + 1);
				insert(Que, Qnext);
			}
			else if (Puzzles[Qsearch].t > extt + 1){
				Puzzles[Qsearch].t = extt + 1;
				insert(Que, Qnext);
			}
		}
	}

	return answer;
}

