int calcDiffSum(int table[4][4]){
    int sum = 0;
    for(int row=0;row<4;row++){
        for(int col=0;col<4;col++){
            if(table[row][col] != 0){
                sum += abs((table[row][col]-1)/4-row) + abs((table[row][col]-1)%4-col);
            }
        }
    }
    return sum;
}

int zeroLoc(int table[4][4]){
    int zero_loc;
    for(int i=0;i<4;i++){
        for(int k=0;k<4;k++){
            if(table[i][k]==0){
                zero_loc=10*i+k;
            }
        }
    }
    return zero_loc;
}

