using namespace std;

#define SIDE 4
#define N 16
#define LIMIT 100

struct Board {
  int state[N];
  int zero_pos;
  int md;
};

int DX[4] = { 0, 1, 0, -1 };
int DY[4] = { 1, 0, -1, 0 };
char DIR[4] = { 'u', 'r', 'd', 'l' };

int MDs[N][N];
int path[LIMIT];
Board b;
int limit;

bool dfs(int depth, int prev) {
  if (b.md <= 0) return true;
  if (depth + b.md > limit) return false;

  int sx = b.zero_pos / SIDE;
  int sy = b.zero_pos % SIDE;

  Board tmp;

  for (int i = 0; i < 4; i++) {
    int new_x = sx + DX[i];
    int new_y = sy + DY[i];

    if (new_x < 0 || new_x >= SIDE || new_y < 0 || new_y >= SIDE) continue;
    if (max(prev, i) - min(prev, i) == 2) continue;

    tmp = b; // preserve current board

    b.md += MDs[new_x * SIDE + new_y][b.state[new_x * SIDE + new_y] - 1];
    b.md -= MDs[sx * SIDE + sy][b.state[sx * SIDE + sy] - 1];

    swap(b.state[sx * SIDE + sy], b.state[new_x * SIDE + new_y]);
    b.zero_pos = new_x * SIDE + new_y;

    if (dfs(depth + 1, i)) {
      path[depth] = i;
      return true;
    }

    b = tmp; // restore current board
  }

  return false;
}

int get_MD_sum(Board in) {
  int sum = 0;
  for (int i = 0; i < N; i++) {
    if (in.state[i] == N) continue;
    sum += MDs[i][in.state[i] - 1];
  }
  return sum;
}

void ida(Board in) {
  in.md = get_MD_sum(in);

  for (limit = in.md; limit <= LIMIT; limit++) {
    b = in;
    if (dfs(0, -100)) {
      string ans = "";
      for (int i = 0; i < limit; i++) ans += DIR[path[i]];

      cout << ans.size() << endl;
      return;
    }
  }
}

