		}

		node * p = heap[1];
		heap_delete(heap, &n, 1);
		int side;
		if (p->steps[0] != -1 && p->steps[1] != -1) {
			continue;
		}
		else if (p->steps[1] == -1) {
			side = 0;
		}
		else {
			side = 1;
		}

		unsigned long long new_data;
		int zero_index = find_zero(p->data);
		int dif_f = 0;

		if (zero_index % 4 != 3) {
			new_data = move_right(p->data, zero_index, &dif_f, goal[side]);
			try
