vector<ll> searched[16][16][16][16][16][16];

class board{
public:
    int moves;
    int wrongs;
    int zero_place;
    int cost;
    vector<int> tiles;

    explicit board(vector<int> num, int move){
        wrongs = 0;
        tiles = num;
        REP(i, 16){
            if(num[i] == 0)
                zero_place = i;
            if(num[i] != answer[i])
                wrongs++;
        }
        moves = move;
        cost = wrongs + moves;
    }

    void board_to_int(){
        ll k = 0;
        REP(i, 10)
            k += (tiles[i+6] * pow(16, i));
        for(int i = searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]][tiles[5]].size(); i > 0 ; i--)
            if(k == searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]][tiles[5]][i-1])
                return;
        pq.push(board(tiles, moves+1));
        searched[tiles[0]][tiles[1]][tiles[2]][tiles[3]][tiles[4]][tiles[5]].push_back(k);
        return;
    }

    void move() {
        if(dir[zero_place][0]){
            swap(tiles[zero_place], tiles[zero_place-1]);
            board_to_int();
            swap(tiles[zero_place], tiles[zero_place-1]);
        }
        if(dir[zero_place][1]){
            swap(tiles[zero_place], tiles[zero_place-4]);
            board_to_int();
            swap(tiles[zero_place], tiles[zero_place-4]);
        }
        if(dir[zero_place][2]){
            swap(tiles[zero_place], tiles[zero_place+4]);
            board_to_int();
            swap(tiles[zero_place], tiles[zero_place+4]);
        }
        if(dir[zero_place][3]){
            swap(tiles[zero_place], tiles[zero_place+1]);
            board_to_int();
            swap(tiles[zero_place], tiles[zero_place+1]);
        }
    }
};

bool operator< (board b1, board b2){
    return ((b1.cost > b2.cost) ? true : false);
}

int solve(){
    pq.push(board(original, 0));
    while(1){
        auto target = pq.top();
        if(target.wrongs == 0)
            return target.cost;
        pq.pop();
        target.move();
    }
}

