using namespace std;

/* constant */

const int N = 4;
const int NN = N * N;

const int dxs[] = {1, 0, -1, 0}, dys[] = {0, -1, 0, 1};

/* typedef */

typedef unsigned long long ull;
typedef pair<int,ull> piul;
typedef map<ull,int> muli;

/* global variables */

muli dists;

/* subroutines */

inline int zeropos(ull bits) {
  for (int i = 0; i < NN; i++)
    if (((bits >> (i * 4)) & 0xf) == 0) return i;
  return -1;
}

inline ull move(ull u, int p0, int p1) {
  ull x = (u >> (4 * p1)) & 0xfULL;
  return ((u | (x << (4 * p0))) & ~(0xfULL << (4 * p1)));
}

/* main */

int main() {
  ull st = 0, gl = 0;

  for (int i = 0; i < NN; i++) {
    ull ai;
    cin >> ai;
    st |= (ai << (i * 4));
  }

  for (int i = 0; i < NN - 1; i++)
    gl |= ((ull)(i + 1) << (i * 4));
  //printf("st=%09llx, gl=%09llx\n", st, gl);

  if (st == gl) {
    puts("0");
    return 0;
  }

  dists[st] = 1;
  dists[gl] = -1;

  queue<piul> q;
  q.push(piul(1, st));
  q.push(piul(-1, gl));

  int mind = -1;

  while (! q.empty()) {
    piul u = q.front(); q.pop();
    int &ud = u.first;
    ull &ui = u.second;

    int upos = zeropos(ui);
    int ux = upos % N, uy = upos / N;

    for (int di = 0; di < 4; di++) {
      int vx = ux + dxs[di], vy = uy + dys[di];
      if (vx >= 0 && vx < N && vy >= 0 && vy < N) {
	int vpos = vy * N + vx;
	ull vi = move(ui, upos, vpos);

	int vd = ud + ((ud >= 0) ? 1 : -1);
	muli::iterator mit = dists.find(vi);
	if (mit == dists.end()) {
	  dists[vi] = vd;
	  q.push(piul(vd, vi));
	}
	else {
	  if (ud * mit->second < 0) {
	    int d = abs(mit->second - ud) - 1;
	    printf("%d\n", d);
	    exit(0);
	  }

	  if ((ud > 0 && mit->second > vd) || (ud < 0 && mit->second < vd)) {
	    mit->second = vd;
	    q.push(piul(vd, vi));
	  }
	}
      }
    }
  }
  return 0;
}

