	int space_row,space_col;
};

int clearFLG;
int diff_row[4] = {-1,0,0,1},diff_col[4] = {0,-1,1,0};

//map<string,bool> MAP;

int calcDiffSum(Info info){
    int sum = 0;

    for(int row = 0; row <= 3; row++){
    	for(int col = 0; col <= 3; col++){
    		if(info.table[row][col] == 0)continue;

    		switch(info.table[row][col]){
    		case 1:
    			sum += abs(row-0)+abs(col-0);
    			break;
    		case 2:
    			sum += abs(row-0)+abs(col-1);
    			break;
    		case 3:
    			sum += abs(row-0)+abs(col-2);
    			break;
    		case 4:
    			sum += abs(row-0)+abs(col-3);
    			break;
    		case 5:
    			sum += abs(row-1)+abs(col-0);
    			break;
    		case 6:
    			sum += abs(row-1)+abs(col-1);
    			break;
    		case 7:
    			sum += abs(row-1)+abs(col-2);
    			break;
    		case 8:
    			sum += abs(row-1)+abs(col-3);
    			break;
    		case 9:
    			sum += abs(row-2)+abs(col-0);
    			break;
    		case 10:
    			sum += abs(row-2)+abs(col-1);
    			break;
    		case 11:
    			sum += abs(row-2)+abs(col-2);
    			break;
    		case 12:
    			sum += abs(row-2)+abs(col-3);
    			break;
    		case 13:
    			sum += abs(row-3)+abs(col-0);
    			break;
    		case 14:
    			sum += abs(row-3)+abs(col-1);
    			break;
    		case 15:
    			sum += abs(row-3)+abs(col-2);
    			break;
    		}
    	}
    }
    return sum;
}

bool rangeCheck(int row,int col){
	if(row >= 0 && row <= 3 && col >= 0 && col <= 3)return true;
	else{
		return false;
	}
}

void recursive(Info info,int depth,int max_depth){

	if(clearFLG)return;

	if(depth == max_depth){

		if(info.table[0][0] == 1 && info.table[0][1] == 2 && info.table[0][2] == 3 && info.table[0][3] == 4 &&
				info.table[1][0] == 5 && info.table[1][1] == 6 && info.table[1][2] == 7 && info.table[1][3] == 8 &&
				info.table[2][0] == 9 && info.table[2][1] == 10 && info.table[2][2] == 11 && info.table[2][3] == 12 &&
				info.table[3][0] == 13 && info.table[3][1] == 14 && info.table[3][2] == 15){
			clearFLG = true;
		}
		return;
	}

	int adj_row,adj_col;

	for(int i = 0; i < 4; i++){
		adj_row = info.space_row+diff_row[i];
		adj_col = info.space_col+diff_col[i];

		if(!rangeCheck(adj_row,adj_col))continue;

		Info next_info;
		for(int row = 0; row <= 3; row++){
			for(int col = 0; col <= 3; col++){
				next_info.table[row][col] = info.table[row][col];
			}
		}

		swap(next_info.table[info.space_row][info.space_col],next_info.table[adj_row][adj_col]);

		/*string tmp;
		for(int row = 0; row <= 3; row++){
			for(int col = 0; col <= 3; col++){
				tmp.append(to_string(next_info.table[row][col])).append(to_string('*'));
			}
		}

		auto at = MAP.find(tmp);
		if(at != MAP.end())continue;

		MAP[tmp] = true;*/

		if(max_depth-(depth+1) < calcDiffSum(next_info))continue;

		next_info.space_row = adj_row;
		next_info.space_col = adj_col;

		recursive(next_info,depth+1,max_depth);
	}
}

