#include <bits/stdc++.h>

#define EPS (1e-10)
#define rep(i, a, b) for (int i = a; i < (int)(b); ++i)
#define rrep(i, a, b) for (int i = b - 1; i >= (int)(a); --i)

using namespace std;
using ll = long long;
using vi = vector<int>;
using vll = vector<ll>;
using vd = vector<double>;
using vvi = vector<vi>;

constexpr int N = 4;
constexpr int N2 = 16;
constexpr int dx[4] = {0, -1, 0, 1};
constexpr int dy[4] = {1, 0, -1, 0};

struct Puzzle {
    int f[N2], space, MD;
    int cost;

    bool operator<(const Puzzle& p) const {
        rep(i, 0, N2) {
            if (f[i] == p.f[i]) { continue; }
            return f[i] < p.f[i];
        }
        return false;
    }
};

struct State {
    Puzzle puzzle;
    int estimated;
    bool operator<(const State& s) const { return estimated > s.estimated; }
};

void init_md(vvi& MDT) {
    rep(i, 0, N2) {
        rep(j, 0, N2) { MDT[i][j] = abs(i / N - j / N) + abs(i % N - j % N); }
    }
}

int get_md(const Puzzle& pz, const vvi& MDT) {
    int sum = 0;
    rep(i, 0, N2) {
        if (pz.f[i] == N2) { continue; }
        sum += MDT[i][pz.f[i] - 1];
    }
    return sum;
}

int astar(Puzzle& s, const vvi& MDT) {
    s.MD = get_md(s, MDT);
    s.cost = 0;

    map<Puzzle, bool> V;
    Puzzle u, v;

    priority_queue<State> PQ;
    State initial;
    initial.puzzle = s;
    initial.estimated = s.MD;
    PQ.push(initial);

    while (!PQ.empty()) {
        State st = PQ.top();
        PQ.pop();

        u = st.puzzle;

        if (u.MD == 0) { return u.cost; }
        V[u] = true;

        int sx = u.space / N;
        int sy = u.space % N;

        rep(i, 0, 4) {
            int tx = sx + dx[i];
            int ty = sy + dy[i];
            if (tx < 0 || ty < 0 || tx >= N || ty >= N) { continue; }

            v = u;
            v.MD -= MDT[tx * N + ty][v.f[tx * N + ty] - 1];
            v.MD += MDT[sx * N + sy][v.f[tx * N + ty] - 1];

            swap(v.f[sx * N + sy], v.f[tx * N + ty]);
            v.space = tx * N + ty;
            if (!V[v]) {
                ++v.cost;
                State news;
                news.puzzle = v;
                news.estimated = v.cost + v.MD;
                PQ.push(news);
            }
        }
    }
    return -1;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    Puzzle P;
    rep(i, 0, N2) {
        cin >> P.f[i];
        if (P.f[i] == 0) {
            P.f[i] = N2;
            P.space = i;
        }
    }

    vvi MDT(N2, vi(N2));
    init_md(MDT);

    cout << astar(P, MDT) << endl;

    return 0;
}

