 // 目标状态的数字所在位置
int mpp[Max][Max],mpp2[Max*Max]; 

int flag = 0,limit,Mi;
// 曼哈顿距离为 所有的数字要走到目标状态，最少要和0换的次数； 
int ddd(int mpp[Max][Max])
{
	int i,j;
	int sum = 0;
	for(i = 0;i<4;i++)
	{
		for(j = 0;j<4;j++)
		{
			if(mpp[i][j]!=0)    //判断曼哈顿距离不能判断0； 
				sum += abs(i-goal[mpp[i][j]][0])+abs(j - goal[mpp[i][j]][1]); 
		}
	}
	return sum;
}
int nix(int mpp2[Max*Max])
{
	int i,j;
	int x,y;
	int sum = 0;
	for(i =0;i<Max*Max;i++)
	{
		if(mpp2[i]==0)
		{
			y = i/4;
			x = i%4;
			continue;
		}
		for(j = i+1;j<Max*Max;j++)
		{
			if(mpp2[i]>mpp2[j])
				sum++;
		}
	}
	return sum;

}

void dfs(int y,int x,int len,int f)   // x,y当前0的坐标 len 为已经走了几步了； 
{									 	// f为当上一次的搜索方向 为了不回搜， 
	int d = ddd(mpp);
	if(flag) return;
	if(len<=limit)
	{
		if(d==0)
		{
			flag = 1;
			Mi = len;
			return ;
		}
		if(len==limit) return;
	}

	for(int i = 0;i<4;i++)
	{
		int tx = x + a[i][0];
		int ty = y + a[i][1];
		if(tx>=0&&ty>=0&&ty<4&&tx<4&&((f==-1)||i!=(f+2)%4))
		{
			swap(mpp[y][x],mpp[ty][tx]);
			if(len+ddd(mpp)<=limit)   // IDA* 减值，当前走的步数 加上 当前状态到达标状态的最小步数， 
			{						// 要小于等于 当前枚举到的最小的 从起始状态到达目标状态的步数，不能超过； 
				dfs(ty,tx,len+1,i);
				if(flag) return ;
			}
			swap(mpp[y][x],mpp[ty][tx]);
		}
	}
}
int main()
{
	int i,j;
	while(~scanf("%d",&mpp2[0]))
	{
		int y,x;
		mpp[0][0] = mpp2[0];
		if(mpp2[0]==0)
		{
			y = 0;
			x = 0;
		}
		for(i = 1;i<Max*Max;i++)
		{
			scanf("%d",&mpp2[i]);
			mpp[i/4][i%4] = mpp2[i];
			if(mpp2[i]==0)
			{
				y = i/4;
				x = i%4;
			}
		}
		int k = abs(y-goal[0][0]);

		int pp = nix(mpp2);

		int f = 1;
		if((pp+k)%2!=0)
			f = 0;
		if(!f)
		{
			//printf("pp==%d\n",pp);
			printf("00000000000\n");
			continue;
		}
		flag = 0;
		limit = ddd(mpp);    // 当前要达到目标状态的最小步数； 
		while(!flag&&limit<=55)  
		{
			dfs(y,x,0,-1);
			if(!flag)
				limit ++;    // 枚举最小步数； 
		}
		if(flag)
			printf("%d\n",Mi);
	}
	return 0;
}

