			swap(v[coor],v[coor-X]);
			if(m.find(v)==m.end() && calc(v)<=val+THRESHOLD)m[v]=make_pair(coor-X,depth+1),q.push(make_pair(v,f));
			if(m2.find(v)!=m2.end()){printf("%d\n",m2[v].second+depth+1);return 0;}
			swap(v[coor],v[coor-X]);
		}
		if(y<Y-1){
			swap(v[coor],v[coor+X]);
			if(m.find(v)==m.end() && calc(v)<=val+THRESHOLD)m[v]=make_pair(coor+X,depth+1),q.push(make_pair(v,f));
			if(m2.find(v)!=m2.end()){printf("%d\n",m2[v].second+depth+1);return 0;}
			swap(v[coor],v[coor+X]);
		}
	}
}

#include <stdio.h>
#include <stdlib.h>
#define N 4

int map[N][N];
int x0,y0;
int lim;
bool check(void){
	for(int i=0;i<N;i++){
		for(int j=0;j<N;j++){
			if(i==3&&j==3) break;
			if(map[i][j]!=i*N+j+1) return false;
		}
	}
	if(map[N-1][N-1]!=0)return false;
	return true;
}

bool swapping(int x,int y,int dep){
	int temp=map[x0+x][y0+y];
	map[x0+x][y0+y]=map[x0][y0];
	map[x0][y0]=temp;
	x0+=x;
	y0+=y;
	if(check()){
		printf("%d\n",dep);
		exit(0);
		return true;
	}
	if(dep<=lim){
		if(x!=1&&x0-1!=-1) swapping(-1,0,dep+1);
		if(x!=-1&&x0+1!=N) swapping(1,0,dep+1);
		if(y!=1&&y0-1!=-1) swapping(0,-1,dep+1);
		if(y!=-1&&y0+1!=N) swapping(0,1,dep+1);
	}
	temp=map[x0-x][y0-y];
	map[x0-x][y0-y]=map[x0][y0];
	map[x0][y0]=temp;
	x0-=x;
	y0-=y;
	return false;
}
int main(void){
	for(int i=0;i<N;i++){
		for(int j=0;j<N;j++){
			scanf("%d",&map[i][j]);
			if(map[i][j]==0){
				x0=i;
				y0=j;
			}
		}
	}
	if(check()){
		printf("0\n");
		return 0;
	}
	for(lim=1;lim<46;lim++){
		if(x0-1!=-1) swapping(-1,0,1);
		if(x0+1!=N) swapping(1,0,1);
		if(y0-1!=-1) swapping(0,-1,1);
		if(y0+1!=N) swapping(0,1,1);
	}
	printf("Unsolved\n");
	return 0;
}

