		int cost = dist[now];
		q.pop();

		if(now==end){
			cout<<dist[end]<<endl;
			break;
		}

		vector<vector<int>> next;
		int z = find(now.begin(), now.end(), 0) - now.begin();
		if(z > 3){
			vector<int> nx = now;
			swap(nx[z], nx[z-4]);
			next.push_back(nx);
		}
		if(z < 12){
			vector<int> nx = now;
			swap(nx[z], nx[z+4]);
			next.push_back(nx);
		}
		if(z % 4 > 0){
			vector<int> nx = now;
			swap(nx[z], nx[z-1]);
			next.push_back(nx);
		}
		if(z % 4 < 3){
			vector<int> nx = now;
			swap(nx[z], nx[z+1]);
			next.push_back(nx);
		}

		for(auto n : next){
			if(dist.find(n) == dist.end() || 1+cost < dist[n]){
				int hv = h(n);
				dist[n]= 1 + cost;
				if(hv < 35) q.push(P(hv + dist[n], n));
			}
		}
	}
}

