			swap(next_table[0][3][0],next_table[0][2][0]);
			if(count < max_depth && calcDiffSum(next_table[0]) <= max_depth-count){
				recursive(next_table[0],max_depth,count+1,tmp_loc);
			}
		}

		if(pre_loc != 31){
			swap(next_table[1][3][0],next_table[1][3][1]);
			if(count < max_depth && calcDiffSum(next_table[1]) <= max_depth-count){
				recursive(next_table[1],max_depth,count+1,tmp_loc);
			}
		}
		break;
	case 31:
	case 32:
		tmp_row = tmp_loc/10,tmp_col = tmp_loc%10;
		pre_row = pre_loc/10,pre_col = pre_loc%10;

		for(int a=0;a<3;a++){
			for(int b=0;b<4;b++){
				for(int c=0;c<4;c++){
					next_table[a][b][c] = table[b][c];
				}
			}
		}

		if(tmp_row!=pre_row||tmp_col!=pre_col+1){
			swap(next_table[0][tmp_row][tmp_col],next_table[0][tmp_row][tmp_col-1]);
			if(count < max_depth && calcDiffSum(next_table[0]) <= max_depth-count){
				recursive(next_table[0],max_depth,count+1,tmp_loc);
			}
		}

		if(tmp_row!=pre_row+1||tmp_col!=pre_col){
			swap(next_table[1][tmp_row][tmp_col],next_table[1][tmp_row-1][tmp_col]);
			if(count < max_depth && calcDiffSum(next_table[1]) <= max_depth-count){
				recursive(next_table[1],max_depth,count+1,tmp_loc);
			}
		}

		if(tmp_row!=pre_row||tmp_col!=pre_col-1){
			swap(next_table[2][tmp_row][tmp_col],next_table[2][tmp_row][tmp_col+1]);
			if(count < max_depth && calcDiffSum(next_table[2]) <= max_depth-count){
				recursive(next_table[2],max_depth,count+1,tmp_loc);
			}
		}
		break;
	case 33:

		for(int a=0;a<2;a++){
			for(int b=0;b<4;b++){
				for(int c=0;c<4;c++){
					next_table[a][b][c] = table[b][c];
				}
			}
		}

		if(pre_loc != 23){
			swap(next_table[0][3][3],next_table[0][2][3]);
			if(count < max_depth && calcDiffSum(next_table[0]) <= max_depth-count){
				recursive(next_table[0],max_depth,count+1,tmp_loc);
			}
		}

		if(pre_loc != 32){
			swap(next_table[1][3][3],next_table[1][3][2]);
			if(count < max_depth && calcDiffSum(next_table[1]) <= max_depth-count){
				recursive(next_table[1],max_depth,count+1,tmp_loc);
			}
		}
		break;
	}
}


