using namespace std;
#define N 4
#define PN 16

int MDT[PN][PN];
int dx[4] = {0,-1,0,1};
int dy[4] = {1,0,-1,0};
int limit;

struct Puzzle{ int f[PN], space, MD;};
Puzzle state;

int sumMD(Puzzle p){
    int sum = 0;
    for(int i = 0; i < PN; i++){
        if(p.f[i] == PN) continue;
        sum += MDT[i][p.f[i]-1];
    }
    return sum;
}

bool dfs(int depth, int prev){
    if(state.MD == 0) return true;
    if(depth+state.MD > limit) return false;

    int sx = state.space/N;
    int sy = state.space%N;
    Puzzle tmp = state;

    for(int r = 0; r < 4; r++){
        int tx = sx + dx[r];
        int ty = sy + dy[r];
        if(tx < 0 || ty < 0 || tx >= N || ty >= N) continue;
        if((r+2)%4 == prev) continue;
        tmp = state;
        state.MD -= MDT[tx*N+ty][state.f[tx*N+ty]-1];
        state.MD += MDT[sx*N+sy][state.f[tx*N+ty]-1];
        swap(state.f[tx*N+ty],state.f[sx*N+sy]);
        state.space = tx*N+ty;
        if(dfs(depth+1,r)) return true;
        //if(dfs(depth+1,r)){path[depth] = r; return true;}
        state = tmp;
    }

    return false;
}

