TBoard InputBoard(std::istream& in)
{
    TBoard Board;
    for(int i = 15; i >= 0; --i){
        int n;
        std::cin >> n;
        if(n <= 9){
            Board.push_back('0' + n);
        }else{
            Board.push_back('A' + n - 10);
        }
    }
    return Board;
