std::vector<TBoard> GetMoved(const TBoard& Board)
{
    assert(Board.length() == 16);
    int i = Board.find('0');
    assert(i >= 0);
    assert(i <= 16);

    std::vector<TBoard> Result;
    if(i > 3){
        std::string copy = Board;
        std::swap(copy[i], copy[i-4]);
        Result.push_back(copy);
    }
    if(i < 0xC){
        std::string copy = Board;
        std::swap(copy[i], copy[i+4]);
        Result.push_back(copy);
    }
    if((i == 0 || i == 4 || i == 8 || i == 0xC) == false){
        std::string copy = Board;
        std::swap(copy[i], copy[i-1]);
        Result.push_back(copy);
    }
    if((i == 3 || i == 7 || i == 0xB || i == 0xF) == false){
        std::string copy = Board;
        std::swap(copy[i], copy[i+1]);
        Result.push_back(copy);
    }

    return Result;
}
