multimap< int, string > Q;   // Key: dist + evaluation , Value: cell hash

// Key: cell hash, Value: cell[SIZE]
string hashkey(vector<int> cell){
  string hash;
  for(const auto& e: cell){
    hash += to_string(e) + ",";
  }
  Node[hash].cell = cell;
  return hash;
}

int estimateH(vector<int> cell){
  int hr = 0; // heuristic
  for(int i = 0 ; i < SIZE ; i++){
    if(cell[i] == 0){
      cell[i] = SIZE;
    }
    int rowhr = abs( (cell[i]-1)%WIDTH - i%WIDTH );
    int colhr = abs( (cell[i]-1)/WIDTH - i/WIDTH );
    hr += rowhr + colhr;
  }
  hr = (int)(hr*0.9);
	return hr;
}

vector<int> updateGQ(vector<int> curCell,int space, int dir, string curHash){
  vector<int> nextCell(curCell);
  int moveto = space + dir; // move to = space(0) + direction
  nextCell[space] = nextCell[moveto];
  nextCell[moveto] = 0;
  const string nextHash = hashkey(nextCell); 
  if( !Node[nextHash].visited ){
    Node[nextHash].visited = true;
  	Node[nextHash].dist = Node[curHash].dist + 1;
    int dist_ev = Node[nextHash].dist + estimateH(nextCell);
		Q.insert(make_pair(dist_ev, nextHash));
  }
  return nextCell;
}

void move(vector<int> curCell, string curHash){
  for(int i = 0 ; i < SIZE ; i++ ){
    vector<int> resultCell;
    if(curCell[i] == 0){
      if(Move[i][LEFT]){
        resultCell = updateGQ(curCell, i, -1, curHash); 
      }
      if(Move[i][RIGHT]){
        resultCell = updateGQ(curCell, i, 1, curHash); 
      }
      if(Move[i][UP]){
        resultCell = updateGQ(curCell, i, -4, curHash); 
      }
      if(Move[i][DOWN]){
        resultCell = updateGQ(curCell, i, 4, curHash); 
      }
    }
  }
  return;
}

