bool dfs(int depth, int prev){
  if(state.x == 0) return true;
  if((depth + state.x) > lim) return false;

  int sx = state.space / N;
  int sy = state.space % N;

  puzzle dummy;

  for(int i = 0; i < N; i++){
    int tx = sx + dx[i];
    int ty = sy + dy[i];

    if(tx < 0 || ty < 0 || tx >= N || ty >=N) continue;
    if(max(prev, i) - min(prev, i) == 2) continue;

    dummy = state;

    state.x -= puz[tx*N + ty][state.f[tx*N + ty] - 1];
    state.x += puz[sx*N + sy][state.f[tx*N + ty] - 1];

    swap(state.f[tx*N + ty], state.f[sx*N + sy]);

    state.space = tx * N + ty;

    if(dfs(depth + 1, i)){
      path[depth] = i;

      return true;

    }

    state = dummy;

  }

  return false;

}

