bool ida_star(const state& crtstate,char x){
  if(h2(crtstate)>x)return false;

  if(crtstate.mh_dist==0)return true;

  rep(dir,4){
    if(dir==crtstate.pre)continue;
    int bi=crtstate.bi;
    int bj=crtstate.bj;
    int ni=bi+di[dir];
    int nj=bj+dj[dir];
    if(ni<0||ni>=N||nj<0||nj>=N)continue;
    state nxtstate=crtstate;

    int num=crtstate.board[ni*N+nj];
    int ai=ans_ps[num].fi;
    int aj=ans_ps[num].se;
    nxtstate.mh_dist-=abs(ai-ni)+abs(aj-nj);
    nxtstate.miss_cnt+=(abs(ai-ni)+abs(aj-nj)==0?1:0);
    nxtstate.mh_dist+=abs(ai-bi)+abs(aj-bj);
    nxtstate.miss_cnt-=(abs(ai-ni)+abs(aj-nj)==0?1:0);

    swap(nxtstate.board[bi*N+bj],nxtstate.board[ni*N+nj]);
    nxtstate.dist++;
    nxtstate.bi=ni; nxtstate.bj=nj;
    nxtstate.pre=(dir+2)%4;
    if(ida_star(nxtstate,x))return true;
  }
  return false;
}

