struct Puzzle {
	char x[4][4];
};
queue<pair<Puzzle, int>>Q; Puzzle Z;
pair<char, char> manh(Puzzle y) {
	char sum = 0; pair<char, char> p[16];
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			p[y.x[i][j]] = make_pair(i, j);
		}
	}
	int ZERO;
	for (int i = 0; i < 16; i++) {
		int X = (i - 1) / 4, Y = (i - 1) % 4;
		if (i == 0) { X = 3; Y = 3; }
		sum += abs(X - p[i].first) + abs(Y - p[i].second);
		if (i == 0) {
			ZERO = abs(X - p[i].first) + abs(Y - p[i].second);
		}
	}
	return make_pair(sum, sum - ZERO);
}
int main() {
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			int p1; cin >> p1;
			Z.x[i][j] = p1;
		}
	}
	Q.push(make_pair(Z, 0));
	while (!Q.empty()) {
		Puzzle r = Q.front().first;
		Puzzle s; int V = Q.front().second;
		pair<char, char>z; Q.pop();
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				if (r.x[i][j] == 0) z = make_pair(i, j);
			}
