int n;
struct Hairetu{
	char array[4][4];
	bool operator< (const Hairetu &a) const{
		for(int i=0; i<n; i++){
			for(int j=0; j<n; j++){
				if(array[i][j] == a.array[i][j]) continue;
				return array[i][j] < a.array[i][j];
			}
		}
		return false;
	}
};
Hairetu a;
std::map<Hairetu,bool> mp;

void init(){
	int N = n*n;
	std::vector<bool> use(N,false);
	int now = 0;
	while(now < N){
		int x = rand() % N;
		if(!use[x]){
			a.array[now/n][now%n] = x;
			use[x] = true;
			now++;
		}
	}
}

bool goal(){
	bool res = true;
	for(int i=0; i<n; i++){
		for(int j=0; j<n; j++){
			if(a.array[i][j] != i*n+j) res = false;
		}
	}
	return res;
}

void print(){
	for(int i=0; i<n; i++){
		for(int j=0; j<n; j++) std::cout << a.array[i][j] << " ";
		std::cout << "\n";
	}
}

int h(int mode){
	if(mode == 0) return 0;
	int res = 0;
	if(mode == 1){
		for(int i=0; i<n; i++){
			for(int j=0; j<n; j++){
				if(a.array[i][j]==n*n-1) continue;
				if(a.array[i][j] != i*n+j) res++;
			}
		}
	}else if(mode == 2){
		for(int i=0; i<n; i++){
			for(int j=0; j<n; j++){
				if(a.array[i][j]==n*n-1) continue;
				int y = a.array[i][j]/n;
				int x = a.array[i][j]%n;
				res += abs(y-i) + abs(x-j);
			}
		}
	}else{
		return 1<<30;
	}
	return res;
}

int f(int mode, int g){
	return h(mode) + g;
}


bool in(int y, int x){
	return 0 <= y && y < n && 0 <= x && x < n;
}

int dy[4] = {1,0,-1,0};
int dx[4] = {0,1,0,-1};

struct dat{
	int f,g;
	Hairetu vec;
	bool operator< (const dat &d) const {
		return f > d.f;
	}
};

int search(int mode){
	std::priority_queue<dat> pq;
	pq.push({f(mode,0),0,a});
	mp[a] = f(mode,0);
	while(!pq.empty()){
		auto p = pq.top(); pq.pop();
		a = p.vec;
		if(goal()) return p.g;
		int y,x;
		for(int i=0; i<n; i++){
			for(int j=0; j<n; j++){
				if(a.array[i][j] == n*n-1){
					y = i; x = j; break;
				}
			}
		}
		for(int i=0; i<4; i++){
			int ny = y + dy[i];
			int nx = x + dx[i];
			if(!in(ny,nx)) continue;
			std::swap(a.array[ny][nx], a.array[y][x]);
			if(mp.find(a) != mp.end()){
				std::swap(a.array[ny][nx], a.array[y][x]);
				continue;
			}
			int cost = f(mode, p.g + 1);
			mp[a] = true;
			pq.push({cost, p.g + 1, a});
			std::swap(a.array[ny][nx], a.array[y][x]);
		}
	}
	return -1;
}


