      MDT[i][j] = abs(i / N - j / N) + abs(i % N - j % N);
    }
  }

  Puzzle in;

  for (int i = 0; i < N2; i++) {
    cin >> in.f[i];
    if (in.f[i] == 0) {
      in.f[i] = N2;
      in.space = i;
    }
  }
  string ans = iterative_deepening(in);
  cout << ans.size() << endl;

  return 0;
}

#include <iostream>
#include <cstdlib>

#define STACK_SIZE 1000000
#define HASH_SIZE 10000000

typedef struct _node {
	unsigned long long data;
	int steps;
	struct _node * next;
} node;

unsigned int hash(unsigned long long data) {
	unsigned long long hash = 0;
	hash += data * 9966091;
	return (unsigned int)(hash % HASH_SIZE);
}

node * hash_unique_create(node ** hash_table, unsigned long long data, int steps) {
	unsigned int hash_value = hash(data);
	//printf("%016llx, %x, %d\n", data, hash_value, steps);
	node * p = hash_table[hash_value];
	if (p == NULL) {
		node *q = (node*)malloc(sizeof(node));
		q->data = data;
		q->steps = steps;
		q->next = NULL;
		hash_table[hash_value] = q;
		return q;
	}
	if (p->data == data) {
		if (p->steps > steps) {
			p->steps = steps;
			return p;
		}
		return NULL;
	}
	while (p->next != NULL) {
		p = p->next;
		if (p->data == data) {
			if (p->steps > steps) {
				p->steps = steps;
				return p;
			}
			return NULL;
		}
	}

	node *q = (node*)malloc(sizeof(node));
	q->data = data;
	q->steps = steps;
	q->next = NULL;
	p->next = q;
	return q;
}

/*
	At the end, return 1; else, return 0; 
*/
int create(unsigned long long data, int steps,
	node ** hash_table, node ** stackA, node ** stackB,
	int * pointerA, int * pointerB, int max_depth)
{
	node * p = hash_unique_create(hash_table, data, steps);
	if (p == NULL) {
		return 0;
	}

	if (data == 0x123456789abcdef0) {
		return 1;
	}

	if (steps < max_depth) {
		stackA[*pointerA] = p;
		*pointerA += 1;
	}
	else {
		stackB[*pointerB] = p;
		*pointerB += 1;
	}

	if (*pointerA == STACK_SIZE) {
		printf("stackA is full\n");
		throw 1;
	}
	if (*pointerB == STACK_SIZE) {
		printf("stackB is full\n");
		throw 1;
	}

	return 0;
}

int find_zero(unsigned long long data) {
	for (int i = 0; i < 16; i++) {
		unsigned int a;
		a = data >> (60 - 4 * i);
		a = a % 16;

		if (a == 0) {
			return i;
		}
	}
	return 0;
}

// zero does move.

unsigned long long move_right(unsigned long long data, int zero_index) {
	unsigned long long a;
	a = (data >> (60 - 4 * (zero_index + 1))) % 16;
	a = a << (60 - 4 * (zero_index + 1));
	unsigned long long b;
	b = data - a;
	a = a << 4;
	b += a;

	return b;
}

unsigned long long move_left(unsigned long long data, int zero_index) {
	unsigned long long a;
	a = (data >> (60 - 4 * (zero_index - 1))) % 16;
	a = a << (60 - 4 * (zero_index - 1));
	unsigned long long b;
	b = data - a;
	a = a >> 4;
	b += a;

	return b;
}

unsigned long long move_down(unsigned long long data, int zero_index) {
	unsigned long long a;
	a = (data >> (60 - 4 * (zero_index + 4))) % 16;
	a = a << (60 - 4 * (zero_index + 4));
	unsigned long long b;
	b = data - a;
	a = a << 16;
	b += a;

	return b;
}

unsigned long long move_up(unsigned long long data, int zero_index) {
	unsigned long long a;
	a = (data >> (60 - 4 * (zero_index - 4))) % 16;
	a = a << (60 - 4 * (zero_index - 4));
	unsigned long long b;
	b = data - a;
	a = a >> 16;
	b += a;

	return b;
}

int Mdistance(unsigned long long data) {
	int distance[16];
	for (int j = 1; j < 16; j++) {
		distance[j] = 0;
		for (int i = 0; i < 16; i++) {
			unsigned int a;
			a = data >> (60 - 4 * i);
			a = a % 16;

			if ((int)a == j) {
				distance[j] = 0;
				distance[j] += std::abs(i % 4 - (j - 1) % 4);
				distance[j] += std::abs(i / 4 - (j - 1) / 4);
			}
		}
	}

	int sum = 0;
	for (int j = 1; j < 16; j++) {
		sum += distance[j];
	}
	return sum;
}


int main() {
	unsigned long long data;
	node ** stackA, ** stackB;
	int pointerA, pointerB;
	int max_depth;
	node ** hash_table;
	int finished;
	int result;

	stackA = (node **)malloc(sizeof(node *) * STACK_SIZE);
	stackB = (node **)malloc(sizeof(node *) * STACK_SIZE);
	pointerA = 0;
	pointerB = 0;
	hash_table = (node **)malloc(sizeof(node *) * HASH_SIZE);
	for (int i = 0; i < HASH_SIZE; i++) {
		hash_table[i] = NULL;
	}

	data = 0;
	for (int i = 0; i < 16; i++) {
		unsigned int a;
		std::cin >> a;
		data = (data << 4) + a;
	}
	//printf("%016llx\n", data);

	max_depth = Mdistance(data);
	//printf("max_depth:%d\n", max_depth);

	try
	{
		finished = create(data, 0, hash_table, stackA, stackB, &pointerA, &pointerB, max_depth);
	}
	catch (...)
	{
		return 1;
	}
	if (finished) {
		printf("0");
		return 0;
	}

	while (1) {
		if (pointerA == 0) {
			if (pointerB == 0) {
				printf("empty stack\n");
				return 1;
			}
			node ** stack_tmp;
			int pointer_tmp;
			stack_tmp = stackA;
			pointer_tmp = pointerA;
			stackA = stackB;
			pointerA = pointerB;
			stackB = stack_tmp;
			pointerB = pointer_tmp;

			max_depth += 2;
		}

		node * p = stackA[pointerA - 1];
		pointerA--;

		unsigned long long new_data;
		int zero_index = find_zero(p->data);

		if (zero_index % 4 != 3) {
			new_data = move_right(p->data, zero_index);
			try
			{
				finished += create(new_data, p->steps + 1, hash_table, stackA, stackB, &pointerA, &pointerB, max_depth);
			}
			catch (...)
			{
				return 1;
			}
		}
		if (zero_index % 4 != 0) {
			new_data = move_left(p->data, zero_index);
			try
			{
				finished += create(new_data, p->steps + 1, hash_table, stackA, stackB, &pointerA, &pointerB, max_depth);
			}
			catch (...)
			{
				return 1;
			}
		}
		if (zero_index < 12) {
			new_data = move_down(p->data, zero_index);
			try
			{
				finished += create(new_data, p->steps + 1, hash_table, stackA, stackB, &pointerA, &pointerB, max_depth);
			}
			catch (...)
			{
				return 1;
			}
		}
		if (zero_index > 3) {
			new_data = move_up(p->data, zero_index);
			try
			{
				finished += create(new_data, p->steps + 1, hash_table, stackA, stackB, &pointerA, &pointerB, max_depth);
			}
			catch (...)
			{
				return 1;
			}
		}

		if (finished) {
			result = p->steps + 1;
			break;
		}
	}

	printf("%d", result);

	return 0;
}

#include<bits/stdc++.h>

using namespace std;

#define N 4
#define N2 16
#define LIMIT 100

const int dx[4]={0,-1,0,1};
const int dy[4]={1,0,-1,0};
const char dir[4]={'r','u','l','d'};

int MDT[N2][N2];

struct puzzle{
    int f[N2],space,MD;
};

puzzle state;
int limit;
int path[LIMIT];

int getALLMD(puzzle pz)
{
    int sum=0;
    for(int i=0;i<N2;i++){
        if(pz.f[i]==N2){
            continue;
        }
        sum+=MDT[i][pz.f[i]-1];
    }
    return sum;
}

bool dfs(int depth,int prev)
{
    if(state.MD==0){
        return true;
    }
    if(depth+state.MD>limit){
        return false;
    }
    int sx=state.space/N;
    int sy=state.space%N;
    puzzle tmp;
    for(int r=0;r<4;r++){
        int tx=sx+dx[r];
        int ty=sy+dy[r];
        if(tx<0||ty<0||tx>=N||ty>=N){
            continue;
        }
//        if(max(prev,r)-min(prev,r)==2){
//            continue;
//        }
        tmp=state;
        //计算曼哈顿距离的差值，同时交换拼图块
        state.MD-=MDT[tx*N+ty][state.f[tx*N+ty]-1];
        state.MD+=MDT[sx*N+sy][state.f[tx*N+ty]-1];
        swap(state.f[tx*N+ty],state.f[sx*N+sy]);
        state.space=tx*N+ty;
        if(dfs(depth+1,r)){
            path[depth]=r;
            return true;
        }
        state=tmp;
    }
    return false;
}

string iterative_deepening(puzzle in)
{
    in.MD=getALLMD(in);//初始状态的曼哈顿距离
    for(limit=in.MD;limit<=LIMIT;limit++){
        state=in;
        if(dfs(0,-100)){
            string ans="";
            for(int i=0;i<limit;i++){
                ans+=dir[path[i]];
            }
            return ans;
        }
    }
    return "unsolvable";
}

int main()
{
    for(int i=0;i<N2;i++){
        for(int j=0;j<N2;j++){
            //曼哈顿距离，此法太妙
            MDT[i][j]=abs(i/N-j/N)+abs(i%N-j%N);
        }
    }
    puzzle in;
    for(int i=0;i<N2;i++){
        cin>>in.f[i];
        if(in.f[i]==0){
            in.f[i]=N2;
            in.space=i;
        }
    }
    string ans=iterative_deepening(in);
    for(int i=0;i<limit;i++){
        cout<<path[i]<<" ";
    }
    cout<<ans.size()<<endl;
    return 0;
}

