#include<cstdio>
#include<algorithm>
#include<cstring>
using namespace std;
const int maxn = 4;


struct Puzzle
{
    int f[maxn][maxn];
    int spaceX;
    int spaceY;
    int dis;
};

const int dx[] = {1, -1, 0, 0};
const int dy[] = {0, 0, 1, -1};

bool is_valid(int x, int y){
    return x >= 0 && x < maxn && y >= 0 && y < maxn;
}

int getH(const Puzzle& p)
{
    int cnt = 0;
    for(int i = 0; i < maxn; i++)
    {
        for(int j = 0; j < maxn; j++)
        {
            if(i == 3 && j == 3)
            {
                if(p.f[i][j] != 0) cnt++;
            }
            else if(p.f[i][j] != i*maxn+j+1) cnt++;
        }
    }
    cnt++;
}

bool dfs(Puzzle start, int d, int maxd)
{
    if(start.dis == 0) return true;
    if(start.dis/2 + d > maxd) return false;
    //if(start.dis == 0) return true;

    for(int i = 0; i < 4; i++)
    {
        int newX = start.spaceX + dx[i];
        int newY = start.spaceY + dy[i];
        if(!is_valid(newX, newY)) continue;
        Puzzle now = start;
        now.spaceX = newX;
        now.spaceY = newY;
        swap(now.f[start.spaceX][start.spaceY], now.f[newX][newY]);
        now.dis = getH(now);
        if(dfs(now, d+1, maxd)) return true;
    }
    return false;
}

int main()
{
    Puzzle start;
    for(int i = 0; i < maxn; i++)
        for(int j = 0; j < maxn ; j++)
        {
            scanf("%d", &start.f[i][j]);
            if(start.f[i][j] == 0) {start.spaceX = i; start.spaceY = j;}
        }
    start.dis = getH(start);
    for(int maxd = 0; maxd <= 45; maxd++)
        if(dfs(start, 0, maxd)) {printf("%d\n", maxd); break;}
    return 0;
}

