typedef unsigned long long ull;
using namespace std;
struct state { ull x; int zero, dist, remain; };
bool operator<(const state& s1, const state& s2) { return s1.dist * 20 + s1.remain * 23 > s2.dist * 20 + s2.remain * 23; }
int a, dist[16][16], goals[16], goals2[16]; ull s, goal = 1147797409030816545;
int solve() {
	if (s == goal) return 0;
	map<ull, bool> dp; dp[s] = true;
	int zz = -1;
	for (int i = 0; i < 16; i++) {
		if (!((s >> (i * 4)) & 15)) zz = i;
	}
	int rr = 0;
	for (int i = 0; i < 16; i++) {
		int ww = ((s >> (i * 4)) & 15);
		if (!ww) continue;
		for (int j = 0; j < 16; j++) {
			if (ww == goals[j]) {
				rr += dist[i][j];
			}
		}
	}
	priority_queue<state> que;
	que.push(state{ s, zz, 0, rr });
	while (!que.empty()) {
		state a = que.top(); que.pop();
		ull v = a.x; int z = a.zero;
		int dir[4] = { 1, 0, -1, 0 };
		for (int i = 0; i < 4; i++) {
			int dx = dir[i], dy = dir[i ^ 1];
			int e = z + dy * 4 + dx;
			int g = ((v >> (e << 2)) & 15);
			if (0 <= e && e < 16 && (e & 3) - (z & 3) == dx) {
				ull w = v;
				w -= ((1ULL * g) << (e << 2));
				w += ((1ULL * g) << (z << 2));
				int xx = a.remain;
				xx -= dist[e][goals2[g]];
				xx += dist[z][goals2[g]];
				if (w == goal) return a.dist + 1;
				if(!dp[w]) que.push(state{ w, e, a.dist + 1, xx });
			}
		}
	}
	return -1;
}
