typedef std::vector<std::vector<int> > TPuzzle;

void MakeGoal(TPuzzle& Goal)
{
	Goal.resize(4);
	for(int i = 0; i < 4; ++i){
		Goal[i].resize(4);
		for(int j = 0; j < 4; ++j){
			Goal[i][j] = (1 + 4 * i + j) % 16;
		}
	}
}

void ZeroPosition(int& Row, int& Col, const TPuzzle& Puzzle)
{
	for(int i = 0; i < 4; ++i){
		for(int j = 0; j < 4; ++j){
			if(Puzzle[i][j] == 0){
				Row = i;
				Col = j;
			}
		}
	}
}

enum TMovePattern
{
	mpUp,
	mpDown,
	mpLeft,
	mpRight
};

bool Movable(const TPuzzle& Puzzle, const TMovePattern& Pattern)
{
	int Row, Col;
	ZeroPosition(Row, Col, Puzzle);
	switch(Pattern){
	case mpUp    : return Row != 0;
	case mpDown  : return Row != 3;
	case mpLeft  : return Col != 0;
	case mpRight : return Col != 3;
	}
	assert(false);
	return false;
}

TPuzzle Move(TPuzzle Puzzle, const TMovePattern& Pattern)
{
	int Row, Col;
	ZeroPosition(Row, Col, Puzzle);
	switch(Pattern){
	case mpUp    : std::swap(Puzzle[Row][Col], Puzzle[Row - 1][Col]);break;
	case mpDown  : std::swap(Puzzle[Row][Col], Puzzle[Row + 1][Col]);break;
	case mpLeft  : std::swap(Puzzle[Row][Col], Puzzle[Row][Col - 1]);break;
	case mpRight : std::swap(Puzzle[Row][Col], Puzzle[Row][Col + 1]);break;
	}
	return Puzzle;
}

void RenewTargets(
	const TPuzzle& Puzzle,
	const TMovePattern& Pattern,
	std::vector<TPuzzle>& Targets,
	std::set<TPuzzle>& History)
{
	if(!Movable(Puzzle, Pattern)) return;
	TPuzzle Moved = Move(Puzzle, Pattern);
	if(History.find(Moved) != History.end()) return;
	Targets.push_back(Moved);
	History.insert(Moved);
}
