bool CountMove(std::vector<TPuzzle>& NextTargets,
	          const TPuzzle& Goal,
	          std::set<TPuzzle>& History)
{
	if(std::find(NextTargets.begin(), NextTargets.end(), Goal) != NextTargets.end()) return true;
	std::vector<TPuzzle> NewTargets;
	for(std::vector<TPuzzle>::const_iterator It = NextTargets.begin(); It != NextTargets.end(); ++It){
		RenewTargets(*It, mpUp,    NewTargets, History);
		RenewTargets(*It, mpDown,  NewTargets, History);
		RenewTargets(*It, mpLeft,  NewTargets, History);
		RenewTargets(*It, mpRight, NewTargets, History);
	}
	NextTargets = NewTargets;
	return false;
}

int CountMinimumMove(const TPuzzle& Puzzle, const TPuzzle& Goal)
{
	std::vector<TPuzzle> Targets(1, Puzzle);
	std::set<TPuzzle> History;
	int Count = 0;
	while(!CountMove(Targets, Goal, History)) ++Count;
	return Count;
}

