vector<int> trans(vector< vector<int> > a){
  vector<int> t(16);
  for(int i=0; i<4; i++) for(int j=0; j<4; j++) t[i*4+j] = a[i][j];
  return t;
}
bool check(vector<int> a){
  for(int i=0; i<16; i++){
    if( a[i] != (i+1)%16 ) return false;
  }
  return true;
}

void bfs(vector<int> sss){
  queue< pair<int, vector<int> > > q;
  q.push(make_pair(0, sss));
  map< vector<int>, bool> mpb;
  while( !q.empty() ){
    pair<int, vector<int> > p = q.front();
    q.pop();

    vector<int> s = p.second;
    mpb[s] = true;
    // cerr << p.first << " " << p.second << endl;
    if( check(s) ){
      cout << p.first << endl;
      return;
    }

    for(int i=0; i<16; i++){
      if( s[i] == 0 ){
        int y = i / 4;
        int x = i % 4;
        for(int d=0; d<4; d++){
          int nx = x + dx[d]; int ny = y + dy[d];
          if( nx < 0 || ny < 0 || nx >= 4 || ny >= 4 ) continue;
          vector<int> t = s;
          swap(t[i], t[ny*4 + nx]);
          if( !mpb[t] ) q.push( make_pair(p.first + 1, t) );
        }
      }
    }

  }
}

