		for (int i = 0; i < size; i++)
			for (int j = 0; j < size; j++) {
				int k = a[i][j];
				if (!k) continue;
				l += abs(i - mt[k].r) + abs(j - mt[k].c);
			}
		return l;
	}

	static long key(const arr &a) {
		long k = 0;
		for (auto &r: a)
			for (int c: r)
				k = (k * 16) + c;
		return k;
	}

	int solver() {
		static const pos to[] = {-1, 0, 0, -1, 1, 0, 0, 1};
		unordered_map<long, pos> m;
		priority_queue<board> q;
		aap mt;
		board e = *this;

		for (int i = 0; i < size * size; i++)
			if (!i)
				mt[0][i] = {size - 1, size - 1};
			else
				mt[0][i] = {(i - 1) / size, (i - 1) % size};
		for (int i = 0, k = 1; i < size; i++)
			for (int j = 0; j < size; j++) {
				mt[1][b[i][j]] = {i, j};
				e.b[i][j] = k == size * size ? 0 : k++;
			}

		e.d = 1;
		e.p = {size - 1, size - 1};
		g = d = e.g = 0;
		f = h = e.f = e.h = hn(b, mt[d]);

		int beam = 100000, beam_count = 11;

		q.push(*this);
		q.push(e);
		while (!q.empty()) {
			board a = q.top();
			q.pop();
			if (!a.h)
				return a.g;
			long k = key(a.b);
			auto res = m.find(k);
			if (res != m.end()) {
				if ((*res).second.r == a.d)
					continue;
				else if (!beam_count--)
						return beam;
				else {
					beam = min(beam, a.g + (*res).second.c);
					continue;
				}
			}
			m[k] = {a.d, a.g};
			for (pos o: to) {
				o.r += a.p.r, o.c += a.p.c;
				if (0 <= o.r && o.r < size && 0 <= o.c && o.c < size) {
					board c = a;
					pos f = mt[c.d][c.b[o.r][o.c]];
					c.h += - abs(o.r - f.r) - abs(o.c - f.c) + abs(a.p.r - f.r) + abs(a.p.c - f.c);
					swap(c.b[a.p.r][a.p.c], c.b[o.r][o.c]);
					c.g += 1;
					c.f = c.g + c.h;
					c.p = o;
					q.push(c);
				}
			}
		}
		return -1;
	}
};

bool operator < (const board &a, const board &b) {
	return a.f > b.f;
}

int main() {
	board b;
	b.read();
	out(b.solver(), '\n');
}

