#include <bits/stdc++.h>
using namespace std;

#define int short

const int N = 4;
int dx[4] = {0, 1, 0, -1}, dy[4] = {-1, 0, 1, 0};

struct Comp {
	int puz[16];
	bool operator < (const Comp &c) const {
		for ( int i = 0; i < N*N; i++ ) {
			if ( puz[i] == c.puz[i] ) continue;
			return puz[i] < c.puz[i];
		}
		return false;
	}	
};

struct State {
	int puz[16];
	int zero;
	int cost;
	int esti;
	bool operator < (const State &s) const {
		return esti < s.esti;
	}
	bool operator > (const State &s) const {
		return esti  > s.esti;
	}
};

signed main() {
	State s;
	s.cost = s.esti = 0;	
	for ( int i = 0; i < N*N; i++ ) {
		cin >> s.puz[i];
		if ( s.puz[i] == 0 ) {
			s.zero = i;
			s.puz[i] = N*N-1;			
		} else {
			s.puz[i]--;
		}

		s.esti += abs(i/N-s.puz[i]/N) + abs(i%N-s.puz[i]%N);		
	}
	//cout << s.esti << endl;
	map<Comp, bool> used;	
	priority_queue<State, vector<State>, greater<State> > Q;	
	Q.push(s);
	int cnt = 0;
	while ( !Q.empty() ) {	 			
		State p = Q.top(); Q.pop();	
		if ( p.cost >= 45 ) continue;
		if ( p.esti >= 52 ) continue;

		//for ( int i = 0; i < N*N; i++ ) cout << s.puz[i] << " ";
		//cout << endl;
		// cout << p.cost << " " << p.esti << endl;			

		if ( p.esti-p.cost == 0 ) {
			cout << p.cost << endl;
			return 0;
		}		

		Comp c;
		for ( int i = 0; i < N*N; i++ ) c.puz[i] = p.puz[i];		
		if ( used.count(c) &&  used[c] <= p.cost ) continue;		
		used[c] = p.cost;		

		for ( int i = 0; i < 4; i++ ) {
			int y = p.zero/N, x = p.zero%N;
			int ny = y+dy[i], nx = x+dx[i];
			if ( ny < 0 || nx < 0 || ny >= N || nx >= N ) continue;
			s = p;			
			int ch_id = ny*4+nx;
			int ch_dat = s.puz[ch_id];
			int dat_y = ch_dat/N;
			int dat_x = ch_dat%N;			
			swap(s.puz[s.zero], s.puz[ch_id]);
			Comp cc = c;
			swap(cc.puz[s.zero], cc.puz[ch_id]);			
			if ( used.count(cc) ) continue;			
			s.esti -= abs(y-(N-1)) + abs(x-(N-1));			
			s.esti -= abs(ny-dat_y) + abs(nx-dat_x);			
			s.esti += abs(y-dat_y) + abs(x-dat_x);			
			s.esti += abs(ny-(N-1)) + abs(nx-(N-1));			
			s.esti++;
			s.cost++;
			s.zero = ch_id;
			Q.push(s);
		}			
	}

	return 0;
}

#include <iostream>
#include <cstdio>
#include <vector>

#define RC2P(r,c) (((r)<<2)+(c))	//r*4+c
#define P2R(p) ((p)>>2)				//p/4
#define P2C(p) ((p)&3)				//p%4
#define HASHMAX 1000003

typedef unsigned long long int Pkey;

struct Pandt{
	Pkey p;
	int t;

	Pandt(){ return; }
	Pandt(Pkey p, int t) :p(p), t(t){ return; }

	bool operator==(const Pandt& rhs) const{
		return (p == rhs.p && t == rhs.t);
	}
};

int dist(Pandt x);
int abs(int x);
void insert(std::vector<Pandt> &A, Pandt v);
Pandt extract(std::vector<Pandt> &A);
int SolvePuzzle(std::vector<int> P);


std::vector< Pandt > Puzzles(HASHMAX);

int h1(Pkey key){
	return (int)(key % HASHMAX); 
}
int h2(Pkey key){
	return (int)((key % (HASHMAX - 1)) + 1);
}
int HashFind(Pkey key);
int HashInsert(Pkey key, int val);


void InitHash(){
	Pandt Nullpandt(0, -1);
	for (int i = 0; i < HASHMAX; i++){
		Puzzles[i] = Nullpandt;
	}
}

int HashFind(Pkey key){

	int curhash = h1(key);
	int sechash = -1;
	for (int i = 0; i < HASHMAX; i++){
		if (Puzzles[curhash].t == -1){
			return -1;
		}
		else if (Puzzles[curhash].p == key){
			return curhash;
		}
		else{
			if (sechash == -1) sechash = h2(key);
			curhash = (curhash + sechash) % HASHMAX;
		}
	}
	return -1;
}

int HashInsert(Pkey key, int val){

	int curhash = h1(key);
	int sechash = -1;
	for (int i = 0; i < HASHMAX; i++){
		if (Puzzles[curhash].t == -1){
			Puzzles[curhash].t = val;
			Puzzles[curhash].p = key;
			return curhash;
		}
		else{
			if (sechash == -1) sechash = h2(key);
			curhash = (curhash + sechash) % HASHMAX;
		}
	}
	return -1;
}

int dist(Pandt x){
	int tmp, result = 0;
	for (int i = 0; i < 16; i++){
		tmp = (x.p & ((Pkey)15 << (i << 2))) >> (i << 2);
		if (tmp == 0) continue;
		result += abs(P2C(tmp - 1) - P2C(i)) + abs(P2R(tmp - 1) - P2R(i));
	}
	return -result - x.t;
}

int abs(int x){
	return x < 0 ? -x : x;
}

void insert(std::vector< Pandt > &A, Pandt v){
	int n = A.size();
	A.push_back(v);
	Pandt tmp;
	while (n != 0){
		int i = (n - 1) >> 1;
		if (dist(A[n]) > dist(A[i])){
			tmp = A[n];
			A[n] = A[i];
			A[i] = tmp;
		}
		n = i;
	}
	return;
}

Pandt extract(std::vector< Pandt > &A){
	int n = A.size() - 1;
	Pandt tmp, res = A[0];
	A[0] = A[n];
	A.pop_back();

	int disttmp1, disttmp2;
	for (int i = 0, j; (i << 1) + 1 < n;){
		j = (i << 1) + 1;
		disttmp1 = dist(A[j]);
		if (j != n - 1){
			disttmp2 = dist(A[j + 1]);
			if (disttmp1 < disttmp2){
				j++;
				disttmp1 = disttmp2;
			}
		}
		if (dist(A[i]) < disttmp1){
			tmp = A[j];
			A[j] = A[i];
			A[i] = tmp;
		}
		i = j;
	}
	return res;
}

Pkey PtoI(std::vector<int> p){
	unsigned long long int keyI = 0;
	for (int i = 0; i < 16; i++){
		keyI += (unsigned long long int)(15 & p[i]) << (i << 2);
	}
	return keyI;
}

void AddToQueue(std::vector<Pandt> &Que, Pkey Qnext, int exttplusone){
	int Qsearch = HashFind(Qnext);
	Pandt Qnextt(Qnext, exttplusone);
	if (Qsearch == -1){
		HashInsert(Qnext, exttplusone);
		insert(Que, Qnextt);
	}
	else if (Puzzles[Qsearch].t > exttplusone){
		Puzzles[Qsearch].t = exttplusone;
		insert(Que, Qnextt);
	}
	return;
}

int SolvePuzzle(std::vector<int> P){
	std::vector< Pandt > Que;
	Pkey init = PtoI(P);
	Pandt initt(init, 0);
	HashInsert(init, 0);
	insert(Que, initt);
	int answer = 44;
	while (true){
		Pandt ext = extract(Que);
		int Cursor;
		if (ext.p == 0xFEDCBA987654321){
			answer = ext.t;
			break;
		}

		if (-dist(ext) >= 45) break;

		for (int i = 0; i < 16; i++){
			if ((ext.p & ((Pkey)15 << (i << 2))) == 0){
				Cursor = i;
				break;
			}
		}
		Pkey Qnext;
		Pkey tmp;
		if (Cursor >= 4){
			tmp = (ext.p & ((Pkey)15 << ((Cursor - 4) << 2)));
			Qnext = ext.p & ~tmp | (tmp << 16);
			AddToQueue(Que, Qnext, ext.t + 1);
		}
		if (Cursor < 12){
			tmp = (ext.p & ((Pkey)15 << ((Cursor + 4) << 2)));
			Qnext = ext.p & ~tmp | (tmp >> 16);
			AddToQueue(Que, Qnext, ext.t + 1);
		}
		if (P2C(Cursor) != 0){
			tmp = (ext.p & ((Pkey)15 << ((Cursor - 1) << 2)));
			Qnext = ext.p & ~tmp | (tmp << 4);
			AddToQueue(Que, Qnext, ext.t + 1);
		}
		if (P2C(Cursor) != 3){
			tmp = (ext.p & ((Pkey)15 << ((Cursor + 1) << 2)));
			Qnext = ext.p & ~tmp | (tmp >> 4);
			AddToQueue(Que, Qnext, ext.t + 1);
		}
	}

	return answer;
}

