int getHeuri(){
  int res=0,a;
  for(int i=0;i<4;i++){
    for(int j=0;j<4;j++){
      if(t[i][j]==0)continue;
      a=t[i][j]-1;
      res+=abs(a/4-i)+abs(a%4-j);
    }
  }
  return res;
}

bool check(int depth,int prev,int py,int px){
  int heuri=getHeuri();
  if(heuri+depth>limit)return false;
  if(heuri==0)return true;
  for(int i=0;i<4;i++){
    if(abs(i-prev)==2)continue;
    int ny=py+dy[i],nx=px+dx[i];
