using namespace std;

typedef long long Board;

const int N = 16;
const Board GOAL = 0x123456789ABCDEF0;

struct State {
    Board board;
    int count;
};

queue<State> q;
set<Board> history;

inline void swap(int numpos, int spacepos, Board& board) {
    long long num = (board >> (numpos*4)) & 0xF;
    board |= num << (spacepos*4);
    board &= ~(0xFLL << (numpos*4));
}

inline int swap_and_check(int numpos, int spacepos, State s) {
    swap(numpos, spacepos, s.board);
    if (s.board == GOAL) {
        return ++s.count;
    }
    if (history.insert(s.board).second) {
        ++s.count;
        q.push(s);
    }
    return -1;
}

void print(Board b) {
    for (int i = N-1; i >= 0; --i) {
        printf("%2llx", (b >> (i*4) & 0xF));
    }
    printf("\n");
}

