const int dy[4] = { -1, 0, 0, 1 };

int min_depth;

void dfs(int a[BOARD_N][BOARD_N], int maxdepth, int depth)
{
	if (maxdepth == depth)
	{
		bool ok = true;

		for (int i = 0; i < BOARD_N * BOARD_N - 1; i++)
		{
			if (a[i / BOARD_N][i % BOARD_N] != i + 1)
			{
				ok = false;
			}
		}

		if (ok == true)
		{
			min_depth = maxdepth;
		}

		return;
	}

	int x, y;

	for (int i = 0; i < BOARD_N; i++)
	{
		for (int j = 0; j < BOARD_N; j++)
		{
			if (a[i][j] == 0)
			{
				x = j;
				y = i;
			}
		}
	}

	int b[BOARD_N][BOARD_N];

	for (int dir = 0; dir < 4; dir++)
	{
		if (0 <= x + dx[dir] && dx[dir] < BOARD_N && 0 <= y + dy[dir] && y + dy[dir] < BOARD_N)
		{
			for (int i = 0; i < BOARD_N; i++)
			{
				for (int j = 0; j < BOARD_N; j++)
				{
					b[i][j] = a[i][j];
				}
			}

			swap(b[y][x], b[y + dy[dir]][x + dx[dir]]);

			dfs(b, maxdepth, depth + 1);
		}
	}
}

