#endif
    compute_md_table();

    puzzle start_puzzle;

    int value;
    for (int y = 0; y < N; ++y) {
        for (int x = 0; x < N; ++x) {
            auto index = to_index(x, y);
            stream >> value;
            start_puzzle.p[index] = value;
            if (value == 0) {
                start_puzzle.p[index] = N2;
                start_puzzle.space = index;
            }
        }
    }

    auto ans = iterative_deepning(start_puzzle);
    cout << ans.size() << endl;
    return 0;
}

