#define LIMIT 45

struct Puzzle{
    int cont[16];
    int space;
    string path;
    bool operator < ( const Puzzle &p ) const{
        for ( int i = 0; i < 16; i++ ){
            if ( cont[i] == p.cont[i] ) continue;
            return cont[i] > p.cont[i];
        }
        return false;
    }
};

int limit;
static const int dx[4] = {-1, 0, 1, 0};
static const int dy[4] = {0, -1, 0, 1};
static const char direction[4] = {'d', 'r', 'u', 'l'};

bool isTarget(Puzzle puzzle){
    for ( int i = 0; i < 15; i++ ){
        if ( puzzle.cont[i] != 1 + i ) return false;
    }
    return true;
}

void printCont(Puzzle p) {
	for (int i = 0; i < 16; i++)
		cout << " " << p.cont[i];
	cout << endl;
	sleep(1);
}

void bfs(Puzzle s){
    queue<Puzzle> Q;
    map<Puzzle, bool> V;
    Puzzle u, v;
    s.path = "";
    Q.push(s);
    V[s] = true;

    while( !Q.empty() ){
        u = Q.front(); Q.pop();
//		printCont(u);
        if ( isTarget(u) ){
            cout << u.path.size() << endl;
            return;
        } else if ( u.path.size() > LIMIT ) break;

        int sx, sy, tx, ty;
        sx = u.space/4;
        sy = u.space%4;

        for ( int r = 0; r < 4; r++ ){
            tx = sx + dx[r];
            ty = sy + dy[r];
            if ( tx < 0 || ty < 0 || tx >= 4 || ty >= 4 ) continue;
            v = u;
            v.cont[u.space] = u.cont[tx*4+ty];
            v.cont[tx*4+ty] = 0;
            v.space = tx*4+ty;
            if ( !V[v] ){
                V[v] = true;
                v.path += direction[r];
                Q.push(v);
            }
        }
    }
    cout << "unsolvable" << endl;
}

