#define int short

const int N = 4;
int dx[4] = {0, 1, 0, -1}, dy[4] = {-1, 0, 1, 0};

struct Comp {
	int puz[16];
	bool operator < (const Comp &c) const {
		for ( int i = 0; i < N*N; i++ ) {
			if ( puz[i] == c.puz[i] ) continue;
			return puz[i] < c.puz[i];
		}
		return false;
	}
};

struct State {
	int puz[16];
	int zero;
	int cost;
	int esti;
	bool operator < (const State &s) const {
		return esti < s.esti;
	}
	bool operator > (const State &s) const {
		return esti  > s.esti;
	}
};

signed main() {
	State s;
	s.cost = s.esti = 0;	
	for ( int i = 0; i < N*N; i++ ) {
		cin >> s.puz[i];
		if ( s.puz[i] == 0 ) {
			s.zero = i;
			s.puz[i] = N*N-1;			
		} else {
			s.puz[i]--;
		}

		s.esti += abs(i/N-s.puz[i]/N) + abs(i%N-s.puz[i]%N);		
	}
	//cout << s.esti << endl;
	map<Comp, int> used;
	priority_queue<State, vector<State>, greater<State> > Q;	
	Q.push(s);
	int cnt = 0;
	while ( !Q.empty() ) {	 			
		State p = Q.top(); Q.pop();
		if ( p.cost >= 45 ) continue;
		if ( s.esti >= 53 ) continue;

		//for ( int i = 0; i < N*N; i++ ) cout << s.puz[i] << " ";
		//cout << endl;
		// cout << p.cost << " " << p.esti << endl;			

		if ( p.esti-p.cost == 0 ) {
			cout << p.cost << endl;
			return 0;
		}		

		Comp c;
		for ( int i = 0; i < N*N; i++ ) c.puz[i] = p.puz[i];		
		if ( used.count(c) &&  used[c] <= p.cost ) continue;		
		used[c] = p.cost;		

		for ( int i = 0; i < 4; i++ ) {
			int y = p.zero/N, x = p.zero%N;
			int ny = y+dy[i], nx = x+dx[i];
			if ( ny < 0 || nx < 0 || ny >= N || nx >= N ) continue;
			s = p;			
			int ch_id = ny*4+nx;
			int ch_dat = s.puz[ch_id];
			swap(s.puz[s.zero], s.puz[ch_id]);
			Comp cc = c;
			swap(cc.puz[s.zero], cc.puz[ch_id]);			
			if ( used.count(cc) ) continue;			
			s.esti -= abs(y-(N-1)) + abs(x-(N-1));			
			s.esti -= abs(ny-ch_dat/N) + abs(nx-ch_dat%N);			
			s.esti += abs(y-ch_dat/N) + abs(x-ch_dat%4);			
			s.esti += abs(ny-(N-1)) + abs(nx-(N-1));				
			s.esti++;
			s.cost++;
			s.zero = ch_id;
			Q.push(s);
		}			
	}

	return 0;
}

#define _CRT_SECURE_NO_WARNINGS
#define _USE_MATH_DEFINES
#include <iostream>
