#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define rep(i, n) for (ll i = 0; i < (ll)n; ++i)
static const int dx[4] = { 0, 1, 0, -1 };
static const int dy[4] = { 1, 0, -1, 0 };
static const char dir[4] = { 'u', 'r', 'd', 'l' };
static const ll INF = 1 << 21;
static const ll MOD = 1e9 + 7;
static const int N = 4;
static const int N2 = 16;
static const int LIMIT = 100;

// マンハッタン距離を記録
int MDT[N2][N2];

struct Puzzle {
    int f[N2]; // パズルの状態
    int space; // スペースのある場所
    int MD; // マンハッタン距離
};

Puzzle state;
int limit; // 深さの制限
int path[LIMIT]; // 経路

// マンハッタン距離を取得
int getAllMD(Puzzle pz)
{
    int sum = 0;
    // i->pz.f[i]-1へのマンハッタン距離を計測
    rep(i, N2)
    {
        if (pz.f[i] == N2) {
            continue;
        }
        sum += MDT[i][pz.f[i] - 1];
    }
    return sum;
}

// 全てのパズルの位置が正しい時にtrue
bool isSolved()
{
    rep(i, N)
    {
        if (state.f[i] != i + 1) {
            return false;
        }
    }
    return true;
}

bool dfs(int depth, int prev)
{
    if (state.MD == 0) {
        return true;
    }
    // 現在の深さにヒューリスティックを足して制限を超えたら枝を刈る
    if (depth + state.MD > limit) {
        return false;
    }

    // 現在のスペースは(sx, sy)
    int sx = state.space / N;
    int sy = state.space % N;
    Puzzle tmp;

    rep(r, 4)
    {
        // 次の位置は(tx, ty)
        int tx = sx + dx[r];
        int ty = sy + dy[r];
        if (tx < 0 || ty < 0 || tx >= N || ty >= N) {
            continue;
        }
        //
        if (abs(prev - r) == 2) { // 前回の動きの真逆(uとd, rとl)のときはcontinue
            continue;
        }
        tmp = state;
        // マンハッタン距離の差分を計算しつつ,ピースをスワップ
        state.space = tx * N + ty;
        state.MD -= MDT[state.space][state.f[state.space] - 1];
        state.MD += MDT[sx * N + sy][state.f[state.space] - 1];
        swap(state.f[state.space], state.f[sx * N + sy]);
        if (dfs(depth + 1, r)) {
            path[depth] = r; // 方向を記録
            return true;
        }
        state = tmp; // stateを更新
    }
    return false;
}

// 反復深化
string iterative_deepen(Puzzle in)
{
    in.MD = getAllMD(in); // 初期状態のマンハッタン距離
    for (limit = in.MD; limit <= LIMIT; limit++) {
        state = in;
        if (dfs(0, -100)) {
            string ans = "";
            rep(i, limit)
            {
                ans += dir[path[i]];
            }
            return ans;
        }
    }

    return "unsolvable";
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    rep(i, N2)
    {
        rep(j, N2)
        {
            // i->j でのマンハッタン距離
            MDT[i][j] = abs(i / N - j / N) + abs(i % N - j % N);
        }
    }
    Puzzle in;

    rep(i, N2)
    {
        cin >> in.f[i];
        if (in.f[i] == 0) {
            in.f[i] = N2;
            in.space = i;
        }
    }

    string ans = iterative_deepen(in);
    cout << ans.size() << endl;

    return 0;
}

#include <iostream>
#include <cstdlib>
#include <cstdio>
#include <algorithm>

#define HEAP_SIZE 10000000
#define HASH_SIZE 10000000
#define MAX_STEPS 45

typedef struct _node {
	unsigned long long data;
	int steps;
	int f;
	struct _node * next;
} node;

unsigned int hash(unsigned long long data) {
	unsigned long long hash = 0;
	hash += data * 9966091;
	return (unsigned int)(hash % HASH_SIZE);
}

node * hash_unique_create(node ** hash_table, unsigned long long data, int steps, int f) {
	unsigned int hash_value = hash(data);
	//std::printf("%016llx, %x, %d\n", data, hash_value, steps);
	node * p = hash_table[hash_value];
	if (p == NULL) {
		node *q = (node*)malloc(sizeof(node));
		q->data = data;
		q->steps = steps;
		q->f = f;
		q->next = NULL;
		hash_table[hash_value] = q;
		return q;
	}
	if (p->data == data) {
		if (p->steps > steps) {
			p->f = f;
			p->steps = steps;
			return p;
		}
		return NULL;
	}
	while (p->next != NULL) {
		p = p->next;
		if (p->data == data) {
			if (p->steps > steps) {
				p->f = f;
				p->steps = steps;
				return p;
			}
			return NULL;
		}
	}

	node *q = (node*)malloc(sizeof(node));
	q->data = data;
	q->steps = steps;
	q->f = f;
	q->next = NULL;
	p->next = q;
	return q;
}

int Mdistance(unsigned long long data) {
	int distance[16];
	for (int j = 1; j < 16; j++) {
		distance[j] = 0;
		for (int i = 0; i < 16; i++) {
			unsigned int a;
			a = data >> (60 - 4 * i);
			a = a % 16;

			if ((int)a == j) {
				distance[j] = 0;
				distance[j] += std::abs(i % 4 - (j - 1) % 4);
				distance[j] += std::abs(i / 4 - (j - 1) / 4);
			}
		}
	}

	int sum = 0;
	for (int j = 1; j < 16; j++) {
		sum += distance[j];
	}
	return sum;
}

void heap_add(node ** heap, int * n, node * a) {
	*n += 1;
	int tmp_n = *n;
	while (tmp_n != 1) {
		if (heap[tmp_n / 2]->f > a->f) {
			heap[tmp_n] = heap[tmp_n / 2];
			tmp_n = tmp_n / 2;
		}
		else {
			break;
		}
	}
	heap[tmp_n] = a;
}

void heap_delete(node ** heap, int * n, int i) {
	if (i == 1) {
		heap[1] = heap[*n];
		*n -= 1;
	}

	if (2 * i > *n) {
		return;
	}
	if (2 * i + 1 > *n) {
		if (heap[i]->f > heap[2 * i]->f) {
			node * tmp = heap[i];
			heap[i] = heap[2 * i];
			heap[2 * i] = tmp;
		}
		return;
	}

	if (heap[i]->f < heap[2 * i]->f && heap[i]->f < heap[2 * i + 1]->f) {
		return;
	}

	if (heap[2 * i]->f < heap[2 * i + 1]->f) {
		node * tmp = heap[i];
		heap[i] = heap[2 * i];
		heap[2 * i] = tmp;
		heap_delete(heap, n, 2 * i);
	}
	else {
		node * tmp = heap[i];
		heap[i] = heap[2 * i + 1];
		heap[2 * i + 1] = tmp;
		heap_delete(heap, n, 2 * i + 1);
	}
}

/*
	At the end, return 1; otherwise, return 0;
*/
int create(unsigned long long data, int steps, int f,
	node ** hash_table, node ** heap, int * n)
{
	node * p = hash_unique_create(hash_table, data, steps, f);
	if (p == NULL) {
		return 0;
	}

	if (data == 0x123456789abcdef0) {
		return 1;
	}

	if (steps == MAX_STEPS) {
		return 0;
	}

	heap_add(heap, n, p);
	if (*n > HEAP_SIZE) {
		printf("heap is full\n");
		throw 1;
	}

	return 0;
}

int find_zero(unsigned long long data) {
	for (int i = 0; i < 16; i++) {
		unsigned int a;
		a = data >> (60 - 4 * i);
		a = a % 16;

		if (a == 0) {
			return i;
		}
	}
	return 0;
}

// zero does move.

unsigned long long move_right(unsigned long long data, int zero_index, int * dif_f) {
	unsigned long long a;
	a = (data >> (60 - 4 * (zero_index + 1))) % 16;
	if (((int)a - 1) % 4 < (zero_index + 1) % 4) {
		*dif_f = 0;
	}
	else {
		*dif_f = 2;
	}
	a = a << (60 - 4 * (zero_index + 1));
	unsigned long long b;
	b = data - a;
	a = a << 4;
	b += a;

	return b;
}

unsigned long long move_left(unsigned long long data, int zero_index, int * dif_f) {
	unsigned long long a;
	a = (data >> (60 - 4 * (zero_index - 1))) % 16;
	if (((int)a - 1) % 4 > (zero_index - 1) % 4) {
		*dif_f = 0;
	}
	else {
		*dif_f = 2;
	}
	a = a << (60 - 4 * (zero_index - 1));
	unsigned long long b;
	b = data - a;
	a = a >> 4;
	b += a;

	return b;
}

unsigned long long move_down(unsigned long long data, int zero_index,int * dif_f) {
	unsigned long long a;
	a = (data >> (60 - 4 * (zero_index + 4))) % 16;
	if (((int)a - 1) / 4 < (zero_index + 4) / 4) {
		*dif_f = 0;
	}
	else {
		*dif_f = 2;
	}
	a = a << (60 - 4 * (zero_index + 4));
	unsigned long long b;
	b = data - a;
	a = a << 16;
	b += a;

	return b;
}

unsigned long long move_up(unsigned long long data, int zero_index, int * dif_f) {
	unsigned long long a;
	a = (data >> (60 - 4 * (zero_index - 4))) % 16;
	if (((int)a - 1) / 4 > (zero_index - 4) / 4) {
		*dif_f = 0;
	}
	else {
		*dif_f = 2;
	}
	a = a << (60 - 4 * (zero_index - 4));
	unsigned long long b;
	b = data - a;
	a = a >> 16;
	b += a;

	return b;
}

