struct Puzzle
{
	int f[N2], space, MD;
	int cost;
	bool operator < (const Puzzle &p) const
	{
		for(int i = 0; i < N2; i++){
			if(f[i] == p.f[i]) continue;
			return f[i] > p.f[i];
		}
		return false;
	}
};

int getallMD(const Puzzle &p)
{
	int h = 0;
	for(int i = 0; i < N2; i++){
	if(i == p.space) continue;
		h += MDT[i][p.f[i] - 1];
	}
	return h;
}

struct State
{
	Puzzle pz;
	int estimated;
	bool operator < (const State &s) const
	{
		return estimated > s.estimated;
	}
};

int astar(Puzzle p)
{
	priority_queue<State> A;
	map<Puzzle, bool> USED;

	State initial;
	initial.pz = p;
	initial.estimated = p.MD;
	A.push(initial);
	USED[p] = true;

	Puzzle u, v;
	int sx, sy, tx, ty, r;

	while(!A.empty())
	{
		u = A.top().pz; A.pop();
		if(u.MD == 0) return u.cost;

		sx = u.space / N;
		sy = u.space % N;
		for(r = 0; r < 4; r++){
			tx = sx + dx[r];
			ty = sy + dy[r];
			if(tx < 0 || tx >= N || ty < 0 || ty >= N) continue;
			v = u;
			v.MD -= MDT[tx * N + ty][u.f[tx * N + ty] - 1];
			v.MD += MDT[sx * N + sy][u.f[tx * N + ty] - 1];
			swap(v.f[sx * N + sy], v.f[tx * N + ty]);
			v.space = tx * N + ty;

			if(!USED[v]){
				v.cost++;
				USED[v] = true;
				State new_s;
				new_s.pz = v;
				new_s.estimated = v.cost + v.MD;
				A.push(new_s);
			}
		}
	};
	return -1;
}

