constexpr int DEPTH_LIMIT = 45;
constexpr int W = 4;
constexpr int H = 4;
constexpr int B = 4;
constexpr int WH = W * H;
constexpr unsigned long long init_key = 1311768467463790320ull;
enum class Direction {Left, Right, Up, Down};

struct Position
{
    int row;
