class Status
{
public:
    // ctor
    Status() = default;
    Status(Board & board_, Position & blank_): board{board_}, blank{blank_} {mhd = calc_MHD(board_); key = calc_key(board_);};
    Status(Board & board_): board{board_} {blank = find_blank(board_); mhd = calc_MHD(board_); key = calc_key(board_);};
    // copy, move ctor
    Status(const Status & status) = default;
    Status(Status && status) = default;
    // copy, move assignment
    Status& operator=(const Status & status) = default;
    Status& operator=(Status && status) = default;
    //detor
    ~Status() = default;

    friend istream & operator>>(istream & is, Status & st);

    bool operator==(const Status & rhs) const {return key == rhs.key;};
    bool operator<(const Status & rhs) const {return key < rhs.key;};
    bool operator>(const Status & rhs) const {return key > rhs.key;};

    bool slide(Direction d);

    int get_mhd() const {return mhd;};
    Board get_board() const {return board;};
