class Npuzzle
{
private:
	Node s_node;
	int limit;
	vector<vector<int> > md;
	vector<int> path;
	int ans;
public:
	Npuzzle() {
		s_node = Node();
		vector<int> in;
		for (int i = 0; i < N2; ++i)
		{
			int tmp;
			cin >> tmp;
			if(tmp == 0) {
				tmp = N2;
				s_node.space = i;
			}
			in.push_back(tmp);
		}
		s_node.puzzle = in;
		set_md();
		s_node.md = get_md_sum(s_node.puzzle);
	}

	int get_md_sum(const vector<int>& puzzle) {
		int sum = 0;
		for (int i = 0; i < N2; ++i)
		{
			if(puzzle[i] == N2) continue;
			sum += md[i][puzzle[i]-1];
		}
		return sum;
	}

	void set_md() {
		md = vector<vector<int> >(N2, vector<int>(N2, 0));
		for (int i = 0; i < N2; ++i)
		{
			for (int j = 0; j < N2; ++j)
			{
				md[i][j] = abs(i / N - j / N) + abs(i % N - j % N);
			}
		}
	}

	bool dfs(Node cur_n, int depth, int pre) {
		if(cur_n.md == 0 ) {
			ans = depth;
			return true;
		}
		if(depth + cur_n.md > limit) return false;
		int s_x = cur_n.space / N;
		int s_y = cur_n.space % N;
		for (int i = 0; i < 4; ++i)
		{
			Node new_n = cur_n;
			int tx = s_x + dx[i];
			int ty = s_y + dy[i];
			if(tx < 0  || ty < 0 || tx >= N || ty >= N) continue; 
			if(max(pre, i) - min(pre, i) == 2) continue;
			int num = new_n.puzzle[tx * N + ty] - 1;
			// cout << dir[i] << endl;
			new_n.md -= md[tx * N + ty][new_n.puzzle[tx * N + ty] - 1];
			new_n.md += md[s_x * N + s_y][new_n.puzzle[tx * N + ty] - 1];
			swap(new_n.puzzle[tx * N + ty], new_n.puzzle[s_x * N + s_y]);
			// cout << new_n.space << endl;
			// cout << s_x << " "<< s_y << endl;
			// cout << tx << " "<< ty << endl;
			new_n.space = tx * N + ty;
			assert(get_md_sum(new_n.puzzle) == new_n.md);
			// return dfs(new_n, depth+1, i);
			if(dfs(new_n, depth + 1, i)){
				path[depth] = i;
				return true;
			}
		}
		return false;
	}

	void ida_star() {
		for (limit = s_node.md; limit < 1000; ++limit)
		{
			path.resize(limit);
			if(dfs(s_node, 0, -1)) {
				cout << limit << endl;
