	puzzle in;
	for (int i = 0; i < num; i++) {
		cin >> in.p[i];
		if (!in.p[i])  in.sp = i;
	}
	for (int i = 0; i < num; i++)
		for (int j = 0; j < num; j++)
			md[i][j] = abs(i / nd - j / nd) + abs(i%nd - j%nd);
	cout << astar(in) << endl;
	return 0;
}

