			int wwt1 = ((x >> (goals4[i] * 4)) & 15);
			int wwt2 = ((x >> (goals4[j] * 4)) & 15);
			if (ww1 > ww2) ret2++;
			if (wwt1 > wwt2) ret3++;
		}
	}
	ret2 = ret2 / 3 + ret2 % 3;
	ret3 = ret3 / 3 + ret3 % 3;
	int ret = max(ret1, ret2 + ret3);
	return ret;
}
int solve() {
	if (s == goal) return 0;
	int zz = -1;
	for (int i = 0; i < 16; i++) {
		if (!((s >> (i * 4)) & 15)) zz = i;
