    for(int i=0;i<NN;i++){
      if(f[i]==p.f[i])continue;
      return f[i]>p.f[i];
    }
    return false;
  }
};

struct Cost{
  P p;
  int cost;
  bool operator < (const Cost &c) const{
    return cost+p.t > c.cost+c.p.t;
  }
};

int man(int f[]){
  int ans=0;
  for(int i=0;i<NN;i++){
    if(f[i]==0)continue;
    ans+=abs((f[i]-1)/N-i/N);
    ans+=abs((f[i]-1)%N-i%N);
  }
  return ans;
}

