using namespace std;

int MDT[16][15];

class puzzle
{
public:
	int f[16];
	int space;
	int MD;
	int cost;

	bool operator<(const puzzle &p)const
	{
		for(int i=0;i<16;i++)
		{
			if(f[i]==p.f[i])continue;
			return f[i]>p.f[i];
		}
		return false;
	}
};

class state
{
public:
	puzzle p;
	int est;//estimated
	bool operator<(const state &s)const
	{
		return est>s.est;
	}
};

int astar(puzzle s)
{
	priority_queue<state>PQ;
	s.cost=0;
	map<puzzle,bool>V;
	puzzle u,v;
	state initial;
	initial.p=s;
	initial.est=s.MD;
	PQ.push(initial);

	while(!PQ.empty())
	{
		state st=PQ.top();PQ.pop();
		u=st.p;
		if(u.MD==0)return u.cost;
		V[u]=true;
		int sx=u.space/4;
		int sy=u.space%4;

		for(int r=0;r<4;r++)
		{
			int tx=sx;
			if(r==0)tx--;
			else if(r==2)tx++;
			int ty=sy;
			if(r==1)ty--;
			else if(r==3)ty++;
			if(tx<0||tx>=4||ty<0||ty>=4)continue;
			v=u;
			v.MD-=MDT[tx*4+ty][v.f[tx*4+ty]-1];
			v.MD+=MDT[sx*4+sy][v.f[tx*4+ty]-1];
			swap(v.f[sx*4+sy],v.f[tx*4+ty]);
			v.space=tx*4+ty;
			if(!V[v])
			{
				v.cost++;
				state news;
				news.p=v;
				news.est=v.cost+v.MD;
				PQ.push(news);
			}
		}
	}

	return -1;
}

