		{
			MDT[i][j]=abs(i/4-j/4)+abs(i%4-j%4);
		}
	}

	puzzle in;

	for(int i=0;i<16;i++)
	{
		cin>>in.f[i];
		if(in.f[i]==0)
		{
			in.f[i]=16;
			in.space=i;
		}
	}

	in.MD=0;
	for(int i=0;i<16;i++)
	{
		if(in.f[i]==16)continue;
		in.MD+=MDT[i][in.f[i]-1];
	}

	cout<<astar(in)<<endl;

	return 0;
}

