#include <iostream>
#include <set>
#include <stack>
#include <cstdlib>
#define N 4
#define N2 16
#define MAX_DEPTH 45
using namespace std;

class game{
  int board[N2];
  int w;
  int last_move;

  void calc_md(){
    int sum=0;
    for(int i=0;i<N2;i++){
      if(board[i]==N2) continue;
      sum+=abs(i%N-(board[i]-1)%N)+abs(i/N-(board[i]-1)/N);
    }
    md = sum;
  }

public:
  int md;
  int depth;

  game(int ary[]){
    for(int i=0;i<N2;i++){
      board[i]=ary[i];
      if(board[i]==N2){
        w=i;
      }
    }

    calc_md();
    last_move=0;
    depth=0;
  }

  void move(int dr){
    int d=w+dr;
    swap(board[w],board[d]);
    md+=abs(w%N-(board[d]-1)%N)+abs(w/N-(board[d]-1));
    md-=abs(d%N-(board[d]-1)%N)+abs(d/N-(board[d]-1));
    w=d;
    last_move=dr;
    depth++;
  }

  set<int> move_list(){
    set<int> v;
    if(w%N<N-1) v.insert(1);
    if(w%N>0  ) v.insert(-1);
    if(w/N<N-1) v.insert(N);
    if(w/N>0  ) v.insert(-N);

    v.erase(-last_move);
    return v;
  }

  void print(){
    for(int i=0;i<N2;i++){
      if(i%N==0) printf("\n");
      printf("%d ",board[i]);
    }
    printf("\n");
  }

  bool is_goal(){
    for(int i=0;i<N2;i++){
      if(board[i]!=i+1) return false;
    }
    return true;
  }
};

bool dfs(game &start,int depth){
  stack<game> s;
  s.push(start);
  while(!s.empty()){
    game g=s.top();s.pop();
    if(g.depth==depth){
      if(g.is_goal()) return true;
      continue;
    }

    if(g.depth+g.md>MAX_DEPTH) continue;

    set<int> mlist = g.move_list();
    for(int m:mlist){
      game _g=g;
      _g.move(m);
      s.push(_g);
    }
  }
  return false;
}

int solve(game &start){
  set<int> v = start.move_list();
  for(int i=0;i<MAX_DEPTH;i++){
    if(dfs(start,i)) return i;
  }
  return -1;
}

