  int ary[N2];
  for(int i=0;i<N2;i++){
    int tmp;cin>>tmp;
    if(tmp==0){
      ary[i]=N2;
    }else{
      ary[i]=tmp;
    }
  }

  game start(ary);
  cout<<solve(start)<<endl;
}

