unsigned long long int fact(int a){
	unsigned long long int b = 1;
	for (int i = 2; i <= a; i++){
		b = b * i;
	}
	return b;
}

int dist(unsigned long long int x){
	std::vector<int> P = ItoP(x);
	int result = 0;
	for (int i = 0; i < DIVN*DIVN; i++){
		if (P[i] == 0) continue;
		result += abs(P[i] % DIVN - (i + 1) % DIVN) + abs((P[i] - 1) / DIVN - i / DIVN);
	}
	int s = SearchPuzzle(x);
	return -result - (s == -1 ? 1048576 : Puzzles[s].t);
}

int abs(int x){
	return x < 0 ? -x : x;
}

void insert(vector< Pandt > &A, Pandt v){
	int n = A.size();
	A.push_back(v);
	while (n != 0){
		int i = (n - 1) / 2;
		unsigned long long int x = A[n].p;
		if (dist(A[n].p) > dist(A[i].p)){
			Pandt tmp = A[n];
			A[n] = A[i];
			A[i] = tmp;
		}
		n = i;
	}
	return;
}

Pandt extract(vector< Pandt > &A){
	int n = A.size() - 1;
	Pandt res = A[0];
	A[0] = A[n];
	A.pop_back();

	for (int i = 0, j; 2 * i + 1 < n;){
		j = 2 * i + 1;
		if (j != n - 1 && dist(A[j].p) < dist(A[j + 1].p)){
			j++;
		}
		if (dist(A[i].p) < dist(A[j].p)){
			Pandt tmp = A[j];
			A[j] = A[i];
			A[i] = tmp;
		}
		i = j;
	}
	return res;
}


unsigned long long int PtoI(vector<int> p){
	int x;
	unsigned long long int result = 0;
	for (int i = 0; i < DIVN*DIVN - 1; i++){
		for (int j = 0; j < DIVN*DIVN - i; j++){
			if (p[j] == i){
				x = j;
				p.erase(p.begin() + j);
				break;
			}
		}
		result += fact(DIVN*DIVN - i - 1) * x;
	}
	return result;
}

vector<int> ItoP(unsigned long long int ii){
	vector<int> result(DIVN*DIVN, -1);
	for (int i = 0; i < DIVN*DIVN; i++){
		int index = ii / fact(DIVN*DIVN - i - 1);
		ii = ii % fact(DIVN*DIVN - i - 1);
		int curindex = -1;
		int x = -1;
		for (int j = 0; j < DIVN*DIVN; j++){
			if (result[j] == -1){
				curindex++;
			}
			if (curindex == index) {
				x = j;
				break;
			}
		}
		result[x] = i;
	}
	return result;
}

int SearchPuzzle(int x){
	for (int i = 0; i < (int)Puzzles.size(); i++){
		if (Puzzles[i].p == x) return i;
	}
	return -1;
}

int SolvePuzzle(vector<int> P){
	vector< Pandt > Que;
	Pandt Ppluszero;
	Ppluszero.p = PtoI(P); Ppluszero.t = 0;
	insert(Que, Ppluszero);
	int answer = 10000;
	Puzzles.push_back(Ppluszero);
	while (!Que.empty()){
		Pandt ext = extract(Que);
		vector<int> Q = ItoP(ext.p);
		int Cursor;
		bool isAligned = true;
		for (int i = 0; i < DIVN*DIVN; i++){
			if (Q[i] != (i + 1) % (DIVN*DIVN)){
				isAligned = false;
				break;
			}
		}
		if (isAligned){
			answer = ext.t;
			break;
		}
		for (int i = 0; i < DIVN*DIVN; i++){
			if (Q[i] == 0){
				Cursor = i;
				break;
			}
		}
		vector<int> Qnext;
		int Qsearch;
		if (Cursor >= DIVN){
			Qnext = Q;
			swap(Qnext[Cursor], Qnext[Cursor - DIVN]);
			Qsearch = SearchPuzzle(PtoI(Qnext));
			if (Qsearch == -1){
				Pandt tmp; tmp.p = PtoI(Qnext); tmp.t = ext.t + 1;
				Puzzles.push_back(tmp);
				insert(Que, tmp);
			}else if (Puzzles[Qsearch].t > ext.t + 1){
				Puzzles[Qsearch].t = ext.t + 1;
				Pandt tmp; tmp.p = PtoI(Qnext); tmp.t = ext.t + 1;
				insert(Que, tmp);
			}
		}
		if (Cursor < DIVN * (DIVN - 1)){
			Qnext = Q;
			swap(Qnext[Cursor], Qnext[Cursor + DIVN]);
			Qsearch = SearchPuzzle(PtoI(Qnext));
			if (Qsearch == -1){
				Pandt tmp; tmp.p = PtoI(Qnext); tmp.t = ext.t + 1;
				Puzzles.push_back(tmp);
				insert(Que, tmp);
			}
			else if (Puzzles[Qsearch].t > ext.t + 1){
				Puzzles[Qsearch].t = ext.t + 1;
				Pandt tmp; tmp.p = PtoI(Qnext); tmp.t = ext.t + 1;
				insert(Que, tmp);
			}
		}
		if (Cursor % DIVN != 0){
			Qnext = Q;
			swap(Qnext[Cursor], Qnext[Cursor - 1]);
			Qsearch = SearchPuzzle(PtoI(Qnext));
			if (Qsearch == -1){
				Pandt tmp; tmp.p = PtoI(Qnext); tmp.t = ext.t + 1;
				Puzzles.push_back(tmp);
				insert(Que, tmp);
			}
			else if (Puzzles[Qsearch].t > ext.t + 1){
				Puzzles[Qsearch].t = ext.t + 1;
				Pandt tmp; tmp.p = PtoI(Qnext); tmp.t = ext.t + 1;
				insert(Que, tmp);
			}
		}
		if (Cursor % DIVN != DIVN - 1){
			Qnext = Q;
			swap(Qnext[Cursor], Qnext[Cursor + 1]);
			Qsearch = SearchPuzzle(PtoI(Qnext));
			if (Qsearch == -1){
				Pandt tmp; tmp.p = PtoI(Qnext); tmp.t = ext.t + 1;
				Puzzles.push_back(tmp);
				insert(Que, tmp);
			}
			else if (Puzzles[Qsearch].t > ext.t + 1){
				Puzzles[Qsearch].t = ext.t + 1;
				Pandt tmp; tmp.p = PtoI(Qnext); tmp.t = ext.t + 1;
				insert(Que, tmp);
			}
		}
	}

	return answer;
}

