using namespace std;

class State
{
public:
  vector<vector<int>> bd;
  int cnt;
  int h;
  int spr, spc;
  bool operator < ( const State& s ) const
  {
    if ( (h + cnt) == (s.h + s.cnt) )
      return cnt > s.cnt;
    else
      return (h + cnt) > (s.h + s.cnt);
  }
  void calch();
  void debugPrint();
};

void State::calch()
{
  int th = 0;

  for ( auto i = 0; i < 4; ++i )
    for ( auto j = 0; j < 4; ++j )
      {
        if ( bd[i][j] == 0 )
          th += abs( i - 3 ) + abs( j - 3 );
        else
          th += abs( i - ((bd[i][j] - 1) / 4) ) + abs( j - ((bd[i][j] - 1) % 4) );
      }
  h = th;
}

void State::debugPrint()
{
  cout << "========================" << endl;
  for ( auto u = 0; u < 4; ++u )
    {
      for ( auto v = 0; v < 4; ++v )
        {
          cout << " " << bd[u][v];
        }
      cout << endl;
    }
  cout << "cnt : " << cnt << endl;
  cout << "h : " << h << endl;
  cout << spr << " " << spc << endl;
}

class FifteenPuzzle
{
public:
  priority_queue<State> pq;
  map<vector<vector<int>>,int> m;
  vector<int> dr,dc;
  FifteenPuzzle(){}
  FifteenPuzzle( State st )
  {
    pq.push(st);
    m[st.bd] = 0;
    dr = {1, -1, 0, 0}; dc = {0, 0, 1, -1};
  }
  int solve();
};

int FifteenPuzzle::solve()
{
  State st, nst;

  while ( ! pq.empty() )
    {
      st = pq.top();
      pq.pop();

      if ( st.h == 0 )
        {
          cout << st.cnt << endl;
          return 0;
        }

      for ( auto i = 0; i < 4; ++i )
        {
          int nr = st.spr + dr[i];
          int nc = st.spc + dc[i];
          if ( nr < 0 || nr > 3 || nc < 0 || nc > 3 ) continue;

          nst = st;
          nst.bd[st.spr][st.spc] = st.bd[nr][nc];
          nst.bd[nr][nc] = 0;
          nst.spr = nr;
          nst.spc = nc;
          nst.cnt = st.cnt + 1;
          nst.calch();

          if ( m.count(nst.bd) == 0 || m[nst.bd] > nst.cnt )
            {
              pq.push(nst);
              m[nst.bd] = nst.cnt;
            }
        }
    }

  return 0;
}

