int getAllMD(Puzzle pz)
{
  int sum=0;
  for(int i=0;i<N2;i++)
    {
      if(pz.f[i]==N2)
	{
	  continue;
	}

      sum+=MDT[i][pz.f[i]-1];
    }

  return sum;
}

bool isSolved()
{
  for(int i=0;i<N2;i++)
    {
      if(state.f[i]!=i+1)
	{
	  return false;
	}
    }

  return true;
}

bool dfs(int depth,int prev)
{
  if(state.MD==0)
    {
      return true;
    }

  if(depth+state.MD>limit)
    {
      return false;
    }

  int sx=state.space/N;
  int sy=state.space%N;

  Puzzle tmp;

  for(int r=0;r<4;r++)
    {
      int tx=sx+dx[r];
      int ty=sy+dy[r];

      if(tx<0||ty<0||tx>=N||ty>=N)
	{
	  continue;
	}

      if(max(prev,r)-min(prev,r)==2)
	{
	  continue;
	}

      tmp=state;

      state.MD-=MDT[tx*N+ty][state.f[tx*N+ty]-1];
      state.MD+=MDT[sx*N+sy][state.f[tx*N+ty]-1];

      swap(state.f[tx*N+ty],state.f[sx*N+sy]);

      state.space=tx*N+ty;

      if(dfs(depth+1,r))
	{
	  path[depth]=r;
	  return true;
	}

      state = tmp;
    }

  return false;
}

string iterative_deepening(Puzzle in)
{
  in.MD=getAllMD(in);

  for(limit=in.MD;limit<=LIMIT;limit++)
    {
      state=in;
      if(dfs(0,-100))
	{
	  string ans="";

	  for(int i=0;i<limit;i++)
	    {
	      ans += dir[path[i]];
	    }

	  return ans;
        }
    }

  return "unsolvable";
}

