		return true;

	}
	if(depth+state.MD>lim){
		return false;
	}
	int stx=state.space/n;
	int sty=state.space%n;
	Puzzle temp;

	for(int i=0;i<n;i++){
		int tx=stx+x[i];
		int ty=sty+y[i];
		if(tx<0||ty<0||tx>=n||ty>=n){
