      ret+=abs(cy[ti]-i);
      // if (cx[ti]!=j||cy[ti]!=i)ret++;
    }
  }
  return ret;
}

bool trymove(int c,int zx,int zy,int pzx,int pzy){
  int dx[]={0,1,0,-1},dy[]={1,0,-1,0};
  if (evaluate()==0)return true;
  if (c+evaluate()>limit)return false;
  for (int i=0;i<4;i++){
    if (0>zx+dx[i]||zx+dx[i]>3||0>zy+dy[i]||zy+dy[i]>3)continue;
    if (zx+dx[i]==pzx&&zy+dy[i]==pzy)continue;
