}
int cost(){
	int ans = 0, x;
	for(int i=0; i<N; i++)
		for(int j=0; j<N; j++){
			if(!m[i][j]) continue;
			x = m[i][j] - 1;
			ans += abs(x/N-i) + abs(x%N-j);
		}
	return ans;
}
bool dfs(int limit, int back, int now, int r, int c){
	int predict = cost();
	int r1, c1;
	if(predict == 0) return 1;
	if(predict+now > limit) return 0;
	for(int i=0; i<4; i++){
		r1 = p[i][0] + r;
