		{
			return;
		}
		if (key[i]>nkey[i])
		{
			if (left == nullptr)
			{
				left = new OwnNode(nkey);
			}
			else
			{
				left->insert(nkey);
			}
		}
		else
		{
			if (right == nullptr)
			{
				right = new OwnNode(nkey);
			}
			else
			{
				right->insert(nkey);
			}
		}
	}

	bool find(int fkey[])
	{
