		{
			if (key[i] != fkey[i])
			{
				break;
			}
		}
		if (i == 16)
		{
			return true;
		}
		if (key[i]>fkey[i])
		{
			if (left == nullptr)
			{
				return false;
			}
			else
			{
				return left->find(fkey);
			}
		}
		else
		{
			if (right == nullptr)
			{
				return false;
