State goal;

int heuristic(State& s)
{
	int eva = 0;
	int pos1[16], pos2[16];
	for (int i = 0; i < 16; i++)
	{
		pos1[s.puzzle[i]] = i;
		pos2[goal.puzzle[i]] = i;
	}
	for (int i = 0; i < 16; i++)
	{
		if (s.puzzle[i] == 0)
		{
			continue;
		}
		int manhattan = 0;
		manhattan += abs(pos1[i] / 4 - pos2[i] / 4);
		manhattan += abs(pos1[i] % 4 - pos2[i] % 4);
		eva += manhattan;
	}
	return eva;
}

int solve(State start, int limit)
{
	State ts = start;
	int mini = 100000;

	if (ts == goal)
	{
		return ts.depth;
	}

	int zeroi = -1;
	for (int i = 0; i < 16; i++)
	{
		if (ts.puzzle[i] == 0)
		{
			zeroi = i;
			break;
		}
