		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				if (r.x[i][j] == 0) z = make_pair(i, j);
			}
		}
		int dx[4] = { 0,1,0,-1 };
		int dy[4] = { 1,0,-1,0 };
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				for (int k = 0; k < 4; k++)s.x[j][k] = r.x[j][k];
			}
			int px = z.first + dx[i], py = z.second + dy[i];
			if (py < 0 || py > 3)continue;
			if (px < 0 || px > 3)continue;
			swap(s.x[z.first][z.second], s.x[px][py]);
			if (manh(r) >= manh(s)) {
				int OK = 1;
				for (int j = 0; j < 4; j++) {
					for (int k = 0; k < 4; k++) {
						if (s.x[j][k] == (j * 4 + k + 1) % 16) {
							OK = 0;
						}
					}
				}
				if (OK == 1) {
					cout << V + 1 << endl;
					return 0;
				}
				Q.push(make_pair(s, V + 1));
			}
		}
	}
	return 0;
}

