	          std::set<TFifteenPuzzle>& History)
{
	if(std::find(NextTargets.begin(), NextTargets.end(), Goal) != NextTargets.end()) return true;
	std::vector<TFifteenPuzzle> NewTargets;
	for(std::vector<TFifteenPuzzle>::const_iterator It = NextTargets.begin(); It != NextTargets.end(); ++It){
		RenewTargets(*It, mpUp,    NewTargets, History);
		RenewTargets(*It, mpDown,  NewTargets, History);
		RenewTargets(*It, mpLeft,  NewTargets, History);
		RenewTargets(*It, mpRight, NewTargets, History);
	}
	NextTargets = NewTargets;
	return false;
}

void AddMovedPuzzle(std::vector<TFifteenPuzzle>& Targets, const TFifteenPuzzle& Puzzle, const TMovePattern& Pattern)
{
	if(!Movable(Puzzle, Pattern)) return;
	TFifteenPuzzle Moved = Move(Puzzle, Pattern);
	Targets.push_back(Moved);
}

void RenewPuzzles(std::vector<TFifteenPuzzle>& Puzzles)
{
	std::vector<TFifteenPuzzle> NewPuzzles;
	for(std::vector<TFifteenPuzzle>::const_iterator It = Puzzles.begin(); It != Puzzles.end(); ++It){
		AddMovedPuzzle(NewPuzzles, *It, mpUp);
		AddMovedPuzzle(NewPuzzles, *It, mpDown);
		AddMovedPuzzle(NewPuzzles, *It, mpLeft);
		AddMovedPuzzle(NewPuzzles, *It, mpRight);
	}
	Puzzles = NewPuzzles;
}

int CountMinimumMove(const TFifteenPuzzle& Puzzle)
{
	std::vector<TFifteenPuzzle> Start(1, Puzzle);
	std::vector<TFifteenPuzzle> Targets(1, TFifteenPuzzle());
	int Count = 0;
	TFifteenPuzzle Target;
	while(std::find_first_of(Start.begin(), Start.end(), Targets.begin(), Targets.end()) == Start.end()){
		++Count;
		RenewPuzzles(Start);
		std::swap(Start, Targets);
	}
	return Count;
}

