#define R 4



inline ull Hash(vector<vector<ll>> &A){
    ull ret=0;
    for(int i=0;i<R;i++){
        for(int t=0;t<R;t++){
            ret+=A[i][t];
            if(i+1!=R || t+1!=R){
                ret*=16;
            }
        }
    }
    return ret;
}

vector<pll> where={{3,3},{0,0},{0,1},{0,2},{0,3},{1,0},{1,1},{1,2},{1,3},{2,0},{2,1},{2,2},{2,3},{3,0},{3,1},{3,2}};
