inline ll dist(vector<vector<ll>> &A){
    ll ret=0;
    for(int i=0;i<R;i++){
        for(int t=0;t<R;t++){
            ret+=abs(where[A[i][t]].F-i)+abs(where[A[i][t]].S-t);
        }
    }
    return ret;
}

