#define mx 20

inline vector<vector<ll>> Rhash(ull hash){
    vector<vector<ll>> ret(R,vector<ll>(R));
    for(int i=R-1;i>=0;i--){
        for(int t=R-1;t>=0;t--){
            ret[i][t]=hash%16;
            hash/=16;
        }
    }
    return ret;
}

inline void Rhash(ull hash,vector<vector<ll>> &ret){
    for(int i=R-1;i>=0;i--){
        for(int t=R-1;t>=0;t--){
            ret[i][t]=hash%16;
            hash/=16;
        }
    }
}

vector<ll> dx={0,1,0,-1};
vector<ll> dy={1,0,-1,0};

map<ull,ll> M;

struct PZL{
    ll D;
    ull hash;
    ll h,w;
    ll d;

    inline bool operator < (const PZL &P) const {
        return D>P.D || (D==P.D && d>P.d);
    }
};

struct PZL2{
    ull hash;
    ll h,w;
    ll d;
};



void bfs(vector<vector<ll>> A){
    queue<PZL2> Q;
    Q.push({Hash(A),3,3,0});
    M[Hash(A)]=0;
    PZL2 W,N;
    while(!Q.empty()){
        W=Q.front(); Q.pop();
        Rhash(W.hash,A);
        for(int i=0;i<4;i++){
            ll x=W.h+dx[i];
            ll y=W.w+dy[i];
            if(x<0 || y<0 || x>=R || y>=R){continue;}
            N=W;
            swap(A[x][y],A[W.h][W.w]);
            N.hash=Hash(A);
            if(M.count(N.hash)){swap(A[x][y],A[W.h][W.w]); continue;}
            N.h=x;
            N.w=y;
            M[N.hash]=++N.d;
            if(N.d>=mx){return;}
            Q.push(N);
            swap(A[x][y],A[W.h][W.w]);
        }
    }
}

ll dfs(vector<vector<ll>> A,ll h,ll w){
    if(A==ans){return 0;}
    priority_queue<PZL> S;
    set<ull> done;
    ull hash=Hash(A);
    if(M.count(hash)){return M[hash];}
    S.push({dist(A),hash,h,w,0});
    done.insert(hash);
    PZL N,W;
    while(!S.empty()){
        W=S.top();
        S.pop();
        Rhash(W.hash,A);
        W.d++;
        W.D+=2;
        W.D-=abs(where[A[W.h][W.w]].F-W.h)+abs(where[A[W.h][W.w]].S-W.w);
        for(int i=0;i<4;i++){
            ll x=W.h+dx[i];
            ll y=W.w+dy[i];
            if(x<0 || y<0 || x>=R || y>=R){continue;}
            N=W;
            N.D-=abs(where[A[x][y]].F-x)+abs(where[A[x][y]].S-y);
            swap(A[x][y],A[W.h][W.w]);
            N.D+=abs(where[A[x][y]].F-x)+abs(where[A[x][y]].S-y);
            N.D+=abs(where[A[W.h][W.w]].F-W.h)+abs(where[A[W.h][W.w]].S-W.w);
            if(N.D>90){swap(A[x][y],A[W.h][W.w]); continue;}
            N.hash=hash=Hash(A);
            if(N.D-N.d*2<=mx*2 && M.count(N.hash)){return N.d+M[N.hash];}
            swap(A[x][y],A[W.h][W.w]);
            if(done.count(hash)){continue;}
            done.insert(hash);
            N.h=x;
            N.w=y;
            S.push(N);
        }
    }
    return -1;
}



