struct puzzle {
	int sp, p[num], mdp, cost;
	bool operator < (const puzzle &pu) const {
		for (int i = 0; i < num; i++) {
			if (p[i] == pu.p[i]) continue;
			return p[i] < pu.p[i];
		}
		return false;
	}
};
struct state {
	puzzle pu;
	bool operator < (const state &s) const {
		return pu.mdp + pu.cost > s.pu.mdp + s.pu.cost;
	}
};
int astar(puzzle pz) {
	int sum = 0;
	for (int i = 0; i < num; i++) {
		if (pz.p[i] == 0) continue;
		sum += md[i][pz.p[i] - 1];
	}
	pz.mdp = sum;
	pz.cost = 0;
	priority_queue<state> pq;
	map<puzzle, bool> m;
	state s;
	s.pu = pz;
	pq.push(s);
	state st, st1;
	puzzle p;
	int tx, ty, ns;
	while (!pq.empty()) {
		st = pq.top(); pq.pop();
		p = st.pu;
		if (!p.mdp) return p.cost;
		puzzle tmp;
		m[p] = true;
		int sx = p.sp / nd;
		int sy = p.sp % nd;
		for (int r = 0; r < nd; r++) {
			tx = sx + ud[r];
			ty = sy + lr[r];
			tmp = p;
			if (tx >= nd || tx < 0 || ty >= nd || ty < 0) continue;
			ns = tx * nd + ty;
			tmp.mdp = p.mdp - md[ns][p.p[ns] - 1] + md[sx*nd + sy][p.p[ns] - 1];
			tmp.sp = ns;
			swap(tmp.p[ns], tmp.p[sx * nd + sy]);
			tmp.cost = p.cost + 1;
			if (!m[tmp]) {
				st1.pu = tmp;
				pq.push(st1);
			}
		}
	}
}

