int swap_upper(int*, int*, int);
int swap_lower(int*, int*, int);
int swap_left(int*, int*, int);
int swap_right(int*, int*, int);
int fair_evaluator(int*, int*);
int Dfs(int*, int*, int, int, int);
int main(void)
{
