int swap_upper(int *board, int *next, int prev)
{
  int i, pos, e = sqrt(Size);
  for (i = 0; i < Size; i++) {
    if (!board[i]) pos = i;
  }
  if (!(pos / e) || prev == 1) return 0;
  else {
    memcpy(next, board, sizeof(int) * Size);
    next[pos] = board[pos - e];
    next[pos - e] = board[pos];
  }
  return 1;
}
int swap_lower(int *board, int *next, int prev)
{
  int i, pos, e = sqrt(Size);
  for (i = 0; i < Size; i++) {
    if (!board[i]) pos = i;
  }
  if ((pos / e) == e - 1 || prev == 0) return 0;
  else {
    memcpy(next, board, sizeof(int) * Size);
    next[pos] = board[pos + e];
    next[pos + e] = board[pos];
  }
  return 1;
}
int swap_left(int *board, int *next, int prev)
{
  int i, pos, e = sqrt(Size);
  for (i = 0; i < Size; i++) {
    if (!board[i]) pos = i;
  }
  if (!(pos % e) || prev == 3) return 0;
  else {
    memcpy(next, board, sizeof(int) * Size);
    next[pos] = board[pos - 1];
    next[pos - 1] = board[pos];
  }
  return 1;
}
int swap_right(int *board, int *next, int prev)
{
  int i, pos, e = sqrt(Size);
  for (i = 0; i < Size; i++) {
    if (!board[i]) pos = i;
  }
  if ((pos % e) == e - 1 || prev == 2) return 0;
  else {
    memcpy(next, board, sizeof(int) * Size);
    next[pos] = board[pos + 1];
    next[pos + 1] = board[pos];
  }
  return 1;
}
int fair_evaluator(int *board, int *goal)
{
  int i, j, e = sqrt(Size), score = 0;
  for (i = 1; i < Size; i++) {
    int x1, y1, x2, y2;
    for (j = 0; j < Size; j++) {
      if (board[j] == i) {
        x1 = j % e;
        y1 = j / e;
      }
      if (goal[j] == i) {
        x2 = j % e;
        y2 = j / e;
      }
    }
    score += fabs(x1 - x2) + fabs(y1 - y2);
  }
  return score;
}
 int Dfs(int *board, int *goal, int depth, int prev, int limit)
{
  int dis = fair_evaluator(board, goal), next[Size];
  if (!dis) return 1;
  else if (depth + dis > limit) return 0;
  if (swap_upper(board, next, prev)) {
    if (Dfs(next, goal, depth + 1, 0, limit)) return 1;
  }
  if (swap_lower(board, next, prev)) {
    if (Dfs(next, goal, depth + 1, 1, limit)) return 1;
  }
  if (swap_left(board, next, prev)) {
    if (Dfs(next, goal, depth + 1, 2, limit)) return 1;
  }
  if (swap_right(board, next, prev)) {
    if (Dfs(next, goal, depth + 1, 3, limit)) return 1;
  }
  return 0;
}

#include <stdio.h>

#define N 16

int board[N];
int rows = 4, cols = 4, zeroIndex;

// for previousMove: 0 is down, 1 is up, 2 is left, 3 is right
int blindSearch(int x, int y, int moves, int previousMove) {
  int i, foundAnswer;

  // answer is less than manhattan distance, not possible
  if (moves < (x + y))
    return 0;

  if (!moves) {
    for (i = 0; i < N - 1; i++) {
      if (board[i] != i + 1)
        return 0;
    }

    return 1;
  }

  if (x > 0 && previousMove != 1) {
    // can expand down
    board[zeroIndex] = board[zeroIndex + rows];
    zeroIndex += rows;

    foundAnswer = blindSearch(x - 1, y, moves - 1, 0);
    if (foundAnswer)
      return 1;

    board[zeroIndex] = board[zeroIndex - rows];
    zeroIndex -= rows;
  }

  if (y > 0 && previousMove != 3) {
    // right
    board[zeroIndex] = board[zeroIndex + 1];
    zeroIndex++;

    foundAnswer = blindSearch(x, y - 1, moves - 1, 2);
    if (foundAnswer)
      return 1;

    board[zeroIndex] = board[zeroIndex - 1];
    zeroIndex--;
  }

  if (y < rows - 1 && previousMove != 2) {
    // left
    board[zeroIndex] = board[zeroIndex - 1];
    zeroIndex--;

    foundAnswer = blindSearch(x, y + 1, moves - 1, 3);
    if (foundAnswer)
      return 1;

    board[zeroIndex] = board[zeroIndex + 1];
    zeroIndex++;
  }

  if (x < cols - 1 && previousMove != 0) {
    // up
    board[zeroIndex] = board[zeroIndex - rows];
    zeroIndex -= rows;

    foundAnswer = blindSearch(x + 1, y, moves - 1, 1);
    if (foundAnswer)
      return 1;

    board[zeroIndex] = board[zeroIndex + rows];
    zeroIndex += rows;
  }

  return 0;
}

int main() {
  int i, x, y, current;

  for (i = 0; i < N; i++) {
    scanf("%d", &board[i]);
    if (!board[i])
      zeroIndex = i;
  }

  x = cols - (zeroIndex / rows) - 1;
  y = rows - (zeroIndex % cols) - 1;

  for (current = 0; current < 50; current++) {
    if (blindSearch(x, y, current, -1)) {
      printf("%d\n", current);
      return 0;
    }
  }
}

