#define N 4
#define LIMIT 100
#define TRUE 1
#define FALSE 0
#define NIL -1

typedef struct{
  int map[N*N];
  int space,MD;
}PUZZLE;

int dx[4]={0,-1,0,1};
int dy[4]={1,0,-1,0};
int limit,path[LIMIT];
int MDT[N*N][N*N];
PUZZLE status,in;

int getHeur(PUZZLE);//マンハッタン距離の総和を計算し、その値をヒューリスティック値とする。
int dfs(int,int);//深さ優先探索
void getAns(PUZZLE);//IDA


int main(){
  int i,j,memory;
  PUZZLE p;
  //  for(i=0;i<LIMIT;i++)path[i]=NIL;


  for(i=0;i<N*N;i++){
    for(j=0;j<N*N;j++){
      MDT[i][j]=abs(i/N-j/N)+abs(i%N-j%N);
    }
  }

  for(i=0;i<N*N;i++){
    scanf("%d",&p.map[i]);
    if(p.map[i]==0)memory=i;
  }
  p.map[memory]=N*N;
  p.space=memory;

  getAns(p);
  // for(i=0;i<100;i++)printf("%d\n",path[i]);

  return 0;
}


int getHeur(PUZZLE p){
  int i;
  int h=0;//ヒューリスティック値
  for(i=0;i<N*N;i++){
    if(p.map[i]==N*N){
      continue;
    }
    h+=MDT[i][p.map[i]-1];
  }
  return h;
}

int dfs(int depth,int prev){
  int i;
  PUZZLE pTemp;
  int sx,sy,tx,ty,temp;


  if(status.MD==0) return TRUE;
  if(depth+status.MD>limit)return FALSE;

  sx=status.space/N;
  sy=status.space%N;

  for(i=0;i<4;i++){
    tx=sx+dx[i];
    ty=sy+dy[i];
    if(!(tx>=0&&tx<N&&ty>=0&&ty<N))continue;
    if(abs(prev-i)==2)continue;

    pTemp=status;
    status.MD+=MDT[sx*N+sy][status.map[tx*N+ty]-1];
    status.MD-=MDT[tx*N+ty][status.map[tx*N+ty]-1];
    temp=status.map[tx*N+ty];
    status.map[tx*N+ty]= status.map[sx*N+sy];
    status.map[sx*N+sy]=temp;
    status.space=tx*N+ty;
    if(dfs(depth+1,i)==TRUE){
      path[depth]=i;
      return TRUE;
    }
    status=pTemp;
  }
  return FALSE;
}



void getAns(PUZZLE p){
  int i,result=0;
  p.MD=getHeur(p);
  for(limit=p.MD;limit<=LIMIT;limit++){
