      scanf("%d",&pu[i][j]);
  }

  empty(&x,&y);
  for(l=0; l<100; l++) {
    for(i=0; i<4; i++) {
      for(j=0; j<4; j++)
	t[i][j] = pu[i][j];
    }

    n = dfs(x,y,-1,0,l);
    if(n!=-1) {
      printf("%d\n",n);
      break;
    }

    for(i=0 ; i<4; i++) {
      for(j=0 ; j<4; j++)
	pu[i][j] = t[i][j];
    }
    n = -1;
