int dfs(int lim,int now,int before){
  //if(lim==19)printf("%d %d\n",now,ndfs.md);
  int i,ans=-1,tmp;
  Board dummy = ndfs;
  //答えになっているか判定
  if(dummy.md==0)return now;
  //探索うちきり
  if(ndfs.md+now>=lim)return -1;
  for(i=0;i<4;i++){
    if(dummy.sp%4==0&&i==2)continue;
    if(dummy.sp%4==3&&i==1)continue;
    ndfs = dummy;
    //-のマスの移動
    ndfs.sp+=mov[i];
    //範囲内かどうか、一手前に戻ってないかどうか
    if(ndfs.sp>=0&&ndfs.sp<16&&before+i!=3){
      //mdをずらす
      ndfs.md -= md[dummy.map[ndfs.sp]][ndfs.sp];
      ndfs.md += md[dummy.map[ndfs.sp]][dummy.sp];
      //swap
      ndfs.map[dummy.sp]=dummy.map[ndfs.sp];
      ndfs.map[ndfs.sp]=0;
      /*for(int j=0;j<16;j++)printf("%2d",dummy.map[j]);
      printf("\n");
      for(int j=0;j<16;j++)printf("%2d",ndfs.map[j]);
      printf("\n\n");*/
      ans = dfs(lim,now+1,i);
      if(ans!=-1)break;
    }
  }
  return ans;
}
