void calcMinCost(data firstData)
{
  int row,col;
  data curData;//current data
  data nextData;
  enqueue(firstData);
  while(head!=tail)
    {
      //printArr();
      curData=dequeue();
      if(curData.cost>=curMinCost) continue;
      if(isCorrect(curData)==1)
	{
	  curMinCost=curData.cost;
	  continue;
	}
      row=get0Row(curData);
      col=get0Col(curData);
      if(row!=N-1&&curData.lastMove!=3)//slide up
	{
	  nextData=curData;
	  nextData.tempArr[row][col]=nextData.tempArr[row+1][col];
	  nextData.tempArr[row+1][col]=0;
	  nextData.cost++;
	  nextData.lastMove=1;
	  enqueue(nextData);
	}
      if(col!=N-1&&curData.lastMove!=4)//slide left
	{
	  nextData=curData;
	  nextData.tempArr[row][col]=nextData.tempArr[row][col+1];
	  nextData.tempArr[row][col+1]=0;
	  nextData.cost++;
	  nextData.lastMove=2;
	  enqueue(nextData);
	}
      if(row!=0&&curData.lastMove!=1)//slide down
	{
	  nextData=curData;
	  nextData.tempArr[row][col]=nextData.tempArr[row-1][col];
	  nextData.tempArr[row-1][col]=0;
	  nextData.cost++;
	  nextData.lastMove=3;
	  enqueue(nextData);
	}
      if(col!=0&&curData.lastMove!=2)//slide right
	{
	  nextData=curData;
	  nextData.tempArr[row][col]=nextData.tempArr[row][col-1];
	  nextData.tempArr[row][col-1]=0;
	  nextData.cost++;
	  nextData.lastMove=4;
	  enqueue(nextData);
	}
    }
}
