void searchMinCost(int tempArr[N][N],int lastMove,int curCost)
{
  int h=0;
  int i,j;
  int blankI,blankJ;
  for(i=0;i<N;++i)
    {
      for(j=0;j<N;++j)
	{
	  if(tempArr[i][j]!=ansArr[i][j])
