	      h+=heuristic[tempArr[i][j]][ansArr[i][j]];
	    }
	  if(tempArr[i][j]==0)
	    {
	      blankI=i;
	      blankJ=j;
	    }
	}
    }
  if(h==0&&curCost<curMinCost)
    {
      curMinCost=curCost;
      return;
