#define tate 4
#define yoko 4
#define Total (tate*yoko)

extern inline void down_0(void);
extern inline void up_0(void);
extern inline void right_0(void);
extern inline void left_0(void);

extern int  serch(int x, int y, int MaxCnt, int pre);
extern int  check(void);

int cnt,num = 0;
int val[Total] ={};


int main( void )
{
    int i = 0;
    int x,y = 0;

    for(i=0; i<Total; i++)
    {
        scanf("%d",&val[i]);

        if(val[i] == 0)
        {
            num = i;
        }
    }

    x = tate - (num/yoko) -1;
    y = yoko - (num%yoko) -1;

//    printf("%d,%d\n",x,y);

    for(i=0; i<45; i++)
    {
        if( serch(x,y,i,4) == 1 )
        {
            printf("%d\n",i);
            break;
        }
    }     

    return 0;
}

int serch(int x, int y, int MaxCnt, int pre)
{
    int result;
    int i=0;

    // 最大数で打ち切り
    if(MaxCnt==0)
    {
        return check();
    }

    for(i=0; i<4; i++)
    {
        result = 0;

        switch(i)
        {
            case 0:
                if( (x > 0) && (pre != 3) )
                {
                    down_0();

                    result = serch(x-1, y, MaxCnt-1, 0);

                    up_0();
                }
                break;
            case 1:
                if( (y > 0) && (pre != 2) )
                {
                    right_0();

                    result = serch(x, y-1, MaxCnt-1, 1);

                    left_0();
                }
                break;
            case 2:
                if( (y < yoko -1 ) && (pre != 1) )
                {
                    left_0();

                    result = serch(x, y+1, MaxCnt-1, 2);

                    right_0();
                }
                break;
            case 3:
                if( (x < tate -1 ) && (pre != 0) )
                {
                    up_0();

                    result = serch(x+1, y, MaxCnt-1, 3);

                    down_0();
                }
                break;
            default:
                break;
        }

        if(result)
        {
            return 1;
        }

    }

    return 0;
}

