#define F 0

int dx[4]={0,-1,0,1};
int dy[4]={1,0,-1,0};
int lim;
int t[n][n];

void swap(int *x,int *y){
  int tp=*x;

  *x=*y;
  *y=tp;

  return ;
}

int getH(){
  int i,j,sum=0,x;

  for(i=0;i<n;i++){
    for(j=0;j<n;j++){
      if(t[i][j]==0)continue;
      x=t[i][j]-1;
      sum+=abs(x/4-i)+abs(x%4-j);
    }
  }

  return sum;
}

int dfs(int d,int pr,int py,int px){
  int h=getH();

  if(h==0)return T;
  if(d+h>lim)return F;
  int i;

  for(i=0;i<4;i++){

    if(abs(i-pr)==2)continue;
    int tx=px+dx[i],ty=py+dy[i];
    if(tx<0||ty<0||tx>=n||ty>=n)continue;
    swap(&t[ty][tx],&t[py][px]);
    if(dfs(d+1,i,ty,tx))return T;
    swap(&t[ty][tx],&t[py][px]);
  }

  return F;
}

