  for( i=0 ; i<4 ; i++ ){
    tx=sx+dx[i];
    ty=sy+dy[i];

    if( tx<0||tx>=N1||ty<0||ty>=N1) 
        continue;

    if( p>i ){
        max=p;min=i;
        }
    else {
        max=i;min=p;
        }

    if( max-min==2 )
        continue;

    tmp=st;

    st.m-=MDT[tx*N1+ty][st.a[tx*N1+ty]-1];
    st.m+=MDT[sx*N1+sy][st.a[tx*N1+ty]-1];


