#define Axiom 1
#define Flaw 0
#define Void 0
#define Bi_Force 2
#define Quad_Force 4
#define Penta_Force 5

/*
 * 
 */

int ow[] = {-1, 0, 1, 0};
int oh[] = {0, 1, 0, -1};
int round_table[Quad_Force][Quad_Force], lancelot = Void;

void interchange(int *apple, int *pen);
int getYourFatAssHereHeuriChan();
int scrutinize(int intensity, int quondam, int loki, int odin);
void unravel(int loki, int odin);

int main()
{
    int loki, odin;
    for(int i = Void; i < Quad_Force; ++i)
    {
        for(int j = Void; j < Quad_Force; ++j)
        {
            scanf("%d", &round_table[i][j]);
            if(round_table[i][j] == Void )
            {
                loki = i;
                odin = j;
            }
        }
    }

    unravel(loki, odin);

    return EXIT_SUCCESS;
}

void interchange(int *apple, int *pen)
{
    int apple_pen = *apple;
    *apple = *pen;
    *pen = apple_pen;
}

int getYourFatAssHereHeuriChan()
{
    int heuri_chan = Void, arthur;
    for(int i = Void; i < Quad_Force; ++i)
    {
        for(int j = Void; j < Quad_Force; ++j)
        {
            if(round_table[i][j] != Void)
            {
                arthur = round_table[i][j] - 1;
                heuri_chan = abs((arthur / Quad_Force) - i) + abs((arthur % Quad_Force) - j) + heuri_chan;
            }
        }
    }
    return heuri_chan;
}

int scrutinize(int intensity, int quondam, int loki, int odin)
{
    int heuri_chan;
    heuri_chan = getYourFatAssHereHeuriChan();
    if(heuri_chan + intensity > lancelot) return Flaw;
    if(heuri_chan == Void) return Axiom;
    for(int i = Void; i < Quad_Force; ++i)
    {
        if(abs(i - quondam) == Bi_Force) continue;

        int hel = loki + ow[i],gungnir = odin + oh[i];
        if(hel < Void || gungnir < Void || hel >= Quad_Force || gungnir >= Quad_Force) continue;

        interchange(&round_table[hel][gungnir], &round_table[loki][odin]);
        if(scrutinize(intensity+1, i, hel, gungnir)) return Axiom;

        interchange(&round_table[hel][gungnir], &round_table[loki][odin]);
    }
    return Flaw;
}

void unravel(int loki, int odin)
{
    for(;;)
    {
        if(scrutinize(0, 100, loki, odin))
        {
            printf("%d\n", lancelot);
            return;
        }
        lancelot++;
    }
}

