Puzzle st;

int get(Puzzle Z){
  int i,sum=0;
  for(i=0;i<S;i++){
    if(Z.f[i] == S) continue;
    sum+=MDT[i][Z.f[i]-1];
  }
  return sum;
}

int max(int a,int b){
  if(a<b) return b;
  else return a;
}
int min(int a,int b){
  if(a<b) return a;
  else return b;
}
void swap(int *a,int *b){
  int t;
  t=*a;
  *a=*b;
  *b=t;
}

char dfs(int df,int p){
  int sx,sy,tx,ty,i;
  Puzzle tmp;

  if(st.m==0)return 1;
  if(df+st.m>limit)return 0;

  sx=st.space/N;
  sy=st.space%N;

  for(i=0;i<4;i++){
    tx=sx+dx[i];
    ty=sy+dy[i];

    if(tx<0||tx>=N||ty<0||ty>=N) continue;
    if(max(p,i)-min(p,i)==2)continue;
    tmp=st;

    st.m-=MDT[tx*N+ty][st.f[tx*N+ty]-1];
    st.m+=MDT[sx*N+sy][st.f[tx*N+ty]-1];

    //printf("st.m=%d\n",st.m);

    swap(&st.f[tx*N+ty],&st.f[sx*N+sy]);

    st.space=tx*N+ty;
    if(dfs(df+1,i)){
      path[df]=i;
      return 1;
    }
    st=tmp;
  }
  return 0;
}

