	if (board[r][c] == i) {
	  if (i == 0) {
	    r_0 = r;
	    c_0 = c;
	  } else md += (int)fabs((i-1)/N - r) + (int)fabs((i-1)%N - c);
	  found = 1;
	  break;
	}
      }
      if (found == 1) break;
    }
  }

  for (i = 0; ; i += 2) {
    if ((r_0 + c_0) % 2 == 0) {
      if (md % 2 == 0) res = search(board, md, md+i, r_0, c_0);
      else res = search(board, md, md+i+1, r_0, c_0);
    } else {
      if (md % 2 == 0) res = search(board, md, md+i+1, r_0, c_0);
