int left[15];
int right[15];
int down[8];

void print(){

  for(int i = 0;i < 8;i++){
    for(int j = 0;j < 8;j++){
      if(board[i][j] == 1){
        if(row[i] != j) {
          return;
        }
      }
    }
  }
  for(int i = 0;i < 8;i++){
    for(int j = 0;j < 8;j++){
      if(row[i] == j) printf("Q");
      else printf(".");
    }
    puts(" ");
  }

}

void backtrack(int i){

  if(i == 8){
    print();
    return;
  }

  for(int j = 0;j < 8;j++){
    if(down[j] == 1 || left[i + j] == 1 || right[i - j + 7] == 1) continue;

    row[i] = j;
    left[i + j] = right[i - j + 7] = down[j] = 1;

    backtrack(i + 1);

    row[i] = down[j] = left[i + j] = right[i - j + 7] = 0;

  }

}


int main(){

  int r,c,k,i,j;

  for(i=0;i<15;i++){
        if(i<8){
            row[i] = 0;
