        right[i] = 0;

        for(j=0;j<8;j++){
            board[i][j] = 0;
        }

  }



  scanf("%d",&k);

  for(int i = 0;i < k;i++){
    scanf("%d%d",&r,&c);
    board[r][c] = 1;
  }
  backtrack(0);
}

