int MDT[N2][N2];

typedef struct p{
  int f[N2];
  int space;
  int MD;
} Puzzle;

Puzzle state;
int lim;
int path[LIMIT];

int getAllMD(Puzzle p){
  int sum=0, i;
  for( i = 0 ; i < N2 ; i++ ){
    if( p.f[i] == N2 ) continue;
    sum += MDT[i][p.f[i]-1];
  }
  return sum;
}

int isSolved(){
  int i;
  for( i = 0 ; i < N2 ; i++ ){
    if( state.f[i] != i+1 ) return 0;
  }
  return 1;
}

int dfs(int depth, int prev){
  int r;
  Puzzle tmp;
  if( state.MD == 0 ) return 1;
  if( depth + state.MD > lim ) return 0;

  int sx = state.space / N;
  int sy = state.space % N;

  for( r = 0 ; r < 4 ; r++ ){
    int tx = sx + dx[r];
    int ty = sy + dy[r];
    if( tx < 0 || ty < 0 || tx >= N || ty >= N ) continue;
    if( (fmax( prev, r ) - fmin( prev, r )) == 2 ) continue;
    tmp = state;
    state.MD -= MDT[tx * N + ty][state.f[tx * N + ty]-1];
    state.MD += MDT[sx * N + sy][state.f[tx * N + ty]-1];
    int t;
    t = state.f[tx * N + ty];
    state.f[tx * N + ty] = state.f[sx * N + sy];
    state.f[sx * N + sy] = t;
    state.space = tx * N + ty;
    if( dfs(depth+1,r) == 1 ){
      path[depth] = r;
      return 1;
    }
    state = tmp;
  }
  return 0;
}

