int search(int board[N][N], int min, int limit, int r_0, int c_0, char mv)
{
  int md_c[4];
  int op[4], num[4];
  int res[4];
  int i;
  char dir[5] = "nswe";

  if (min == 0) return 0;

  for (i = 0; i < 4; i++) {
    md_c[i] = min;
    res[i] = -1;
  }
  op[0] = r_0-1;
  op[1] = r_0+1;
  op[2] = c_0-1;
  op[3] = c_0+1;

  if (op[0] >= 0) {
    if (mv != 's') {
      num[0] = board[op[0]][c_0];
      md_c[0] -= (int)fabs((num[0]-1)/N - op[0]);
      md_c[0] += (int)fabs((num[0]-1)/N - r_0);
    }
  }
  if (op[1] <= N-1) {
    if (mv != 'n') {
      num[1] = board[op[1]][c_0];
      md_c[1] -= (int)fabs((num[1]-1)/N - op[1]);
      md_c[1] += (int)fabs((num[1]-1)/N - r_0);
    }
  }
  if (op[2] >= 0) {
    if (mv != 'e') {
      num[2] = board[r_0][op[2]];
      md_c[2] -= (int)fabs((num[2]-1)%N - op[2]);
      md_c[2] += (int)fabs((num[2]-1)%N - c_0);
    }
  }
  if (op[3] <= N-1) {
    if (mv != 'w') {
      num[3] = board[r_0][op[3]];
      md_c[3] -= (int)fabs((num[3]-1)%N - op[3]);
      md_c[3] += (int)fabs((num[3]-1)%N - c_0);
    }
  }

  for (i = 0; i < 4; i++) {
    if (md_c[i] - min == -1) {
      if (i / 2 == 0) {
	board[op[i]][c_0] = 0;
	board[r_0][c_0] = num[i];
	res[i] = search(board, md_c[i], limit-1, op[i], c_0, dir[i]);
	if (res[i] == -1) {
	  board[op[i]][c_0] = num[i];
          board[r_0][c_0] = 0;
	} else res[i]++;
      } else {
	board[r_0][op[i]] = 0;
	board[r_0][c_0] = num[i];
	res[i] = search(board, md_c[i], limit-1, r_0, op[i], dir[i]);
	if (res[i] == -1) {
          board[r_0][op[i]] = num[i];
          board[r_0][c_0] = 0;
        } else res[i]++;
      }
    }

    if (res[i] != -1) break;
  }

  for (i = 0; i < 4; i++) {
    if (md_c[i] - min == 1) {
      if (md_c[i] <= limit - 1) {
	if (i / 2 == 0) {
	  board[op[i]][c_0] = 0;
	  board[r_0][c_0] = num[i];
	  res[i] = search(board, md_c[i], limit-1, op[i], c_0, dir[i]);
	  if (res[i] == -1) {
	    board[op[i]][c_0] = num[i];
	    board[r_0][c_0] = 0;
	  } else res[i]++;
	} else {
	  board[r_0][op[i]] = 0;
	  board[r_0][c_0] = num[i];
	  res[i] = search(board, md_c[i], limit-1, r_0, op[i], dir[i]);
	  if (res[i] == -1) {
	    board[r_0][op[i]] = num[i];
	    board[r_0][c_0] = 0;
	  } else res[i]++;
	}
      } else res[i] = -1;
    }
  }

  if (res[0] == -1 && res[1] == -1 && res[2] == -1 && res[3] == -1) return -1;
  else if (res[0] != -1) return res[0];
  else if (res[1] != -1) return res[1];
  else if (res[2] != -1) return res[2];
  else return res[3];
}

#include <stdio.h>
#include <math.h>
#include <stdbool.h>
#include <string.h>
#define N 4
#define N2 16
#define LIMIT 100

int dx[4] = {0, -1, 0, 1};
int dy[4] = {1, 0, -1, 0};
char dir[4] = {'r', 'u', 'l', 'd'};
int MDT[N2][N2];

typedef struct
{
    int f[N2];
    int space;
    int MD;
} puzzle;

puzzle state;
int limit;
int path[LIMIT];

void swap(int *a, int *b)
{
    int tmp;
    tmp = *a;
    *a = *b;
    *b = tmp;
}
int getALLMD(puzzle pz)
{
    int sum = 0;
    for (int i = 0; i < N2; i++)
    {
        if (pz.f[i] == N2)
            continue;
        sum += MDT[i][pz.f[i] - 1];
    }
    return sum;
}

bool isSolved()
{
    for (int i = 0; i < N2; i++)
    {
        if (state.f[i] != i + 1)
            return false;
        return true;
    }
}

bool dfs(int depth, int prev)
{
    if (!state.MD)
        return true;
    if (depth + state.MD > limit)
        return false;

    int sx = state.space / N;
    int sy = state.space % N;
    puzzle tmp;

    for (int r = 0; r < 4; r++)
    {
        int tx = sx + dx[r];
        int ty = sy + dy[r];
        if (tx < 0 || ty < 0 || tx >= N || ty >= N)
            continue;
        if (fmax(prev, r) - fmin(prev, r) == 2)
            continue;
        tmp = state;
        state.MD -= MDT[tx * N + ty][state.f[tx * N + ty] - 1];
        state.MD += MDT[sx * N + sy][state.f[tx * N + ty] - 1];
        swap(&state.f[tx * N + ty], &state.f[sx * N + sy]);
        state.space = tx * N + ty;
        if (dfs(depth + 1, r))
        {
            path[depth] = r;
            return true;
        }
        state = tmp;
    }
    return false;
}

int deepening(puzzle in)
{
    in.MD = getALLMD(in);

    for (limit = in.MD; limit <= LIMIT; limit++)
    {
        state = in;
        if (dfs(0, -100))
        {
            char a[LIMIT] = {};
            for (int i = 0; i < limit; i++)
                a[i] += dir[path[i]];
            return strlen(a);
        }
    }

    return false;
}

int main()
{
    for (int i = 0; i < N2; i++)
        for (int j = 0; j < N2; j++)
            MDT[i][j] = fabs(i / N - j / N) + fabs(i % N - j % N);

    puzzle in;
    for (int i = 0; i < N2; i++)
    {
        scanf("%d", &in.f[i]);
        if (!in.f[i])
        {
            in.f[i] = N2;
            in.space = i;
        }
    }
    printf("%d\n", deepening(in));
    if (!isSolved())
        printf("failed\n");
    return 0;
}

