  for (i = 0; i < N * N; i++) {
    found = 0;
    for (r = 0; r < N; r++) {
      for (c = 0; c < N; c++) {
    if (board[r][c] == i) {
      if (i == 0) {
        r_0 = r;
        c_0 = c;
      } else md += (int)fabs((i-1)/N - r) + (int)fabs((i-1)%N - c);
      found = 1;
      break;
    }
      }
      if (found == 1) break;
    }
  }

  for (i = 0; ; i += 2) {
    if ((r_0 + c_0) % 2 == 0) {
      if (md % 2 == 0) res = search(board, md, md+i, r_0, c_0, 'c');
      else res = search(board, md, md+i+1, r_0, c_0, 'c');
    } else {
      if (md % 2 == 0) res = search(board, md, md+i+1, r_0, c_0, 'c');
      else res = search(board, md, md+i, r_0, c_0, 'c');
    }

    if (res != -1) break;
  }

  printf("%d\n", res);

  return 0;
}

int search(int board[N][N], int min, int limit, int r_0, int c_0, char mv)
{
  int md_c[4];
  int op[4], num[4];
  int res[4];
  int i;
  char dir[5] = "nswe";

  if (min == 0) return 0;

  for (i = 0; i < 4; i++) {
    md_c[i] = min;
    res[i] = -1;
  }
  op[0] = r_0-1;
  op[1] = r_0+1;
  op[2] = c_0-1;
  op[3] = c_0+1;

  if (op[0] >= 0) {
    if (mv != 's') {
      num[0] = board[op[0]][c_0];
      md_c[0] -= (int)fabs((num[0]-1)/N - op[0]);
      md_c[0] += (int)fabs((num[0]-1)/N - r_0);
    }
  }
  if (op[1] <= N-1) {
    if (mv != 'n') {
      num[1] = board[op[1]][c_0];
      md_c[1] -= (int)fabs((num[1]-1)/N - op[1]);
      md_c[1] += (int)fabs((num[1]-1)/N - r_0);
    }
  }
  if (op[2] >= 0) {
    if (mv != 'e') {
      num[2] = board[r_0][op[2]];
      md_c[2] -= (int)fabs((num[2]-1)%N - op[2]);
      md_c[2] += (int)fabs((num[2]-1)%N - c_0);
    }
  }
  if (op[3] <= N-1) {
    if (mv != 'w') {
      num[3] = board[r_0][op[3]];
      md_c[3] -= (int)fabs((num[3]-1)%N - op[3]);
      md_c[3] += (int)fabs((num[3]-1)%N - c_0);
    }
  }

  for (i = 0; i < 4; i++) {
    if (md_c[i] - min == -1) {
      if (i / 2 == 0) {
    board[op[i]][c_0] = 0;
    board[r_0][c_0] = num[i];
    res[i] = search(board, md_c[i], limit-1, op[i], c_0, dir[i]);
    if (res[i] == -1) {
      board[op[i]][c_0] = num[i];
          board[r_0][c_0] = 0;
    } else res[i]++;
      } else {
    board[r_0][op[i]] = 0;
    board[r_0][c_0] = num[i];
    res[i] = search(board, md_c[i], limit-1, r_0, op[i], dir[i]);
    if (res[i] == -1) {
          board[r_0][op[i]] = num[i];
          board[r_0][c_0] = 0;
        } else res[i]++;
      }
    }

    if (res[i] != -1) break;
  }

  for (i = 0; i < 4; i++) {
    if (md_c[i] - min == 1) {
      if (md_c[i] <= limit - 1) {
    if (i / 2 == 0) {
      board[op[i]][c_0] = 0;
      board[r_0][c_0] = num[i];
      res[i] = search(board, md_c[i], limit-1, op[i], c_0, dir[i]);
      if (res[i] == -1) {
        board[op[i]][c_0] = num[i];
        board[r_0][c_0] = 0;
      } else res[i]++;
    } else {
      board[r_0][op[i]] = 0;
      board[r_0][c_0] = num[i];
      res[i] = search(board, md_c[i], limit-1, r_0, op[i], dir[i]);
      if (res[i] == -1) {
        board[r_0][op[i]] = num[i];
        board[r_0][c_0] = 0;
      } else res[i]++;
    }
      } else res[i] = -1;
    }
  }

  if (res[0] == -1 && res[1] == -1 && res[2] == -1 && res[3] == -1) return -1;
  else if (res[0] != -1) return res[0];
  else if (res[1] != -1) return res[1];
  else if (res[2] != -1) return res[2];
  else return res[3];
}

#include <stdio.h>
#include <stdlib.h>

#define tate 4
#define yoko 4
#define Total (tate*yoko)
#define TryCnt 45

extern inline void down_0(void);    // 0 を下に移動
extern inline void up_0(void);      // 0 を上に移動
extern inline void right_0(void);   // 0 を右に移動
extern inline void left_0(void);    // 0 を左に移動

extern int  serch(int x, int y, int MaxCnt, int pre);

int num = 0;        // 0 の位置を示す
int val[Total] ={}; // 数値配列


int main( void )
{
    int i = 0;
    int x,y = 0;

    // 文字列の取り込み
    for(i=0; i<Total; i++)
    {
        scanf("%d",&val[i]);

        if(val[i] == 0)
        {
            num = i;
        }
    }

    // 右下に行くために 0 を何回動かせばいいか。
    x = tate - (num/yoko) -1;
    y = yoko - (num%yoko) -1;

    for(i=0; i<TryCnt; i++)
    {
        if( serch(x,y,i,4) == 1 )
        {
            printf("%d\n",i);
            break;
        }
    }     

    return 0;
}

int serch(int x, int y, int MaxCnt, int pre)
{
    int result;
    int i=0;

    if(MaxCnt < (x + y) )
    {
        return 0;
    }

    // 最大数でゴールと一致しているか確認
    if(MaxCnt==0)
    {
        for(i=0; i<Total-1; i++)
        {
            if(val[i] != (i+1))
            {
                // ゴールと不一致
                return 0;
            }
        }
        // ゴールと一致！！
        return 1;
    }


    // 0 の移動
    for(i=0; i<4; i++)
    {
        result = 0;

        switch(i)
        {
            case 0:
                if( (x > 0) && (pre != 3) )
                {
                    down_0();

                    result = serch(x-1, y, MaxCnt-1, 0);

                    up_0();
                }
                break;

            case 1:
                if( (y > 0) && (pre != 2) )
                {
                    right_0();

                    result = serch(x, y-1, MaxCnt-1, 1);

                    left_0();
                }
                break;

            case 2:
                if( (y < yoko -1 ) && (pre != 1) )
                {
                    left_0();

                    result = serch(x, y+1, MaxCnt-1, 2);

                    right_0();
                }
                break;

            case 3:
                if( (x < tate -1 ) && (pre != 0) )
                {
                    up_0();

                    result = serch(x+1, y, MaxCnt-1, 3);

                    down_0();
                }
                break;

            default:
                // 何もしない。
                break;
        }

        if(result)
        {
            return 1;
        }
    }

    return 0;
}


inline void down_0()
{
    val[num] = val[num + yoko];
    num = num + yoko;
}

inline void up_0()
{
    val[num] = val[num - yoko];
    num = num - yoko;
}

inline void right_0()
{
    val[num] = val[num +1];
    num = num + 1;
}

inline void left_0()
{
    val[num] = val[num -1];
    num = num - 1;
}

