int getAllMD(Puzzle pz){
	int sum = 0,i;
	for(i=0;i<N2;i++){
		if(pz.f[i]==N2)continue;
		sum+=MDT[i][pz.f[i]-1];
	}
	return sum;
}

int isSolved(){
	int i;
	for(i=0;i<N2;i++){
		if(state.f[i]!=i+1)return 0;
	}
	return 1;
}

int dfs(int depth,int prev){
	int r,sx,sy,tx,ty,max,min;
	if(state.MD ==0)return 1;
	if(depth+state.MD>limit)return 0;
	sx=state.space/N;
	sy=state.space%N;
	Puzzle tmp;
	for(r=0;r<4;r++){
		tx=sx+dx[r];
		ty=sy+dy[r];
		if(tx<0 || ty<0 || tx>=N || ty>=N)continue;
		if(prev>r)max=prev;
		else max=r;
		if(prev<r)min=prev;
		else min=r;
		if(max-min==2)continue;
		tmp=state;
		state.MD-=MDT[tx*N+ty][state.f[tx*N+ty]-1];
		state.MD+=MDT[sx*N+sy][state.f[tx*N+ty]-1];
		int a;
		a=state.f[tx*N+ty];
		state.f[tx*N+ty]=state.f[sx*N+sy];
		state.f[sx*N+sy]=a;
		state.space=tx*N+ty;
		if(dfs(depth+1,r)){
			path[depth]=r;
			return 1;
		}
		state=tmp;
	}
	return 0;
}

int iterative_deepening(Puzzle in,int *ans){
	int i,n=0;
	//fprintf(stderr,"1111111111111\n");
	in.MD=getAllMD(in);
