#include<stdio.h>
#include<string.h>
#include<math.h>
#define Limit 100
#define Size 16
int mdt[Size][Size], space, score, edge;
int swap_upper(int*, int*, int);
int swap_lower(int*, int*, int);
int swap_left(int*, int*, int);
int swap_right(int*, int*, int);
int Dfs(int*, int*, int, int, int);
int main(void)
{
  int i, j, init[Size], goal[Size];
  edge = sqrt(Size);
  for (i = 0; i < Size; i++) {
    for (j = 0; j < Size; j++) {
      mdt[i][j] = fabs(i / edge - j / edge) + fabs(i % edge - j % edge);
    }
  }
  for (i = 0; i < Size; i++) {
    scanf("%d", &init[i]);
    if (!init[i]) space = i;
    else score += mdt[i][init[i]-1];
    goal[i] = (i + 1) % Size;
  }
  for (i = score; i < Limit; i++) {
    if (Dfs(init, goal, 0, -1, i)) {
      printf("%d\n", i);
      break;
    }
  }
}
int swap_upper(int *board, int *next, int prev)
{
  int i;
  if (!(space / edge) || prev == 1) return 0;
  else {
    memcpy(next, board, sizeof(int) * Size);
    next[space] = board[space - edge];
    next[space - edge] = board[space];
    score += mdt[space][next[space] - 1] - mdt[space - edge][next[space] - 1];
    space -= edge;
  }
  return 1;
}
int swap_lower(int *board, int *next, int prev)
{
  int i;
  if ((space / edge) == edge - 1 || prev == 0) return 0;
  else {
    memcpy(next, board, sizeof(int) * Size);
    next[space] = board[space + edge];
    next[space + edge] = board[space];
    score +=  mdt[space][next[space] - 1] - mdt[space + edge][next[space] - 1];
    space += edge;
  }
  return 1;
}
int swap_left(int *board, int *next, int prev)
{
  int i;
  if (!(space % edge) || prev == 3) return 0;
  else {
    memcpy(next, board, sizeof(int) * Size);
    next[space] = board[space - 1];
    next[space - 1] = board[space];
    score +=  mdt[space][next[space] - 1] - mdt[space - 1][next[space] - 1];
    space--;
  }
  return 1;
}
int swap_right(int *board, int *next, int prev)
{
  int i;
  if ((space % edge) == edge - 1 || prev == 2) return 0;
  else {
    memcpy(next, board, sizeof(int) * Size);
    next[space] = board[space + 1];
    next[space + 1] = board[space];
    score +=  mdt[space][next[space] - 1] - mdt[space + 1][next[space] - 1];
    space++;
  }
  return 1;
}
int Dfs(int *board, int *goal, int depth, int prev, int limit)
{
  int next[Size], prespace = space, prescore = score;
  if (!score) return 1;
  else if (depth + score > limit) return 0;
  if (swap_upper(board, next, prev)) {
    if (Dfs(next, goal, depth + 1, 0, limit)) return 1;
  }
  space = prespace;
  score = prescore;
  if (swap_lower(board, next, prev)) {
    if (Dfs(next, goal, depth + 1, 1, limit)) return 1;
  }
  space = prespace;
  score = prescore;
  if (swap_left(board, next, prev)) {
    if (Dfs(next, goal, depth + 1, 2, limit)) return 1;
  }
  space = prespace;
  score = prescore;
  if (swap_right(board, next, prev)) {
    if (Dfs(next, goal, depth + 1, 3, limit)) return 1;
  }
  space = prespace;
  score = prescore;
  return 0;
}

