#define N 4
#define N2 16
#define LIMIT 100

int H[N2][N2];//マンハッタン距離の組み合わせの集合
int dx[4] = {0,-1,0,1};
int dy[4] = {1,0,-1,0}; //方向

void swap(int *x,int *y){
  int tmp;
  tmp = *x;
  *x = *y;
  *y = tmp;
}

typedef struct puzzle
{
  int f[N2];//どの場所になんの数字が入っているか
  int space;//空マス
  int MD;//マンハッタン距離
}Puzzle;

Puzzle state;//現在の状態
int limit;//深さの制限
int path[LIMIT];

int getAllMD(Puzzle pz){
  int sum = 0;
  int i;
  for(i=0; i<N2; i++){
    if(pz.f[i] == N2)continue; //正しい位置にあればそのまま
    sum += H[i][pz.f[i] - 1];//マンハッタン距離を加える
  }
  return sum;
}

int isSolved(){
  int i;
  for (int i = 0; i < N2; ++i)if(state.f[i] != i+1)return 0;
    return 1;
}

int dfs(int depth, int prev){
  if(state.MD == 0)return 1; //終了
  if(depth + state.MD > limit)return 0;

  int sx = state.space / N; //空のマスのx座標;
  int sy = state.space % N; //空のマスのy座標;

  Puzzle tmp;
  int r;
  for(r = 0;r < 4;r++){
    int tx = sx + dx[r]; //空のマスの次の位置
    int ty = sy + dy[r];
    if(tx < 0|| ty <0||tx >= N||ty >= N)continue; //行けないマスはスルー
    if(abs(prev - r) == 2)continue;//一個前の状態に戻る操作はスルー
    state.MD += (H[sx*N+sy][state.f[tx*N+ty]-1] - H[tx*N+ty][state.f[tx*N+ty]-1]);//入れ替わった分のマンハッタンん距離の増減を加算
    swap(&state.f[tx*N+ty],&state.f[sx*N+sy]);
    state.space = tx*N+ty;
    if(dfs(depth+1,r)){path[depth] = r; return 1;}
    state = tmp;
  }
  return 0;
}

int iterative_deepening(Puzzle in){
  in.MD = getAllMD(in);

  for(limit = in.MD;limit <= LIMIT; limit++){//limit = c
    state = in;
    if(dfs(0,-100)){
      //pathに入っている文字数を数えたい
      int count = 0,l;
      for(l=0;l<limit;l++){
        if(path[l] != '\0')count++;
      }
      return count;

    }
  }
  return -1;
}

int main(void){
  int i,j;
  for(i=0;i<N2;i++){
    for(j=0;j<N2;j++){
      H[i][j] = abs(i/N - j/N) + abs(i%N -j%N);//マンハッタン距離の組み合わせの初期化
    }
  }

  Puzzle in;//初期のパズル

  for(i=0;i<N2;i++){
    scanf("%d", &in.f[i]);
    if(in.f[i]==0){
      in.f[i] = N2;
      in.space = i;
    }
  }

  int ans = iterative_deepening(in);
  printf("ans\n");
  return 0;

}

