#define get(a, i) (int)(((ull)(a) >> ((int)(i) * 4)) & 15)
#define set(a, i, v) (((ull)(a) & ~(15ull << ((int)(i) * 4))) | ((ull)(v) << ((int)(i) * 4)))

ull swap(ull a, int l, int r) {
	int lv = get(a, l);
	int rv = get(a, r);

	return set(set(a, l, rv), r, lv);
}


#define checkFinished(p) (p == 18364758544493064720ull)

int check(Puzzle p) {
	int i;
	for (i = 0; i < 16; ++i) {
		if (get(p, i) == 15)
			break;
	}

	int j, k, cnt = 0;
	Puzzle cp = p;
	for (j = 0; j < 16; ++j) {
		if (get(cp, j) == j)
			continue;

		for (k = j + 1; k < 16; ++k) {
			if (get(cp, k) != j)
				continue;

			cp = swap(cp, j, k);

			++cnt;

			break;
		}
	}

	return (cnt & 1) == (((i % 4 - 3) + (i / 4 - 3)) & 1);
}

int md(Puzzle p) {
	int i, cnt = 0;
	for (i = 0; i < 16; ++i) {
        if(get(p, i) == 15)
            continue;
		cnt += abs(get(p, i) / 4 - i / 4) + abs(get(p, i) % 4 - i % 4);
	}

	return cnt;
}

int id(Puzzle p) {
	int i, j, cnt = 0;
	for (i = 0; i < 16; ++i) {
		for (j = i + 1; j < 16; ++j) {
			if (get(p, i) > get(p, j))
				++cnt;
		}
	}

	return cnt / 3 + cnt % 3;
}

ull hash(int* p) {
	ull h = 0;
	int i;
	for (i = 0; i < 16; ++i) {
		h |= (ull)(p[i]) << (i * 4);
	}

	return h;
}

typedef struct {
	Puzzle p;
	int counter;
	int md;
	int prev;
} Node;
int last = 0;
Node heap[30000000];

void insert_heap(Node value) {
    int i = last++;

    while(i > 0) {
        int p = (i - 1) / 2;

        if(heap[p].md <= value.md)
            break;

        heap[i] = heap[p];
        i = p;
    }

    heap[i] = value;
}

void delete_heap() {
    Node x = heap[--last];

    int i = 0;
    while(i * 2 + 1 < last) {
        int a = i * 2 + 1, b = i * 2 + 2;

        if(b < last && heap[b].md < heap[a].md)
            a = b;

        if(heap[a].md >= x.md)
            break;

        heap[i] = heap[a];
        i = a;
    }
    heap[i] = x;
}


