typedef unsigned long long ull;

#define GOAL 0x123456789ABCDEF0LL
#define ABS(a) ((a)>=0?(a):-(a))

typedef struct {
	ull s;		// パズルの状態。4bitで数字１つに対応。計64bit
	char x;		// 0の位置（0-origin）
	char v;		// ステップ数
} TBL; TBL tbl[500000]; int sz;

int hi[16] = {2,3,3,2,3,4,4,3,3,4,4,3,2,3,3,2};
int to[16][4] = {
{1,4},{0,2,5},{1,3,6},{2,7},
