int dy[4]={1,0,-1,0};

int count;

int A[N][N];

int abs(int a){
  if(a > 0) return a;
  else return a*-1;
}

void swap(int *x,int *y){
  int tmp=*x;
  *x=*y;
  *y=tmp;
  return ;
}

int Heuristic(){
  int i,j,sum = 0,x;
  for(i = 0;i < N;i++){
    for(j = 0;j < N;j++){
    if(A[i][j]==0)continue;
    x = A[i][j] - 1;
    sum+=abs(x/N - i)+abs(x%N - j);
    }
  }
  return sum;
}

int move(int d,int pre,int s,int t){
  int i,x,y,h = Heuristic();
  if(h==0)return 1;
  if(d+h > count)return 0;
  for(i=0;i<4;i++){
    if(abs(i - pre)==2)continue;/*return move*/

    x = s + dy[i];
    y = t + dx[i];

    if(x<0||y<0||x>=N||y>=N)continue;/*frame over*/

    swap(&A[x][y],&A[s][t]);
    if(move(d+1,i,x,y))return 1;
    swap(&A[x][y],&A[s][t]);/*return move because next move's starat is same this one */
  }
  return 0;
}

void counter(int s,int t){
  count = 0;
  while(1){
    if(move(0,10,s,t)){
      printf("%d\n",count);
      return ;
    }
    count++;
  }
}

int main(){
  int i,j,s,t;
  for(i = 0;i < N;i++){
    for(j = 0;j < N;j++){
      scanf("%d",&A[i][j]);
      if(A[i][j] == 0){
        s = i;
        t = j;
      }
    }
  }
  counter(s,t);
  return 0;
}

