	} else res[i]++;
      } else {
	board[r_0][op[i]] = 0;
	board[r_0][c_0] = num[i];
	res[i] = search(board, md_c[i], limit-1, r_0, op[i], dir[i]);
	if (res[i] == -1) {
	  board[r_0][op[i]] = num[i];
	  board[r_0][c_0] = 0;
	} else res[i]++;
      }
    }

    if (res[i] != -1) break;
  }

  for (i = 0; i < 4; i++) {
    if (md_c[i] - min == 1) {
      if (md_c[i] <= limit - 1) {
	if (i / 2 == 0) {
	  board[op[i]][c_0] = 0;
	  board[r_0][c_0] = num[i];
