void empty(int *x,int *y)
{
    int p,q;
    for(p = 0;p < 4; p++)
      {
        for(q = 0; q < 4; q++)
      {
            if(!pz[p][q])
          {
                *x = q;
                *y = p;
                return;
          }
      }
      }
}

void swap(int *m,int *n)
{
    int sw;
    sw = *m;
    *m = *n;
    *n = sw;
}


int cal()
{
    int i,s,sum=0;
    for(i = 0; i < 16; i++)
      {
        s = pz[i/4][i%4];
        if(s)
      {
            s--;
            sum += abs(i/4 - s/4) + abs(i%4 - s%4);
      }
      }
    return sum;
}


int dfs(int x,int y,int p,int dep,int lim)
{
    int i,h,fx,fy,res;

    h = cal();
    if(h==0) return dep;
    if(dep+h>lim) return -1;

    for(i=0; i<4; i++)
      {
        fx = x+dx[i];
        fy = y+dy[i];

        if((~p && i == (p+2) % 4) || (!(0 <= fx && fx < 4 && 0 <= fy && fy < 4))) continue;

        swap(&pz[y][x],&pz[fy][fx]);
        res = dfs(fx,fy,i,dep+1,lim);
        if(~res) return res;

        swap(&pz[y][x],&pz[fy][fx]);
      }

    return -1;
}

