// I/O
int get_uint() {
    int n = 0;
    int c = getchar_unlocked();
    if(c < 48 || 57 < c) return c;
    while(47 < c && c < 58) n = 10 * n + (c & 0xf), c = getchar_unlocked();
    return n;
}
void put_uint(int n) {
    if(!n) {
        putchar_unlocked('0');
        return;
    }
    char buf[11];
    int i = 0;
    while(n) buf[i++] = (char)(n % 10 + '0'), n /= 10;
    while(i--)putchar_unlocked(buf[i]);
}


// Node
typedef struct NodeKey {
    int board[16];
    int space;
    // heuristic: manhattan distance
    int est;
} NodeKey;


// solve
int dfs(const int lim, const int depth, const int prev, const NodeKey *node, const int M, const int L1[][16]) {
    if(node->est == 0) return 1;
    if(depth + node->est > lim) return 0;

    static const int dx[] = {-1, 0, 1, 0};
    static const int dy[] = {0, -1, 0, 1};
    const int x = node->space % M;
    const int y = node->space / M;

    for(int i = 0; i < 4; ++i) {
        const int nx = x + dx[i];
        const int ny = y + dy[i];
        if(nx < 0 || M <= nx || ny < 0 || M <= ny) continue;
        if(abs(prev - i) == 2) continue;

        const int next_space = nx + ny * M;
        NodeKey next_node = *node;
        next_node.est -= L1[next_space][next_node.board[next_space] - 1];
        next_node.est += L1[next_node.space][next_node.board[next_space] - 1];
        next_node.board[next_node.space] = next_node.board[next_space];
        next_node.board[next_space] = 0;
        next_node.space = next_space;
        if(dfs(lim, depth + 1, i, &next_node, M, L1)) return 1;
    }
    return 0;
}

int interative_deepening(NodeKey *node) {
    const int N = 16;
    const int M = 4;
    int L1[N][N];
    for(int i = 0; i < N; ++i)
        for(int j = 0; j < N; ++j) L1[i][j] = abs(i % M - j % M) + abs(i / M - j / M);

    int min = 0;
    for(int i = 0; i < N; ++i)
        if(i != node->space) min += L1[i][node->board[i] - 1];
    node->est = min;
    for(const int lim = 46; min < lim; ++min)
        if(dfs(min, 0, 9, node, M, L1)) return min;
    return -1;
}

int main(int argc, char **argv) {
    NodeKey initial;
    for(int i = 0; i < 16; ++i) {
        int x = get_uint();
        initial.board[i] = x;
        if(x == 0) initial.space = i;
    }
    put_uint(interative_deepening(&initial));
    putchar_unlocked('\n');
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define N 4
#define N2 16
#define LIMIT 100

int H[N2][N2];//マンハッタン距離の組み合わせの集合
int dx[4] = {0,-1,0,1};
int dy[4] = {1,0,-1,0}; //方向

void swap(int *x,int *y){
  int tmp;
  tmp = *x;
  *x = *y;
  *y = tmp;
}

typedef struct puzzle
{
  int f[N2];//どの場所になんの数字が入っているか
  int space;//空マス
  int MD;//マンハッタン距離
}Puzzle;

Puzzle state;//現在の状態
int limit;//深さの制限
int path[LIMIT];

int getAllMD(Puzzle pz){
  int sum = 0;
  int i;
  for(i=0; i<N2; i++){
    if(pz.f[i] == N2)continue; //正しい位置にあればそのまま
    sum += H[i][pz.f[i] - 1];//マンハッタン距離を加える
  }
  printf("getALLMD\n");
  return sum;
}

int isSolved(){
  int i;
  for (int i = 0; i < N2; ++i)if(state.f[i] != i+1)return 0;
  return 1;
}

int dfs(int depth, int prev){
  printf("dfs start\n");
  if(state.MD == 0)return 1; //終了
  if(depth + state.MD > limit)return 0;

  int sx = state.space / N; //空のマスのx座標;
  int sy = state.space % N; //空のマスのy座標;

  Puzzle tmp;
  int r;
  for(r = 0;r < 4;r++){
    int tx = sx + dx[r]; //空のマスの次の位置
    int ty = sy + dy[r];
    if(tx < 0|| ty <0||tx >= N||ty >= N)continue; //行けないマスはスルー
    if((prev - r == 2)||(prev - r == -2))continue;//一個前の状態に戻る操作はスルー
    tmp = state;
    state.MD -= H[tx * N + ty][state.f[tx * N + ty]-1];//入れ替わった分のマンハッタンん距離の増減を加算
    state.MD += H[sx * N + sy][state.f[tx * N + ty]-1];
    swap(&state.f[tx * N + ty],&state.f[sx * N + sy]);
    state.space = tx * N + ty;
    if(dfs(depth+1,r) != 0){path[depth] = r; return 1;}
    state = tmp;
  }
  return 0;
}

int iterative_deepening(Puzzle in){
  in.MD = getAllMD(in);

  for(limit = in.MD;limit <= LIMIT; limit++){//limit = c
    state = in;
    if(dfs(0,-100) != 0){
      //pathに入っている文字数を数えたい
      int count = 0,l;
      for(l=0;l<limit;l++){
        if(path[l] != '\0')count++;
      }
      printf("return count\n");
      return count;

    }
  }
  return -1;
}

