int dfs(int x,int y,int p, int dep, int lim){
	int i,j,h,n1,n2,res;
	int cp;

	h = cal();

	if(h == 0)return dep;
	if(dep + h > lim) return -1;

	for(i = 0; i< 4; i++){
		n1 = x + dx[i];
		n2 = y + dy[i];

		if(~p && i == (p+2)%4) continue;
		if(!(0 <= n1 && n1 < 4 && 0 <= n2 && n2 < 4)) continue;

		cp = Puzzle[y][x];
		Puzzle[y][x] = Puzzle[n2][n1];
		Puzzle[n2][n1] = cp;

		res = dfs(n1,n2,i,dep+1,lim);
		if(~res)return res;

		cp = Puzzle[y][x];
		Puzzle[y][x] = Puzzle[n2][n1];
		Puzzle[n2][n1] = cp;

	}
	return -1;
}

void empty(int *x,int *y){
	int i,j;
	for(i = 0; i < N ; i++){
		for(j = 0 ; j < N ; j++){
			if(!Puzzle[i][j]){
				*x = j;
				*y = i;
				return;
			}
		}
	}
}

int cal(void){
	int i,a;
	int sum = 0;

	for(i = 0; i< N+12 ; i++){
		a = Puzzle[i/N][i%N];
		if(a){
			a--;
			sum += abs(i/N - a/N)  + abs(i%N - a%N);
		}
	}
	return sum;
}

