int huri(){

  int x,y ,i,j,sum=0;

  for(i=0;i<N;i++){
    for(j=0;j<N;j++){
      if(puzz[i][j] == 0)continue;

      x=(puzz[i][j]-1)%N-j;
      y=(puzz[i][j]-1)/N-i;
      x=abs(x);
      y=abs(y);

      sum+=x;
      sum+=y;
    }
  }
  return sum;
}

int DFS(int iof0,int jof0,int lim,int dpt,int n){

  int i,j,h,x,y,tmp,ans=-1;

  h = huri();
  if(h == 0) return dpt;
  if(h+dpt > lim) return -1;

  for(i=0;i<4;i++){
    if(abs(i-n) == 2)continue;

    x = iof0 + dx[i];
    y = jof0 + dy[i];

    if(x >= N || x < 0) continue;
    if(y >= N || y < 0) continue;

    tmp = puzz[x][y];
    puzz[x][y] = puzz[iof0][jof0];
    puzz[iof0][jof0] = tmp;

    ans = DFS(x,y,lim,dpt+1,i);

    if(ans != -1) return ans;
    tmp = puzz[x][y];
    puzz[x][y] = puzz[iof0][jof0];
    puzz[iof0][jof0] = tmp;
  }
  return -1;
}

