int Heu(Papa Q){
  int i ,j;
  int hx,hy,sum=0;
  for(i=0;i<N;i++){
    for(j=0;j<N;j++){
      if(Q.P[i][j]==0)continue;

      hx=(Q.P[i][j]-1)%N-j;
      hy=(Q.P[i][j]-1)/N-i;

      if(hx<0)sum-=hx;
      else sum+=hx;

      if(hy<0)sum-=hy;
      else sum+=hy;
    }
  }
  return sum;
}

