int pz[4][4];
int tmp[4][4];
int dx[4] = {0,1,0,-1};
int dy[4] = {1,0,-1,0};


void emp(int *x,int *y)
{
    int p,q;
    for(p = 0;p < 4; p++)
      {
        for(q = 0; q < 4; q++)
      {
            if(!pz[p][q])
          {
                *x = q;
                *y = p;
                return;
          }
      }
    }
}

void SWAP(int *m,int *n)
{

    int tmp1;
    tmp1 = *m;
    *m = *n;
    *n = tmp1;

}


int cal()
{
    int i,n,sum=0;

    for(i = 0; i < 16; i++)
      {
        n = pz[i/4][i%4];
        if(n)
      {
            n--;
            sum += abs(i/4 - n/4) + abs(i%4 - n%4);
      }
    }

    return sum;

}


int dfs(int x,int y,int p,int dep,int lim)
{
    int i,h,fx,fy,res;

    h = cal();

    if(h==0) return dep;

    if(dep+h>lim) return -1;

    for(i=0; i<4; i++)
      {
        fx = x+dx[i];
        fy = y+dy[i];

        if((~p && i == (p+2) % 4) || (!(0 <= fx && fx < 4 && 0 <= fy && fy < 4))) continue;

        SWAP(&pz[y][x],&pz[fy][fx]);

        res = dfs(fx,fy,i,dep+1,lim);

        if(~res) return res;

        SWAP(&pz[y][x],&pz[fy][fx]);

      }

    return -1;

}


int main() {

