    for(k = 0; k < 100; k++) {

        for(i = 0; i < 4; i++) {

            for(j = 0; j < 4; j++) tmp[i][j] = pz[i][j];

        }

        A = dfs(x,y,-1,0,k);

        if(A!=-1) {
            printf("%d\n",A);
            break;
        }

        for(i = 0 ; i < 4; i++) {
            for(j = 0 ; j < 4; j++) pz[i][j] = tmp[i][j];
        }
        A = -1;
        if(k == 99) printf("%d\n",A);
    }
