int get_uint()
{
  int n=0;
  int c=getchar_unlocked();

  if(c < 48 || 57 < c) return c;
  while(47 < c && c < 58) n = 10 * n + (c & 0xf), c = getchar_unlocked();
  return n;
}

void put_uint(int n)
{
  char buf[11];
  int i;

  if(!n) {
    putchar_unlocked('0');
    return;
  }
    i = 0;
    while(n) buf[i++] = (char)(n % 10 + '0'), n /= 10;
    while(i--)putchar_unlocked(buf[i]);
}


int dfs(const int lim, const int depth, const int prev, const NodeKey *node, const int M, const int L1[][16])
{
  if(node->est == 0) return 1;
  if(depth + node->est > lim) return 0;

  static const int dx[] = {-1, 0, 1, 0};
  static const int dy[] = {0, -1, 0, 1};
  const int x = node->space % M;
  const int y = node->space / M;
  NodeKey next_node;
  int i;

  for(i=0;i<4;++i) {
    const int nx = x + dx[i];
    const int ny = y + dy[i]; 
    if(nx < 0 || M <= nx || ny < 0 || M <= ny) continue;
    if(abs(prev - i) == 2) continue;

    const int next_space = nx + ny * M;
    next_node = *node;
    next_node.est -= L1[next_space][next_node.board[next_space] - 1];
    next_node.est += L1[next_node.space][next_node.board[next_space] - 1];
    next_node.board[next_node.space] = next_node.board[next_space];
    next_node.board[next_space] = 0;
    next_node.space = next_space;
    if(dfs(lim, depth + 1, i, &next_node, M, L1)) return 1;
  }
  return 0;
}

int iterative_deepening(NodeKey *node)
{
  const int N = 16;
  const int M = 4;
  int L1[N][N];
  int i,j,min=0;

  for(i=0;i<N;++i)
    for(j=0;j<N;++j) L1[i][j] = abs(i % M - j % M) + abs(i / M - j / M);

  for(i=0;i<N;++i)
    if(i != node->space) min += L1[i][node->board[i] - 1];
  node->est = min;
  for(const int lim = 46; min < lim; ++min)
    if(dfs(min, 0, 9, node, M, L1)) return min;
  return -1;
}

