int mv[4][2]={0,1,0,-1,-1,0,1,0};//上下左右 xy

//function
int man(int n,int x,int y){
  int nx, ny;

  nx=(n-1)%N;
  ny=(n-1)/N;

  x=x-nx;
  if(x<0) x*=-1;

  y=y-ny;
  if(y<0) y*=-1;

  return x+y;
}

int judge(struct node *n){
  int i, j=0;

  if(n==NULL) return -1;

  for(i=0;i<N*N;i++){
    if(n->data[i%N][i/N]==0) continue;
    if(n->data[i%N][i/N]!=i+1) j+=man(n->data[i%N][i/N],i%N,i/N);
  }

  return j;
}

struct xy blank(struct node *n){
  struct xy ddd;
  int i;

  for(i=0;i<N*N;i++)
    if(n->data[i%N][i/N]==0) break;

  ddd.x=i%N;
  ddd.y=i/N;

  return ddd;
}

struct node *mk(struct node *n,struct xy b, struct xy m){
  struct node *aaa;
  int i;

  aaa=malloc(sizeof(struct node));

  for(i=0;i<N*N;i++) aaa->data[i%N][i/N]=n->data[i%N][i/N];

  aaa->data[b.x][b.y]=aaa->data[m.x][m.y];
  aaa->data[m.x][m.y]=0;
  aaa->p=n;

  return aaa;
}


int puzzle(struct node *n,struct node *bp, int g,int d){
  int h=judge(n), i, j;
  struct xy bl, m;
  struct node *mm;

  if(h==0) return g;

  if(g+h>d) return -1;

  bl=blank(n);

  for(i=0;i<4;i++){
    m.x=bl.x+mv[i][0];
    m.y=bl.y+mv[i][1];

    if(m.x<0 || m.y<0 || m.x==N || m.y==N ) continue;

    mm=mk(n,bl,m);
    if(bp!=NULL){
      for(j=0;j<N*N;j++)
	if(mm->data[j%N][j/N]!=bp->data[j%N][j/N]) break;
      if(j==N*N){
	free(mm);
	continue;
      }
    }

    j=puzzle(mm,mm->p,g+1,d);
    if(j>0) return j;
  }

  if(n!=&root) free(n);
  return -1;
}

