void searchMinCost(int tempArr[N][N],int lastMove,int curCost)
{
  int h=0;
  int i,j;
  int blankI,blankJ;
  for(i=0;i<N;++i)
    {
      for(j=0;j<N;++j)
	{
	  if(tempArr[i][j]!=ansArr[i][j])
	    {
	      h+=heuristic[tempArr[i][j]][ansArr[i][j]];
	    }
	  if(tempArr[i][j]==0)
	    {
	      blankI=i;
	      blankJ=j;
	    }
	}
    }
  if(h==0&&curCost<curMinCost)
    {
      curMinCost=curCost;
      return;
    }
  if(curCost+h>curMinCost) return;
  if(blankI>0&&lastMove!=3)
    {
      tempArr[blankI][blankJ]=tempArr[blankI-1][blankJ];
      tempArr[blankI-1][blankJ]=0;
      searchMinCost(tempArr,1,curCost+1);
      tempArr[blankI-1][blankJ]=tempArr[blankI][blankJ];
      tempArr[blankI][blankJ]=0;
    }
  if(blankJ>0&&lastMove!=4)
    {
      tempArr[blankI][blankJ]=tempArr[blankI][blankJ-1];
      tempArr[blankI][blankJ-1]=0;
      searchMinCost(tempArr,2,curCost+1);
      tempArr[blankI][blankJ-1]=tempArr[blankI][blankJ];
      tempArr[blankI][blankJ]=0;
    }
  if(blankI<N-1&&lastMove!=1)
    {
      tempArr[blankI][blankJ]=tempArr[blankI+1][blankJ];
      tempArr[blankI+1][blankJ]=0;
      searchMinCost(tempArr,3,curCost+1);
      tempArr[blankI+1][blankJ]=tempArr[blankI][blankJ];
      tempArr[blankI][blankJ]=0;
    }
  if(blankJ<N-1&&lastMove!=2)
    {
      tempArr[blankI][blankJ]=tempArr[blankI][blankJ+1];
      tempArr[blankI][blankJ+1]=0;
      searchMinCost(tempArr,4,curCost+1);
      tempArr[blankI][blankJ+1]=tempArr[blankI][blankJ];
      tempArr[blankI][blankJ]=0;
    } 
}
void initHeuristic(void)
{
  int i,j;
  for(i=0;i<N*N;i++)
    {
      for(j=0;j<N*N;j++)
	{
	  heuristic[i][j]=abs(y[i]-y[j])+abs(x[i]-x[j]);
	  heuristic[i][j]*=7;
	  heuristic[i][j]/=9;
	}
    }
}

