#include <stdio.h>

#include <stdlib.h>

int A[4][4];
int B[4][4];

void I() {
  int i, j;
  for(i = 0; i < 4; i++)
    for(j = 0; j < 4; j++)
      scanf("%d", &A[i][j]);
}

void O() {
  int i, j;
  for(i = 0; i < 4; i++) {
    for(j = 0; j < 4; j++) printf("%3d", A[i][j]);
    puts("");
  }
}

void C(int m[4][4], int t[4][4]) {
  int i, j;

  for(i = 0; i < 4; i++)
    for(j = 0; j < 4; j++) m[i][j] = t[i][j];
}

int CA() {
  int i, sum = 0;
  for(i = 0; i < 16; i++) {
    int v = A[i/4][i%4];
    if(v) {
      v--;
      sum += abs(i/4-v/4)+abs(i%4-v%4);
    }
  }
  return sum;
}

int dx[] = {0, 1, 0, -1};
int dy[] = {1, 0, -1, 0};

void S(int *a, int *b) {
  int tmp = *a;
  *a = *b;
  *b = tmp;
}

int IN(int x, int y) {
  return 0<=x&&x<4&&0<=y&&y<4;
}

int D(int x, int y, int p, int dep, const int lim) {
  int i, h = CA();
  if(h == 0) return dep;
  if(dep+h > lim) return -1;

  for(i = 0; i < 4; i++) {
    int nx = x+dx[i], ny = y+dy[i], res;
    if(~p && i == (p+2)%4) continue;
    if(!IN(nx, ny)) continue;
    S(&A[y][x], &A[ny][nx]);
    res = D(nx, ny, i, dep+1, lim);
    if(~res) return res;
    S(&A[y][x], &A[ny][nx]);
  }

  return -1;
}

void G(int *x, int *y) {
  int i, j;
  for(i = 0; i < 4; i++) {
    for(j = 0; j < 4; j++) {
      if(!A[i][j]) {
	*x = j;
	*y = i;
	return;
      }
    }
  }
}

int  SO() {
  int x, y, lim, ans;
  G(&x, &y);
  for(lim = 0; lim < 50; lim++) {
    C(B, A);
    if((ans = D(x, y, -1, 0, lim)) != -1) return ans;
    C(A, B);
  }
  return -1;
}

int main() {
  I();
  printf("%d\n", SO());
  return 0;
}

