void sorting(int X[N][N], int Xj[N][N], int n)
{
  int i,j,k,l,d=0,f=0,tmp[N][N];

  for(i=0;i<N;i++) {
    for(j=0;j<N;j++) {
      if(Fin[i][j]!=X[i][j]) f++;
      if(X[i][j]==0) {
