      min=n;
    }
    return;
  }
  if(d+n>min) return;


  if(k>0 && k<N) {
    memcpy(tmp,X,sizeof(int)*N*N);
    f=tmp[k][l];
    tmp[k][l]=tmp[k-1][l];
    tmp[k-1][l]=f;
    if(memcmp(tmp,Xj,sizeof(int)*N*N)!=0)
      sorting(tmp, X, n+1);
  }
    if(l>0 && l<N) {
    memcpy(tmp,X,sizeof(int)*N*N);
    f=tmp[k][l];
    tmp[k][l]=tmp[k][l-1];
    tmp[k][l-1]=f;
    if(memcmp(tmp,Xj,sizeof(int)*N*N)!=0)
