  if(l>=0 && l<N-1) {
    memcpy(tmp,X,sizeof(int)*N*N);
    f=tmp[k][l];
    tmp[k][l]=tmp[k][l+1];
    tmp[k][l+1]=f;
    if(memcmp(tmp,Xj,sizeof(int)*N*N)!=0)
      sorting(tmp, X, n+1);
  }

}

