int dx[4] = {0,-1,0,1}, dy[4] = {1,0,-1,0}, limit, t[N][N];

void swap(int *a,int *b){
  int tmp = *a;
  *a = *b; *b = tmp;
  return;
}

int getsum(){
  int i, j, sum = 0, x;

  for(i = 0; i < N; i++){
    for(j = 0; j < N; j++){
      if(t[i][j] == 0) continue;
      x = t[i][j] -1;
      sum += abs(x/4-i) + abs(x%4-j);
    }
  }
  return sum;
}

int DFS(int depth, int pre, int py, int px){
  int i, tx, ty,h = getsum();

  if (h == 0) return TRUE;
  if (depth+h > limit) return FALSE;
  for (i = 0; i < 4; i++){
    if(abs(i-pre) == 2) continue;
    tx=px+dx[i];
    ty=py+dy[i];
    if(tx < 0 || ty < 0 || tx >= N || ty >= N) continue;
    swap(&t[ty][tx],&t[py][px]);
    if(DFS(depth+1,i,ty,tx)) return TRUE;
    swap(&t[ty][tx],&t[py][px]);
  }
  return FALSE;
}

