   public class Main {
       public static void main(String[] args) {
           Scanner sc = new Scanner(System.in);
           n = 16;
           char[] s = new char[n];
           for (int i = 0; i < n; i++) {
               s[i] = (char)('0' + sc.nextInt());
           }
           ans = "123456789:;<=>?0";
