		{13, 14, 15,  0}
	};

	public static int dfs(final int deep, int prev_x, int prev_y, final int limit, int[][] matrix){

		if(deep >= limit){
			return -1;
		}

		boolean same = true;
		LOOP:
		for(int i = 0; i < SIZE; i++){
			for(int j = 0; j < SIZE; j++){
				if(answer[i][j] != matrix[i][j]){
					same = false;
					break LOOP;
				}
			}
		}

		if(same){
			return 0;
		}

		for(int i = 0; i < SIZE; i++){
			for(int j = 0; j < SIZE; j++){

				if(matrix[i][j] == 0){

					for(int dx = -1; dx <= 1; dx++){
						for(int dy = -1; dy <= 1; dy++){
							if(dx == 0 && dy == 0){ continue; }
							if(dx != 0 && dy != 0){ continue; }

							final int nx = j + dx;
							final int ny = i + dy;

							if(prev_x == nx && prev_y == ny){
								continue;
							}

							if(0 <= nx && nx < SIZE && 0 <= ny && ny < SIZE){
								int tmp = matrix[i][j];
								matrix[i][j] = matrix[ny][nx];
								matrix[ny][nx] = tmp;

								int ret = dfs(deep + 1, j, i, limit, matrix);
								if(ret >= 0){
									return ret + 1;
								}

								tmp = matrix[i][j];
								matrix[i][j] = matrix[ny][nx];
								matrix[ny][nx] = tmp;
							}

						}
					}
				}
			}
		}

		return -1;
	}

