		int[][] matrix = new int[SIZE][SIZE];
		for(int i = 0; i < SIZE; i++){
			for(int j = 0; j < SIZE; j++){
				matrix[i][j] = sc.nextInt();
			}
		}

		for(int i = 0; i <= 45; i++){
			int ret = dfs(0, -1, -1, i, matrix);

			if(ret >= 0){
				System.out.println(ret);
				break;
			}
		}

	}

