		for(int i = 0; i < SIZE; i++){
			for(int j = 0; j < SIZE; j++){
				ret += DIST[board[i][j]][i][j];
			}
		}

		return ret;
	}

	public static void do_move(int[][] board, int x, int y, int dx, int dy){
		int tmp = board[y][x];
		board[y][x] = board[y + dy][x + dx];
		board[y + dy][x + dx] = tmp;
	}

	public static int calc_move(int[][] board, int x, int y, int dx, int dy){
		do_move(board, x, y, dx, dy);

		final int ret = calc_dist(board);

		do_move(board, x, y, dx, dy);

		return ret;
	}

	public static int check_move(int[][] board, int x, int y, int dx, int dy){
		final int nx = x + dx;
		final int ny = y + dy;

		if(0 > nx || nx >= SIZE || 0 > ny || ny >= SIZE){
			return Integer.MAX_VALUE;
		}else{
			return calc_move(board, x, y, dx, dy);
		}
	}

	public static class Tag implements Comparable<Tag>{
		int lower;
		int dx, dy;

		public Tag(int lower, int dx, int dy){
			this.lower = lower;
			this.dx = dx;
			this.dy = dy;
		}

		@Override
		public int compareTo(Tag arg0) {
			return this.lower - arg0.lower;
		}
	}

	public static int[][] move_dir = new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

	public static int min = Integer.MAX_VALUE;
	public static void dfs(int[][] board, int x, int y, int limit, int deep, int prev_x, int prev_y){
		//System.out.println(x + ", " + y + " : " + deep + "/" + limit);
		PriorityQueue<Tag> tags = new PriorityQueue<Tag>(4);
		for(int[] moves : move_dir){
			tags.add(new Tag(check_move(board, x, y, moves[0], moves[1]), moves[0], moves[1]));
		}

		while(!tags.isEmpty()){
			Tag tag = tags.poll();

			if(tag.lower >= Integer.MAX_VALUE){
				break;
			}else if(tag.lower == 0){
				min = Math.min(min, deep + 1);
				continue;
			}else if(limit <= deep + tag.lower){
				continue;
			}else if(x + tag.dx == prev_x && y + tag.dx == prev_y){
				continue;
			}else if(min != Integer.MAX_VALUE){
				continue;
			}

			do_move(board, x, y, tag.dx, tag.dy);
			dfs(board, x + tag.dx, y + tag.dy, limit, deep + 1, x, y);
			do_move(board, x, y, tag.dx, tag.dy);
		}
	}

