        {
            for (int i = 0; i < N2; i++)
            {
                if (state.f[i] != i + 1) return false;
            }
            return true;
        }
        static void P_COPY(Puzzle x, Puzzle y)
        {
            x.f = (int[])y.f.Clone();
            x.space = y.space;
            x.MD = y.MD;
        }
        static bool DFS(int depth, int prev)
        {
            if (state.MD == 0)
            {
                //Console.WriteLine(string.Join(" ",state.f));
                return true;
            }
            if (depth + state.MD > limit) return false;

            int sx = state.space / N;
