    {
        var code = Nodes.Select(x => x.Current).Aggregate((accum, x) => accum * 10 + x);
        return code;
    }

    private static int GetManhattanDistance(int current, int correct)
    {
        var cu = current - 1;
        var co = correct == 0 ? 15 : correct - 1;
        var d = Math.Abs(cu / 4 - co / 4) + Math.Abs(cu % 4 - co % 4);
        return d;
    }

