	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)

	var arr [N * N]int
	for i := 0; i < len(arr); i++ {
		x, err := nextInt(sc)
		if err != nil {
			panic(err)
		}
		arr[i] = x
	}

	puzzle := NewPuzzle(arr)
	fmt.Println(solve(puzzle))
}

