func dls(limit int, now int, state [16]byte, parents [][16]byte) (bool, int) {
	for _, s := range parents {
		if s == state {
			return false, 0
		}

	}

	if state == goal {
		return true, len(parents)
	}

	if manhattan(state)+now > limit {
		return false, 0
	}

	parents = append(parents, state)

	ok, ur := up(state)
	if ok {
		p := make([][16]byte, len(parents))
		copy(p, parents)
		ok, ans := dls(limit, now+1, ur, p)
		if ok {
			return true, ans
		}
	}
	ok, dr := down(state)
	if ok {
		p := make([][16]byte, len(parents))
		copy(p, parents)
		ok, ans := dls(limit, now+1, dr, p)
		if ok {
			return true, ans
		}
	}
	ok, lr := left(state)
	if ok {
		p := make([][16]byte, len(parents))
		copy(p, parents)
		ok, ans := dls(limit, now+1, lr, p)
		if ok {
			return true, ans
		}
	}
	ok, rr := right(state)
	if ok {
		p := make([][16]byte, len(parents))
		copy(p, parents)
		ok, ans := dls(limit, now+1, rr, p)
		if ok {
			return true, ans
		}
	}

	return false, 0

