func dls(limit int, now int, state [16]byte, parents map[[16]byte]bool) bool {

	if parents[state] {
		return false
	}

	if now == limit+1 {
		return false

	}

	if state == goal {
		return true
	}

	parents[state] = true

	ok, ur := up(state)
	if ok {
		if dls(limit, now+1, ur, parents) {
			return true

		}
	}
	ok, dr := down(state)
	if ok {
		if dls(limit, now+1, dr, parents) {
			return true

		}
	}
	ok, lr := left(state)
	if ok {
		if dls(limit, now+1, lr, parents) {
