    if H.empty_p que then assert false else
    let st = H.pop que in
    let { board = b; space = s; md = m; cost = c } = st.puzzle in
    let u = { board = Array.copy b; space = s; md = m; cost = c } in
    if u.md == 0 then u.cost
    else begin
      Hashtbl.add tbl u true;
      let (sx, sy) = (u.space / n1, u.space mod n1) in
