class Puzzle:
    def __init__(self, state):
        self.WIDTH = 4
        self.HIGHT = 4

        self.state = state
        self.x, self.y = self.idx_to_xy(self.state.index('0'))

    def idx_to_xy(self, idx):
        return idx % self.HIGHT, idx // self.WIDTH

    def xy_to_idx(self, x, y):
        return y * self.WIDTH + x

    def swap(self, x, y):
        zero = self.xy_to_idx(self.x, self.y)
        idx = self.xy_to_idx(x, y)

        tmp = self.state[zero]
        self.state[zero] = self.state[idx]
        self.state[idx] = tmp

        self.x, self.y = x, y

    def is_completed(self):
        for i in range(1, 16):
            if self.state[i - 1] != str(i):
                return False
        return True

    def pretty_print(self):
        for r in range(self.HIGHT):
            print(self.state[r*self.WIDTH:(r+1)*self.WIDTH])

