MAX_ITER = 45
def shortest_steps(p, iter, cache):
    # print(iter)
    # p.pretty_print()
    key = ' '.join(p.state)
    if key in cache and cache[key][0] < 10**3:
        return cache[key]
    elif p.is_completed():
        return 0, [p]
    else:
        if iter == MAX_ITER:
            return 10**3, [p]
        else:
            canditees = []
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                next_x = p.x + dx
                next_y = p.y + dy
                if 0 <= next_x and next_x < p.WIDTH and 0 <= next_y and next_y < p.HIGHT:
                    next_p = Puzzle(list(p.state))
                    next_p.swap(next_x, next_y)
                    canditees.append(next_p)
            steps, hist  = min(map(lambda np: shortest_steps(np, iter+1, cache), canditees),key=lambda i:i[0])
            steps += 1
            hist = list(hist)
            hist.append(p)
            cache[key] = [steps, hist]
            return steps, hist

