    value = 0
    for i in range(4):
        value += HS(i,0,puz[i*4])
        value += HS(i,1,puz[i*4+1])
        value += HS(i,2,puz[i*4+2])
        value += HS(i,3,puz[i*4+3])
    return value

def HS(i,j,num):
    if(num != 0):
        k = num-1
    else:
        k = 15
    ki = (int)(k/4)
    kj = k - ki*4
    value = abs(i-ki)+abs(j-kj)
    return value


