from collections import namedtuple


def get_offset(x, y):
    return 16 * y + 4 * x


def swap(board, orig_x, orig_y, dest_x, dest_y):
    orig_offset = get_offset(orig_x, orig_y)
    dest_offset = get_offset(dest_x, dest_y)
    try:
        dest_val = board & (0b1111 << dest_offset)
    except:
        print(orig_x, orig_y, dest_x, dest_y)
        raise
    offset_diff = dest_offset - orig_offset
    swap_val = dest_val >> offset_diff if offset_diff > 0 else dest_val << abs(offset_diff)
    return board - dest_val + swap_val


def put_next_puzzle(puzzle):
    board, x0, y0, count = puzzle.board, puzzle.x0, puzzle.y0, puzzle.count
    for move_horizontal in [0, 1]:
        for direction in [-1, 1]:
            if move_horizontal:
                new_x0, new_y0 = x0 + direction, y0
                if not 0 <= new_x0 < 4:
                    continue
            else:
                new_x0, new_y0 = x0, y0 + direction
                if not 0 <= new_y0 < 4:
                    continue
            new_board = swap(board, x0, y0, new_x0, new_y0)
            if new_board in cache:
                continue
            if new_board == CORRECT:
                return count + 1
            cache.append(new_board)
            puzzles.put(Puzzle(
                    board=new_board,
                    count=count + 1,
                    x0=new_x0,
                    y0=new_y0
            ))
    return -1


