OPEN = 0
CLOSE = 1
FORE = 0
BACK = 1

X=4
Y=4

adjacent=[]
for coor in range(X*Y):
	lst=[]
	x=coor%X
	y=coor/X
	if 0<x: lst.append(coor-1)
	if x<X-1: lst.append(coor+1)
	if 0<y: lst.append(coor-X)
	if y<Y-1: lst.append(coor+X)
	adjacent.append(lst)

def output(a):
	print(len(a)-1)
def backtrack(x):
	if x is not None:
		return backtrack(x.prev)+[x.board]
	return []
def forwardtrack(x):
	r=[]
	while x is not None:
		r.append(x.board)
		x = x.prev
	return r

def make_distance_table(board, wide):
	size = len(board)
	table = [[0]*size for _ in range(size)]
	for i in range(size):
		p = board[i]
		if p == 0: continue
		x1 = i / wide
		y1 = i % wide
		for j in range(size):
			x2 = j / wide
			y2 = j % wide
			table[p][j] += max(x1 - x2, x2 - x1)
			table[p][j] += max(y1 - y2, y2 - y1)
	return table

def get_distance(board, distance):
	v = 0
	for x in range(X*Y):
		p = board[x]
		if p == 0: continue
		v += distance[p][x]
	return v

class State:
	def __init__(self, board, space, prev, move, dir, kind = OPEN):
		self.board = board
		self.space = space
		self.prev = prev
		self.move = move
		self.dir = dir
		self.kind = kind
		if dir == FORE:
			dt = start_distance
		else:
			dt = goal_distance
		if prev is None:
			self.cost = move + get_distance(board, dt)
		else:
			p = board[prev.space]
			self.cost = prev.cost + 1 - dt[p][space] + dt[p][prev.space]
	def __lt__(x, y):
		return x.cost<y.cost

def a_star_search(start, goal):
	global start_distance, goal_distance
	q = []
	table ={}
	# start
	start_distance = make_distance_table(goal, X)
	a = State(start, start.index(0), None, 0, FORE)
	heapq.heappush(q,a)
	table[tuple(start)] = a
	# goal
	goal_distance = make_distance_table(start, X)
	a = State(goal, goal.index(0), None, 0, BACK)
	heapq.heappush(q,a)
	table[tuple(goal)] = a
	while q:
		a = heapq.heappop(q)
		if a.kind == CLOSE: continue
		for x in adjacent[a.space]:
			b = a.board[:]
			b[a.space] = b[x]
			b[x] = 0
			key = tuple(b)
			if key in table:
				c = table[key]
				if a.dir != c.dir:
					if a.dir == FORE:
						output(backtrack(a)+forwardtrack(c))
					else:
						output(backtrack(c)+forwardtrack(a))
					return
				if c.move > a.move + 1:
					if c.kind == OPEN:
						c.kind = CLOSE
						c = State(b, x, a, a.move + 1, a.dir)
						table[key] = c
					else:
						c.prev = a
						c.cost = c.cost - c.move + a.move + 1
						c.move = a.move + 1
						c.kind = OPEN
					heapq.heappush(q,c)
			else:
				c = State(b, x, a, a.move + 1, a.dir)
				heapq.heappush(q,c)
				table[key] = c
		a.kind = CLOSE

