solution = [i + 1 for i in range(15)]
solution.append(0)

def get_patten(B):
    return ''.join(map(str, B))

def change_left(index, B):
    C = B.copy()
    C[index], C[index - 1] = C[index - 1], C[index]
    return C

def change_right(index, B):
    C = B.copy()
    C[index], C[index + 1] = C[index + 1], C[index]
    return C

def change_top(index, B):
    C = B.copy()
    C[index], C[index - 4] = C[index - 4], C[index]
    return C

def change_bottom(index, B):
    C = B.copy()
    C[index], C[index + 4] = C[index + 4], C[index]
    return C

def get_diff(B):
    index_list = [0] * 16
    for i, v in enumerate(B):
        index_list[v] = i

    diff = 0
    for i, v in enumerate(solution):
        index = index_list[v]
        d = abs(i - index)
        if d >= 4:
            diff += (d // 4) + (d % 4)
        elif i // 4 == index // 4:
            diff += d
        elif d == 0:
            continue
        else: # d = 1 or 2 or 3
            diff += 1 + (4 - d)

    return diff


def get_diff_old(B):
    diff = 0
    for i in range(16):
        if i == 0:
            place = 15
        else:
            place = i - 1
        index = B.index(i)

        d = abs(place - index) 
        if d >= 4:
            diff += (d // 4) + (d % 4)
        elif place // 4 == index // 4:
            diff += d
        elif d == 0:
            continue
        else: # d = 1 or 2 or 3
            diff += 1 + (4 - d)

    return diff

def judge(B):
    for i in range(16):
        if solution[i] != B[i]:
            return False
    return True


