from heapq import heappush, heappop

def get_patten(B):
    return ''.join(map(str, B))

def change_left(index, B):
    C = B.copy()
    C[index], C[index - 1] = C[index - 1], C[index]
    return C

def change_right(index, B):
    C = B.copy()
    C[index], C[index + 1] = C[index + 1], C[index]
    return C

def change_top(index, B):
    C = B.copy()
    C[index], C[index - 4] = C[index - 4], C[index]
    return C

def change_bottom(index, B):
    C = B.copy()
    C[index], C[index + 4] = C[index + 4], C[index]
    return C

def get_diff(B):
    diff = 0
    for i in range(16):
        if i == 0:
            place = 15
        else:
            place = i - 1
        index = B.index(i)

        d = abs(place - index) 
        if d >= 4:
            diff += (d // 4) + (d % 4)
        elif place // 4 == index // 4:
            diff += d
        elif d == 0:
            continue
        else: # d = 1 or 2 or 3
            diff += 1 + (4 - d)

    return diff

