    if diff_count > 45:
        continue

    p = get_patten(B)
    if p == '1234567891011121314150':
        print(count)
        exit()

    index = B.index(0)

    if index % 4 != 0 and prev != 'right':
        C = change_left(index, B)
        diff = get_diff(C)
        heappush(q, (diff + count, C, 'left', count + 1))

    if index % 4 != 3 and prev != 'left':
        C = change_right(index, B)
        diff = get_diff(C)
        heappush(q, (diff + count, C, 'right', count + 1))

    if index >= 4 and prev != 'bottom':
        C = change_top(index, B)
        diff = get_diff(C)
        heappush(q, (diff + count, C, 'top', count + 1))

    if index <= 11 and prev != 'top':
        C = change_bottom(index, B)
        diff = get_diff(C)
        heappush(q, (diff + count, C, 'bottom', count + 1))

